// Generated by scripts/build_recipes.py from data/recipes/*.json. Edit the recipes, not this file.
window.FISHPOND = {"meta":{"built":"2026-11-09","count":311},"items":[{"id":"catch-up-on-a-long-email-thread-in-a-minute","t":"Catch up on a long email thread in a minute","d":"Turn a 30-message thread into a short summary of what was decided, what's still open and what's expected of you.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant","Gmail","Outlook"],"when":"When you're copied into a thread late or come back from leave","steps":[{"h":"Try the built-in summary first","b":"Gemini in Gmail and Copilot in Outlook can summarise a thread from a button at the top of the email, if your plan includes it."},{"h":"Or copy the whole thread","b":"Open the thread, expand all messages, select all and copy. Check your workplace AI policy before pasting work emails into a personal AI account."},{"h":"Ask for a structured catch-up","b":"Paste the thread into your AI assistant with this prompt.","p":"Summarise this email thread for me. I am [your name and role]. Give me: 1) The background in two sentences. 2) Decisions already made, with who made them. 3) Open questions still being discussed. 4) Anything anyone has asked me or my team to do, with deadlines. 5) A suggested one-paragraph reply if one is needed from me. Use bullet points and keep it under 200 words. Thread: [paste thread]"}],"example":"Background: Venue for the 12 Dec staff lunch. Decided: The Old Mill, 40 people (Jo). Open: vegetarian numbers, who pays deposit. Asked of you: confirm final headcount by Fri 21 Nov. Suggested reply: 'Thanks all, I'll send the final headcount by Friday.'","tips":["Ask 'what did I miss that sounds urgent?' as a follow-up question; it often surfaces a buried request."],"auto":{"trigger":{"type":"manual","detail":"User opens a long thread and asks for a catch-up"},"actions":[{"type":"ai.summarize","detail":"Summarise background, decisions, open questions and asks"},{"type":"email.draft","detail":"Draft a short reply if one is needed"}]}},{"id":"turn-meeting-notes-into-actions-and-a-follow-up-email","t":"Turn meeting notes into actions and a follow-up email","d":"Paste in your scribbled notes and get a tidy action list plus a ready-to-send follow-up email for everyone who attended.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Gmail","Outlook"],"when":"Straight after any meeting","steps":[{"h":"Grab your notes","b":"Type up or photograph your handwritten notes. Messy is fine, as long as you can read them."},{"h":"Ask for actions and an email","b":"Paste or attach the notes with this prompt.","p":"Here are my notes from a meeting about [topic] with [attendees]. 1) List every action as: owner - task - deadline. If an owner or deadline is unclear, mark it '?' so I can check. 2) Write a follow-up email to the attendees under 150 words: thank them, recap the 2 or 3 main decisions, list the actions, and confirm the next meeting date [date if known]. Friendly, professional, British English. Notes: [paste notes]"},{"h":"Fill the gaps and send","b":"Replace any '?' with the right name or date, then send the email from your usual account."}],"example":"Actions: Rachel - send venue options - Fri 21 Nov. Imran - get catering quotes - ?. Me - draft invite - Mon 24 Nov. Email: Hi all, thanks for a productive chat today. We agreed on a Thursday evening event for around 60 people...","tips":["Send the follow-up within the hour; people are far more likely to act on it while the meeting is fresh."],"auto":{"trigger":{"type":"manual","detail":"User pastes or photographs meeting notes"},"actions":[{"type":"ai.extract","detail":"Pull out owners, tasks and deadlines"},{"type":"email.draft","detail":"Draft a follow-up email to attendees"},{"type":"list.add","detail":"Add the user's own actions to their to-do list"}]}},{"id":"get-started-on-a-task-you-keep-putting-off","t":"Get started on a task you keep putting off","d":"Name the task you're avoiding and get a tiny first step, a 25-minute plan and a kinder way to think about it.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant","Reminders app"],"when":"When you've been avoiding something for days","steps":[{"h":"Be honest about what's stopping you","b":"Note the task and why it feels hard: boring, confusing, scary, or too big."},{"h":"Ask for a way in","b":"Paste this prompt into your AI assistant.","p":"I keep putting off this task: [task]. It feels hard because [reason]. Help me start. Give me: 1) A first step so small it takes under 2 minutes. 2) A 25-minute plan broken into 3 or 4 mini steps. 3) What 'good enough' looks like for a first attempt. 4) One reframe for why this feels hard, in a kind, practical tone, not a pep talk."},{"h":"Set a 25-minute timer","b":"Do the 2-minute step straight away, then start a timer on your phone and work through the mini steps. Stop when it rings if you want to."}],"example":"2-minute step: Open the tax return website and log in. 25 minutes: 1) Find last year's P60 (5 min). 2) Fill in personal details (5 min). 3) Enter income figures (10 min). 4) Save and note questions (5 min). Good enough: Half done and saved.","tips":["Starting is the hardest part; most people keep going once the first step is done.","For money, tax or legal tasks, use this to get organised, and check anything you're unsure about with a qualified adviser."],"auto":{"trigger":{"type":"manual","detail":"User names a task they are avoiding"},"actions":[{"type":"ai.generate","detail":"Suggest a tiny first step and a 25-minute plan"},{"type":"notify","detail":"Start a 25-minute reminder"}]}},{"id":"answer-customers-in-their-own-language","t":"Answer customers in their own language","d":"Understand a message in any language and send back a natural, accurate reply in that language, with an English copy for your records.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"When a message arrives in a language you don't speak","steps":[{"h":"Paste in the message","b":"Copy the customer's message into ChatGPT, Claude or Gemini, removing any account numbers or addresses."},{"h":"Ask for a translation and reply","b":"Use this prompt so you understand the message and get a reply in one go.","p":"Here is a customer message: [paste]. 1) Tell me what language it's in and translate it into English. 2) Point out anything that might be lost in translation, like tone or slang. 3) Here is my reply in English: [your reply]. Translate it into the customer's language so it sounds natural and polite for a small business, not word-for-word. 4) Translate your version back into English so I can check the meaning is unchanged."},{"h":"Check the back-translation","b":"Read the English back-translation. If the meaning has shifted, ask the AI to fix that sentence before you send."}],"example":"Language: Polish. Translation: 'Hello, I ordered two jars but received one. Can you send the second one?' Tone: polite, a little disappointed. Your reply in Polish: 'Dzień dobry, bardzo przepraszamy za pomyłkę...' Back-translation: 'Hello, we're very sorry for the mistake. The second jar ships today.'","tips":["For refunds, contracts or anything legal, mention that the English version is the official one.","Add a line saying you used translation, so customers forgive the odd awkward phrase."],"auto":{"trigger":{"type":"message_received","detail":"A customer message in another language arrives"},"actions":[{"type":"ai.generate","detail":"Translate the message into English"},{"type":"ai.generate","detail":"Translate the approved reply into the customer's language"},{"type":"notify","detail":"Show both versions to the person replying"}]}},{"id":"walk-into-every-sales-call-fully-prepared","t":"Walk into every sales call fully prepared","d":"A one-page brief on a prospect's business, recent news, likely needs and smart questions to ask, ready in five minutes before the call.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","LinkedIn"],"when":"Before every sales call","steps":[{"h":"Grab the basics","b":"Note the company's website, the person's job title and anything they told you when they booked. A quick look at their LinkedIn company page helps too."},{"h":"Ask your AI assistant for a brief","b":"Use an assistant that can search the web, such as ChatGPT, Claude or Gemini with search turned on, and paste this prompt.","p":"I have a sales call with [name, job title] at [company], website [URL]. I sell [what you sell] to [type of customer]. Search the web and give me a one-page brief: 1) what the company does in 2 lines, 2) size and location if public, 3) any news from the last 6 months, 4) 3 problems they likely have that I could help with, and why you think so, 5) 5 open questions to ask on the call, 6) one thing to avoid saying. Include the source link for every fact and say clearly if you couldn't find something."},{"h":"Check the facts","b":"Click two or three of the source links to confirm the key facts, especially news and numbers."},{"h":"Keep it handy","b":"Paste the brief into your notes app or the calendar event so it's open when the call starts."}],"example":"Greenway Joinery: bespoke kitchens, about 25 staff, two showrooms in Leeds. News: opened a second showroom in March (source). Likely needs: more enquiries from new area; quicker quoting. Ask: 'How are leads from the new showroom tracking?' Avoid: assuming they sell online.","tips":["AI can mix up companies with similar names, so always check the website matches.","Only use information that's publicly available, and don't dig into anyone's personal life."],"auto":{"trigger":{"type":"calendar_event","detail":"One hour before a meeting tagged 'sales'"},"actions":[{"type":"web.fetch","detail":"Look up the prospect's company website and recent news"},{"type":"ai.generate","detail":"Write a one-page brief with questions to ask"},{"type":"notify","detail":"Send the brief to the user before the call"}]}},{"id":"let-unsuccessful-candidates-down-kindly","t":"Let unsuccessful candidates down kindly","d":"Respectful, personal rejection emails for each stage of hiring, with optional feedback that's honest, useful and safe to send.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail"],"when":"When you've made a hiring decision","steps":[{"h":"Write down why, against your criteria","b":"For anyone who interviewed, note one or two job-related reasons from your scoring sheet, such as 'less experience of managing budgets than other candidates'."},{"h":"Ask AI for the messages","b":"Paste this prompt into your AI assistant.","p":"Write 3 rejection email templates for [job title] at [business]: 1) applied but not shortlisted (under 80 words), 2) interviewed, no detailed feedback (under 100 words), 3) interviewed, with brief feedback (under 140 words) using these points: [job-related points from scoring sheet]. All should thank them sincerely, be clear the decision is final, avoid any comments on personality or anything not related to the job criteria, and wish them well. Template 3 should frame feedback constructively. British English, warm, human. Use [Name] placeholders."},{"h":"Personalise and send promptly","b":"Add one specific, genuine line where you can, such as something they did well. Send within a few days of deciding."}],"example":"Hi [Name], thank you for coming in to meet us on Tuesday and for preparing so thoroughly. We enjoyed hearing about your work at the farm shop. We've decided to offer the role to someone with more experience of running stock systems. We'd be happy to hear from you for future roles. Wishing you all the best.","tips":["Keep feedback tied to the job criteria; it's fairer and protects you if a decision is ever questioned.","Tell candidates how long you'll keep their details, in line with your privacy notice."],"auto":{"trigger":{"type":"manual","detail":"A candidate's status changes to Unsuccessful"},"actions":[{"type":"ai.generate","detail":"Write a rejection email for the right stage"},{"type":"email.draft","detail":"Save it as a draft for the manager to personalise and send"}]}},{"id":"brief-yourself-on-a-company-before-a-sales-call","t":"Brief yourself on a company before a sales call","d":"A one-page snapshot of a prospect's recent posts, news, tone and likely priorities, with three smart questions to open the call.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","LinkedIn"],"when":"Before every sales or partnership call","steps":[{"h":"Gather a few recent posts","b":"Skim the company's LinkedIn page and website news for the last month. Copy the text of three to five recent posts or announcements."},{"h":"Ask for a call brief","b":"Paste the posts into an AI assistant with web search turned on and use this prompt.","p":"I have a call with [company name] ([website]) about [what you offer]. Here are their recent posts and news: [paste]. Also search for any recent public news about them. Give me: 1) a 3-sentence summary of what they're focused on right now; 2) their tone and what they seem proud of; 3) likely challenges they might have that relate to [your offer]; 4) three open questions I could ask early in the call; 5) anything to avoid mentioning. Mark anything you're unsure of as 'unconfirmed'. One page max."},{"h":"Keep it with the meeting","b":"Paste the brief into the calendar invite's notes or your notes app so it's in front of you when the call starts."}],"example":"Focus: opening a second site in Manchester and hiring 20 staff. Tone: proud of their apprentices. Likely challenge: training new staff quickly. Ask: 'How are you getting new starters up to speed for the Manchester opening?' Avoid: last year's product recall (unconfirmed).","tips":["Stick to public, business information. Don't dig into individuals' personal social accounts."],"auto":{"trigger":{"type":"calendar_event","detail":"One hour before a meeting tagged sales"},"actions":[{"type":"web.fetch","detail":"Read the company's recent public posts and news"},{"type":"ai.summarize","detail":"Write the one-page call brief"},{"type":"notify","detail":"Send the brief to the user"}]}},{"id":"get-a-professional-editor-s-notes-on-your-draft","t":"Get a professional editor's notes on your draft","d":"Line-by-line feedback on clarity, structure and tone for anything you've written, plus a tidied version you can accept or ignore.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Docs"],"when":"Before publishing or sending anything important","steps":[{"h":"Paste your draft","b":"Copy your finished draft into your AI assistant. Tell it who will read it and what you want them to do afterwards."},{"h":"Ask for edits, not a rewrite","b":"Use this prompt so your voice stays intact.","p":"Act as a careful editor. Reader: [who]. Goal: [what they should think or do]. Draft: [paste]. Don't rewrite it in your voice. Give me: 1) the 3 biggest problems (structure, clarity, missing information); 2) a list of specific line edits as 'Original -> Suggested -> Why'; 3) any sentences over 30 words to split; 4) jargon to replace; 5) a one-line verdict on whether the opening makes people want to keep reading. Use British English spelling."},{"h":"Accept what helps","b":"Make the changes you agree with in Google Docs. Ignore anything that flattens your style; you're the author."}],"example":"Big problem 1: Your main point appears in paragraph 4; move it to the top. Line edit: 'In order to facilitate' -> 'To help' (simpler). Long sentence: para 2, 42 words. Verdict: The opening is a definition; start with the customer story instead.","tips":["Run a second pass asking only for spelling, grammar and consistency once you're happy with the structure."],"auto":{"trigger":{"type":"new_file","detail":"Draft added to the To edit folder"},"actions":[{"type":"ai.generate","detail":"Write editor's notes and line edits"},{"type":"doc.create","detail":"Save the notes next to the draft"},{"type":"notify","detail":"Tell the user the notes are ready"}]}},{"id":"get-the-key-points-from-a-long-youtube-video","t":"Get the key points from a long YouTube video","d":"A short summary, the main points with timestamps and any steps or links mentioned, so you can decide whether to watch the whole thing.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":3,"tools":["YouTube","AI assistant"],"when":"Whenever a video is too long to watch right now","steps":[{"h":"Share the video with your assistant","b":"In Gemini you can paste a YouTube link directly. For other assistants, open the video on YouTube, click 'Show transcript' under the description, and copy the text."},{"h":"Ask for a structured summary","b":"Paste the link or transcript with this prompt.","p":"Summarise this YouTube video: [link or transcript]. Give me: 1) what it's about in 2 sentences; 2) the 5-8 main points, each with its timestamp; 3) any step-by-step instructions as a numbered list; 4) any products, tools, books or links mentioned; 5) who would find it most useful; 6) a verdict: worth watching in full, or is this summary enough? Don't add information that isn't in the video."},{"h":"Save the useful bits","b":"Copy the summary into your notes app with the video link so you can jump to the right moment later."}],"example":"About: a physio explains five desk stretches for back pain. Points: 1:20 why sitting tightens hips; 3:05 cat-cow in a chair... Steps: 1. Sit tall... Verdict: summary covers it; watch 3:05-6:00 to see the movements.","tips":["For health, money or legal videos, treat the summary as a starting point and check advice with a qualified professional."],"auto":{"trigger":{"type":"manual","detail":"User shares a YouTube link"},"actions":[{"type":"web.fetch","detail":"Get the video transcript"},{"type":"ai.summarize","detail":"Summarise key points with timestamps"},{"type":"file.save","detail":"Save the summary to the user's notes"}]}},{"id":"get-the-gist-of-any-long-web-page-fast","t":"Get the gist of any long web page fast","d":"Paste a long article or web page into your AI assistant and get a short summary, the key facts and anything you should double-check.","cat":"Research & News","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"Whenever a page is too long to read now","steps":[{"h":"Copy the page or its link","b":"Select all the text on the page and copy it, or copy the address from your browser bar. Some assistants can open links, but pasting the text is the most reliable."},{"h":"Ask for a structured summary","b":"Open ChatGPT, Claude or Gemini, paste the text and this prompt.","p":"Summarise the article below for someone who has [2] minutes. Give me: 1) a one-sentence headline, 2) the 5 most important points as bullets, 3) any numbers, dates or names mentioned, 4) what the author wants the reader to believe or do, 5) any claims that are not backed up by evidence in the text. Only use what is in the article; if something is unclear, say so. Article: [paste text here]"},{"h":"Check anything you'll act on","b":"If a number or claim matters to you, find it in the original page and confirm it says what the summary says. AI summaries can drop context or get details wrong."}],"example":"Headline: The council plans to cut town-centre parking by 20% from April. Key points: 300 spaces removed; two new park-and-ride sites; consultation closes 14 March... Unsupported claims: 'footfall will rise' has no figures behind it.","tips":["Ask 'what did you leave out?' as a follow-up to catch anything important the summary skipped."],"auto":{"trigger":{"type":"manual","detail":"User shares a web page link"},"actions":[{"type":"web.fetch","detail":"Fetch the page text"},{"type":"ai.summarize","detail":"Write headline, key points, figures and unsupported claims"},{"type":"notify","detail":"Send the summary to the user"}]}},{"id":"ask-a-long-pdf-questions-and-get-page-numbers","t":"Ask a long PDF questions and get page numbers","d":"Upload a long PDF and ask it anything in plain English, getting answers that point to the exact page so you can check them.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"Whenever you have a long document to get through","steps":[{"h":"Upload the PDF","b":"Open ChatGPT, Claude or Gemini and attach the PDF using the paperclip or plus button. Scanned documents work best if the text is clear."},{"h":"Set the ground rules","b":"Paste this prompt first so every answer comes with evidence.","p":"You are helping me understand the attached document, [document name]. For every answer: quote the relevant sentence, give the page number, and say 'not in the document' if the answer isn't there rather than guessing. My first questions: 1) What is this document for, in two sentences? 2) What are the key dates or deadlines? 3) [your own question]"},{"h":"Ask follow-ups","b":"Keep asking in the same chat, for example 'What does it say about cancellations?' or 'What do I have to do, and by when?'"},{"h":"Check the pages","b":"Open the PDF at the page numbers given for anything important. AI can occasionally mis-number pages or miss a clause."}],"example":"Q: What's the notice period? A: 'Either party may end this agreement with 60 days' written notice' (page 7, section 12.1). Q: Is there an early exit fee? A: Not in the document.","tips":["Remove or black out account numbers and personal details before uploading, and check your workplace AI policy for work documents."],"auto":{"trigger":{"type":"new_file","detail":"User uploads a PDF"},"actions":[{"type":"ai.extract","detail":"Read the document and index it by page"},{"type":"ai.generate","detail":"Answer questions with quotes and page numbers"}]}},{"id":"turn-rough-job-notes-into-a-professional-quote","t":"Turn rough job notes into a professional quote","d":"Go from scribbled notes or a voice memo to a clear, itemised quote with scope, exclusions, timescales and payment terms.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Voice notes","Word"],"when":"After every site visit or enquiry call","steps":[{"h":"Capture the job details","b":"Straight after the visit, record a voice note or jot down what the customer wants, measurements, materials and anything tricky."},{"h":"Draft the quote","b":"Paste your notes (or the voice note transcript) into your AI assistant with this prompt.","p":"Turn my notes below into a professional quote for [customer first name] from [my business name]. Include: a short summary of the job, an itemised table (item, quantity, unit price, total) using ONLY the prices I give, subtotal, VAT at [rate, or 'not VAT registered'], total, what's included, what's NOT included, estimated start date and duration, how long the quote is valid ([30] days), and payment terms ([e.g. 25% deposit, balance on completion]). Friendly, clear tone. Mark any price I haven't given as [PRICE NEEDED]. My notes: [paste notes]"},{"h":"Check the numbers","b":"Add up the table yourself or paste it into a spreadsheet. AI can make arithmetic slips."},{"h":"Put it on your letterhead","b":"Paste the final text into your quote template in Word or Google Docs, save as PDF and send."}],"example":"Quote Q-1042 for Mrs Ellis. Supply and fit 12 sq m oak-effect laminate in the lounge. Laminate 13 sq m @ £24 = £312; Underlay = £65; Labour 1.5 days = £330. Total £707 (not VAT registered). Not included: moving furniture, skirting replacement. Valid 30 days.","tips":["Save your standard 'included / not included' wording and payment terms in a note so every quote is consistent."],"auto":{"trigger":{"type":"manual","detail":"User shares job notes or a voice memo"},"actions":[{"type":"ai.generate","detail":"Draft an itemised quote using the given prices"},{"type":"doc.create","detail":"Create the quote document"},{"type":"notify","detail":"Ask the user to check prices before sending"}]}},{"id":"turn-tonight-s-leftovers-into-tomorrow-s-lunch","t":"Turn tonight's leftovers into tomorrow's lunch","d":"Snap your leftovers and get two or three quick lunch ideas that use them up, with no extra shopping.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":3,"tools":["AI assistant","Phone camera"],"when":"After dinner, when there's food left over","steps":[{"h":"Photograph the leftovers","b":"Take a photo of what's left in the pans or containers, plus any odds and ends in the fridge you'd like to use."},{"h":"Ask for lunch ideas","b":"Attach the photo in your AI assistant and paste this prompt.","p":"Here's a photo of my leftovers: [describe briefly, e.g. half a roast chicken, some rice, wilting spinach]. Suggest 3 lunches I can make tomorrow in under [10] minutes, ideally ones that travel well in a lunchbox. Only use what's in the photo plus basic store-cupboard items like oil, spices, eggs and bread. For each: name, what to do tonight, what to do tomorrow, and how long it keeps in the fridge."},{"h":"Prep and pack tonight","b":"Do the 'tonight' steps straight away and put the food in a labelled container so it's ready to grab."}],"example":"1) Chicken & spinach fried rice: tonight shred the chicken; tomorrow fry with rice, spinach and an egg (8 mins). 2) Chicken wrap with yoghurt dressing... Keeps: cooked rice 1 day only, so eat it first.","tips":["Food safety matters: follow official food hygiene guidance on how long cooked rice and meat keep, and when in doubt throw it out."],"auto":{"trigger":{"type":"manual","detail":"User shares a photo of leftovers"},"actions":[{"type":"ai.generate","detail":"Suggest 3 lunches using only the leftovers shown"},{"type":"notify","detail":"Send the ideas and prep steps to the user"}]}},{"id":"understand-any-menu-or-sign-with-your-phone","t":"Understand any menu or sign with your phone","d":"Point your camera at a menu, sign or label abroad and get a clear translation plus what the dishes actually are.","cat":"Travel","side":"life","lvl":"Beginner","mins":2,"tools":["AI assistant","Phone camera"],"when":"While you're travelling","steps":[{"h":"Take a clear photo","b":"Snap the menu, sign or label straight on, in good light, so the text is sharp."},{"h":"Ask for a translation with context","b":"Attach the photo to your AI assistant with this prompt. Google Lens and your phone's camera translate feature can also translate text on the spot.","p":"Translate this [menu/sign/label] into English. For a menu: list each dish with a short description of what it is, the main ingredients, whether it's likely spicy, and flag anything that may contain [my dietary needs, e.g. pork, shellfish, nuts]. Suggest 3 dishes a first-time visitor might enjoy. For a sign: tell me what it means and whether I need to do anything."},{"h":"Confirm with staff","b":"If you have an allergy or strict diet, show staff the relevant phrase and ask them to confirm."}],"example":"Bacalhau a Bras - shredded salt cod with crispy potatoes and egg, not spicy. Polvo a lagareiro - roast octopus with garlic and olive oil (shellfish/seafood). Try: bifana (pork sandwich), caldo verde (kale soup)... Sign: 'Proibido estacionar' - no parking.","tips":["Translations can miss hidden ingredients, so always check with staff if you have a food allergy."],"auto":{"trigger":{"type":"manual","detail":"User snaps a photo of a menu or sign"},"actions":[{"type":"ai.extract","detail":"Read the text from the photo"},{"type":"ai.generate","detail":"Translate and explain dishes, flagging dietary concerns"}]}},{"id":"understand-a-hospital-letter-in-plain-english","t":"Understand a hospital letter in plain English","d":"Get a plain-English explanation of medical words in a letter or leaflet, plus questions to ask your care team.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant"],"when":"When a letter or leaflet is hard to follow","steps":[{"h":"Remove personal details","b":"Before sharing anything, cover or delete your name, address, date of birth, hospital and NHS or insurance numbers."},{"h":"Ask for a plain-English version","b":"Paste the text, or a photo with details covered, into your AI assistant with this prompt.","p":"Please explain this [hospital letter/leaflet] in plain English for someone without medical training: [paste text]. Explain each medical word or abbreviation simply, list any practical things it asks me to do (appointments, preparation, dates), and give me 5 questions I could ask my doctor or nurse. Don't interpret test results or tell me what they mean for my health, and say clearly if something should be checked with my care team."},{"h":"Check with your care team","b":"Take your questions to your GP, consultant, nurse or pharmacist. They know your full history and can explain what it means for you."}],"example":"'Bilateral' means both sides. 'Ultrasound' is a scan using sound waves, it's painless. What to do: drink 1 litre of water an hour before your scan on 4 Dec, don't empty your bladder. Questions: How long will results take? Who will tell me the results?","tips":["AI explanations can be wrong or miss context, so always check what matters with your care team.","Health information is sensitive: share only what you need and check the AI tool's privacy settings."],"auto":{"trigger":{"type":"manual","detail":"User pastes a letter with personal details removed"},"actions":[{"type":"ai.generate","detail":"Explain terms in plain English and list actions and questions"}]}},{"id":"understand-every-line-on-your-payslip","t":"Understand every line on your payslip","d":"A plain-English explanation of your payslip, what each deduction is for, and a short list of questions to ask payroll if something looks off.","cat":"Money","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"When you start a new job or your pay changes","steps":[{"h":"Photograph or download your payslip","b":"Take a clear photo or download the PDF from your employer's payroll portal."},{"h":"Cover personal identifiers","b":"Blur or crop out your name, employee number, National Insurance or tax ID number and bank details before sharing."},{"h":"Ask for an explanation","b":"Attach the payslip to your AI assistant and use this prompt.","p":"This is my payslip from [country]. Explain every line in plain English: what it is, why it's taken, and whether it's a standard deduction. Show how gross pay becomes net pay step by step. Point out anything unusual, such as a tax code that looks like an emergency code, a pay rate that doesn't match [my agreed salary or hourly rate], or a deduction I may not recognise. Finish with up to 5 questions I could ask payroll. Don't give me tax advice, just explain."},{"h":"Check anything flagged","b":"If the AI spots something odd, confirm it with your payroll team or your country's official tax website rather than relying on the AI's answer."}],"example":"Gross pay £2,500. Income tax £291 (based on your tax code). National Insurance £158. Pension 5% £105 (your workplace pension). Student loan £62. Net £1,884. Worth asking: your tax code ends in W1/M1, which is often temporary. Is this correct?","tips":["Tax rules vary by country and change often. Use the AI to understand, and your payroll team or official tax service to confirm.","Keep a folder of payslips. They're useful for mortgages, rentals and tax queries."],"auto":{"trigger":{"type":"new_file","detail":"A new payslip is saved to the Payslips folder"},"actions":[{"type":"ai.extract","detail":"Pull gross pay, deductions and net pay from the payslip"},{"type":"sheet.append","detail":"Log this month's figures in a pay history sheet"},{"type":"notify","detail":"Alert the user if net pay changed by more than 5%"}]}},{"id":"get-a-tricky-topic-explained-at-your-level","t":"Get a tricky topic explained at your level","d":"A clear explanation of any idea you're stuck on, pitched at your level, with an everyday example and a quick check that you've got it.","cat":"Learning","side":"life","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"When you're stuck on an idea","steps":[{"h":"Say what's confusing you","b":"Write down the topic and, if you can, the exact part that stops making sense."},{"h":"Ask for a layered explanation","b":"Paste this prompt into your AI assistant.","p":"Explain [topic] to me. I'm [describe: for example a 15-year-old studying GCSE chemistry, or an adult with no science background]. The part I don't get is: [describe]. Do it in three layers: 1) a one-sentence version a 10-year-old would understand, 2) a fuller explanation with an everyday analogy, 3) the proper version with correct terms for my level. Then ask me 3 quick questions to check I understand, one at a time, and explain anything I get wrong."},{"h":"Ask follow-ups","b":"If something still doesn't click, say which sentence lost you and ask for another analogy."},{"h":"Write it in your own words","b":"Finish by writing a three-line summary in your own words. Ask the AI to check it."}],"example":"1) Interest is a fee for borrowing money, or a reward for lending it. 2) It's like renting a bike: the longer you keep it, the more you pay. 3) Compound interest means interest is charged on the original amount plus interest already added...","tips":["Tell it what you already know so it doesn't start too basic or too advanced.","For exam answers, check the wording against your textbook or mark scheme."],"auto":{"trigger":{"type":"manual","detail":"User asks about a topic"},"actions":[{"type":"ai.generate","detail":"Explain the topic in three layers"},{"type":"ai.generate","detail":"Ask three check questions"},{"type":"doc.create","detail":"Save the explanation to study notes"}]}},{"id":"reach-out-to-people-for-career-advice","t":"Reach out to people for career advice","d":"Short, friendly messages to old colleagues or people in a field you're curious about, asking for a quick chat without feeling awkward.","cat":"Careers","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","LinkedIn"],"when":"When you want advice or a foot in the door","steps":[{"h":"Pick three people","b":"Choose a mix: someone you know well, a former colleague you've lost touch with, and someone doing a job you're curious about."},{"h":"Draft the messages","b":"Paste a few details about each person into your AI assistant with this prompt.","p":"Write short LinkedIn messages (under 80 words each) for these people. My situation: [for example exploring a move into project management]. Person 1: [how I know them, what they do]. Person 2: [...]. Person 3: [...]. Each message should be warm and specific, mention why I'm contacting them in particular, ask for a 15-minute chat or one piece of advice, and make it easy to say no. No flattery, no asking for a job directly. Then write a short follow-up for anyone who doesn't reply within 2 weeks."},{"h":"Personalise and send","b":"Edit each message so it sounds like you, then send through LinkedIn or email."},{"h":"Prepare for the chat","b":"If someone says yes, ask the AI for 5 good questions to ask about their role and how they got into it."}],"example":"Hi Jen, it's been ages since our days on the Riverside reception desk! I saw you're now a project coordinator at a housing charity. I'm thinking about a similar move and would love 15 minutes to hear how you made the jump. Completely understand if you're too busy.","tips":["Most people are glad to help when the ask is small and specific.","Always thank people afterwards and let them know what you did with their advice."],"auto":{"trigger":{"type":"manual","detail":"User lists people to contact"},"actions":[{"type":"ai.generate","detail":"Draft personalised outreach messages"},{"type":"sheet.append","detail":"Log who was contacted and when"},{"type":"calendar.create","detail":"Add a two-week follow-up reminder"}]}},{"id":"turn-a-messy-brain-dump-into-a-clear-to-do-list","t":"Turn a messy brain dump into a clear to-do list","d":"Everything swirling in your head, typed or spoken in one go, sorted into a prioritised list with quick wins and things you can drop.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Reminders app"],"when":"When you feel overwhelmed","steps":[{"h":"Get it all out","b":"Type or speak everything on your mind into your AI assistant, in any order. Half-sentences are fine."},{"h":"Ask it to sort","b":"Follow your brain dump with this prompt.","p":"That was everything on my mind. Turn it into an organised to-do list. Group tasks into: Today, This week, Later, and Could drop or delegate. Mark anything that takes under 5 minutes as a quick win. For bigger tasks, break them into the first small step only. Point out anything that has a deadline. Keep wording short so I can paste it into my reminders app. Then ask me if any priorities are wrong."},{"h":"Correct the priorities","b":"Tell the AI if anything is in the wrong group. You know your life best."},{"h":"Move tasks into your reminders","b":"Copy the Today and This week items into your phone's Reminders app or to-do list, with dates for anything time-sensitive."}],"example":"Today: Reply to Sam about Saturday (quick win). Book MOT (quick win, due 30 Nov). This week: Sort school trip money. Start tax return: first step, find last year's login. Later: Clear out garage. Could drop: Re-organising the spice rack.","tips":["Do two quick wins straight away. It makes the rest feel lighter.","Voice mode is great for brain dumps when you're walking or driving (hands-free only)."],"auto":{"trigger":{"type":"manual","detail":"User records or types a brain dump"},"actions":[{"type":"ai.classify","detail":"Sort tasks into Today, This week, Later and Drop"},{"type":"list.add","detail":"Add today's and this week's tasks to reminders"},{"type":"notify","detail":"Show quick wins to do now"}]}},{"id":"turn-a-rambling-draft-into-a-short-clear-email","t":"Turn a rambling draft into a short, clear email","d":"Paste a messy draft and get back a tidy email with the main point first, short paragraphs and one clear ask.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"Before sending anything long or important","steps":[{"h":"Write it badly first","b":"Type everything you want to say without worrying about order or wording. Bullet points are fine."},{"h":"Ask AI to tighten it","b":"Paste your draft with this prompt.","p":"Rewrite my draft email so it's clear and quick to read. Rules: put the main point or request in the first two sentences; keep it under [150] words; use short paragraphs; keep every fact, date and number exactly as I wrote them; don't add anything new; match a [friendly / formal] tone. Suggest a subject line under 8 words. Then list any part of my draft that was unclear so I can fix it. Draft: [paste draft]"},{"h":"Check facts and send","b":"Read the new version against your notes to make sure nothing important was dropped, then send."}],"example":"Subject: Need your sign-off on the new rota by Friday. Hi team, I need everyone's sign-off on the December rota by Friday 28 Nov. The main change is late shifts now finish at 9pm, not 10pm. Please reply 'OK' or let me know which dates clash.","tips":["Ask for a version with bullet points if your reader is skimming on a phone."],"auto":{"trigger":{"type":"manual","detail":"User pastes a draft and asks for a rewrite"},"actions":[{"type":"ai.generate","detail":"Rewrite the draft with the main point first"},{"type":"email.draft","detail":"Replace the draft with the clearer version"}]}},{"id":"write-a-meeting-agenda-people-will-actually-follow","t":"Write a meeting agenda people will actually follow","d":"Get a timed agenda with a clear purpose, the decisions needed and what to read beforehand, ready to paste into the invite.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"When you're sending a meeting invite","steps":[{"h":"List what needs covering","b":"Note the topics, how long the meeting is, and anything that must be decided by the end."},{"h":"Ask AI to shape it","b":"Paste this prompt into your AI assistant.","p":"Create an agenda for a [length]-minute meeting about [topic] with [who's attending]. Topics: [list]. Decisions we need by the end: [list]. Format: a one-line purpose at the top; then each item with minutes allowed, who leads it, and whether it's 'Inform', 'Discuss' or 'Decide'; finish with 5 minutes to confirm actions. Keep items in a sensible order, put decisions early, and tell me if there's too much for the time."},{"h":"Add it to the invite","b":"Paste the agenda into the invite description and attach or link any pre-reading."}],"example":"Purpose: Choose a date and format for the summer fete. 1. Budget update - 5 min - Ana - Inform. 2. Pick date (21 Jun or 28 Jun) - 10 min - Chair - Decide. 3. Stall ideas - 10 min - All - Discuss. 4. Volunteers needed - 5 min - Tom - Discuss. 5. Confirm actions - 5 min.","tips":["If the AI says it won't fit, cut an item or make it a written update rather than going over time."],"auto":{"trigger":{"type":"calendar_event","detail":"User creates a meeting with no description"},"actions":[{"type":"ai.generate","detail":"Draft a timed agenda from the topics"},{"type":"calendar.create","detail":"Add the agenda to the invite description"}]}},{"id":"turn-a-messy-brain-dump-into-a-prioritised-to-do-list","t":"Turn a messy brain dump into a prioritised to-do list","d":"Empty everything on your mind into one note and get back a short, ordered list of what to do today, this week and later.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"Whenever you feel overwhelmed","steps":[{"h":"Dump it all out","b":"Spend five minutes typing every task, worry and reminder into your notes app, in any order. Voice typing works well for this."},{"h":"Ask AI to sort it","b":"Paste the whole list into your AI assistant with this prompt.","p":"Here's everything on my mind: [paste brain dump]. Today is [day and date] and I have about [hours] free today. Turn this into: 1) Today: no more than 3 must-dos and 3 quick wins under 10 minutes. 2) This week: tasks with a rough day for each. 3) Later or someday. 4) Things to delegate or drop, with a suggestion of who or why. Rewrite each item so it starts with a verb and is specific. Ask me about anything that's too vague to act on."},{"h":"Answer any questions","b":"If it asks what you meant by something vague, reply and ask it to update the list."},{"h":"Move today's list somewhere visible","b":"Copy the Today section into your reminders app or onto a sticky note, and start with the first quick win."}],"example":"Today must-dos: Pay nursery invoice. Finish slides for Thursday. Call Mum about Christmas plans. Quick wins: Book dentist. Reply to Sara. This week: Return parcel (Wed). Later: Sort loft. Drop: Re-organising photo albums, not urgent this month.","tips":["Three must-dos is the limit for a reason; if you finish early, pull one more in."],"auto":{"trigger":{"type":"manual","detail":"User pastes a brain dump"},"actions":[{"type":"ai.classify","detail":"Sort items into today, this week, later and drop"},{"type":"list.add","detail":"Add today's tasks to the to-do list"}]}},{"id":"reply-calmly-to-an-angry-customer-in-minutes","t":"Reply calmly to an angry customer in minutes","d":"Paste in a heated complaint and get a warm, firm reply that acknowledges the problem, explains what happens next and keeps the customer.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Gmail"],"when":"Whenever a complaint makes your heart race","steps":[{"h":"Copy the complaint, minus personal details","b":"Copy the customer's message and replace their name, order number and address with placeholders like [Customer] before you paste it anywhere."},{"h":"Note the facts on your side","b":"Jot down in a line or two what actually happened and what you can offer, such as a refund, replacement or call back."},{"h":"Ask your AI assistant for a draft","b":"Open ChatGPT, Claude or Gemini and paste this prompt with the complaint and your notes.","p":"You are helping a small business reply to an upset customer. Here is their message: [paste complaint]. Here are the facts from our side: [what happened]. What we can offer: [refund / replacement / discount / call back]. Write a reply under 150 words that: 1) opens by acknowledging how they feel without grovelling, 2) takes responsibility for anything we got wrong, 3) explains clearly what we will do and by when, 4) ends with one easy next step for them. Tone: warm, calm, human, British English. Do not promise anything not listed in our offer. Then give me a shorter 2-sentence version for text or WhatsApp."},{"h":"Read it as the customer would","b":"Check every promise is something you can keep, add their name back in, and send it from your usual inbox."}],"example":"Hi [Customer], I'm really sorry your order arrived damaged, just before the weekend. That's not the standard we aim for. I've sent a replacement today by tracked delivery, so it should be with you by Thursday. If you'd prefer a full refund instead, just reply 'refund' and I'll sort it straight away.","tips":["If you are still annoyed, wait ten minutes before sending, even with a good draft.","Ask for two versions, one more formal and one more casual, and pick what fits your brand."],"auto":{"trigger":{"type":"new_email","detail":"An email arrives with words like complaint, refund or disappointed"},"actions":[{"type":"ai.classify","detail":"Rate how upset the customer is and what they are asking for"},{"type":"ai.generate","detail":"Draft a calm reply using the business's agreed offers"},{"type":"email.draft","detail":"Save the reply as a draft for the owner to check"}]}},{"id":"write-a-cold-email-that-people-actually-answer","t":"Write a cold email that people actually answer","d":"A short, personal first email to a potential client that leads with their problem, not your sales pitch, plus two subject lines to test.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail"],"when":"Before contacting a new prospect","steps":[{"h":"Find one real reason to write","b":"Look for something specific about the prospect: a new branch, a job advert, a post they wrote, or a review. That's your opening line."},{"h":"Ask for a draft","b":"Paste this prompt into your AI assistant.","p":"Write a cold email from me, [your name], [what you do], to [their job title] at [company]. Reason I'm writing: [the specific thing you noticed]. The problem I think they have: [problem]. Proof I can help: [one result for a similar client, no names]. Rules: under 110 words; first line about them, not me; one clear, low-effort ask such as a 15-minute call or 'shall I send an example?'; no buzzwords, no flattery, no fake urgency; British English; plain text. Give me 2 subject lines under 6 words each and one alternative opening line."},{"h":"Make it sound like you","b":"Read it out loud and change anything you wouldn't say in person. Add a line letting them know how to say no thanks."},{"h":"Send it from your own inbox","b":"Send it one at a time from Gmail or Outlook, not as a bulk blast, and note the date in your lead list."}],"example":"Subject: Your new Leeds showroom Hi Jess, congrats on the Leeds opening. New showrooms often get lots of browsers but slow quote requests. I helped a Sheffield kitchen fitter double their booked consultations in three months with a simple follow-up routine. Would a 15-minute call next week be useful? No worries if not.","tips":["Rules on business emails differ by country; in the UK and EU you need a fair reason to contact someone and an easy way to opt out.","Send fewer, better emails; ten researched ones beat a hundred generic ones."],"auto":{"trigger":{"type":"new_row","detail":"A new prospect is added to the lead list"},"actions":[{"type":"ai.generate","detail":"Write a personalised cold email from the prospect notes"},{"type":"email.draft","detail":"Save it as a draft for the user to check and send"},{"type":"sheet.update","detail":"Mark the prospect as 'Draft ready'"}]}},{"id":"write-a-clear-welcoming-job-advert","t":"Write a clear, welcoming job advert","d":"A job ad that explains the role honestly, uses inclusive language, lists only real must-haves and tells people exactly how to apply.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"Whenever you need to hire","steps":[{"h":"Note the facts about the role","b":"Write down the job title, hours, pay range, location or remote options, main tasks, and the 3 to 5 skills someone truly needs on day one."},{"h":"Ask AI to draft the advert","b":"Paste your notes into your AI assistant with this prompt.","p":"Write a job advert for a [job title] at [business], a [one-line description]. Facts: [paste notes]. Structure: a 2-line intro on why the role matters, What you'll do (5 bullets), What you'll need (only these must-haves: [list]), Nice to have (max 3), Pay and benefits, How to apply and the closing date. Use plain, inclusive British English: avoid gendered words, age-coded phrases like 'young and dynamic' or 'digital native', and unnecessary requirements like degrees unless essential. Add a line welcoming applicants from all backgrounds and offering adjustments for the application or interview. Keep it under 400 words."},{"h":"Check for bias and accuracy","b":"Ask the AI: 'List any words or requirements in this ad that might put off women, older people, disabled people or people from other backgrounds, and suggest alternatives.' Then read it yourself, as AI can miss things."},{"h":"Publish and save the final version","b":"Save the final ad in Google Docs so it's ready for next time, then post it on your chosen job boards and social channels."}],"example":"Café Team Member (part-time, 20 hours, £12.60 to £13.50/hour) What you'll do: make great coffee, keep the counter spotless, chat with regulars... What you'll need: friendly with customers, reliable on weekend shifts. No barista experience needed; we'll train you. Tell us if you need any adjustments to apply.","tips":["Always include the pay range; it saves everyone time and gets more applications.","Check local employment law, such as minimum wage and right-to-work rules, before you post."],"auto":{"trigger":{"type":"manual","detail":"Manager starts a new vacancy"},"actions":[{"type":"ai.generate","detail":"Draft an inclusive job advert from the role notes"},{"type":"ai.classify","detail":"Flag potentially biased words or unnecessary requirements"},{"type":"doc.create","detail":"Save the advert for the manager to review"}]}},{"id":"turn-one-idea-into-posts-for-every-platform","t":"Turn one idea into posts for every platform","d":"Write one rough idea and get a LinkedIn post, an Instagram caption, a Facebook post and a short video hook, each in the right style.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"Whenever you have something worth sharing","steps":[{"h":"Jot down the idea in plain words","b":"In your notes app, write two or three sentences about the news, tip or story. Don't polish it, just get the point down."},{"h":"Ask your AI assistant to adapt it","b":"Open ChatGPT, Claude or Gemini and paste this prompt with your idea.","p":"I run [type of business] for [audience]. Here is a rough idea I want to share: [your idea]. Turn it into: 1) a LinkedIn post (120-180 words, a strong first line, short paragraphs, end with a question); 2) an Instagram caption (under 100 words, friendly, 5 relevant hashtags at the end); 3) a Facebook post (conversational, under 80 words, with a clear call to action: [what you want people to do]); 4) three opening lines for a 30-second video. Use British English, no hype words, and keep the facts exactly as I gave them."},{"h":"Make it sound like you","b":"Read each version aloud and change anything you wouldn't say. Ask the assistant to 'make it more casual' or 'shorter' if a version feels off."},{"h":"Post or schedule each one","b":"Copy each version into its app. Most platforms let you schedule a post for later if you'd rather spread them across the week."}],"example":"LinkedIn: 'Most of our customers ask the same question in their first week...' Instagram: 'The one thing we wish every new customer knew...' +#smallbusiness #tips. Facebook: 'Quick tip from the team: ... Pop in on Saturday and we'll show you.' Video hooks: 'Stop doing this in week one.'","tips":["Save the prompt in your notes app with your business details filled in, so next time you only paste the idea.","Check any facts, prices or dates before posting; the assistant can quietly change them."],"auto":{"trigger":{"type":"manual","detail":"User submits a rough idea"},"actions":[{"type":"ai.generate","detail":"Write platform-specific versions of the idea"},{"type":"doc.create","detail":"Save all versions in one note for review"},{"type":"notify","detail":"Tell the user the drafts are ready to check"}]}},{"id":"teach-your-ai-assistant-to-write-like-you","t":"Teach your AI assistant to write like you","d":"A personal style guide built from your own writing that you can reuse so every draft sounds like you, not like a robot.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Notes app"],"when":"Set up once, update every few months","steps":[{"h":"Gather three samples","b":"Pick three pieces you've written and like: an email, a post and something longer. Remove other people's names and private details."},{"h":"Ask it to describe your style","b":"Paste the samples into your AI assistant with this prompt.","p":"Here are three samples of my writing: [paste samples]. Analyse my style and write a voice guide I can reuse. Include: 1) tone in 5 words; 2) typical sentence length and rhythm; 3) words and phrases I use often; 4) words I never seem to use; 5) how I open and close pieces; 6) how I use humour, questions or lists; 7) 5 do's and 5 don'ts. Then rewrite this paragraph in my voice to test it: [a generic paragraph]."},{"h":"Save the guide where you'll reuse it","b":"Copy the guide into your notes app. In ChatGPT you can paste it into custom instructions, in Claude into a project's instructions, or in Gemini into a Gem, so it's applied automatically."},{"h":"Correct it as you go","b":"When a draft sounds wrong, tell the assistant what you'd change and ask it to update the guide."}],"example":"Tone: warm, direct, a bit dry, practical, unhurried. Short sentences, often one-line paragraphs. Often uses 'honestly', 'here's the thing'. Never uses 'leverage' or exclamation marks. Opens with a small story; closes with one clear next step.","tips":["If you use AI at work, check your company's policy before pasting work documents as samples."],"auto":{"trigger":{"type":"manual","detail":"User uploads writing samples"},"actions":[{"type":"ai.extract","detail":"Identify tone, vocabulary and structure"},{"type":"ai.generate","detail":"Write a reusable voice guide"},{"type":"doc.create","detail":"Save the guide for future drafts"}]}},{"id":"write-captions-and-alt-text-for-your-photos","t":"Write captions and alt text for your photos","d":"Upload photos and get a ready caption plus accessible alt text for each, so your posts and website work for everyone.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Instagram"],"when":"Before posting photos","steps":[{"h":"Attach your photos","b":"Open your AI assistant and attach up to a handful of photos at once."},{"h":"Ask for both captions and alt text","b":"Paste this prompt alongside the photos.","p":"For each attached photo, write: 1) alt text under 125 characters that plainly describes what's in it for someone who can't see it (no 'image of', include any visible text); 2) a social caption for [platform] in the voice of [business/you], 30-60 words, with context the photo doesn't show: [details like event, date, place]. Number them to match the photo order. Don't guess people's names or identities."},{"h":"Add them when posting","b":"Paste the caption as usual. On Instagram, alt text is found under the advanced settings when posting, or by editing a post; on websites, it's the image description field."}],"example":"Photo 1 alt text: 'Three volunteers in green aprons sorting tins at a long table in a church hall.' Caption: 'Saturday's food bank sort was our busiest yet: 240 parcels packed in three hours. Thank you to everyone who came along.'","tips":["Get permission from people in your photos before posting, and take extra care with children."],"auto":{"trigger":{"type":"new_file","detail":"Photos added to the To post folder"},"actions":[{"type":"ai.generate","detail":"Write alt text and a caption for each photo"},{"type":"doc.create","detail":"Save captions in posting order"},{"type":"notify","detail":"Tell the user they're ready"}]}},{"id":"fact-check-a-viral-claim-before-you-share-it","t":"Fact-check a viral claim before you share it","d":"Paste a post, headline or forwarded message and get a clear breakdown of what's true, what's misleading and where to check it yourself.","cat":"Research & News","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","WhatsApp"],"when":"Before you forward or repost something surprising","steps":[{"h":"Copy the claim exactly","b":"Copy the text of the post or message, or take a screenshot. Note where you saw it and when."},{"h":"Ask for a source-backed check","b":"Use an AI assistant with web search turned on and paste this prompt.","p":"Fact-check the claim below. Search for reliable sources. Tell me: 1) the specific claims being made, listed separately, 2) for each one: true, false, misleading, or can't tell, 3) the evidence for your verdict with links to the original sources (official bodies, established fact-checkers, the original study), 4) whether this appears to be old news being reshared, 5) what I could say if I want to reply politely. If you can't find good evidence, say so plainly. Claim: [paste text or attach screenshot] Where I saw it: [app / site, date]"},{"h":"Open the sources yourself","b":"Click at least two of the links and check they say what the AI says. AI can be confidently wrong, especially about very recent events."},{"h":"Decide whether to share","b":"If it's false or you can't tell, don't forward it. If you reply, keep it kind and include a link."}],"example":"Claim 1: 'Supermarkets will stop accepting cash in January' - False. No announcement found; the trade body says cash remains accepted (link). Claim 2: the photo is from 2019 in another country (link). Suggested reply: 'I checked and couldn't find any source for this - here's what I found.'","tips":["For photos, try a reverse image search (Google Lens can do this) to find where the picture first appeared."],"auto":{"trigger":{"type":"message_received","detail":"User forwards a claim to check"},"actions":[{"type":"ai.extract","detail":"Split the message into individual claims"},{"type":"web.fetch","detail":"Search reliable sources for each claim"},{"type":"ai.classify","detail":"Rate each claim true, false, misleading or unclear"},{"type":"message.send","detail":"Reply with verdicts and source links"}]}},{"id":"get-the-right-spreadsheet-formula-by-describing-it","t":"Get the right spreadsheet formula by describing it","d":"Describe what you want in everyday words and get a working Excel or Google Sheets formula, explained so you understand what it does.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant","Excel","Google Sheets"],"when":"Whenever you're stuck on a formula","steps":[{"h":"Note where your data is","b":"Write down which columns hold what, and which row your data starts on. For example: 'Names in A, amounts in C, from row 2'."},{"h":"Describe what you want","b":"Paste this prompt into your AI assistant.","p":"I'm using [Excel / Google Sheets]. My data: [column letters and what's in each], starting on row [2]. I want a formula in cell [cell] that [describe the result, e.g. adds up column C only where column B says 'Paid' and the date in column D is this month]. Give me: the formula, a plain-English explanation of each part, and what to change if my data grows. Also tell me one common mistake to avoid."},{"h":"Test it on a few rows","b":"Paste the formula in and check the result against a few rows you can work out in your head. If it errors, copy the error message back to the assistant."}],"example":"=SUMIFS(C:C, B:B, \"Paid\", D:D, \">=\"&EOMONTH(TODAY(),-1)+1, D:D, \"<=\"&EOMONTH(TODAY(),0)) It adds column C where B is 'Paid' and the date in D falls in the current month. Mistake to avoid: dates stored as text won't be counted.","tips":["It works the other way round too: paste a formula you inherited and ask what it does."],"auto":{"trigger":{"type":"manual","detail":"User describes the result they want"},"actions":[{"type":"ai.generate","detail":"Write the formula with a plain-English explanation"},{"type":"notify","detail":"Send the formula and testing tip"}]}},{"id":"chase-overdue-invoices-politely-and-get-paid","t":"Chase overdue invoices politely and get paid","d":"Get a friendly, firm series of payment reminders for overdue invoices, from a gentle nudge to a final notice, ready to send.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail","Outlook"],"when":"When an invoice is a few days overdue","steps":[{"h":"Gather the invoice facts","b":"Note the invoice number, amount, date sent, due date and how the customer can pay."},{"h":"Draft a set of reminders","b":"Paste this prompt into your AI assistant.","p":"Write 3 payment reminder emails for an overdue invoice. Details: customer [first name / company], invoice [number] for [amount], due on [date], payment by [bank transfer / card link]. Email 1 (a few days late): friendly, assumes it's an oversight. Email 2 (2 weeks late): polite but firmer, asks for a payment date. Email 3 (4 weeks late): clear final reminder that explains the next steps I've chosen: [e.g. pausing further work]. Each email: a clear subject line, under 120 words, invoice details repeated, no threats or legal claims."},{"h":"Save them as templates","b":"Save each email as a template: Gmail has Templates you can switch on in its settings, and Outlook has My Templates. Then you can reuse them in a couple of clicks."},{"h":"Note when you sent each one","b":"Add a note to your invoice list each time you send a reminder, so you know which one comes next."}],"example":"Subject: Quick reminder - invoice 2087 (£640). Hi Tom, I hope all's well. Just a nudge that invoice 2087 for £640 was due on 31 Oct. It may have slipped through - you can pay by bank transfer using the details on the invoice. Thanks, Jo","tips":["Before you mention late payment interest or legal steps, check the rules with your accountant or solicitor, as they vary by country."],"auto":{"trigger":{"type":"schedule","detail":"Daily check for invoices past their due date"},"actions":[{"type":"ai.classify","detail":"Work out which reminder stage each invoice is at"},{"type":"email.draft","detail":"Draft the right reminder for each overdue invoice"},{"type":"notify","detail":"Ask the user to review and send"}]}},{"id":"scale-any-recipe-to-the-number-you-re-feeding","t":"Scale any recipe to the number you're feeding","d":"Resize a recipe for more or fewer people, convert cups to grams and get adjusted cooking times in one go.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":3,"tools":["AI assistant"],"when":"When a recipe serves the wrong number of people","steps":[{"h":"Copy the recipe","b":"Copy the ingredients and method from the website or book, or take a photo of the page."},{"h":"Ask it to scale and convert","b":"Paste the recipe into your AI assistant with this prompt.","p":"Here is a recipe that serves [original servings]: [paste recipe]. Rewrite it to serve [new servings]. Convert all measurements to [metric: grams and ml / UK spoons]. Round to sensible amounts (for example whole eggs). Tell me which tin or dish size to use, whether the cooking time or temperature should change, and flag anything that doesn't scale neatly, like baking powder or spices."},{"h":"Save your version","b":"Paste the scaled recipe into your notes app with the date, so you can tweak it next time."}],"example":"Lasagne for 10 (was 4): beef mince 1.25kg, chopped tomatoes 5 x 400g tins, lasagne sheets about 500g... Use 2 large dishes rather than one deep one. Bake 45-50 mins at 180C fan. Note: increase salt gradually and taste as you go.","tips":["For baking, scaling isn't always exact, so try a test batch before a big occasion."],"auto":{"trigger":{"type":"manual","detail":"User pastes a recipe and the number of servings"},"actions":[{"type":"ai.generate","detail":"Scale quantities, convert units and adjust times"},{"type":"doc.create","detail":"Save the scaled recipe to the user's recipe notes"}]}},{"id":"pack-the-right-things-for-this-trip-s-weather","t":"Pack the right things for this trip's weather","d":"Get a packing list tailored to your destination, activities, luggage allowance and who's travelling.","cat":"Travel","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"About a week before you leave","steps":[{"h":"Check the forecast and allowance","b":"Look up the weather forecast for your destination and your airline's baggage allowance on their official site."},{"h":"Ask for a tailored list","b":"Paste this prompt into your AI assistant.","p":"Make a packing list for [number] nights in [destination] in [month]. Expected weather: [forecast]. Travellers: [adults, children's ages]. Activities: [e.g. beach, hiking, one smart dinner]. Luggage: [e.g. cabin bag only, 10kg]. Laundry available: [yes/no]. Group the list by person and category (clothes, toiletries, documents, tech, health, kids' stuff), give quantities, and suggest outfits that mix and match. Flag liquids rules for hand luggage to check on the airport's site."},{"h":"Save it as a checklist","b":"Paste the list into your notes app as a checklist and tick items off as you pack. Keep it for next time."}],"example":"Each adult: 4 tops, 2 shorts, 1 trousers, light rain jacket, swimwear x2. Documents: passports, insurance details, booking printouts. Kids: 2 changes in hand luggage, sun hats, travel games. Tech: adapter (type F), power bank in hand luggage.","tips":["Liquid and battery rules differ by airport and airline, so check their official sites before packing hand luggage."],"auto":{"trigger":{"type":"schedule","detail":"7 days before a trip's start date"},"actions":[{"type":"web.fetch","detail":"Get the forecast for the destination"},{"type":"ai.generate","detail":"Create a packing list for the travellers and weather"},{"type":"list.add","detail":"Save the list as a checklist"}]}},{"id":"beat-desk-stiffness-with-short-movement-breaks","t":"Beat desk stiffness with short movement breaks","d":"Get a set of two-minute stretches you can do at your desk, with gentle reminders through the working day.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Reminders app"],"when":"During long days at a desk","steps":[{"h":"Ask for a stretch routine","b":"Paste this prompt into your AI assistant.","p":"I sit at a desk for about [hours] a day and feel stiff in my [neck/shoulders/back/hips]. Create 4 different 2-minute movement breaks I can do at my desk or next to it, in work clothes, without getting sweaty. For each: 3-4 moves with simple instructions, how long to hold or repeat, and an easier option. Tell me to stop any move that causes pain."},{"h":"Set reminders","b":"Create repeating reminders every 60 to 90 minutes during work hours on your phone or computer, each named after one of the routines."},{"h":"Pair it with a habit","b":"Link a break to something you already do, like after every video call or each time you refill your water."}],"example":"Break 1 - Neck & shoulders: shoulder rolls x10 back, x10 forward. Slow chin tucks x8. Ear-to-shoulder hold 15 sec each side. Doorway chest stretch 20 sec. Easier: do it all seated.","tips":["If pain persists or you have numbness or tingling, see your GP or a physiotherapist."],"auto":{"trigger":{"type":"schedule","detail":"Every 90 minutes between 9am and 5pm on weekdays"},"actions":[{"type":"notify","detail":"Send the next 2-minute movement break"}]}},{"id":"make-sense-of-a-confusing-bill-or-letter","t":"Make sense of a confusing bill or letter","d":"A plain-English summary of any bill, bank letter or official money letter, what it's asking of you, the deadline and a suggested reply.","cat":"Money","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"When a letter or bill doesn't make sense","steps":[{"h":"Photograph the letter","b":"Take a clear photo of each page, or copy the text if it came by email."},{"h":"Hide personal details","b":"Cover account numbers, reference numbers, your address and date of birth before sharing."},{"h":"Ask what it means","b":"Attach the photos to your AI assistant and use this prompt.","p":"Explain this letter in plain English. Tell me: 1) who it's from and what it's about, 2) what they are asking me to do, 3) any deadline, 4) how much money is involved and why, 5) what happens if I do nothing, and 6) anything that looks unusual or worth questioning. If it might be a scam, say what signs to check. Then draft a short, polite reply or list of questions I could send. Don't give legal or financial advice."},{"h":"Decide and act","b":"Use the summary to decide your next step. For anything with serious consequences, such as debt collection or tax demands, speak to the organisation directly or a free advice service."}],"example":"From: your energy supplier. About: your annual statement. Ask: nothing, your direct debit rises from £85 to £97 from January because you used more than estimated. Deadline: none, but you can query it within 28 days. Worth asking: was this based on a real meter reading?","tips":["If a letter asks you to pay urgently by an unusual method, contact the company using the number on their official website, not the one in the letter.","For debt or legal letters, a free advice charity can help you respond."],"auto":{"trigger":{"type":"manual","detail":"User shares a photo of a letter"},"actions":[{"type":"ai.summarize","detail":"Explain the letter, the ask and the deadline"},{"type":"calendar.create","detail":"Add a reminder for any deadline"},{"type":"email.draft","detail":"Draft a reply or list of questions"}]}},{"id":"turn-your-notes-into-a-practice-quiz","t":"Turn your notes into a practice quiz","d":"Paste or photograph your notes and get a ten-question quiz with answers, so you can test yourself instead of just re-reading.","cat":"Learning","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"After each study session","steps":[{"h":"Gather your notes","b":"Copy your typed notes, or take clear photos of handwritten pages or textbook sections."},{"h":"Ask for a quiz","b":"Open your AI assistant, add the notes and paste this prompt.","p":"Using only the notes below, write a 10-question quiz to help me revise [topic] for [exam or level]. Mix the types: 4 multiple choice, 3 short answer, 2 'explain in your own words' and 1 question that applies the idea to a new example. Don't show the answers yet. Ask me the questions one at a time, wait for my answer, then tell me if I'm right, explain briefly, and move on. At the end, list the topics I got wrong. [paste notes]"},{"h":"Answer honestly","b":"Type your answers without looking at your notes. Getting things wrong now is how your memory improves."},{"h":"Save the weak spots","b":"Copy the list of topics you got wrong into your notes app and start your next session with them."}],"example":"Q3 (short answer): What is the role of chlorophyll in photosynthesis? You said: 'it makes the plant green'. Partly right: it absorbs light energy, mostly red and blue, which powers the reaction. Weak spots today: limiting factors, the word equation.","tips":["Ask it to stick to your notes so it doesn't test you on things your course doesn't cover.","Check any surprising answer against your textbook, as AI can occasionally get facts wrong."],"auto":{"trigger":{"type":"new_file","detail":"New notes are saved to the Revision folder"},"actions":[{"type":"ai.generate","detail":"Write a 10-question quiz from the notes"},{"type":"doc.create","detail":"Save the quiz and answer key"},{"type":"notify","detail":"Remind the user to take the quiz the next day"}]}},{"id":"tailor-your-cv-to-a-job-ad-in-minutes","t":"Tailor your CV to a job ad in minutes","d":"A version of your CV that highlights your real experience most relevant to a specific job, plus a list of gaps to address honestly.","cat":"Careers","side":"life","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"Before every application","steps":[{"h":"Copy the job ad and your CV","b":"Copy the full job description and your current CV text. Remove your phone number, address and email first."},{"h":"Ask for tailoring suggestions","b":"Paste both into your AI assistant with this prompt.","p":"Here is a job ad and my CV. Help me tailor my CV for this role using only experience, skills and results that are already in my CV. Do not invent or exaggerate anything. Give me: 1) the 6 to 8 most important requirements in the ad, 2) for each one, which part of my CV best shows it, or 'not shown' if it isn't there, 3) a rewritten 3-line profile at the top, 4) reworded bullet points for my two most relevant roles that use the ad's language where it genuinely fits, and 5) questions about any real experience I might have left out. JOB AD: [paste] MY CV: [paste]"},{"h":"Answer the gap questions","b":"If the AI asks about experience you do have but didn't include, add it in your own words. If you don't have it, leave it out and consider mentioning how you'd learn it in your cover letter."},{"h":"Save a copy per job","b":"Make a copy of your CV document named after the job and company, and paste in the changes you agree with."}],"example":"Requirement: 'managing stakeholder expectations' - shown in your Retail Supervisor role (weekly updates to area manager). Rewritten bullet: 'Kept area manager and 12-person team updated weekly on targets, cutting missed deliveries by a third.' Not shown: Excel pivot tables.","tips":["Never add skills, jobs or qualifications you don't have. Employers check, and it can cost you the job later.","Recruiters often skim for the exact words in the ad, so use them where they truly describe what you did."],"auto":{"trigger":{"type":"manual","detail":"User pastes a job ad"},"actions":[{"type":"ai.extract","detail":"Pull out the key requirements from the ad"},{"type":"ai.generate","detail":"Match requirements to existing CV content and suggest wording"},{"type":"doc.create","detail":"Save a tailored CV copy for this role"}]}},{"id":"find-thoughtful-gift-ideas-for-anyone","t":"Find thoughtful gift ideas for anyone","d":"A shortlist of personal, in-budget gift ideas for someone tricky to buy for, based on what they actually enjoy.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"A couple of weeks before a birthday or celebration","steps":[{"h":"Describe the person","b":"Write a few lines about them: age range, hobbies, what they talk about, things they already have, and anything they've mentioned wanting."},{"h":"Ask for ideas","b":"Paste your notes into your AI assistant with this prompt.","p":"Help me find a gift for my [relationship, for example dad] for [occasion]. Budget: [amount]. About them: [notes]. They already have: [list]. Give me 10 ideas across different types: 3 physical gifts, 3 experiences, 2 handmade or personal ideas, and 2 that help with something they do often. For each, one line on why it suits them and a rough price. Avoid generic gifts like mugs and socks unless there's a personal twist. Then ask me 2 questions that could help narrow it down."},{"h":"Keep a gift ideas note","b":"Start a note called Gift ideas with a section per person. Add things they mention through the year, and paste them into the prompt next time."}],"example":"For Dad, 65, keen gardener, loves crosswords, £40: 1) Personalised plant markers with his allotment name (£15). 2) Half-day pruning workshop at a local garden (£35). 3) Book of cryptic crosswords plus a nice pen (£22). 4) Framed photo of his best marrow...","tips":["The best ideas come from things people say in passing, so jot them down when you hear them.","Check prices and availability yourself, as AI guesses at prices."],"auto":{"trigger":{"type":"calendar_event","detail":"A birthday is two weeks away"},"actions":[{"type":"notify","detail":"Remind the user about the upcoming birthday"},{"type":"ai.generate","detail":"Suggest gift ideas from the person's notes"},{"type":"list.add","detail":"Add the chosen gift to the shopping list"}]}},{"id":"check-if-a-suspicious-email-is-a-scam","t":"Check if a suspicious email is a scam","d":"Get a plain-English verdict on a worrying email, with the warning signs spelled out and what to do next.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant","Gmail","Outlook"],"when":"Whenever an email asks you to click, pay or log in","steps":[{"h":"Don't click anything","b":"Leave links and attachments alone. Copy the sender's full address (not just the display name), the subject and the text."},{"h":"Ask AI for a second opinion","b":"Paste the details with this prompt. Never paste passwords or codes.","p":"Help me check whether this email is likely to be a phishing scam. Sender address: [full address]. Subject: [subject]. Text: [paste text]. Link text shown (don't visit it): [paste if any]. Give me: 1) A verdict: likely scam, unclear, or likely genuine. 2) Each warning sign you can see, explained in plain English. 3) What I should do now. 4) How to check with the real organisation safely, without using any contact details in the email."},{"h":"Act on it safely","b":"If it looks like a scam, report it using the 'Report phishing' or 'Report' option in Gmail or Outlook, then delete it. If unsure, contact the organisation using a number or website you already know."}],"example":"Verdict: likely scam. Signs: sender is 'support@royalmaii-parcels.com' (misspelt), urgent 'pay £1.99 within 24 hours', generic greeting, link text doesn't match the company. Next: report as phishing, delete, and check any real parcel on the courier's own app.","tips":["AI can't see where a link really goes, so treat 'likely genuine' as a hint, not a guarantee.","At work, forward suspicious emails to your IT team as well."],"auto":{"trigger":{"type":"manual","detail":"User flags an email as suspicious"},"actions":[{"type":"ai.classify","detail":"Rate the email as likely scam, unclear or likely genuine"},{"type":"ai.generate","detail":"Explain the warning signs and safe next steps"},{"type":"notify","detail":"Show the verdict to the user"}]}},{"id":"find-a-meeting-time-that-works-across-time-zones","t":"Find a meeting time that works across time zones","d":"Get three sensible meeting slots for people in different countries, with each person's local time shown side by side.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"When you're arranging a call with people abroad","steps":[{"h":"Note who's where and when they're free","b":"List each person's city and the rough hours they're available, plus your own free times this week."},{"h":"Ask for the best slots","b":"Paste this prompt into your AI assistant.","p":"Find meeting times for a [length]-minute call between: [name - city - available hours, for each person]. Dates: [date range]. Avoid times before 8am or after 7pm local for anyone where possible. Suggest the 3 best slots and show a table with each person's local date and time. Flag if any slot falls on a public holiday or weekend in any of the countries, and note any clock changes in that period."},{"h":"Double-check and send","b":"Use Google Calendar's 'Find a time' or Outlook's Scheduling Assistant to confirm the slot is clear, then send the invite. The calendar shows it in each person's own time zone."}],"example":"Option 1: Tue 18 Nov - London 9:00, Toronto 4:00 (too early), Dubai 13:00. Option 2: Tue 18 Nov - London 14:00, Toronto 9:00, Dubai 18:00 (best). Option 3: Wed 19 Nov - London 15:00, Toronto 10:00, Dubai 19:00.","tips":["AI can get clock changes wrong, so check times against your calendar before sending.","Rotate awkward early or late slots fairly if you meet regularly."],"auto":{"trigger":{"type":"manual","detail":"User lists attendees, cities and availability"},"actions":[{"type":"ai.generate","detail":"Suggest 3 slots with local times for each person"},{"type":"calendar.create","detail":"Create the invite for the chosen slot"}]}},{"id":"plan-today-around-your-meetings-and-energy","t":"Plan today around your meetings and energy","d":"Get an hour-by-hour plan for today that fits your tasks into the gaps between meetings and puts hard work when you're sharpest.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"Every morning, or the evening before","steps":[{"h":"Copy today's commitments","b":"Note your meetings and fixed times (school run, appointments) and your task list for today."},{"h":"Ask for a time-blocked day","b":"Paste this prompt into your AI assistant.","p":"Plan my day. Fixed commitments: [list with times]. Tasks: [list with rough time estimates if you know them]. I start at [time] and finish at [time]. My sharpest time is [time of day]. Rules: put the hardest task in my sharpest slot; group small admin tasks together; add a 5-minute break after any 90 minutes of work and a proper lunch break; leave a 30-minute buffer in the afternoon. Show the plan as a simple timeline and tell me which tasks won't fit."},{"h":"Follow it loosely","b":"Keep the timeline open on your screen. If the day goes off-track, paste in what's changed and ask for a revised plan for the rest of the day."}],"example":"8:30 Admin batch: emails, invoices (30 min). 9:00 Deep work: write tender response. 10:30 Break. 10:45 Team call. 11:30 Tender response cont. 12:30 Lunch. 13:15 Calls: plumber, bank. 14:00 Client meeting. 15:30 Buffer. 16:00 Plan tomorrow. Won't fit: website update.","tips":["People usually underestimate tasks, so ask the AI to add 25% to any time estimates you give."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 8am"},"actions":[{"type":"web.fetch","detail":"Read today's calendar and task list"},{"type":"ai.generate","detail":"Create a time-blocked plan for the day"},{"type":"notify","detail":"Send the plan to the user"}]}},{"id":"solve-customer-problems-from-their-photos-and-screenshots","t":"Solve customer problems from their photos and screenshots","d":"Upload a customer's photo or screenshot and get a plain-English read of what's wrong plus a step-by-step reply to help them fix it.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"When a customer sends a picture instead of an explanation","steps":[{"h":"Check the image for private details","b":"Crop out or blur names, addresses, card numbers and faces before uploading. Most phones have a markup or crop tool in the photo editor."},{"h":"Upload it with some context","b":"Attach the image in ChatGPT, Claude or Gemini and paste this prompt.","p":"A customer sent this image with the message: [paste their message]. Our product/service: [what it is]. 1) Describe what you can see that's relevant to the problem. 2) Give the 2 or 3 most likely causes, most likely first. 3) Write a friendly reply with numbered steps they can follow to fix it, under 120 words, British English. 4) Tell me what to ask them if the steps don't work. If you can't tell from the image, say so rather than guessing."},{"h":"Sense-check against what you know","b":"You know your product best, so remove any step that doesn't apply before sending the reply."}],"example":"What I can see: the error 'Payment declined: address mismatch' on the checkout page. Likely cause: billing postcode differs from the card's. Reply: Hi Jo, thanks for the screenshot! 1) Check the billing postcode matches your card statement. 2) Try again. If it still fails, reply and we'll send a payment link.","tips":["Screenshots of error messages work best; ask customers for one when they say 'it won't work'.","Save good replies into your FAQ so you don't need AI next time."],"auto":{"trigger":{"type":"message_received","detail":"A customer message arrives with an image attached"},"actions":[{"type":"ai.extract","detail":"Read the error or problem shown in the image"},{"type":"ai.generate","detail":"Draft step-by-step fix instructions"},{"type":"notify","detail":"Show the draft for approval before replying"}]}},{"id":"ask-happy-clients-for-reviews-and-referrals","t":"Ask happy clients for reviews and referrals","d":"A warm thank-you message that asks for a review and an introduction at the right moment, with ready versions for email and WhatsApp.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail","WhatsApp"],"when":"When a client says they're pleased with your work","steps":[{"h":"Pick the right moment","b":"Ask straight after a win: a finished project, a great result or a kind message from them."},{"h":"Ask AI for the message","b":"Paste this prompt into your AI assistant.","p":"Write a thank-you message from me, [your name], to [client first name], whose [project] I just finished. Something specific they liked: [detail]. Ask, in a relaxed way, for: 1) a short Google review via this link [link], with 2 example prompts to make it easy (like 'what was it like working with me?'), and 2) whether they know one other [type of person/business] who might need help with [service]. Make it clear there's no pressure. Give an email version (under 120 words) and a WhatsApp version (under 50 words). British English, genuine, no sales language."},{"h":"Send it personally","b":"Send from your own email or WhatsApp, and thank them again when they leave a review or make an introduction."}],"example":"WhatsApp: Hi Sophie, thanks again for being so lovely to work with; I'm so glad the new bathroom feels calmer. If you have a minute, a quick Google review would help me loads: [link]. And if you know anyone else planning a refit, I'd be grateful for an intro. No pressure at all!","tips":["Never offer payment or gifts in exchange for reviews; review sites ban it.","Keep a list of who referred whom and send a handwritten thank-you card."],"auto":{"trigger":{"type":"new_row","detail":"A project is marked Complete in the tracker"},"actions":[{"type":"ai.generate","detail":"Write a personal thank-you with review and referral request"},{"type":"email.draft","detail":"Draft the email for the user to send"},{"type":"calendar.create","detail":"Set a reminder to thank them after they respond"}]}},{"id":"prepare-fair-structured-interview-questions","t":"Prepare fair, structured interview questions","d":"A set of the same questions for every candidate, linked to the job's criteria, with follow-up prompts and notes on what a strong answer includes.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"Before the first interview for a role","steps":[{"h":"Start from your criteria","b":"Use the same criteria as your job ad and scoring sheet, so interviews test the things that matter for the job."},{"h":"Ask AI for the question set","b":"Paste this prompt into your AI assistant.","p":"Write a structured interview plan for a [job title] at a [type of business]. Criteria: [list]. For each criterion: 1 main question asking for a real example ('Tell me about a time...'), 2 follow-up prompts, and 3 bullet points describing what a strong answer includes. Add 1 practical question or short task suited to the role. Avoid any questions about age, family plans, health, religion, nationality or other personal topics that aren't related to the job, and flag any of my criteria that might lead there. Finish with a 2-minute welcome script and a closing script explaining next steps and timescales. Total interview length: [30/45] minutes."},{"h":"Make an interview pack","b":"Paste it into Google Docs with space under each question for notes and a score, and use a fresh copy for each candidate."},{"h":"Offer adjustments","b":"When you invite candidates, ask whether they need any adjustments, such as extra time, a quiet room or questions in advance."}],"example":"Criterion: Working under pressure Q: Tell me about a time several things needed doing at once. What did you do? Follow-ups: How did you decide what came first? What would you do differently? Strong answer: prioritises clearly, keeps others informed, reflects on what they learned.","tips":["Ask every candidate the same main questions in the same order; it's fairer and makes comparing much easier.","Write notes on what they said, not your impressions of them."],"auto":{"trigger":{"type":"manual","detail":"Interviews are confirmed for a role"},"actions":[{"type":"ai.generate","detail":"Write structured questions and strong-answer guides per criterion"},{"type":"doc.create","detail":"Create an interview pack with scoring space"}]}},{"id":"get-a-plain-english-health-check-of-any-web-page","t":"Get a plain-English health check of any web page","d":"A friendly report on one page of your website: what's clear, what's confusing, and a short fix list to help it show up in search.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"When a page isn't getting visits or enquiries","steps":[{"h":"Copy the page's words","b":"Open the page, select all the text and copy it. Also note the page title shown in the browser tab and the main phrase you want it to be found for."},{"h":"Ask for a review","b":"Paste the text into your AI assistant with this prompt. Some assistants can read a link directly, but pasting the text is more reliable.","p":"Review this web page for a small business. Page title: [title]. Phrase I want it found for: [phrase]. Audience: [who it's for]. Page text: [paste]. Give me: 1) a score out of 10 for clarity and one for search-friendliness, with reasons; 2) whether the main phrase appears in the title, first paragraph and a heading; 3) the three biggest problems a visitor would notice; 4) a rewritten page title (under 60 characters) and meta description (under 155 characters); 5) a numbered fix list, easiest first. Plain English, no jargon."},{"h":"Make the easy fixes first","b":"Work through the fix list in your website editor. Most site builders let you change the page title and description in the page's settings or SEO section."}],"example":"Clarity 6/10: the first paragraph talks about your history, not what you do. Search 4/10: 'dog grooming Bristol' isn't in the title or headings. New title: Dog Grooming in Bristol | Gentle, Fear-Free Care. Fix 1: Move prices higher up the page.","tips":["Re-run it a month after making changes and compare scores.","Treat it as a second opinion, not a guarantee of rankings."],"auto":{"trigger":{"type":"manual","detail":"User gives a page address"},"actions":[{"type":"web.fetch","detail":"Read the page text and title"},{"type":"ai.generate","detail":"Write the plain-English review and fix list"},{"type":"doc.create","detail":"Save the report"}]}},{"id":"get-a-researched-brief-with-sources-on-any-topic","t":"Get a researched brief with sources on any topic","d":"A clear two-page brief on a subject you need to write about, with key facts, different viewpoints and links to check every claim.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"Before writing about something new to you","steps":[{"h":"Turn on web search","b":"Use an AI assistant that can search the web (ChatGPT, Claude and Gemini all can). Some also offer a deeper research mode for longer reports."},{"h":"Ask for a structured brief","b":"Paste this prompt and fill in your topic.","p":"Research [topic] for an article aimed at [audience] in [country]. Give me a brief with: 1) a 5-sentence plain-English summary; 2) 8-10 key facts or figures, each with the source name, date and link; 3) the main debates or different viewpoints; 4) common myths and what's actually true; 5) 5 questions readers are likely to ask; 6) gaps where reliable information is thin. Prefer official, academic and reputable news sources from the last [2] years. Say clearly if you're unsure."},{"h":"Check the sources","b":"Open each link and make sure it says what the brief claims. Delete anything you can't verify."},{"h":"Save it for writing","b":"Paste the checked brief into a Google Doc at the top of your draft so the facts are to hand."}],"example":"Summary: Heat pumps work in cold weather, but efficiency drops below -5C... Fact: average UK household install cost £X (source, date, link). Debate: whether older homes need full insulation first. Myth: 'They don't work in winter.' Gap: little data on terraced houses.","tips":["AI can invent sources that look real. Never quote a figure you haven't seen on the source page yourself."],"auto":{"trigger":{"type":"manual","detail":"User enters a topic and audience"},"actions":[{"type":"web.fetch","detail":"Search reputable sources on the topic"},{"type":"ai.summarize","detail":"Write a structured brief with linked sources"},{"type":"doc.create","detail":"Save the brief as a document"}]}},{"id":"understand-voice-messages-in-another-language","t":"Understand voice messages in another language","d":"A voice message in a language you don't speak becomes a clear English translation, plus a reply you can send back in their language.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":5,"tools":["WhatsApp","AI assistant"],"when":"When you get a voice note you can't understand","steps":[{"h":"Get the words as text","b":"WhatsApp can transcribe voice messages if you turn on transcripts in its settings (supported languages vary). Otherwise, play it near an AI assistant in voice mode, or forward the audio file to an assistant that accepts audio."},{"h":"Translate and draft a reply","b":"Paste the transcript into your AI assistant with this prompt.","p":"This is a transcript of a voice message I received, probably in [language, or 'unknown']: [paste]. 1) Tell me which language it is. 2) Translate it into English, keeping the tone. 3) Note anything ambiguous or culturally important. 4) Write a short, polite reply in that language saying: [what you want to say], and give me the English version so I know what I'm sending."},{"h":"Reply your way","b":"Send the reply as text, or read it aloud and record a voice note if you're confident."}],"example":"Language: Portuguese. Translation: 'Hi, it's Ana from the flat downstairs. The water's been dripping through my ceiling since this morning. Can you check your bathroom?' Reply: 'Olá Ana, desculpe! Vou verificar agora e falo consigo em 10 minutos.'","tips":["Voice messages are personal; avoid sharing ones with sensitive details, and for anything legal or medical, use a professional translator."],"auto":{"trigger":{"type":"message_received","detail":"Voice message in another language"},"actions":[{"type":"ai.extract","detail":"Transcribe and detect the language"},{"type":"ai.generate","detail":"Translate and draft a reply in the same language"},{"type":"notify","detail":"Show the translation and suggested reply"}]}},{"id":"understand-a-study-or-research-paper-in-plain-english","t":"Understand a study or research paper in plain English","d":"Upload a study and get a plain-language explanation of what was tested, what was found, how strong the evidence is and what it doesn't show.","cat":"Research & News","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant"],"when":"When a headline cites a study you want to understand","steps":[{"h":"Find the original paper","b":"Follow the link in the news article to the study itself. Many papers are free to read; download the PDF if you can."},{"h":"Upload it and ask for a plain explanation","b":"Attach the PDF to ChatGPT, Claude or Gemini and paste this prompt.","p":"Explain this research paper to a non-expert. Cover: 1) the question it asked, 2) who or what was studied and how many, 3) what they did, 4) the main findings in plain numbers, 5) how strong the evidence is (study type, size, limitations the authors mention), 6) what it does NOT show, 7) any funding or conflicts of interest declared. Quote the page or section for each point. If something isn't in the paper, say so."},{"h":"Compare with the headline","b":"Ask: 'Does this headline fairly describe the study? [paste headline]'. Then check one or two of the quoted sections yourself."}],"example":"Question: does a daily 20-minute walk improve sleep? Studied: 120 adults for 8 weeks. Finding: walkers fell asleep about 9 minutes faster on average. Strength: small, short study; sleep was self-reported (Limitations, p.11). Doesn't show: that walking cures insomnia.","tips":["For health studies, use this to understand the research, not to change treatment. Talk to your GP or pharmacist before acting on it."],"auto":{"trigger":{"type":"new_file","detail":"User uploads a research paper"},"actions":[{"type":"ai.extract","detail":"Pull out question, method, sample and findings"},{"type":"ai.summarize","detail":"Write a plain-English explanation with section references"},{"type":"notify","detail":"Send the explanation to the user"}]}},{"id":"shrink-a-long-report-into-a-one-page-brief","t":"Shrink a long report into a one-page brief","d":"Turn a 40-page report into a one-page brief with the main findings, key numbers, recommendations and what it means for you.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Word"],"when":"Whenever a long report lands on your desk","steps":[{"h":"Attach the report","b":"Upload the PDF or Word file to your AI assistant, or paste the text if it's short."},{"h":"Ask for a one-page brief","b":"Paste this prompt, telling it who the brief is for.","p":"Write a one-page brief of the attached report for [audience, e.g. my manager / our board / myself]. Use these headings: Purpose (1 sentence), Key findings (5 bullets with page numbers), Important numbers (a short table), Recommendations (as stated in the report), What this means for [our team / my situation] (3 bullets, clearly marked as your interpretation), Questions to ask. Keep it under 400 words."},{"h":"Check the numbers","b":"Go to the page numbers given and confirm every figure in the table. Numbers are where summaries most often go wrong."},{"h":"Paste into Word or Docs","b":"Copy the brief into a document, add the report's title and date at the top, and share it."}],"example":"Purpose: annual review of the town's bus services. Key findings: passenger numbers up 6% (p.4); route 12 runs at a loss (p.18)... Numbers: Journeys 2.1m, +6%. Recommendation: trial on-demand buses in villages (p.31).","tips":["Ask 'what in this report would someone disagree with?' to spot weak points before a meeting."],"auto":{"trigger":{"type":"new_file","detail":"A report is added to a chosen folder"},"actions":[{"type":"ai.summarize","detail":"Write a one-page brief with page references"},{"type":"doc.create","detail":"Save the brief next to the report"},{"type":"notify","detail":"Tell the user the brief is ready"}]}},{"id":"understand-a-contract-in-plain-english-before-signing","t":"Understand a contract in plain English before signing","d":"Get a plain-English summary of a contract: what you're committing to, unusual clauses and questions to raise before you sign.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"Before you sign any supplier, lease or client agreement","steps":[{"h":"Remove sensitive details","b":"Make a copy of the contract and remove bank details or personal information that isn't needed to understand the terms."},{"h":"Ask for a plain-English breakdown","b":"Upload the contract to your AI assistant with this prompt.","p":"I'm a small business owner about to sign the attached [type of agreement] as the [customer / supplier / tenant]. In plain English, tell me: 1) what I'm agreeing to do and pay, 2) what the other side must do, 3) how long it lasts and how I can end it, including notice periods and fees, 4) automatic renewals, price rises or penalties, 5) who is liable if something goes wrong, 6) any clauses that seem unusual or one-sided, 7) 6 questions to ask before signing. Quote the clause number for each point. Don't tell me whether to sign."},{"h":"Check the key clauses yourself","b":"Read the clauses it quotes for notice, renewal, fees and liability in the actual contract."},{"h":"Get professional advice for anything important","b":"For high-value, long or unusual contracts, take the summary and your questions to a solicitor. AI can misread legal wording and doesn't know your full situation."}],"example":"You agree to: pay £89/month for 36 months (clause 3.1). Ending early: you pay the remaining months in full (clause 9.2). Auto-renewal: renews for 12 months unless you give 90 days' notice (clause 10). Unusual: they can raise prices yearly with no cap (clause 4.4). Ask: 'Can we cap annual increases?'","tips":["A solicitor should check anything you're unsure about. This helps you ask better questions; it isn't legal advice."],"auto":{"trigger":{"type":"new_file","detail":"A contract is uploaded for review"},"actions":[{"type":"ai.extract","detail":"Find obligations, term, renewal, fees and liability"},{"type":"ai.summarize","detail":"Write a plain-English summary with clause numbers"},{"type":"notify","detail":"Send the summary with a reminder to get legal advice"}]}},{"id":"work-out-what-s-wrong-with-a-struggling-plant","t":"Work out what's wrong with a struggling plant","d":"Photograph a sick-looking houseplant or garden plant and get likely causes and a simple care plan to try.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":3,"tools":["AI assistant","Phone camera"],"when":"When leaves go yellow, brown or spotty","steps":[{"h":"Take close and wide photos","b":"Photograph the whole plant, a close-up of the damaged leaves (top and underside) and the soil."},{"h":"Ask for likely causes","b":"Attach the photos to your AI assistant with this prompt.","p":"Please help me work out what's wrong with this plant. It's a [plant name if known] kept [indoors/outdoors] in [light conditions]. I water it [how often] and it's been like this for [time]. Recent changes: [repotting, moved, cold snap]. Give me the 3 most likely causes ranked by likelihood, what to look for to tell them apart, and a simple 2-week care plan for the most likely one. If you can't identify the plant, say so."},{"h":"Set a check-in reminder","b":"Add a reminder for two weeks' time to see if it's improving, and take a new photo to compare."}],"example":"Most likely: overwatering (yellow lower leaves, damp soil). Check: push a finger 3cm into the soil - if wet, wait. Plan: water only when top 3cm is dry, empty the saucer, move away from the radiator. Less likely: spider mites - look for fine webbing under leaves.","tips":["AI can misidentify plants, so if it might be toxic to pets or children, check with a garden centre or a reliable plant database."],"auto":{"trigger":{"type":"manual","detail":"User shares plant photos"},"actions":[{"type":"ai.generate","detail":"Suggest likely causes and a care plan"},{"type":"calendar.create","detail":"Add a 2-week check-in reminder"}]}},{"id":"learn-the-30-phrases-you-ll-actually-use-abroad","t":"Learn the 30 phrases you'll actually use abroad","d":"Get a one-page phrase sheet for your trip with simple pronunciation, polite phrases and the words you'll need most.","cat":"Travel","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"A week or two before you go","steps":[{"h":"Ask for a phrase sheet","b":"Paste this prompt into your AI assistant.","p":"I'm travelling to [country/region] where they speak [language]. I'll be [activities, e.g. eating out, using trains, shopping at markets]. Dietary needs: [e.g. vegetarian, nut allergy]. Give me the 30 most useful phrases in a table with: English, [language], simple pronunciation for an English speaker, and when to use it. Include greetings, please and thank you, asking for help, numbers 1-10, ordering food, my dietary needs, and 'I don't understand, please speak slowly'. Note any polite customs I should know."},{"h":"Practise out loud","b":"Ask the assistant to read the phrases aloud if your app has a voice mode, or quiz you on them for five minutes a day."},{"h":"Save it offline","b":"Save the sheet in your notes app or take a screenshot so you can use it without signal."}],"example":"Good morning - Bom dia - bong DEE-ah. A table for two, please - Uma mesa para dois, por favor - OO-ma MAY-za PA-ra doysh, poor fa-VOR. I'm allergic to nuts - Sou alergico a frutos secos... Custom: say 'obrigado' (men) or 'obrigada' (women).","tips":["For serious allergies, ask a native speaker or your doctor about a printed allergy card rather than relying on AI translation alone."],"auto":{"trigger":{"type":"schedule","detail":"14 days before a trip abroad"},"actions":[{"type":"ai.generate","detail":"Create a phrase sheet for the destination's language"},{"type":"notify","detail":"Send a daily 5-phrase practice reminder"}]}},{"id":"check-in-with-yourself-through-a-short-weekly-journal","t":"Check in with yourself through a short weekly journal","d":"Use a few gentle questions each week to notice your mood, what helped and what drained you, with a calm summary.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"Once a week, at a quiet moment","steps":[{"h":"Get your check-in questions","b":"Paste this prompt into your AI assistant to get a set of questions you'll reuse each week.","p":"Give me 6 gentle weekly reflection questions for a personal journal. Cover: mood this week from 1 to 10, what gave me energy, what drained me, one thing I'm proud of, how I looked after myself, and one small thing I'd like to do differently next week. Keep the wording warm and simple. After I answer, summarise my answers kindly in 3 sentences and suggest one small, realistic self-care action. Don't give medical or therapy advice."},{"h":"Answer in your notes app","b":"Copy the questions into a weekly note and write your answers there, adding the date."},{"h":"Notice patterns over time","b":"Every month or so, read back through your notes, or paste them into the assistant and ask what's changed."}],"example":"Week of 3 Nov - Mood: 6/10. Energy: Saturday walk with Jo, early night Tuesday. Drained: late emails. Proud: said no to an extra shift. Next week: no emails after 8pm. Summary: a steady week, with rest making a clear difference.","tips":["If you're struggling, feel low most days or think about harming yourself, talk to your GP or contact a local crisis line or emergency services straight away.","Your journal is private: keep it in a note only you can open."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 8pm"},"actions":[{"type":"notify","detail":"Send the weekly check-in questions"},{"type":"ai.summarize","detail":"Kindly summarise the answers and suggest one small action"}]}},{"id":"see-where-your-money-went-last-month","t":"See where your money went last month","d":"Paste a month of bank transactions and get a clear spending breakdown by category, with your three biggest leaks pointed out.","cat":"Money","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"At the start of each month","steps":[{"h":"Download last month's transactions","b":"In your banking app or website, look for an option to export or download transactions as a CSV or PDF. A screenshot of the list works too."},{"h":"Strip out private details","b":"Delete or cover account numbers, sort codes, card numbers and your address before you share anything. Merchant names and amounts are all the AI needs."},{"h":"Ask for a breakdown","b":"Open ChatGPT, Claude or Gemini, attach the file or paste the list, and use this prompt.","p":"Here are my bank transactions for [month]. Group every outgoing payment into categories such as Housing, Bills, Groceries, Eating out, Transport, Shopping, Subscriptions, Kids, Health and Other. Give me a table with each category, its total and its share of total spending. Then list my 10 largest single payments, flag any payments that look like repeat subscriptions, and point out the three areas where I could most easily spend less. Don't give investment or financial advice, just describe my spending."},{"h":"Check the categories","b":"Skim the table and tell the AI about anything it put in the wrong place, for example a supermarket shop that was really a birthday present."},{"h":"Keep a running record","b":"Copy the category totals into a simple sheet with one column per month so you can see trends over time."}],"example":"October total: £2,184. Housing £950 (43%), Groceries £412 (19%), Eating out £186 (9%), Transport £143 (7%), Subscriptions £67 (3%)... Easy wins: 11 coffee shop visits (£42), two food delivery apps, a gym membership with no visits since August.","tips":["Never paste full statements with account numbers, and remember the AI can misread amounts, so check the totals against your bank app.","Ask it to compare with last month's table if you paste both."],"auto":{"trigger":{"type":"schedule","detail":"First day of each month"},"actions":[{"type":"notify","detail":"Remind the user to export last month's transactions"},{"type":"ai.classify","detail":"Sort transactions into spending categories"},{"type":"sheet.append","detail":"Add category totals as a new month column"}]}},{"id":"help-your-child-with-homework-without-giving-the-answers","t":"Help your child with homework without giving the answers","d":"A patient AI tutor that asks your child guiding questions and gives hints, so they work it out themselves and actually learn.","cat":"Learning","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant"],"when":"When homework gets stuck","steps":[{"h":"Sit down together","b":"Use the AI alongside your child rather than leaving them alone with it, especially for younger children. Check the app's age rules too."},{"h":"Set it up as a tutor","b":"Start a new chat and paste this prompt before sharing the homework question.","p":"You are a patient, encouraging tutor for a [age]-year-old in [year or grade] working on [subject]. Never give the final answer. Instead: ask what they already know, break the problem into small steps, give one hint at a time, and ask them to try each step. If they're right, say why. If they're wrong, ask a question that helps them spot the mistake. Use simple language and examples from everyday life. When they've solved it, ask them to explain the method back in their own words. Here is the question: [paste or describe the homework]"},{"h":"Let your child type or talk","b":"Have your child answer the AI's questions themselves. Voice mode in the AI app can help younger children who type slowly."},{"h":"Check with the teacher's method","b":"Schools teach some methods in specific ways, such as long division. If the AI's approach differs, ask it to use the method from the worksheet."}],"example":"AI: What do you need to find out in this question? Child: How many sweets each person gets. AI: Great. How many sweets are there and how many people? Child: 24 and 4. AI: Which operation shares things out equally? ...","tips":["Don't share your child's full name, school or photos of their face.","If your child is getting frustrated, take a break. The goal is understanding, not finishing fast."],"auto":{"trigger":{"type":"manual","detail":"Parent starts a homework session"},"actions":[{"type":"ai.generate","detail":"Guide the child with questions and hints, no answers"},{"type":"ai.summarize","detail":"Note which steps the child found hard"},{"type":"notify","detail":"Share a short summary with the parent"}]}},{"id":"write-a-cover-letter-that-sounds-like-you","t":"Write a cover letter that sounds like you","d":"A short, specific cover letter built from your real experience and the job ad, written in your own voice rather than generic phrases.","cat":"Careers","side":"life","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"When an application asks for a cover letter","steps":[{"h":"Jot down why you want this job","b":"Write three honest sentences about why this role and organisation appeal to you. This is what makes a letter feel real."},{"h":"Draft the letter","b":"Paste the job ad, your CV and your notes into your AI assistant with this prompt.","p":"Write a cover letter for this job using only facts from my CV and notes. Do not invent experience or results. Keep it under 300 words, in a warm, plain, confident tone, avoiding cliches like 'I am writing to apply' or 'passionate team player'. Structure: an opening that says which role and one specific reason I'm interested, two short paragraphs each linking one requirement from the ad to a real example from my CV, and a short close. Here is a sample of how I write, so match my style: [paste a few sentences you've written]. JOB AD: [paste] MY CV: [paste] WHY I WANT IT: [paste notes]"},{"h":"Make it yours","b":"Read it aloud and change any sentence that doesn't sound like you. Check every claim is true."},{"h":"Save and reuse the good parts","b":"Keep your best paragraphs in a document so you can adapt them for similar roles."}],"example":"Dear Hiring Team, I'd love to join Greenleaf Housing as a Tenant Liaison Officer. I grew up in housing association homes and know how much a responsive officer matters. In my four years at a busy call centre, I resolved around 40 queries a day...","tips":["Hiring managers can often spot an obviously AI-written letter. Your own phrasing and a specific reason for applying make the difference.","Remove contact details when pasting your CV, then add them back to the final letter."],"auto":{"trigger":{"type":"manual","detail":"User starts an application"},"actions":[{"type":"ai.generate","detail":"Draft a cover letter from the CV, ad and notes"},{"type":"doc.create","detail":"Save the letter with the job name"},{"type":"sheet.update","detail":"Mark the application as letter drafted"}]}},{"id":"write-a-tricky-email-or-message-the-right-way","t":"Write a tricky email or message the right way","d":"A calm, clear draft for awkward messages like complaints, refund requests, saying no or chasing a tradesperson, in the tone you want.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Gmail"],"when":"When you're putting off a difficult message","steps":[{"h":"Write the facts","b":"Jot down what happened, dates, what you've already tried, and what outcome you want."},{"h":"Ask for a draft","b":"Paste your notes into your AI assistant with this prompt.","p":"Help me write a [complaint / refund request / polite no / chaser / apology] to [who, for example an online shop, my landlord, a friend]. What happened: [facts and dates]. What I want: [outcome]. Tone: [firm but polite / warm / formal]. Keep it under 200 words, stick to facts, avoid emotional language, and make the request and any deadline clear. Give me two versions: one shorter and one more detailed. Add a subject line if it's an email."},{"h":"Adjust and send","b":"Pick the version you like, adjust any wording that doesn't sound like you, and send it from your usual email or messaging app."},{"h":"Keep a record","b":"For complaints and refunds, keep a copy of what you sent and note the date in case you need to escalate."}],"example":"Subject: Refund request - order 4471 (faulty kettle) Hello, I bought a kettle from you on 2 November. It stopped working on 9 November. I'd like a full refund of £34.99. Please let me know how to return it. I'd appreciate a reply within 14 days. Thank you, Alex","tips":["Remove order numbers and personal details you don't want to share, then add them back to the final message.","For consumer rights questions, check your country's official consumer advice website."],"auto":{"trigger":{"type":"manual","detail":"User describes the situation"},"actions":[{"type":"ai.generate","detail":"Draft two versions of the message"},{"type":"email.draft","detail":"Save the chosen version as a draft"},{"type":"calendar.create","detail":"Add a follow-up reminder for the reply deadline"}]}},{"id":"read-and-reply-to-emails-in-another-language","t":"Read and reply to emails in another language","d":"Understand an email in any language and send back a natural-sounding reply, with a back-translation so you know what you said.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":3,"tools":["AI assistant","Gmail","Outlook"],"when":"When you get an email you can't fully read","steps":[{"h":"Get a quick translation","b":"Gmail can translate an email from the menu at the top of the message, and Outlook offers a Translate option too. Use these for a fast read."},{"h":"Write your reply in your own words","b":"Type what you want to say in English, as naturally as you would to anyone."},{"h":"Ask AI for a natural reply","b":"Paste the original email and your reply with this prompt.","p":"Here's an email in [language] and my reply in English. 1) Give me a short English summary of their email, noting anything polite or cultural I should respond to. 2) Translate my reply into natural [language] at a [formal / friendly] level suitable for [relationship], adjusting greetings and sign-offs to local custom. 3) Give a word-for-word back-translation into English so I can check the meaning. Their email: [paste] My reply: [paste]"},{"h":"Check names, dates and numbers","b":"Make sure dates, prices and names are exactly right in the translated version before sending."}],"example":"Summary: Lucía confirms the 12 March booking and asks if you need parking. Reply (Spanish): Hola Lucía, muchas gracias por confirmar la reserva del 12 de marzo. Sí, necesitaríamos una plaza de aparcamiento... Back-translation: Hello Lucía, thank you very much for confirming...","tips":["For contracts or anything legal, use a professional translator rather than relying on AI alone."],"auto":{"trigger":{"type":"new_email","detail":"An email arrives in a language other than the user's"},"actions":[{"type":"ai.summarize","detail":"Summarise the email in English"},{"type":"ai.generate","detail":"Translate the user's reply and back-translate it"},{"type":"email.draft","detail":"Save the translated reply as a draft"}]}},{"id":"decline-meetings-kindly-or-suggest-an-email-instead","t":"Decline meetings kindly or suggest an email instead","d":"Get polite, ready-to-send replies that decline a meeting, ask for an agenda first or offer a written update in its place.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"When an invite lands that you don't need to attend","steps":[{"h":"Decide what you need","b":"Work out whether you should decline, send someone else, join for part of it, or just get the notes."},{"h":"Get a set of replies","b":"Paste the invite details with this prompt.","p":"I've been invited to this meeting: [title, organiser, purpose]. I'd prefer to [decline / ask for an agenda / join for 15 minutes / send a written update instead] because [reason]. Write 3 short options (under 50 words each) I can put in the calendar decline note or an email. Polite, positive, not apologetic, and offer to help in another way where it makes sense."},{"h":"Respond in your calendar","b":"Choose 'No' or 'Maybe' on the invite and paste your note into the message box, or propose a new time if that's what you need."}],"example":"Option 2: Thanks for including me, Paul. I don't think I'm needed for the whole session, so I'll skip this one. Could you share the notes? If a decision needs my input, I'm happy to reply by email the same day.","tips":["Save your favourite reply as a template so declining takes ten seconds next time."],"auto":{"trigger":{"type":"calendar_event","detail":"A new meeting invite arrives"},"actions":[{"type":"ai.classify","detail":"Check if the invite has an agenda and needs the user"},{"type":"ai.generate","detail":"Draft a polite decline or alternative"},{"type":"notify","detail":"Show the suggested response to the user"}]}},{"id":"write-your-weekly-update-in-five-minutes","t":"Write your weekly update in five minutes","d":"Turn a few rough notes into a clear status update for your manager, team or client: progress, next steps and anything blocking you.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Slack","Microsoft Teams","Gmail"],"when":"Every Friday","steps":[{"h":"Jot down your week","b":"Write quick notes on what you did, what's next and anything stuck. Look through your sent emails and calendar for reminders."},{"h":"Turn it into an update","b":"Paste your notes with this prompt.","p":"Write a weekly update from my notes for [audience, e.g. my manager]. Format: 'Done this week' (3 to 5 bullets, each with the result, not just the activity), 'Next week' (3 bullets), 'Blockers or help needed' (each with what I need and from whom), and a one-line overall status: On track, At risk or Off track. Under 150 words. Keep the numbers and names exactly as I wrote them. Notes: [paste notes]"},{"h":"Send it the same way every week","b":"Post it in Slack, Teams or email at the same time each week so people know when to expect it."}],"example":"Status: On track. Done: Signed 2 new clients (Harbour Dental, Oak Lane Vets). Cut invoice backlog from 18 to 5. Next week: Launch winter newsletter. Hire temp for December. Blockers: Need sign-off on newsletter budget from Paula by Tue.","tips":["Keep a running note during the week and add one line each day; Friday's update then writes itself."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3pm"},"actions":[{"type":"ai.generate","detail":"Turn the week's notes into a structured update"},{"type":"message.send","detail":"Post the update to the chosen channel after review"}]}},{"id":"hand-over-a-customer-case-without-losing-anything","t":"Hand over a customer case without losing anything","d":"Turn a long, messy email or chat thread into a short handover note so a colleague can pick up the case without rereading everything.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Slack"],"when":"Before holidays, shift changes or passing a case on","steps":[{"h":"Copy the whole thread","b":"Open the email or chat thread and copy it all, oldest message first if possible. Replace bank details and passwords with [removed]."},{"h":"Ask for a handover note","b":"Paste the thread into your AI assistant with this prompt.","p":"Turn this customer support thread into a handover note for a colleague. Thread: [paste]. Use these headings: Customer and issue (2 lines), What's been tried, What we've promised and by when, Customer's mood and preferences, Open questions, Next step (one clear action). Keep it under 200 words. Quote any exact promise word-for-word. If dates or amounts conflict in the thread, flag them."},{"h":"Send it with a link","b":"Post the note in Slack, Teams or email to your colleague, along with a link to the original thread."}],"example":"Customer and issue: Amira, kitchen tap leaking after install on 2 June. Tried: washer replaced 9 June, still dripping. Promised: 'a plumber visit before Friday 16th'. Mood: patient but tired of chasing; prefers text. Open: is the tap under warranty? Next step: book plumber and text Amira a time today.","tips":["The 'promises' heading is the most valuable; broken promises are what turn a case into a complaint.","Keep handover notes in the same place each time, like a pinned Slack thread or shared doc."],"auto":{"trigger":{"type":"manual","detail":"Agent marks a case for handover"},"actions":[{"type":"ai.summarize","detail":"Summarise the thread into a structured handover note"},{"type":"message.send","detail":"Send the note to the colleague taking over"}]}},{"id":"follow-up-politely-when-prospects-go-quiet","t":"Follow up politely when prospects go quiet","d":"Three short, friendly follow-up emails, each adding something useful, scheduled to send on the right days from your own inbox.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Gmail"],"when":"When someone hasn't replied for a week","steps":[{"h":"Note where you left things","b":"Copy your last message to them and note what they were interested in. Remove anything confidential."},{"h":"Ask AI for a gentle sequence","b":"Paste this prompt into your AI assistant.","p":"I sent this to a prospect and got no reply: [paste last email]. They were interested in [topic]. Write 3 follow-up emails for days 5, 12 and 21. Each under 70 words, in British English, warm and not pushy. Email 1: friendly nudge plus one useful tip. Email 2: share a short example or result relevant to them. Email 3: a polite 'shall I close your file?' that makes it easy to say not now. No guilt-tripping, no 'just checking in'. Reply in the same thread so give no new subject lines."},{"h":"Schedule them","b":"In Gmail, reply in the same thread, paste the first follow-up, and use the arrow next to Send to choose Schedule send. Add calendar reminders for the next two, since you'll stop if they reply."},{"h":"Stop when they reply","b":"If they reply at any point, cancel the remaining reminders and answer them personally."}],"example":"Day 5: Hi Ben, a quick thought on the menu reprint: printing seasonal specials on a separate card often saves reprinting the whole menu. Happy to show a sample. Day 21: I don't want to fill your inbox, so shall I close this for now? If timing's better in spring, just say and I'll check back then.","tips":["Outlook also has a schedule send option under the Send button's arrow.","The third email often gets the most replies, because it's easy to answer."],"auto":{"trigger":{"type":"schedule","detail":"Daily check for prospects with no reply after 5 days"},"actions":[{"type":"ai.generate","detail":"Write the next follow-up in the sequence"},{"type":"email.draft","detail":"Place it as a reply draft in the same thread"},{"type":"notify","detail":"Remind the user to review and send"}]}},{"id":"send-a-warm-clear-job-offer","t":"Send a warm, clear job offer","d":"A friendly offer email and a checklist of what the formal offer letter must cover, so your new hire knows exactly what to expect.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Gmail","Word"],"when":"When you've chosen someone to hire","steps":[{"h":"Gather the offer details","b":"Note the job title, start date, pay, hours, place of work, probation period, holiday, and any conditions such as references or right-to-work checks."},{"h":"Draft the offer email","b":"Paste the details into your AI assistant with this prompt.","p":"Write a job offer email to [first name] for the role of [job title] at [business]. Details: [paste]. Tone: warm and excited but clear. Include: the offer and why we chose them (one genuine line: [reason]), key terms in a short bullet list, conditions of the offer, what happens next and by when, and a request to confirm acceptance by [date]. Under 200 words, British English. Then, separately, give me a checklist of what a written statement of employment terms usually needs to include in [country], so I can check my formal letter or contract covers it."},{"h":"Check the formal paperwork","b":"Use the checklist to review your contract or written statement. Have the contract template checked by an HR or employment law professional at least once."},{"h":"Call first, then send","b":"Ring the candidate with the good news, then send the email and formal letter straight after."}],"example":"Hi Tom, I'm delighted to offer you the role of Workshop Technician at Kestrel Bikes. Your mechanical know-how really stood out. Start: Mon 3 March. Pay: £27,500 a year. Hours: 37.5, Tue to Sat. Holiday: 28 days including bank holidays. Subject to two references. Please let me know by Friday 21st.","tips":["AI checklists are a starting point, not legal advice; employment rules vary by country.","Keep offer details consistent between the email and the contract to avoid confusion later."],"auto":{"trigger":{"type":"manual","detail":"Manager marks a candidate as Offer"},"actions":[{"type":"ai.generate","detail":"Draft the offer email and terms checklist"},{"type":"email.draft","detail":"Save the offer email for the manager to send after calling"},{"type":"calendar.create","detail":"Add a reminder for the acceptance deadline"}]}},{"id":"post-a-fresh-google-business-profile-update-every-week","t":"Post a fresh Google Business Profile update every week","d":"Short, local updates for your Google Business Profile that keep your listing active and tell nearby customers what's new.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera"],"when":"Every week","steps":[{"h":"Take one photo","b":"Snap a recent job, product, dish or your team at work. Real photos tend to do better than stock images."},{"h":"Write four updates at once","b":"Paste this into your AI assistant to get a month's worth.","p":"Write 4 Google Business Profile updates for [business] in [town]. What's happening this month: [news, offers, events, seasonal services]. Each update: 60-100 words, mentions the local area naturally, describes one specific thing (a job, offer or event), and ends with a clear action that matches a button: Call, Book, Learn more or Order online. Avoid phone numbers and links in the text. British English, friendly and plain."},{"h":"Post it on your profile","b":"Search your business name on Google or open the Google Business Profile app while signed in, choose to add an update, add the photo and text, and pick the matching button."}],"example":"'This week we fitted a new walk-in shower for a family in Headingley, swapping a tired bath for something far easier to use. If you're thinking about a bathroom refresh before spring, we're booking free home visits for February. Tap Book to choose a time.'","tips":["Ask the homeowner before posting photos of their house, and leave out house numbers."],"auto":{"trigger":{"type":"schedule","detail":"Every Wednesday at 10am"},"actions":[{"type":"notify","detail":"Remind the user to take a photo"},{"type":"ai.generate","detail":"Write the week's profile update"},{"type":"message.send","detail":"Send the update text to the user's phone to post"}]}},{"id":"write-product-descriptions-that-sell-for-your-shop","t":"Write product descriptions that sell for your shop","d":"Clear, benefit-led product descriptions, a short SEO title and bullet points for each item, written in your shop's voice.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Shopify"],"when":"When adding or refreshing products","steps":[{"h":"Note the facts","b":"For each product, jot down materials, size, care, who it's for, and what makes it different. A photo helps too."},{"h":"Ask for a description","b":"Paste the details (and attach a photo if you like) into your AI assistant with this prompt.","p":"Write a product description for [shop name], which sells [what you sell] to [audience]. Product: [name]. Facts: [materials, size, care, price, origin]. What makes it different: [details]. Give: 1) a 2-3 sentence opening that describes how it feels to use; 2) 4-5 bullet points of features turned into benefits; 3) a size or care note; 4) an SEO title under 60 characters and meta description under 155. Only use the facts I've given; don't invent claims. British English, warm tone."},{"h":"Add it to your shop","b":"Paste it into the product page in your Shopify admin (or any shop platform). Shopify Magic, built into the admin, can also suggest descriptions if you prefer to work there."}],"example":"'A mug that fits your whole hand, made for slow Sunday mornings.' Bullets: Holds 400ml, enough for a proper brew. Hand-thrown in Cornwall, so no two are the same. Dishwasher safe. SEO title: Handmade Stoneware Mug 400ml | Cornish Pottery.","tips":["Never claim things like 'eco-friendly' or 'hypoallergenic' unless you can back them up."],"auto":{"trigger":{"type":"new_row","detail":"New product added to the product sheet"},"actions":[{"type":"ai.generate","detail":"Write description, bullets and SEO fields"},{"type":"sheet.update","detail":"Add the copy next to the product"},{"type":"notify","detail":"Tell the user it's ready to review"}]}},{"id":"plan-a-short-video-with-a-script-and-shot-list","t":"Plan a short video with a script and shot list","d":"A 30 to 60 second script with a strong hook, plus a simple shot list you can film on your phone in one go.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera"],"when":"Before filming any Reel, Short or TikTok","steps":[{"h":"Decide the one point","b":"Write down the single thing you want viewers to learn or feel. Short videos work best with just one idea."},{"h":"Get a script and shot list","b":"Paste this into your AI assistant.","p":"Write a [30/45/60]-second vertical video script for [business or channel] aimed at [audience]. Main point: [point]. Format: 1) a hook for the first 2 seconds, spoken and as on-screen text; 2) the script split into numbered shots, each with what's said, what's on screen, and how long it lasts; 3) on-screen captions in short phrases; 4) a closing line with a call to action: [CTA]; 5) a caption for posting under 60 words. Everything must be filmable on a phone by one person at [location]."},{"h":"Film shot by shot","b":"Film each shot separately in good natural light, holding the phone upright. Do two takes of each so you have a spare."},{"h":"Edit and add captions","b":"Put the clips together in your phone's editor, Instagram, YouTube Shorts or Canva, and turn on automatic captions where offered; most viewers watch with the sound off."}],"example":"Hook: 'You're watering your houseplants wrong.' Shot 1 (2s): close-up of wilting plant. Shot 2 (5s): finger in soil, 'Check two knuckles deep first.' ... Shot 5 (4s): healthy plant, 'Follow for one plant tip a week.'","tips":["Ask anyone who appears in your video for permission first, and never film customers without asking."],"auto":{"trigger":{"type":"manual","detail":"User enters a video idea"},"actions":[{"type":"ai.generate","detail":"Write a timed script and shot list"},{"type":"doc.create","detail":"Save the script to the phone notes"},{"type":"notify","detail":"Send the shot list to the user's phone"}]}},{"id":"see-a-news-story-from-more-than-one-angle","t":"See a news story from more than one angle","d":"Get a balanced overview of a news story: the agreed facts, how different outlets frame it and the questions still unanswered.","cat":"Research & News","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant"],"when":"When a story is everywhere and you want the full picture","steps":[{"h":"Name the story","b":"Note the headline or topic and roughly when it broke."},{"h":"Ask for a balanced overview","b":"Use an assistant with web search on and paste this prompt.","p":"Give me a balanced overview of this news story: [story or headline], from around [date]. Search a range of reputable outlets with different viewpoints. Structure it as: 1) the facts most sources agree on, 2) how [3] different outlets frame it, with a short quote and link for each, 3) the strongest argument from each main side, 4) what is still unknown or disputed, 5) primary sources I can read myself (official statements, documents, data). Keep your own opinion out of it."},{"h":"Read at least one primary source","b":"Open the official statement, report or data the AI points to. It's the best way to check the summary hasn't drifted from the facts."}],"example":"Agreed facts: the rail strike is planned for 3 days from 12 Dec. Framing: Outlet A leads on passenger disruption; Outlet B on pay offers; Outlet C on safety staffing. Unknown: whether talks resume this week. Primary sources: union statement (link), operator timetable notice (link).","tips":["News moves fast. Ask the assistant to give the date of each source so you can see if anything is out of date."],"auto":{"trigger":{"type":"manual","detail":"User names a news story"},"actions":[{"type":"web.fetch","detail":"Gather coverage from several outlets and primary sources"},{"type":"ai.summarize","detail":"Write agreed facts, framings and open questions"},{"type":"notify","detail":"Send the overview with links"}]}},{"id":"pull-a-table-out-of-a-pdf-into-a-spreadsheet","t":"Pull a table out of a PDF into a spreadsheet","d":"Get tables trapped in PDFs or screenshots into Excel or Google Sheets as clean, sortable rows without retyping anything.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Excel","Google Sheets"],"when":"When you need numbers from a PDF in a spreadsheet","steps":[{"h":"Attach the PDF or a screenshot","b":"Upload the PDF to your AI assistant, or take a clear screenshot of just the table you need."},{"h":"Ask for clean rows","b":"Paste this prompt.","p":"Extract the table on page [page number] (titled '[table title]') from the attached file. Output it as a table I can paste into a spreadsheet: one header row, one row per line, numbers without currency symbols or commas, dates as DD/MM/YYYY, and empty cells left blank. Don't add or calculate anything. After the table, list any cells you couldn't read clearly."},{"h":"Paste into your spreadsheet","b":"Copy the table and paste it into Excel or Google Sheets. If it all lands in one column, ask the assistant for the same data as CSV and use the import option instead."},{"h":"Spot-check against the original","b":"Compare the totals and a few random rows with the PDF. If the PDF has a total row, add a SUM formula to make sure it matches."}],"example":"Month | Visitors | Sales | Refunds 01/01/2026 | 1840 | 12450 | 320 01/02/2026 | 1620 | 11010 | 290 Unclear cells: none.","tips":["Excel can also import tables straight from a PDF using its Get Data option, which is worth trying for very long tables."],"auto":{"trigger":{"type":"new_file","detail":"User uploads a PDF with a table"},"actions":[{"type":"ai.extract","detail":"Extract the table as clean rows"},{"type":"sheet.append","detail":"Add the rows to a spreadsheet"},{"type":"notify","detail":"List any cells that couldn't be read"}]}},{"id":"compare-supplier-quotes-fairly-side-by-side","t":"Compare supplier quotes fairly side by side","d":"Line up several supplier quotes in one table that compares like with like, including hidden extras, terms and the questions to ask each one.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Excel"],"when":"When you've got two or more quotes to choose between","steps":[{"h":"Collect the quotes","b":"Save each quote as a PDF or take a clear photo. Note anything the supplier told you on the phone."},{"h":"Ask for a fair comparison","b":"Upload them to your AI assistant with this prompt.","p":"Compare the attached supplier quotes for [what you're buying]. Make a table with: supplier, total price, what's included, what's excluded or extra (delivery, set-up, call-out fees), lead time, contract length, payment terms, warranty or guarantee, and how long the quote is valid. Then: 1) adjust for any missing items so I can compare like with like, and show how you did it, 2) list questions to ask each supplier where something is unclear. Don't recommend one; I'll decide."},{"h":"Ask the questions","b":"Email or call each supplier with their questions. Update the table with their answers in Excel or Google Sheets."},{"h":"Decide and keep a record","b":"Make your choice and save the table with the quotes, so you can compare when it's time to renew."}],"example":"| Supplier | Price | Delivery | Lead time | Valid | | Fernhill Print | £1,150 | Included | 5 days | 30 days | | Inkwell Studio | £980 | +£85 | 10 days | 14 days | Like-for-like: Inkwell £1,065. Ask Fernhill: is design proofing included?","tips":["Cheapest isn't always best: ask each supplier for references from similar customers."],"auto":{"trigger":{"type":"manual","detail":"User uploads several quotes"},"actions":[{"type":"ai.extract","detail":"Pull price, inclusions, terms and validity from each"},{"type":"ai.generate","detail":"Build a like-for-like comparison and questions"},{"type":"sheet.append","detail":"Save the comparison to a spreadsheet"}]}},{"id":"declutter-a-room-in-short-doable-sessions","t":"Declutter a room in short, doable sessions","d":"Break a cluttered room into 20-minute sessions with clear keep, donate and bin decisions so you actually finish.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"When a room feels overwhelming","steps":[{"h":"Photograph the room","b":"Take two or three wide photos showing the problem areas, like the wardrobe, desk or garage shelves."},{"h":"Ask for a session plan","b":"Attach the photos to your AI assistant and paste this prompt.","p":"Here are photos of my [room]. I can spend [20] minutes at a time, [number] times a week. Break decluttering this room into short sessions, starting with the quickest visible win. For each session give: the exact area (for example 'top shelf only'), what to sort, simple rules for keep, donate, sell or bin, and what 'done' looks like. Include a final session for taking donations out of the house."},{"h":"Book the sessions in","b":"Put the sessions in your calendar or reminders app like appointments, and tick each one off."}],"example":"Session 1 (20m): bedside table only. Bin anything broken, keep 1 book. Session 2: top wardrobe shelf - donate anything not worn in a year... Session 6: drop the donate bags at a charity shop, no second-guessing.","tips":["Keep a 'donate' bag by the door and take it out the same week so things don't creep back."],"auto":{"trigger":{"type":"manual","detail":"User shares photos of a room"},"actions":[{"type":"ai.generate","detail":"Create a set of 20-minute declutter sessions"},{"type":"calendar.create","detail":"Book each session into the user's calendar"}]}},{"id":"choose-the-right-neighbourhood-to-stay-in","t":"Choose the right neighbourhood to stay in","d":"Compare areas of a city side by side for safety feel, transport, noise and price, based on what matters to you.","cat":"Travel","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Maps"],"when":"Before booking accommodation","steps":[{"h":"Decide what matters","b":"Note your budget per night, who's travelling and your priorities, like quiet nights, nightlife, walking to sights or good transport."},{"h":"Ask for a comparison","b":"Paste this prompt into your AI assistant.","p":"I'm visiting [city] for [number] nights with [who]. Budget: about [amount] per night. Priorities: [e.g. quiet at night, walkable, near the station, family-friendly]. Compare the [4] best neighbourhoods to stay in using a table with: general feel, best for, getting to the main sights, noise, typical price level, and one downside. Then recommend one, explain why, and list what to search for in reviews to confirm it."},{"h":"Check on the map","b":"Drop the areas into Google Maps to see the walking distance to your top sights, and read recent reviews of places you're considering."}],"example":"Alfama: charming, hilly, can be noisy on weekends. Baixa: central, flat, great transport, busy. Principe Real: quiet, leafy, pricier. Recommended: Baixa for your first visit with a buggy. Search reviews for: 'lift', 'street noise', 'stairs'.","tips":["Area reputations change, so check recent reviews and official travel advice rather than relying on AI alone."],"auto":{"trigger":{"type":"manual","detail":"User enters a city and priorities"},"actions":[{"type":"ai.generate","detail":"Compare neighbourhoods against the user's priorities"}]}},{"id":"make-sense-of-your-fitness-tracker-s-weekly-numbers","t":"Make sense of your fitness tracker's weekly numbers","d":"Turn your watch or phone's weekly steps, sleep and activity stats into a short, plain-English summary and one goal.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"Once a week","steps":[{"h":"Grab your weekly summary","b":"Open your fitness or health app's weekly view and take screenshots of steps, active minutes and sleep, or note the numbers down."},{"h":"Ask for a plain-English summary","b":"Attach the screenshots to your AI assistant with this prompt.","p":"Here are my weekly fitness tracker stats: [attach screenshots or paste numbers]. My goal is [e.g. move more, sleep better]. In plain English: 1) summarise the week in 3 sentences; 2) compare with general guidance for adults, such as around 150 minutes of moderate activity a week; 3) point out my best and hardest days; 4) suggest one small, specific goal for next week. Don't make health judgements from the data."},{"h":"Set next week's goal","b":"Put the goal in your reminders app, for example 'Walk to the shop on Tuesday and Thursday'."}],"example":"This week: 41,200 steps (about 5,900 a day), 96 active minutes, average 6h 40m sleep. Best day: Saturday (11,800 steps). Hardest: Wednesday. You're about two-thirds of the way to 150 active minutes. Goal: a 20-minute walk on 3 weekdays.","tips":["Trackers are estimates; if your numbers worry you, such as heart rate alerts, talk to your GP rather than relying on AI."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8am"},"actions":[{"type":"ai.summarize","detail":"Summarise last week's activity and sleep stats"},{"type":"list.add","detail":"Add next week's goal to reminders"}]}},{"id":"save-towards-a-goal-with-a-clear-weekly-plan","t":"Save towards a goal with a clear weekly plan","d":"A saving plan for a holiday, deposit or big purchase that tells you how much to put aside each week and tracks your progress.","cat":"Money","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Sheets"],"when":"When you start saving for something specific","steps":[{"h":"Define the goal","b":"Decide what you're saving for, how much it will cost, and the date you need it by."},{"h":"Ask for a plan","b":"Share the goal and your rough budget with your AI assistant using this prompt.","p":"I want to save [amount] for [goal] by [date]. I've already saved [amount]. After bills, I usually have about [amount] spare each month. Work out how much I need to save per week and per month. If that's not realistic with my spare money, show two alternatives: a later date, or a smaller target. Give me 5 practical, low-effort ways to find the extra money based on everyday spending. Then create a simple weekly tracker table with columns: Week, Date, Planned, Actually saved, Running total, which I can paste into Google Sheets."},{"h":"Set up the tracker","b":"Paste the tracker into a Google Sheet. Many banking apps let you create a separate savings pot, so you can move the weekly amount there."},{"h":"Set a weekly nudge","b":"Add a recurring calendar reminder or phone reminder on payday to move the money and update the sheet."}],"example":"Goal: £1,200 summer holiday by 1 July (33 weeks). Saved: £150. Need: £32 a week (£139 a month). Ideas: swap two takeaways a month (£40), sell unused gadgets (one-off £80), pause one streaming service (£11). Week 1 | 16 Nov | £32 | | £150","tips":["Automating the transfer on payday works far better than relying on willpower.","This is a planning aid, not advice on where to keep your savings. Check options with a qualified adviser for larger sums."],"auto":{"trigger":{"type":"schedule","detail":"Every payday"},"actions":[{"type":"notify","detail":"Remind the user to move this week's savings"},{"type":"sheet.update","detail":"Update the running total in the tracker"},{"type":"ai.generate","detail":"Send a short progress note and whether the goal is on track"}]}},{"id":"practise-a-new-language-in-ten-minutes-a-day","t":"Practise a new language in ten minutes a day","d":"A daily conversation partner that chats with you at your level, gently corrects mistakes and keeps a list of words to review.","cat":"Learning","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"Every day, at the same time","steps":[{"h":"Pick a time and topic","b":"Choose a regular slot, such as your commute or after dinner, and a topic you'd actually talk about, like your day, food or travel plans."},{"h":"Start the conversation","b":"Open your AI assistant, ideally in voice mode for speaking practice, and paste this prompt.","p":"Be my [language] conversation partner. My level is [beginner / A2 / intermediate]. Today's topic: [topic]. Speak only in [language] using vocabulary at my level, with short sentences. Ask me one question at a time. After each of my replies, first answer naturally, then add a short 'Correction' line showing any mistake and the correct version, with a one-line explanation in English. After 10 exchanges, give me a list of 8 new or tricky words and phrases with English meanings."},{"h":"Save the word list","b":"Copy the word list at the end into a note called Language words so you can review it later."},{"h":"Repeat tomorrow with a twist","b":"Next day, start by pasting yesterday's word list and ask the AI to use those words again in a new conversation."}],"example":"AI: ¿Qué hiciste el fin de semana? You: Yo fui al mercado y compré frutas. AI: ¡Qué bien! ¿Qué frutas compraste? Correction: none, nice use of the past tense. Words today: el mercado (market), madrugar (to get up early)...","tips":["Speaking out loud in voice mode builds confidence faster than typing.","AI is a great practice partner but can sound formal. Mix in podcasts or shows for how people really speak."],"auto":{"trigger":{"type":"schedule","detail":"Daily at the user's chosen time"},"actions":[{"type":"notify","detail":"Send today's conversation topic"},{"type":"ai.generate","detail":"Hold a level-matched conversation with corrections"},{"type":"list.add","detail":"Add new words to the review list"}]}},{"id":"practise-a-job-interview-with-realistic-questions","t":"Practise a job interview with realistic questions","d":"A mock interview for the exact role you've applied for, with feedback on each answer and tips to make your examples stronger.","cat":"Careers","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant"],"when":"A few days before an interview","steps":[{"h":"Gather the details","b":"Have the job ad, your CV and anything you know about the interview format ready."},{"h":"Start the mock interview","b":"Paste this prompt into your AI assistant. Voice mode works well if you want to practise speaking.","p":"Act as an interviewer for this role: [paste job ad]. My CV: [paste, without contact details]. The interview is [format, for example 45 minutes, panel, competency-based]. Ask me 8 questions one at a time, mixing: 2 about my background, 4 competency questions ('tell me about a time...'), 1 about the organisation and 1 tricky one. Wait for my answer each time. After each answer, give brief feedback: what was good, what was missing, and whether I used a clear structure (situation, task, action, result). At the end, list my 3 strongest examples and 2 areas to improve."},{"h":"Answer as if it's real","b":"Answer each question fully, out loud or typed. Use your real experiences, not ones you wish you had."},{"h":"Polish your best stories","b":"Write your strongest examples as short bullet notes you can glance at before the interview."}],"example":"Q3: Tell me about a time you handled an upset customer. Feedback: Good situation and action. Missing the result: what happened afterwards? Try adding 'the customer emailed to thank us and renewed their contract'. Structure: 3 out of 4 parts covered.","tips":["Practise the questions you dread most. They're usually the ones that come up.","Ask it to play a tougher interviewer once you feel comfortable."],"auto":{"trigger":{"type":"calendar_event","detail":"An interview event is three days away"},"actions":[{"type":"notify","detail":"Suggest a mock interview session"},{"type":"ai.generate","detail":"Run a role-specific mock interview with feedback"},{"type":"doc.create","detail":"Save strongest examples as interview notes"}]}},{"id":"make-a-tough-decision-with-a-clear-head","t":"Make a tough decision with a clear head","d":"A structured look at a decision you're stuck on, with options, trade-offs, what matters most to you and a sensible next step.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":15,"tools":["AI assistant"],"when":"When you keep going round in circles","steps":[{"h":"Describe the decision","b":"Write down the choice you're facing, the options you can see, your deadline, and what's worrying you about each."},{"h":"Work through it together","b":"Paste your notes into your AI assistant with this prompt.","p":"I need help thinking through a decision, not being told what to do. The decision: [describe]. Options I see: [list]. Deadline: [date]. What matters to me: [for example money, time with family, stress, long-term growth]. First, ask me up to 5 questions, one at a time, to understand what I value. Then create a table scoring each option against my priorities, list the main risks and how I could reduce them, and point out any option I haven't considered. Finish with the smallest next step that would give me more information."},{"h":"Sleep on it","b":"Read the summary again the next day. Notice which option you feel relieved or disappointed about. That's useful information too."},{"h":"Get the right advice","b":"For decisions involving health, money or the law, use this to prepare, then check with a qualified professional."}],"example":"Decision: move to a smaller flat closer to work or stay put. Priorities: commute time (high), space for kids (high), cost (medium). Scores: Move 7/10, Stay 6/10. Risk of moving: kids changing school, so check catchment first. Next step: visit two flats this weekend and time the school run.","tips":["The AI is a sounding board. You make the call.","Telling it what matters most to you makes the analysis far more useful than a generic pros and cons list."],"auto":{"trigger":{"type":"manual","detail":"User describes a decision"},"actions":[{"type":"ai.generate","detail":"Ask clarifying questions and build a scored comparison"},{"type":"doc.create","detail":"Save the decision summary"},{"type":"calendar.create","detail":"Add a reminder to revisit it the next day"}]}},{"id":"say-no-politely-without-damaging-the-relationship","t":"Say no politely without damaging the relationship","d":"Get a kind, clear email that turns down a request, invite or extra work while keeping the door open where you want it.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":4,"tools":["AI assistant"],"when":"When you need to decline something","steps":[{"h":"Decide what you're offering instead","b":"Work out if there's anything you can offer, such as a later date, a smaller version or a recommendation. It's fine if the answer is nothing."},{"h":"Ask for a gracious no","b":"Paste the request and this prompt into your AI assistant.","p":"Help me say no to this request: [paste or describe the request]. Who it's from: [relationship]. My real reason (you decide how much to share): [reason]. What I can offer instead, if anything: [alternative or 'nothing']. Write a reply under 90 words that thanks them, says no clearly in the first two sentences, doesn't over-apologise or make up excuses, and ends warmly. Give me one version that keeps the door open and one that closes it kindly."},{"h":"Send it promptly","b":"A quick, clear no is kinder than a slow maybe. Send it today if you can."}],"example":"Hi Gemma, thank you for thinking of me for the committee. I'm not able to take it on this year, as my evenings are full until the summer. I'd be happy to help with the spring fair on the day if that's useful. Wishing you a great first meeting!","tips":["Remove 'just', 'sorry' and 'I'm afraid' from the final version; one thank-you is enough."],"auto":{"trigger":{"type":"manual","detail":"User asks for help declining a request"},"actions":[{"type":"ai.generate","detail":"Write a door-open and a door-closed decline"},{"type":"email.draft","detail":"Save the chosen version as a reply draft"}]}},{"id":"turn-dates-in-emails-and-letters-into-calendar-events","t":"Turn dates in emails and letters into calendar events","d":"Paste an email, school letter or booking confirmation and get every date pulled out as calendar events with times and reminders.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera","Google Calendar","Outlook Calendar"],"when":"Whenever a message or letter is full of dates","steps":[{"h":"Capture the dates","b":"Copy the email text, or take a clear photo of the letter or timetable."},{"h":"Ask AI to list the events","b":"Paste or attach it with this prompt.","p":"Find every date, event and deadline in this text or image. For each give: event title (short and clear), date, start and end time (or 'all day'), location, what to bring or do, and a sensible reminder (e.g. 1 day before). Present it as a table in date order. Flag anything where the date or time is unclear. If you can create files, also give me a calendar file (.ics) I can import. [paste text or attach photo]"},{"h":"Add them to your calendar","b":"Import the calendar file if you got one, or add each row as an event in Google Calendar or Outlook. Gemini can add events to Google Calendar directly if connected."},{"h":"Share with your household","b":"Invite your partner or add the events to a shared family calendar so everyone sees them."}],"example":"Fri 28 Nov | Non-uniform day | all day | bring £1 | reminder Thu 7pm. Tue 9 Dec | Nativity play | 14:00-15:00 | school hall | reminder 1 day before. Wed 17 Dec | Term ends | 13:30 pickup | reminder morning of.","tips":["Gmail already adds flights and restaurant bookings to Google Calendar automatically for many confirmations, so check before adding twice."],"auto":{"trigger":{"type":"new_email","detail":"An email with dates or bookings arrives"},"actions":[{"type":"ai.extract","detail":"Pull out events, dates, times and locations"},{"type":"calendar.create","detail":"Add each event with a reminder"},{"type":"notify","detail":"List the events added so the user can check them"}]}},{"id":"turn-scattered-notes-into-an-organised-document","t":"Turn scattered notes into an organised document","d":"Paste in jumbled notes, screenshots or photos of a notebook and get one neat document with headings, key points and actions.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera","Google Docs","Notes app"],"when":"When notes pile up after a course, project or busy week","steps":[{"h":"Collect the notes","b":"Copy text from your notes app, and photograph handwritten pages in good light, one page per photo."},{"h":"Ask AI to organise them","b":"Paste or attach everything with this prompt.","p":"Organise these notes into one clear document about [topic]. Group related points under short headings, remove repeats, keep my original facts and numbers, and fix spelling. At the end add: 'Actions' (anything I said I'd do) and 'Questions' (anything I wrote with a ? or seemed unsure about). If you can't read part of a handwritten page, mark it [unclear] rather than guessing."},{"h":"Save the clean version","b":"Paste the result into a Google Doc, Word file or notes app with a clear title and date so you can find it later."}],"example":"Garden redesign notes. Layout: Move veg beds to south fence; keep apple tree. Budget: Max £1,200; sleepers approx £35 each. Plants: Lavender along path, [unclear] near shed. Actions: Get skip quote. Questions: Do we need permission for the new shed?","tips":["Ask for a one-paragraph summary at the top if you'll be sharing it with someone else."],"auto":{"trigger":{"type":"new_file","detail":"Photos or notes are added to a 'To tidy' folder"},"actions":[{"type":"ai.extract","detail":"Read text from notes and photos"},{"type":"ai.generate","detail":"Organise into headings, actions and questions"},{"type":"doc.create","detail":"Save the tidy document"}]}},{"id":"reply-to-every-online-review-in-your-own-voice","t":"Reply to every online review in your own voice","d":"Thoughtful, personal responses to good and bad Google reviews in minutes, so potential customers see you care.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Business Profile"],"when":"Once a week, or when a new review arrives","steps":[{"h":"Collect new reviews","b":"Open your Google Business Profile (search your business name on Google while signed in) and copy any reviews you haven't answered yet."},{"h":"Ask AI for tailored replies","b":"Paste the reviews into your AI assistant with this prompt.","p":"I own [business name], a [type of business] in [town]. Write a public reply to each review below. Reviews: [paste, one per line with star rating]. Rules: under 70 words each; mention one specific thing the reviewer said; thank them by first name only if they used one; for 1 to 3 stars, apologise for their experience without arguing, mention one thing we're doing about it ([what you're changing]), and invite them to contact [email or phone] to put it right; never reveal any private details about the customer; British English; vary the wording so replies don't all sound the same."},{"h":"Post after a quick check","b":"Read each reply aloud, make sure nothing confirms private details like what treatment or service someone had, then post it on the review."}],"example":"5 stars: Thanks so much, Leah! We're thrilled the cinnamon buns made your Saturday. See you next time. 2 stars: We're sorry the wait was so long on Sunday. We've added a second person on the till at weekends. Please email hello@[cafe].co.uk so we can make it up to you.","tips":["Reply to bad reviews within a couple of days; a calm public reply often matters more to readers than the review itself.","For health, legal or financial services, never confirm someone was a client in a public reply."],"auto":{"trigger":{"type":"schedule","detail":"Every Friday at 3pm"},"actions":[{"type":"web.fetch","detail":"Collect new unanswered reviews"},{"type":"ai.generate","detail":"Draft a personal reply for each review"},{"type":"notify","detail":"Send drafts to the owner to approve and post"}]}},{"id":"turn-call-notes-into-a-polished-proposal","t":"Turn call notes into a polished proposal","d":"A clear, client-focused proposal with scope, timeline, prices and next steps, built from your rough notes in about fifteen minutes.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"After a client asks 'can you send me something?'","steps":[{"h":"Collect your notes and prices","b":"Gather your notes about what the client wants, plus your prices, timescales and any terms you always include."},{"h":"Ask AI to draft the proposal","b":"Paste everything into your AI assistant with this prompt.","p":"Write a proposal from [my business] to [client company] using these notes: [paste notes]. My prices and packages: [paste]. Structure: 1) Your goals (in the client's own words where possible), 2) What I'll do (bullet points), 3) What's not included, 4) Timeline with milestones, 5) Investment (a table with 2 or 3 options, recommended one marked), 6) Why me (2 short points), 7) Next steps to get started. Plain British English, confident but not salesy, under 600 words. Use only my prices; don't invent any numbers. Mark anything you're unsure of with [CHECK]."},{"h":"Polish it in a document","b":"Paste it into Google Docs or Word, add your logo, check every figure and [CHECK] note, then export it as a PDF."},{"h":"Send with a short personal note","b":"Email it with two lines recapping the main benefit and suggesting a time to talk it through."}],"example":"Investment Option A: Essentials - 5-page website, 3 weeks - £1,950 Option B (recommended): Essentials plus online booking and 2 months of support - £2,600 Not included: copywriting for blog posts, paid advertising. Next steps: sign below and pay a 30% deposit to book a May start.","tips":["Offering three options usually works better than a single price.","Have contract terms and payment conditions checked by a qualified professional once, then reuse them."],"auto":{"trigger":{"type":"manual","detail":"User marks a lead as 'proposal needed'"},"actions":[{"type":"ai.generate","detail":"Draft a proposal from call notes and price list"},{"type":"doc.create","detail":"Create the proposal document"},{"type":"notify","detail":"Remind the user to check prices and send"}]}},{"id":"prepare-for-a-difficult-conversation-with-a-team-member","t":"Prepare for a difficult conversation with a team member","d":"A calm plan for a tricky one-to-one, with an opening line, key points, likely reactions and how to agree next steps fairly.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Notes app"],"when":"Before a performance or behaviour conversation","steps":[{"h":"Write down the facts, not the person","b":"Note specific examples with dates, the impact on the team or customers, and what you want to change. Use a role instead of the person's name."},{"h":"Ask AI to help you plan","b":"Paste this prompt into your AI assistant.","p":"Help me prepare for a one-to-one with a [role] about [issue]. Facts: [dated examples and impact]. What I want to happen: [outcome]. Anything I know about their situation: [context, without health details]. Give me: 1) a calm opening of 2 sentences that explains why we're meeting, 2) the 3 key points in plain language, 3) 3 open questions to understand their side, 4) likely reactions (upset, defensive, quiet) and how to respond to each, 5) how to agree clear next steps and a review date, 6) a short summary note I can send afterwards. Supportive but direct, British English. Remind me where I should get HR or legal advice."},{"h":"Check your process","b":"If the issue could lead to formal action, follow your written disciplinary or performance process and speak to an HR adviser first."},{"h":"Have the conversation and note it","b":"Keep your plan in your notes app, have the conversation in private, listen properly, and send the agreed summary afterwards."}],"example":"Opening: 'Thanks for making time. I want to talk about the late starts over the last few weeks and how we can sort it together.' Question: 'Is anything making mornings harder at the moment?' If upset: pause, acknowledge, offer to continue tomorrow. Next step: agree start time, review in 2 weeks.","tips":["If someone mentions health, caring duties or personal problems, stop and get HR advice; you may need to make adjustments.","Keep notes factual and store them securely; staff can ask to see what's recorded about them."],"auto":{"trigger":{"type":"manual","detail":"Manager plans a difficult conversation"},"actions":[{"type":"ai.generate","detail":"Create a conversation plan with opening, questions and next steps"},{"type":"calendar.create","detail":"Book the follow-up review date"}]}},{"id":"find-the-words-your-customers-actually-search-for","t":"Find the words your customers actually search for","d":"A sorted list of 30 to 50 real search phrases for your business, grouped by what people want, ready to use in your website and posts.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Sheets"],"when":"Before writing web pages or blog posts","steps":[{"h":"Collect search suggestions","b":"Type your main service into Google slowly and note the suggestions that drop down, plus the 'People also ask' questions and related searches at the bottom of the results. Try four or five starting phrases."},{"h":"Ask the AI to sort and expand them","b":"Paste what you collected into your AI assistant with this prompt.","p":"I run [business] in [town or region] for [audience]. Here are phrases from Google suggestions and 'People also ask': [paste list]. 1) Remove duplicates. 2) Group them by intent: wants to buy now, comparing options, wants to learn, local search. 3) Add 10 more realistic phrases a customer might type. 4) For each group, suggest one web page or blog post title that would answer them. Output as a table: Phrase, Intent, Suggested page. Don't invent search volumes."},{"h":"Save it in a sheet","b":"Paste the table into Google Sheets and add a column for where you've used each phrase, so you can tick them off."}],"example":"'emergency plumber near me' (buy now) -> Page: Emergency plumbing in Leeds. 'how much does a boiler service cost' (comparing) -> Post: What a boiler service costs and what's included. 'why is my radiator cold at the top' (learn) -> Post: Cold radiator? Five fixes.","tips":["AI can't see real search volumes; if you want numbers, check Google Trends to compare which phrases are more popular."],"auto":{"trigger":{"type":"manual","detail":"User pastes collected search phrases"},"actions":[{"type":"ai.classify","detail":"Group phrases by search intent"},{"type":"ai.generate","detail":"Suggest extra phrases and page titles"},{"type":"sheet.append","detail":"Save phrases to the keyword sheet"}]}},{"id":"turn-a-messy-brain-dump-into-a-clear-article","t":"Turn a messy brain dump into a clear article","d":"Type or dictate everything you know about a topic in any order, and get back a well-structured article that keeps your ideas and examples.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Voice notes"],"when":"When you know a topic but hate starting from a blank page","steps":[{"h":"Dump it all out","b":"Spend ten minutes typing, or record a voice note and use your phone's transcription, saying everything you'd tell a friend about the topic. Don't worry about order."},{"h":"Ask for structure","b":"Paste the text into your AI assistant with this prompt.","p":"Below is a messy brain dump about [topic] for [audience]. Turn it into a structured article of [800-1,000] words. Rules: keep my examples, opinions and phrases wherever possible; organise it into a logical order with clear H2 headings; cut repetition; flag with [CHECK] anything that sounds like a fact I should verify; flag with [GAP] anywhere a reader would need more explanation. Then list 3 title options. Brain dump: [paste]."},{"h":"Fill the gaps","b":"Work through the [CHECK] and [GAP] flags, adding detail or fixing facts yourself."},{"h":"Read it aloud","b":"Reading it aloud is the quickest way to spot sentences that don't sound like you."}],"example":"Title: What I've Learnt From 10 Years of Wedding Flowers. H2s: Start with the venue, not the flowers. Seasonal blooms save money. The bouquet that wilted. [CHECK] 'Peonies are only in season in May and June.' [GAP] Explain how far ahead to book.","tips":["Speaking often gives a more natural voice than typing; try a walk with a voice note."],"auto":{"trigger":{"type":"new_file","detail":"New voice note or brain dump saved"},"actions":[{"type":"ai.generate","detail":"Structure the notes into an article with flags"},{"type":"doc.create","detail":"Save the article draft"},{"type":"notify","detail":"Tell the user the draft is ready to finish"}]}},{"id":"write-youtube-titles-descriptions-and-chapters-in-minutes","t":"Write YouTube titles, descriptions and chapters in minutes","d":"From your video's transcript, get title options, a full description, timestamped chapters and tags ready to paste into YouTube Studio.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":10,"tools":["YouTube","AI assistant"],"when":"Every time you upload a video","steps":[{"h":"Get the transcript","b":"Upload your video to YouTube Studio as private or unlisted and wait for automatic captions. In the Subtitles section you can open and copy or download the captions with timings."},{"h":"Ask for the details","b":"Paste the transcript into your AI assistant with this prompt.","p":"Here is the timed transcript of my YouTube video: [paste]. Channel: [channel topic] for [audience]. Give me: 1) 5 title options under 60 characters, main search phrase near the start, honest (no clickbait); 2) a description: two opening lines that make sense in search results, then a 100-word summary, then [links/CTA]; 3) chapters starting at 0:00, at least 3, each with a short clear name, using the real times from the transcript; 4) 10 tags; 5) 3 ideas for thumbnail text (max 4 words)."},{"h":"Paste into YouTube Studio","b":"Add the title, description (chapters go at the bottom, each on its own line starting with the timestamp) and tags, then publish or schedule the video."}],"example":"Title: How to Re-Grout a Shower in One Afternoon. Chapters: 0:00 What you'll need, 1:12 Removing old grout, 4:30 Mixing new grout, 7:05 Applying and cleaning, 10:40 Sealing. Thumbnail text: 'Like new in 4 hours'.","tips":["Double-check chapter times by clicking each one after publishing; auto captions can drift slightly."],"auto":{"trigger":{"type":"new_file","detail":"New video uploaded to the channel"},"actions":[{"type":"web.fetch","detail":"Get the video's automatic transcript"},{"type":"ai.generate","detail":"Write titles, description, chapters and tags"},{"type":"notify","detail":"Send the details to the user to paste in"}]}},{"id":"walk-into-every-call-knowing-the-latest-company-news","t":"Walk into every call knowing the latest company news","d":"Before a meeting, get a one-page brief on the company you're speaking to: what they do, recent news, likely priorities and smart questions to ask.","cat":"Research & News","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Calendar"],"when":"The day before any external meeting","steps":[{"h":"Spot tomorrow's external meetings","b":"Glance at your calendar at the end of the day and note any meetings with people outside your organisation."},{"h":"Ask for a brief with sources","b":"Use an assistant that can search the web (ChatGPT, Gemini, Claude or Perplexity with search turned on) and paste this prompt.","p":"I have a meeting with [company name] ([their website]) tomorrow about [topic]. Search the web and give me a one-page brief: 1) what they do in two sentences, 2) news from the last [3] months with the date and a link for each item, 3) their likely priorities or pressures right now, 4) who [person's name and job title] is, using only public professional information, 5) five questions I could ask. Mark anything you are not sure of, and do not include anything without a source."},{"h":"Open the links before you rely on them","b":"Click through the two or three items you plan to mention and make sure the date and details are right. AI search sometimes mixes up companies with similar names."},{"h":"Save the brief to the meeting","b":"Paste the final brief into the calendar event's description so it's there when you join."}],"example":"Northgate Joinery Ltd: makes bespoke kitchens for the trade. News: opened a second workshop in Leeds (12 Sept, link); won a regional apprenticeship award (2 Aug, link). Likely priorities: hiring, lead times. Ask: 'How is the new workshop changing your delivery times?'","tips":["Stick to professional, public information about people. Don't dig into anyone's personal life."],"auto":{"trigger":{"type":"calendar_event","detail":"A meeting with an external guest is tomorrow"},"actions":[{"type":"web.fetch","detail":"Search recent news about the guest's company"},{"type":"ai.generate","detail":"Write a one-page brief with sources and questions"},{"type":"notify","detail":"Send the brief the evening before"}]}},{"id":"ask-your-spreadsheet-questions-in-plain-english","t":"Ask your spreadsheet questions in plain English","d":"Get straight answers from your spreadsheet, like your best month or biggest customer, without writing formulas or pivot tables.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Google Sheets","Excel"],"when":"Whenever you have a question about your data","steps":[{"h":"Tidy the sheet first","b":"Make sure there's one header row and one row per record. Delete blank rows and unmerge any merged cells."},{"h":"Use the built-in assistant or upload a copy","b":"If your plan includes Gemini in Google Sheets or Copilot in Excel, open its side panel. Otherwise download the sheet as a CSV or Excel file and upload it to ChatGPT, Claude or Gemini."},{"h":"Ask clear questions","b":"Paste this prompt and change the questions to your own.","p":"This spreadsheet contains [what the data is, e.g. our sales for 2026, one row per order]. Columns: [list the main columns]. Answer these questions, showing the figures you used and how you worked each one out: 1) [Which month had the highest total sales?] 2) [Who are our top 5 customers by total spend?] 3) [What is the average order value by product category?] Then point out anything unusual in the data, such as gaps, duplicates or odd values."},{"h":"Double-check one answer","b":"Pick one answer and check it yourself with a quick filter or SUM. If it doesn't match, ask the assistant to show its working."}],"example":"1) Highest sales: July, £18,240 (312 orders). 2) Top customers: Harbour Café £2,410, Lane Studio £1,980... 3) Average order: Cakes £21.40, Bread £8.90. Unusual: 14 orders have no date; 3 look duplicated (same customer, amount and time).","tips":["Delete columns with names, emails or phone numbers before uploading if you don't need them for the question."],"auto":{"trigger":{"type":"manual","detail":"User asks a question about a spreadsheet"},"actions":[{"type":"ai.generate","detail":"Calculate the answer and show the working"},{"type":"ai.classify","detail":"Flag gaps, duplicates and odd values"},{"type":"notify","detail":"Send the answers to the user"}]}},{"id":"make-a-professional-invoice-template-in-ten-minutes","t":"Make a professional invoice template in ten minutes","d":"Create a clean, reusable invoice template in Word or Google Docs with everything a customer needs to pay you quickly.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Word","Google Docs","Canva"],"when":"Once, when you start invoicing","steps":[{"h":"Gather your details","b":"Have your business name, address, contact details, payment details and VAT number (if you have one) to hand."},{"h":"Ask for a template layout","b":"Paste this prompt into your AI assistant.","p":"Create an invoice template for [business name], a [business type] in [country]. Include: the word INVOICE, my business details, customer details, invoice number, invoice date, due date, a line-item table (description, quantity, unit price, total), subtotal, VAT [at rate / or 'not VAT registered'], total due, payment terms ([e.g. 14 days]), how to pay, and a short thank-you line. Use [square brackets] for everything I fill in each time. Then list anything that invoices in my country usually must show, so I can check it with my accountant."},{"h":"Build it in Word or Docs","b":"Paste the layout into a document, add your logo and use a table for the line items. Canva also has free invoice templates if you prefer a designed look."},{"h":"Save as a template","b":"Save a master copy and make a copy for each new invoice. Name files like 'INV-0001 Customer Name'."}],"example":"INVOICE | Bloom & Branch Florals | Invoice no: [0001] | Date: [date] | Due: [date + 14 days] | Wedding table arrangements x 8 @ £45 = £360 | Total due: £360 (not VAT registered) | Pay by bank transfer to: [account details]. Thank you for your business!","tips":["If you send lots of invoices, accounting apps like Xero or QuickBooks number, send and track invoices for you."],"auto":{"trigger":{"type":"manual","detail":"User asks for an invoice template"},"actions":[{"type":"ai.generate","detail":"Create an invoice layout with placeholders"},{"type":"doc.create","detail":"Save the template as a document"}]}},{"id":"pack-school-lunches-your-fussy-eater-will-actually-eat","t":"Pack school lunches your fussy eater will actually eat","d":"Get two weeks of varied lunchbox ideas built around your child's safe foods, with a few gentle new things to try.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Notes app"],"when":"Every couple of weeks during term","steps":[{"h":"List what your child will eat","b":"Write down their 'safe' foods, things they've refused, any allergies and whether the school is nut-free."},{"h":"Ask for a lunchbox rotation","b":"Paste this prompt into your AI assistant.","p":"My child is [age] and a fussy eater. They reliably eat: [list]. They refuse: [list]. Allergies or school rules: [e.g. nut-free school]. Create a 10-day packed lunch rotation that mostly uses their safe foods, with one small new or slightly different item each day to try. Include a main, a fruit or veg, and a snack, no reheating needed, and keep prep under [10] minutes in the morning. Add a short list of things I can prep on Sunday."},{"h":"Keep the rotation handy","b":"Save it in your notes app and add the shopping items to your list."}],"example":"Day 1: ham & cheese pinwheels, cucumber sticks, apple slices; try: 3 cherry tomatoes. Day 2: pasta salad with sweetcorn, grapes (halved), plain popcorn; try: a pepper strip... Sunday prep: cook pasta, wash grapes, bake mini muffins.","tips":["Halve grapes and cherry tomatoes for younger children, and always check your school's food policy."],"auto":{"trigger":{"type":"schedule","detail":"Every other Sunday during term"},"actions":[{"type":"ai.generate","detail":"Create a 10-day lunchbox rotation from saved preferences"},{"type":"list.add","detail":"Add lunchbox items to the shopping list"}]}},{"id":"turn-holiday-voice-notes-into-a-travel-journal","t":"Turn holiday voice notes into a travel journal","d":"Record a quick voice note each evening and get a readable journal of your trip to keep or share with family.","cat":"Travel","side":"life","lvl":"Beginner","mins":5,"tools":["Voice notes","AI assistant","Google Docs"],"when":"Each evening of a trip, then once you're home","steps":[{"h":"Record a nightly voice note","b":"Spend two minutes each evening talking through the day: where you went, what you ate, what made you laugh. Your phone's voice recorder can often create a transcript."},{"h":"Turn notes into journal entries","b":"Paste the transcripts into your AI assistant with this prompt, or speak the notes to it directly.","p":"Here are my voice note transcripts from a trip to [destination], one per day: [paste transcripts]. Turn them into a warm, readable travel journal in my own voice, with a short entry for each day: a title, 150-200 words, and one 'best moment'. Keep names and details exactly as I said them, don't invent anything, and fix filler words and repetition."},{"h":"Add photos and save","b":"Paste the journal into Google Docs, Word or Canva, add a few photos for each day and save it as a PDF or print it."}],"example":"Day 4 - The day it rained in Porto. We gave up on the river cruise and ducked into a tiny cafe where the owner taught Leo to say 'obrigado'. Afternoon: port cellar tour, Mum's first taste of white port... Best moment: the bookshop queue that was worth it.","tips":["Ask everyone in the family to record a 30-second note too; the different views make the journal much richer."],"auto":{"trigger":{"type":"schedule","detail":"Every evening at 9pm during a trip"},"actions":[{"type":"notify","detail":"Remind the user to record a voice note"},{"type":"ai.generate","detail":"Turn the transcript into a journal entry"},{"type":"doc.create","detail":"Add the entry to the trip journal document"}]}},{"id":"make-healthier-swaps-in-your-weekly-shop","t":"Make healthier swaps in your weekly shop","d":"Share your usual shopping list and get realistic swaps and easy label-reading tips, without giving up favourites.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant","Phone camera"],"when":"Before your next big shop","steps":[{"h":"Grab your usual list","b":"Copy your regular shopping list, or take photos of a recent receipt or your cupboard."},{"h":"Ask for realistic swaps","b":"Paste the list into your AI assistant with this prompt.","p":"Here's my usual weekly shop: [paste list]. Suggest up to [8] healthier swaps that are realistic and similar in price, such as higher-fibre, less sugar or less salt options, but keep [favourites I won't give up]. Put them in a table: current item, swap, why it helps, and roughly what it does to cost. Then give me 3 simple tips for reading front-of-pack food labels."},{"h":"Try a few at a time","b":"Add two or three swaps to this week's list and see what the household likes before changing more."}],"example":"White sliced bread - wholemeal sliced: more fibre, similar price. Sugary cereal - plain wheat biscuits with banana: less sugar, cheaper. Flavoured yoghurt - plain yoghurt with berries. Label tip: traffic-light labels with more greens are generally a healthier choice.","tips":["If you have a medical condition or special diet, check changes with your GP or a registered dietitian."],"auto":{"trigger":{"type":"manual","detail":"User shares their shopping list"},"actions":[{"type":"ai.generate","detail":"Suggest realistic healthier swaps"},{"type":"list.add","detail":"Add chosen swaps to the shopping list"}]}},{"id":"split-shared-household-costs-fairly","t":"Split shared household costs fairly","d":"A clear, fair split of rent, bills and shared shopping between housemates or partners, with a message ready to send everyone.","cat":"Money","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","WhatsApp"],"when":"Monthly, or when someone moves in or out","steps":[{"h":"List the shared costs","b":"Write down each shared cost, how much it was and who paid it this month."},{"h":"Agree the rule","b":"Decide how you split: equally, by room size, or by income. Write the rule down so everyone agrees."},{"h":"Work out who owes what","b":"Paste the list into your AI assistant with this prompt.","p":"We are [number] people sharing a home: [names or initials]. Our splitting rule is: [equal / by room size with these percentages / by income ratio]. This month's shared costs and who paid them: [list each cost, amount and payer]. Work out each person's fair share, what each has already paid, and the smallest number of payments needed to settle up (who pays whom and how much). Show the working in a simple table, then write a friendly, neutral message I can send to the group chat."},{"h":"Share and settle","b":"Double-check the maths, then post the message to your household WhatsApp group so everyone can see the same numbers."}],"example":"Total shared: £1,620. Each share: £540. Sam paid £1,100 (rent part + energy), Alex £320, Jo £200. Settle up: Jo pays Sam £340, Alex pays Sam £220. Message: 'Hi all, here's November's split...'","tips":["Use initials rather than full names if you prefer.","Ask the AI to keep a running tally if you paste each month's results back in."],"auto":{"trigger":{"type":"schedule","detail":"Last day of each month"},"actions":[{"type":"ai.generate","detail":"Calculate each person's share and settle-up payments"},{"type":"message.send","detail":"Post the summary to the household group chat"},{"type":"sheet.append","detail":"Log the month's split"}]}},{"id":"learn-from-youtube-videos-without-losing-the-key-points","t":"Learn from YouTube videos without losing the key points","d":"Structured study notes from any educational video, with key ideas, timestamps to revisit and a few questions to test yourself.","cat":"Learning","side":"life","lvl":"Beginner","mins":5,"tools":["YouTube","AI assistant","Notes app"],"when":"After watching a tutorial or lecture","steps":[{"h":"Open the transcript","b":"On many YouTube videos you can show the transcript from the description area. Copy it. Some AI assistants, such as Gemini, can also read a YouTube link directly."},{"h":"Turn it into notes","b":"Paste the transcript or link into your AI assistant with this prompt.","p":"Turn this video transcript into study notes for someone learning [topic] at [level]. Include: a 2-sentence summary, the key ideas as headed bullet points, any steps or methods as a numbered list, important terms with simple definitions, the timestamps of the 3 most important moments, and 5 questions to test my understanding (answers at the end). Only use what's in the transcript. [paste transcript]"},{"h":"Save and test yourself","b":"Paste the notes into your notes app. Try the questions the next day without looking."}],"example":"Summary: How to make a basic budget formula in a spreadsheet. Steps: 1) Put categories in column A, 2) amounts in B, 3) type =SUM(B2:B10). Key moment: 04:12 absolute references. Q1: What does the $ sign do in $B$2?","tips":["Auto-generated transcripts can mishear technical terms, so check unfamiliar words.","Notes are no substitute for trying it yourself. Pause and practise as you go."],"auto":{"trigger":{"type":"manual","detail":"User shares a video link or transcript"},"actions":[{"type":"ai.summarize","detail":"Create structured study notes"},{"type":"ai.generate","detail":"Write five self-test questions"},{"type":"file.save","detail":"Save notes to the study folder"}]}},{"id":"research-a-fair-salary-before-you-negotiate","t":"Research a fair salary before you negotiate","d":"A sensible salary range for your role and area based on public sources, and a calm script for asking for it.","cat":"Careers","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant"],"when":"Before an offer conversation or pay review","steps":[{"h":"Gather real salary data","b":"Look up advertised salaries for similar roles on job sites, plus any public salary surveys for your field and area. Note five to ten examples."},{"h":"Ask the AI to make sense of it","b":"Paste what you found into your AI assistant with this prompt. If it can search the web, ask it to add sources too.","p":"I'm a [job title] with [years] years' experience in [location], working in [sector]. Here are salary figures I've found for similar roles: [paste with sources]. Work out a realistic range (low, typical, high) and explain what pushes someone towards the top, such as specific skills, responsibilities or certifications. List the sources you used and how reliable each is. Then write a short, polite script for asking for [amount] in an offer conversation, plus answers to 'what are your salary expectations?' and 'that's above our budget'."},{"h":"Check the sources","b":"Open any sources the AI mentions to confirm the figures are current and relevant to your area."},{"h":"Practise the conversation","b":"Ask the AI to play the hiring manager and push back, so you can practise staying calm and clear."}],"example":"Range for Payroll Administrator, 3 years, Leeds: £25k to £31k, typical £27.5k. Higher end: payroll qualification, multi-site experience. Script: 'Thank you for the offer. Based on my research and my experience running payroll for 200 staff, I was hoping for £29,500. Is there flexibility?'","tips":["AI salary estimates can be out of date, so rely on the real listings you collected.","Consider the whole package: holiday, pension, flexible hours and training can be worth a lot."],"auto":{"trigger":{"type":"manual","detail":"User starts salary research for a role"},"actions":[{"type":"web.fetch","detail":"Gather advertised salaries for similar roles"},{"type":"ai.summarize","detail":"Calculate a realistic salary range with sources"},{"type":"ai.generate","detail":"Write a negotiation script"}]}},{"id":"plan-a-party-or-gathering-without-the-stress","t":"Plan a party or gathering without the stress","d":"A complete checklist and timeline for a birthday, celebration or get-together, from invites to clean-up, with a shopping list and budget.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs","WhatsApp"],"when":"Three to six weeks before the event","steps":[{"h":"Decide the basics","b":"Note the occasion, date, rough number of guests, location, budget and any dietary needs you know about."},{"h":"Get a plan","b":"Paste your notes into your AI assistant with this prompt.","p":"Help me plan a [occasion] on [date] for about [number] guests at [location]. Budget: [amount]. Guests include: [for example lots of children under 8, two vegetarians, one nut allergy]. Give me: 1) a countdown timeline from now to the day after, with tasks for each week, 2) a simple menu that fits the budget and dietary needs, 3) a shopping list grouped by shop or aisle with rough costs, 4) a run sheet for the day itself with times, and 5) a short, friendly invite message I can send on WhatsApp. Keep it doable for one or two people."},{"h":"Save the checklist","b":"Paste the timeline into Google Docs or your notes app and tick things off as you go. Share it with anyone helping."},{"h":"Send the invites","b":"Adjust the invite message and send it to your guests, asking for replies and allergies by a set date."}],"example":"4 weeks: send invites, book hall. 2 weeks: order cake, buy decorations. Day before: make sandwiches, charge speaker. Day: 1pm set up, 2pm guests arrive, 2:30 games, 3:15 food, 4pm cake. Budget: food £60, cake £25, decorations £15, party bags £30.","tips":["Always ask about allergies in the invite and label food on the day.","Ask a friend to own one job, like games or food, so you can enjoy it too."],"auto":{"trigger":{"type":"manual","detail":"User enters the event details"},"actions":[{"type":"ai.generate","detail":"Create a timeline, menu, shopping list and run sheet"},{"type":"doc.create","detail":"Save the plan as a shared checklist"},{"type":"calendar.create","detail":"Add weekly task reminders before the event"}]}},{"id":"reply-to-tricky-emails-calmly-and-clearly","t":"Reply to tricky emails calmly and clearly","d":"Paste in an awkward email and get two ready-to-send replies, one warm and one firm, that say exactly what you mean.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Gmail","Outlook"],"when":"Whenever an email makes you hesitate","steps":[{"h":"Copy the email you need to answer","b":"Copy the message (and the one before it if it gives context). Remove phone numbers, account numbers or anything private first."},{"h":"Jot down what you actually want to say","b":"One or two rough lines is enough, for example 'Can't do Friday, can do next Tuesday, and I need the files first'."},{"h":"Ask your AI assistant for two versions","b":"Open ChatGPT, Claude or Gemini and paste this prompt with the email and your notes.","p":"I need to reply to the email below. My goal: [what you want to happen]. My key points: [your rough notes]. My relationship with the sender: [e.g. client, manager, neighbour]. Write two replies under 120 words each: Version A warm and friendly, Version B polite but firm. Keep my points in the same order, use plain British English, no clichés, and end with one clear next step. Then list anything in their email I haven't answered. Their email: [paste email]"},{"h":"Pick one, tweak and send","b":"Choose the version that sounds most like you, change any words you wouldn't use, and paste it into your reply."}],"example":"Version B: Hi Sam, thanks for the update. I can't take on the extra pages by Friday, but I can deliver them by Tuesday 14th if I have the final copy by Thursday. Shall we go with that? Not yet answered: their question about invoicing.","tips":["Ask it to 'make this sound more like me' and paste two emails you've sent before as a style guide.","Always read the reply aloud once before sending; tone is easier to hear than see."],"auto":{"trigger":{"type":"manual","detail":"User selects an email and asks for help replying"},"actions":[{"type":"ai.generate","detail":"Write a warm and a firm reply from the user's key points"},{"type":"email.draft","detail":"Save the chosen version as a draft reply"}]}},{"id":"walk-into-any-meeting-prepared-in-ten-minutes","t":"Walk into any meeting prepared in ten minutes","d":"Get a one-page brief before a meeting: the goal, key background, smart questions to ask and the outcome you want.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"Before any important meeting","steps":[{"h":"Gather what you have","b":"Open the calendar invite and copy the title, description and attendee roles. Add any related email or document text, removing anything confidential."},{"h":"Ask for a prep brief","b":"Paste it all into your AI assistant with this prompt.","p":"Help me prepare for a meeting. Details: [paste invite and background]. My role: [your role]. What I want from it: [your goal]. Give me a one-page brief: 1) The likely purpose of the meeting in one sentence. 2) Three key facts I should have to hand. 3) Five good questions to ask, most important first. 4) Two possible objections or tricky questions and short answers. 5) The single outcome I should push for, phrased as a sentence I can say at the end."},{"h":"Keep it on screen or paper","b":"Paste the brief into the calendar event's notes so it's there when the meeting starts."}],"example":"Purpose: Agree next year's cleaning contract terms. Key facts: current cost £640/month; two missed visits in Oct. Ask first: 'What can you guarantee on missed visits?' Push for: 'Can we confirm a 12-month contract with a service credit for any missed visit?'","tips":["Practise saying your outcome sentence out loud once; it makes it much easier to say in the room."],"auto":{"trigger":{"type":"calendar_event","detail":"One hour before an important meeting"},"actions":[{"type":"ai.generate","detail":"Create a one-page prep brief from the invite and background"},{"type":"notify","detail":"Send the brief to the user"}]}},{"id":"break-a-big-project-into-small-steps-with-dates","t":"Break a big project into small steps with dates","d":"Describe a project and get a step-by-step plan with milestones, deadlines worked back from your end date and the first action for today.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Sheets","Notes app"],"when":"At the start of any project that feels too big","steps":[{"h":"Describe the project","b":"Write a few lines on what you're trying to achieve, the deadline, who's helping and how much time you have each week."},{"h":"Ask for a plan","b":"Paste this prompt into your AI assistant.","p":"Help me plan this project: [describe goal]. Deadline: [date]. Time I can give it: [hours per week]. Who's involved: [people]. Break it into 4 to 6 phases. For each phase list the tasks (each under 2 hours, starting with a verb), who does it, and a target date working back from the deadline. Add a buffer week before the deadline. Highlight any task others are waiting on. Finish with the very first step I can do today in under 15 minutes."},{"h":"Put it somewhere you'll track it","b":"Copy the plan into a Google Sheet, Excel file or notes app, with a column to tick tasks off."},{"h":"Check in weekly","b":"Each week, paste what you've done and ask the AI to adjust the remaining dates."}],"example":"Phase 1 Plan (by 21 Nov): Set budget; list must-haves. Phase 2 Quotes (by 5 Dec): Contact 3 kitchen fitters; compare quotes. Phase 3 Order (by 19 Dec)... Buffer week: 2-9 Mar. First step today: Measure the kitchen walls and write them down.","tips":["If a task takes longer than two hours, ask the AI to split it again; smaller steps are easier to start."],"auto":{"trigger":{"type":"manual","detail":"User describes a new project"},"actions":[{"type":"ai.generate","detail":"Break the project into phases, tasks and dates"},{"type":"sheet.append","detail":"Add each task as a row in the project tracker"},{"type":"calendar.create","detail":"Add milestone dates to the calendar"}]}},{"id":"tell-customers-clearly-when-something-goes-wrong","t":"Tell customers clearly when something goes wrong","d":"A calm, honest message to all affected customers about a delay, outage or mistake, with versions for email, social media and your website.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Mailchimp"],"when":"When a problem affects many customers at once","steps":[{"h":"Write down the facts","b":"Note what happened, who is affected, what you're doing about it, and when you'll next update people. Stick to what you know for sure."},{"h":"Get all versions at once","b":"Paste your notes into your AI assistant with this prompt.","p":"Something has gone wrong at [business name]. Facts: [what happened]. Who is affected: [customers]. What we're doing: [actions]. When customers will hear from us next: [time]. Anything we're offering: [refund / credit / nothing yet]. Write: 1) a customer email (subject line plus under 150 words), 2) a social media post under 280 characters, 3) a two-sentence banner for our website. Be honest and specific, apologise once, do not speculate about causes we haven't confirmed, and avoid jargon. British English."},{"h":"Send it and keep your promise","b":"Send the email through Mailchimp or your usual email tool, post the update, and set a reminder for the time you said you'd update people next."}],"example":"Subject: Your order is running a few days late Hi there, our courier had a warehouse fault on Monday, so orders placed between 3 and 5 May will arrive 2 to 3 days later than planned. We're really sorry. Every affected order now has free delivery refunded, and we'll email you a fresh tracking link by Friday.","tips":["Send a short follow-up when it's fixed; customers remember that more than the problem.","If the issue involves people's personal data, speak to a professional adviser before you send anything, as there may be legal steps to follow."],"auto":{"trigger":{"type":"manual","detail":"Owner reports an incident"},"actions":[{"type":"ai.generate","detail":"Write email, social post and website banner versions"},{"type":"email.draft","detail":"Prepare the customer email for review"},{"type":"calendar.create","detail":"Add a reminder for the promised follow-up update"}]}},{"id":"find-out-why-your-sales-page-isn-t-converting","t":"Find out why your sales page isn't converting","d":"An honest review of your landing page with the top problems, a rewritten headline and clear fixes, ranked by how much difference they'll make.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant"],"when":"When visits are coming in but enquiries aren't","steps":[{"h":"Capture the page","b":"Take full screenshots of your page on a computer and on your phone, or copy all of its text. Note who the page is for and what you want visitors to do."},{"h":"Ask AI for a review","b":"Attach the screenshots or paste the text into your AI assistant with this prompt.","p":"Review my sales page as if you were a busy [ideal customer]. The goal is for visitors to [book a call / buy / sign up]. Here it is: [attach screenshots or paste text]. Give me: 1) what you understand I offer after 5 seconds, 2) the 5 biggest problems stopping people taking action, ranked by impact, each with a specific fix, 3) 3 alternative headlines that say the benefit clearly, 4) any missing trust signals (reviews, guarantees, prices, photos), 5) one thing that already works well. Be direct and specific. British English."},{"h":"Make the top two changes","b":"Fix the two highest-impact issues first, then wait a couple of weeks to see if enquiries change before doing more."}],"example":"5-second read: 'Some kind of wellness service?' Top problem: headline 'Holistic solutions for you' doesn't say what you do. Fix: 'Sports massage in Cardiff for runners and cyclists'. Problem 2: booking button only at the bottom. Fix: add it under the headline. Works well: genuine client photos.","tips":["Ask a real customer the same 5-second question; if their answer matches the AI's, you know it's right.","Change one thing at a time so you can tell what made the difference."],"auto":{"trigger":{"type":"manual","detail":"User submits a page link"},"actions":[{"type":"web.fetch","detail":"Read the page content"},{"type":"ai.generate","detail":"List ranked problems, fixes and new headlines"},{"type":"doc.create","detail":"Save the review as a checklist"}]}},{"id":"run-one-to-ones-your-team-look-forward-to","t":"Run one-to-ones your team look forward to","d":"A simple, repeatable agenda for regular one-to-ones, tailored questions for each person and a short record of what you both agreed.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Calendar","Google Docs"],"when":"Before each regular one-to-one","steps":[{"h":"Book a regular slot","b":"Set a recurring Google Calendar event, such as 30 minutes every fortnight, with each team member, and attach a shared Google Doc for notes."},{"h":"Get an agenda and questions","b":"Paste this prompt into your AI assistant.","p":"Create a 30-minute one-to-one agenda for me (a manager at a [type of business]) and a [role] who has been with us [time]. What I know: recent wins [wins], current challenges [challenges], their goals [goals]. Include: a 5-minute check-in, their topics first, progress on goals, one development question, any feedback both ways, and agreed actions. Suggest 6 open questions I could rotate over the next few months, such as about workload, learning and what support they need. Supportive tone, British English."},{"h":"Let them add topics first","b":"Paste the agenda into the shared doc a couple of days before and ask them to add what they'd like to talk about at the top."},{"h":"Record actions together","b":"At the end, write down two or three agreed actions with names and dates in the doc, so you can check them next time."}],"example":"Agenda, 14 May: 1. How are things? (5 min) 2. Ellis's topics: training budget, Friday cover 3. Goal: lead the stock count, on track 4. Question: 'What would make next month easier?' 5. Feedback both ways. Actions: Ellis books first-aid course by 31 May; I sort Friday cover rota.","tips":["Keep one-to-ones even when you're busy; cancelling them often sends the wrong message.","Keep notes respectful and factual, as the team member can see them and may ask for them later."],"auto":{"trigger":{"type":"calendar_event","detail":"Two days before each recurring one-to-one"},"actions":[{"type":"ai.generate","detail":"Prepare an agenda with last time's actions and fresh questions"},{"type":"doc.create","detail":"Add the agenda to the shared one-to-one doc"},{"type":"notify","detail":"Invite the team member to add their topics"}]}},{"id":"reply-to-instagram-comments-and-messages-faster","t":"Reply to Instagram comments and messages faster","d":"A bank of warm, ready-made replies for the questions you get most, saved in Instagram so you can answer in two taps.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Instagram"],"when":"Set up once, refresh every few months","steps":[{"h":"List your most common questions","b":"Scroll back through your comments and DMs and write down the ten questions you answer most, like prices, opening hours or delivery."},{"h":"Draft replies with AI","b":"Paste the list into your AI assistant with this prompt.","p":"I run [business] on Instagram. Here are the questions people ask most: [list]. For each, write a short reply (under 40 words) that sounds friendly and human, answers the question using these facts: [prices, hours, links, policies], and ends with a light next step. Also give each reply a 1-2 word shortcut name. Format: Shortcut | Reply. British English, no emoji overload (one at most)."},{"h":"Save them as quick replies","b":"In Instagram, professional accounts can save replies for messages: look in your settings under Business or Creator tools for saved or quick replies, then add each shortcut and reply."},{"h":"Personalise before sending","b":"When you use one, add the person's name or a detail from their message so it never feels copied and pasted."}],"example":"price | Hi! Our cut and finish starts at £38, and colour from £65. Want me to check this week's free slots for you? delivery | We post UK-wide in 2-3 working days, free over £40. Anything I can help you choose?","tips":["Never paste customers' private messages into an AI tool with their names or phone numbers; the questions alone are enough."],"auto":{"trigger":{"type":"message_received","detail":"New Instagram comment or direct message"},"actions":[{"type":"ai.classify","detail":"Match the message to a common question"},{"type":"ai.generate","detail":"Suggest a personalised reply from the saved bank"},{"type":"notify","detail":"Show the suggested reply for the user to approve"}]}},{"id":"draft-a-blog-post-from-a-few-keywords","t":"Draft a blog post from a few keywords","d":"Start with three or four keywords and end with an outlined, fully drafted blog post in Google Docs, ready for your own edit.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"Whenever you need a new article","steps":[{"h":"Choose your keywords and reader","b":"Write down the main phrase you want to be found for, two or three related phrases, and who the article is for."},{"h":"Get an outline first","b":"Ask for the outline before the full draft so you can steer it. Paste this into your AI assistant.","p":"I'm writing a blog post for [business or blog name]. Reader: [who they are and what they're struggling with]. Main keyword: [phrase]. Related phrases: [list]. Suggest 3 title options (under 60 characters, main keyword near the start) and an outline with an intro, 4-6 H2 headings, a short bullet list under each of what to cover, and a conclusion with a call to action to [action]. Note any facts or figures I'll need to check or supply."},{"h":"Adjust, then ask for the draft","b":"Change the outline as you like, then reply: 'Write the full post from this outline, 900-1,200 words, in a friendly, expert tone, short paragraphs, British English. Use my own examples where I've marked them.'"},{"h":"Edit it in Google Docs","b":"Paste the draft into a Google Doc. Add your own stories, opinions and photos; that is what makes it worth reading and stops it sounding generic."}],"example":"Title: Garden Office Planning Permission: What You Need to Know. H2s: Do you need permission at all? The 2.5 metre rule. Listed buildings and conservation areas. How to check with your council. What we do for you. CTA: Book a free site survey.","tips":["Check every fact, rule or statistic the draft includes against an official source before publishing."],"auto":{"trigger":{"type":"manual","detail":"User enters keywords and audience"},"actions":[{"type":"ai.generate","detail":"Suggest titles and an outline"},{"type":"ai.generate","detail":"Write the full draft from the approved outline"},{"type":"doc.create","detail":"Create a Google Doc with the draft"}]}},{"id":"check-product-photos-meet-listing-rules-before-uploading","t":"Check product photos meet listing rules before uploading","d":"A quick pass or fail on every product photo against marketplace rules and your own standards, with what to fix on any that fail.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera"],"when":"Before uploading product photos","steps":[{"h":"Write your checklist","b":"List the rules for where you sell (for example plain background, product fills most of the frame, no added text) plus your own standards like lighting and angles. Check the marketplace's help pages for its current image rules."},{"h":"Attach photos and check them","b":"Attach a batch of photos to your AI assistant with this prompt.","p":"Check each attached product photo against this checklist: [paste checklist]. For each photo, in order, give: Photo number | Pass or Fail | Which rules it fails | What exactly to fix (e.g. 'reshoot with more light from the left', 'crop tighter'). Then a one-line summary of the most common problem across the batch. Be strict but only judge what you can see."},{"h":"Fix and reshoot","b":"Reshoot or edit the failures, then run the check again on the new versions before uploading."}],"example":"Photo 1 | Pass. Photo 2 | Fail | background not plain, shadow on left | Move to the window and use a white card as a reflector. Photo 3 | Fail | product fills only half the frame | Crop tighter. Most common problem: harsh shadows.","tips":["AI can miss small details like a faint watermark or a scratch, so give each photo a final look yourself at full size."],"auto":{"trigger":{"type":"new_file","detail":"Photos added to the product photos folder"},"actions":[{"type":"ai.classify","detail":"Pass or fail each photo against the checklist"},{"type":"sheet.append","detail":"Log results and fixes"},{"type":"notify","detail":"Tell the user which photos need reshooting"}]}},{"id":"compare-products-side-by-side-before-you-buy","t":"Compare products side by side before you buy","d":"Get a clear comparison table of the products you're considering, covering price, features, common complaints and which suits your needs.","cat":"Research & News","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"Before any purchase over about £100","steps":[{"h":"Write down what you need","b":"List your budget, must-haves and deal-breakers. For example: 'under £400, quiet, fits a 60cm gap'."},{"h":"Ask for a comparison table","b":"Use an AI assistant with web search on, and paste this prompt with your shortlist (or ask it to suggest one).","p":"I'm choosing a [product type]. My budget is [amount], I must have [must-haves] and I want to avoid [deal-breakers]. Compare these options: [product 1], [product 2], [product 3] (or suggest 3 if I haven't listed any). Make a table with: price range, key specs, warranty, what owners praise, what owners complain about most, and a link to the manufacturer's page. Then tell me which fits my needs best and why. Say where information was hard to find or might be out of date."},{"h":"Check price and specs at the source","b":"Prices and model numbers change often. Confirm the details on the manufacturer's or retailer's page before you buy."},{"h":"Read a few real reviews","b":"Skim three or four recent owner reviews of your top choice to make sure the complaints the AI found are real and still relevant."}],"example":"| Model | Price | Noise | Warranty | Common complaint | | Brook 7 | £380 | 44dB | 2 yrs | Slow eco cycle | | Vela S | £349 | 47dB | 5 yrs | Flimsy cutlery tray | Best fit: Vela S - under budget, longest warranty, and the tray issue is minor.","tips":["Ask it to flag models that have been replaced by newer versions, so you don't pay full price for an old one."],"auto":{"trigger":{"type":"manual","detail":"User lists products and needs"},"actions":[{"type":"web.fetch","detail":"Look up specs, prices and reviews"},{"type":"ai.generate","detail":"Build a comparison table and a recommendation"},{"type":"notify","detail":"Send the comparison to the user"}]}},{"id":"see-exactly-what-changed-between-two-document-versions","t":"See exactly what changed between two document versions","d":"Compare two versions of a document and get a clear list of every meaningful change, so nothing slips through unnoticed.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":5,"tools":["Word","Google Docs","AI assistant"],"when":"When someone sends back an edited document","steps":[{"h":"Try the built-in compare first","b":"Word has a Compare feature on its Review tab that marks every change. Google Docs has 'Compare documents' in its Tools menu. Use these for an exact line-by-line view."},{"h":"Get a plain-English summary","b":"Upload both versions to your AI assistant and paste this prompt to understand what the changes mean.","p":"Compare these two versions of [document name]: version A (the original) and version B (the new one). List every meaningful change in a table: Section, What it said before, What it says now, Why it might matter. Ignore pure formatting and typo fixes but mention how many there were in one line at the end. Flag any change to dates, amounts, names, obligations or deadlines at the top."},{"h":"Check the flagged changes","b":"Look at each flagged change in the actual document using the built-in compare view. Ask the other person about anything you didn't agree."}],"example":"Flagged: payment terms changed from 30 to 45 days (section 4). Deadline moved from 1 March to 15 March (section 2). Other changes: 'should' changed to 'must' in section 6, making the step compulsory. Formatting: 14 minor typo and layout fixes.","tips":["For contracts or anything legally binding, have a solicitor review changes you're unsure about."],"auto":{"trigger":{"type":"new_file","detail":"A new version of a tracked document is saved"},"actions":[{"type":"ai.extract","detail":"Find the differences between versions"},{"type":"ai.summarize","detail":"List meaningful changes and flag key terms"},{"type":"notify","detail":"Send the change summary"}]}},{"id":"prepare-for-a-supplier-price-negotiation-with-confidence","t":"Prepare for a supplier price negotiation with confidence","d":"Go into a supplier conversation with your facts, a fair target, alternatives and a polite email or call script ready to use.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Gmail"],"when":"When a supplier raises prices or a contract is due for renewal","steps":[{"h":"Gather the facts","b":"Note what you buy, how much you spend per year, how long you've been a customer, the new price and any quotes from other suppliers."},{"h":"Plan your approach","b":"Paste this prompt into your AI assistant.","p":"Help me prepare to negotiate with a supplier. Facts: I buy [what] from them, spending about [amount] a year, for [number] years. They want to raise prices by [amount or %] from [date]. Alternatives I've found: [other quotes or 'none yet']. Give me: 1) my strongest points, 2) a realistic target outcome and a fallback, 3) 4 things I could offer instead of paying more (e.g. longer contract, bigger orders, faster payment), 4) a short, polite email asking to discuss it, 5) a 5-line call script with responses if they say no."},{"h":"Adjust to your relationship","b":"Tone down or firm up the wording so it sounds like you. A good long-term relationship is often worth more than a small saving."},{"h":"Send or call, then confirm in writing","b":"Send the email or make the call, then email a summary of anything agreed."}],"example":"Strongest points: 6 years as a customer, always pay within 14 days, two cheaper quotes. Target: hold price until April; fallback: 3% rise instead of 8%. Offer: a 12-month commitment. Email opener: 'Thanks for letting us know about the new prices. Before they take effect, could we talk about options?'","tips":["Don't forward other suppliers' quotes in full; mention the price range instead."],"auto":{"trigger":{"type":"new_email","detail":"A supplier price-change notice arrives"},"actions":[{"type":"ai.extract","detail":"Pull out the old price, new price and start date"},{"type":"ai.generate","detail":"Prepare negotiation points and a reply"},{"type":"email.draft","detail":"Draft the email asking to discuss"}]}},{"id":"plan-a-week-of-family-dinners-on-a-set-budget","t":"Plan a week of family dinners on a set budget","d":"Get seven dinners that fit your weekly food budget, reuse ingredients across meals and come with one shopping list.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"Once a week before you shop","steps":[{"h":"Note your budget and household","b":"Jot down how much you want to spend on dinners this week, how many people you're feeding and any allergies or dislikes."},{"h":"Ask for a budget meal plan","b":"Open ChatGPT, Claude or Gemini and paste this prompt with your details filled in.","p":"Plan 7 dinners for [number] people (including [ages of children, if any]) with a total food budget of about [amount] for the week. We shop at [supermarket type, e.g. a big supermarket or a discount store]. Avoid [allergies and dislikes]. Reuse ingredients across meals so nothing is wasted, include at least 2 meat-free dinners, and keep weeknight meals under [30] minutes. Give me: 1) a table with day, dinner, main ingredients and rough cost; 2) one shopping list grouped by aisle with quantities; 3) which leftovers to save for the next day."},{"h":"Check it against what you have","b":"Cross off anything already in your cupboards, then ask the assistant to recalculate the list without those items."},{"h":"Save the plan and list","b":"Copy the plan into your notes app and stick the shopping list somewhere the whole household can see it."}],"example":"Mon: Lentil & sweet potato curry (about 4.20). Tue: Leftover curry wraps with salad. Wed: Sausage & bean one-pot... Shopping: Veg - 2 onions, 1kg sweet potato, garlic. Tins - 2 chopped tomatoes, 1 coconut milk. Leftovers: save half the rice for Thursday's egg fried rice.","tips":["Prices are estimates, so treat the costs as a rough guide and check your supermarket's app for current prices.","Tell it which meals were a hit so next week's plan repeats the favourites."],"auto":{"trigger":{"type":"schedule","detail":"Every Saturday at 10am"},"actions":[{"type":"ai.generate","detail":"Plan 7 budget dinners and a shopping list from saved household preferences"},{"type":"list.add","detail":"Add the shopping items to the household list"},{"type":"notify","detail":"Send the week's dinner plan to the user"}]}},{"id":"get-a-day-by-day-itinerary-that-fits-your-pace","t":"Get a day-by-day itinerary that fits your pace","d":"Turn your dates, interests and energy levels into a realistic daily plan with rest time and a rainy-day backup.","cat":"Travel","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Maps"],"when":"A few weeks before a trip","steps":[{"h":"Jot down the basics","b":"Note where you're staying, your dates, arrival and departure times, who's going and what you enjoy."},{"h":"Ask for a paced itinerary","b":"Paste this prompt into your AI assistant.","p":"Plan a [number]-day trip to [destination] for [who is going]. We arrive [day and time] and leave [day and time], staying near [area or hotel]. We enjoy [interests] and prefer a [relaxed/moderate/packed] pace with [amount] of walking. For each day give: morning, afternoon and evening, grouped by area to cut travel time, how to get between places, one rainy-day alternative, and a rough daily spend. Mark anything that usually needs booking ahead."},{"h":"Check the details","b":"Look up each place on its official website for current opening times, prices and booking rules, as these change often."},{"h":"Pin it to a map","b":"Save each stop to a Google Maps list for the trip so you can see what's nearby while you're there."}],"example":"Day 2 (Old Town): 9:30 castle (book ahead, allow 2h), lunch near the square, 2pm river walk, 4pm rest at hotel, 7pm dinner in the market district. Rainy day: national museum. Rough spend: 60 for two.","tips":["AI can suggest places that have closed or changed hours, so always check official sites before you go."],"auto":{"trigger":{"type":"manual","detail":"User enters destination, dates and interests"},"actions":[{"type":"ai.generate","detail":"Create a paced day-by-day itinerary"},{"type":"doc.create","detail":"Save the itinerary as a trip document"}]}},{"id":"get-a-home-workout-plan-that-fits-your-week","t":"Get a home workout plan that fits your week","d":"Get a simple four-week workout plan for your fitness level, space and kit, with sessions that fit the time you have.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"When you want to start or restart exercising","steps":[{"h":"Be honest about your starting point","b":"Note how active you are now, how many days and minutes you can spare, what space and equipment you have, and anything you want to avoid."},{"h":"Ask for a plan","b":"Paste this prompt into your AI assistant.","p":"Create a 4-week home workout plan for a [beginner/returning] exerciser. I can do [number] sessions a week of [minutes] minutes. Space: [e.g. living room]. Equipment: [none/dumbbells/resistance band]. Goal: [e.g. feel stronger, more energy]. Avoid: [e.g. jumping, floor work]. For each session give a warm-up, the exercises with sets, reps or time, an easier and harder version of each, and a cool-down. Build up gradually each week. Remind me to stop if anything hurts."},{"h":"Keep it where you'll see it","b":"Save the plan in your notes app and put your session times in your calendar like appointments."}],"example":"Week 1, Session A (20 mins): 5-min march and arm circles. Sit-to-stand x10 (easier: higher chair), wall press-ups x8, glute bridge x10, 20-sec plank on knees. 2 rounds. Cool down: 3 stretches, 30 sec each. Week 2: add a third round.","tips":["If you have a health condition, are pregnant or haven't exercised in a long time, check with your GP or a qualified professional before starting."],"auto":{"trigger":{"type":"manual","detail":"User enters fitness level, time and equipment"},"actions":[{"type":"ai.generate","detail":"Create a 4-week progressive home workout plan"},{"type":"calendar.create","detail":"Add workout sessions to the user's calendar"}]}},{"id":"compare-broadband-phone-or-energy-deals-properly","t":"Compare broadband, phone or energy deals properly","d":"A side-by-side comparison of the deals you're considering, with the true total cost over the contract and the catches in the small print.","cat":"Money","side":"life","lvl":"Beginner","mins":15,"tools":["AI assistant"],"when":"When a contract is ending or a price goes up","steps":[{"h":"Collect the offers","b":"Copy the details of two to five deals from provider websites or comparison sites, including the monthly price, contract length, setup fees and any price rise terms."},{"h":"Note what you need","b":"Write down what matters to you, such as minimum speed, data allowance, no long contract, or green energy."},{"h":"Ask for a fair comparison","b":"Paste everything into your AI assistant with this prompt.","p":"I'm comparing these [broadband / mobile / energy] deals. My needs are: [list]. My current deal costs [amount] a month and ends on [date]. [paste each deal's details] For each deal, calculate the total cost over the full contract including setup fees, any known mid-contract price rises and exit fees. Make a comparison table with: provider, monthly price, contract length, total contract cost, key restrictions, and anything in the terms I should watch out for. Then say which deal best matches my needs and why, and what questions I should ask before signing."},{"h":"Check the figures yourself","b":"Confirm prices and terms on the provider's own website before you switch, since deals change quickly."},{"h":"Use it to haggle","b":"Ask the AI to write a short script you can use when calling your current provider to ask them to match the best offer."}],"example":"Deal A: £27/mo x 24 = £648 + £0 setup, price rises each April. Deal B: £32/mo x 12 = £384 + £20 setup, no rise. Deal C: £24/mo x 18 = £432 + £35 router. Best fit for 'no long contract': B. Ask A whether the April rise is a fixed amount.","tips":["The AI only knows what you paste, so include the full terms, not just the headline price.","Ask your current provider for a retention offer before switching. It's often cheaper."],"auto":{"trigger":{"type":"manual","detail":"User starts a deal comparison"},"actions":[{"type":"ai.generate","detail":"Calculate total contract costs and compare deals"},{"type":"doc.create","detail":"Save the comparison and haggling script"},{"type":"calendar.create","detail":"Add a reminder a month before the new contract ends"}]}},{"id":"practise-maths-with-questions-made-for-you","t":"Practise maths with questions made for you","d":"Fresh practice questions on exactly the maths topic you're working on, getting harder as you improve, with worked solutions.","cat":"Learning","side":"life","lvl":"Beginner","mins":5,"tools":["AI assistant"],"when":"When you need extra practice","steps":[{"h":"Pick the topic","b":"Choose one topic, like percentages, fractions or solving equations, and note the level you're working at."},{"h":"Start a practice session","b":"Paste this prompt into your AI assistant.","p":"Give me practice questions on [maths topic] at [level, for example Year 8, GCSE Foundation, adult brush-up]. Start easy. Give one question at a time and wait for my answer. If I'm right, make the next one slightly harder. If I'm wrong, show a clear worked solution step by step, then give me a similar question to try again. Include some word problems from everyday life like shopping or cooking. After 10 questions, tell me what I'm good at and what to practise next."},{"h":"Work it out on paper","b":"Do the working on paper rather than in your head, then type your final answer."},{"h":"Double-check calculations","b":"If an answer seems wrong, check it with a calculator. AI can occasionally make arithmetic slips."}],"example":"Q4: A jacket costs £60 and is reduced by 15%. What's the sale price? You: £51. Correct! 15% of 60 = 9, and 60 - 9 = 51. Next (harder): A price rises by 20% to £84. What was the original price?","tips":["Ask the AI to double-check its own working if something looks off.","For school work, ask it to use the same method your teacher uses."],"auto":{"trigger":{"type":"manual","detail":"User picks a maths topic"},"actions":[{"type":"ai.generate","detail":"Generate adaptive practice questions"},{"type":"ai.summarize","detail":"Report strengths and topics to practise"},{"type":"sheet.append","detail":"Log the session score"}]}},{"id":"refresh-your-linkedin-profile-so-recruiters-find-you","t":"Refresh your LinkedIn profile so recruiters find you","d":"A clearer LinkedIn headline, About section and experience bullets based on your real background and the roles you want next.","cat":"Careers","side":"life","lvl":"Beginner","mins":20,"tools":["LinkedIn","AI assistant"],"when":"Before a job search, then twice a year","steps":[{"h":"Copy your current profile","b":"Copy your headline, About section and the text of your last two or three roles from LinkedIn."},{"h":"Ask for improvements","b":"Paste them into your AI assistant with this prompt.","p":"Help me improve my LinkedIn profile. I want to be found for roles like [target roles] in [sector or location]. Here's my current profile: [paste]. Using only my real experience, give me: 3 headline options under 220 characters that include words recruiters search for, an About section under 200 words in first person and a friendly tone, 3 to 4 bullet points for each of my last two roles focusing on results, and 10 skills to add that I've clearly shown. Don't invent achievements; ask me questions if a result could be made more specific."},{"h":"Add real numbers","b":"Answer the AI's questions with genuine figures, such as team size, customers served or time saved, to make your bullets stronger."},{"h":"Update and switch on Open to Work","b":"Paste the changes into LinkedIn. If you're job hunting, consider the Open to Work setting, which can be shown to recruiters only."}],"example":"Headline: Customer service team leader | Training and coaching | Moving into Learning & Development. About: 'For six years I've helped new starters find their feet...' Bullet: 'Trained 30+ new advisors, with 90% passing probation first time.'","tips":["Keep your LinkedIn and CV consistent. Recruiters compare them.","Choose the recruiters-only Open to Work option if you don't want your current employer to see it."],"auto":{"trigger":{"type":"schedule","detail":"Every six months"},"actions":[{"type":"notify","detail":"Remind the user to refresh their profile"},{"type":"ai.generate","detail":"Suggest headline, About and experience updates"},{"type":"doc.create","detail":"Save the suggested profile text"}]}},{"id":"sort-out-your-phone-photos-and-files","t":"Sort out your phone photos and files","d":"A simple folder system for your photos, documents and downloads, and a step-by-step plan for tidying the mess you have now.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Drive","OneDrive"],"when":"Once, then a quick monthly tidy","steps":[{"h":"Take stock","b":"Note where your stuff lives: phone photos, cloud storage, downloads folder, old laptop, email attachments. Rough sizes help if you can see them."},{"h":"Get a plan","b":"Paste your notes into your AI assistant with this prompt.","p":"Help me organise my digital life. Here's where my files and photos are: [describe]. I mostly need to find: [for example family photos, house documents, kids' school stuff, work-related files]. Suggest a simple folder structure no more than 2 levels deep, with clear names. Then give me a step-by-step plan over 4 short sessions to tidy up: what to delete first (screenshots, duplicates, blurry photos), what to move, and how to back up. Include a 10-minute monthly routine to keep it tidy. Keep it non-technical."},{"h":"Use built-in helpers","b":"Most phone photo apps can show duplicates and screenshots in one place. Look in your photo app's albums or utilities to clear these quickly."},{"h":"Back up what matters","b":"Make sure important photos and documents are backed up in at least one cloud service such as Google Drive, OneDrive or iCloud."}],"example":"Folders: Home (insurance, tenancy, appliance manuals), Money (payslips, statements), Family (school, health, IDs), Photos/2026, Photos/2025... Session 1: delete screenshots and duplicates (around 2,000 photos). Monthly: empty downloads, file new documents.","tips":["Store scans of passports and ID in a secure, password-protected place with two-step login switched on.","Do one session at a time. Trying to sort everything in one go usually stalls."],"auto":{"trigger":{"type":"schedule","detail":"First Saturday of each month"},"actions":[{"type":"notify","detail":"Remind the user to do the monthly tidy"},{"type":"ai.generate","detail":"Give a short checklist for this month's tidy"},{"type":"list.add","detail":"Add tidy tasks to the to-do list"}]}},{"id":"write-an-out-of-office-reply-that-helps-people","t":"Write an out-of-office reply that helps people","d":"Get a clear, friendly out-of-office message with your return date, who to contact and what will wait, ready to switch on.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":5,"tools":["AI assistant","Gmail","Outlook"],"when":"Before any holiday, leave or busy period","steps":[{"h":"Gather the details","b":"Note your away dates, the date you'll reply by, who covers urgent matters and how to reach them."},{"h":"Ask AI to write it","b":"Paste this prompt into your AI assistant.","p":"Write an out-of-office email reply. I'm away from [date] to [date] and will reply from [date]. For urgent [topics], contact [name, role, email]. Things that can wait: [e.g. invoices, general questions]. Audience: [clients / colleagues / both]. Keep it under 70 words, warm but businesslike, no jokes. Also give me a shorter 25-word version for internal colleagues."},{"h":"Switch it on with dates","b":"In Gmail, find Vacation responder in settings and set the first and last day. In Outlook, use Automatic replies and tick the option to send only during a time range."}],"example":"Thanks for your email. I'm away until Monday 5 January and will reply by Wednesday 7th. For anything urgent about orders, please contact Maya Patel (Customer Team) at orders@example.com. Everything else will be waiting safely for me.","tips":["Set the reply to start the evening before you leave so late messages get it too.","Avoid saying exactly where you are or that your home is empty."],"auto":{"trigger":{"type":"calendar_event","detail":"A holiday or leave event is added to the calendar"},"actions":[{"type":"ai.generate","detail":"Write an out-of-office reply with dates and cover contact"},{"type":"notify","detail":"Remind the user to switch it on the day before"}]}},{"id":"protect-time-for-focused-work-every-week","t":"Protect time for focused work every week","d":"Set up recurring focus blocks in your calendar that decline clashing meetings, sized and placed to suit how you work.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":10,"tools":["Google Calendar","Outlook Calendar","AI assistant"],"when":"Set up once, review monthly","steps":[{"h":"Work out your best hours","b":"Ask your AI assistant to help you decide where focus time should go.","p":"Help me plan weekly focus time. My usual meetings: [e.g. Mon 10am team, Wed 2pm 1:1s]. My best concentration time: [e.g. mornings]. Work I need deep focus for: [tasks]. Suggest 3 to 4 recurring focus blocks per week, each 90 minutes to 2 hours, avoiding my meetings. Give each a clear name that tells colleagues what I'm doing, and a one-line note for the event description explaining how to reach me if it's urgent."},{"h":"Create the blocks","b":"In Google Calendar, choose 'Focus time' as the event type if your account has it, which can auto-decline meetings. In Outlook, create a recurring event marked as Busy, or use Viva Insights focus time if your plan includes it."},{"h":"Silence notifications","b":"Turn on Do Not Disturb on your phone and computer during the blocks, and pause chat notifications in Slack or Teams."}],"example":"Tue 9:00-11:00 Focus: quarterly report. Thu 9:00-11:00 Focus: client proposals. Fri 13:30-15:00 Focus: planning next week. Description: 'Heads-down time. For anything urgent, call me on my mobile.'","tips":["Treat focus blocks like a meeting with your most important client: move them, don't delete them."],"auto":{"trigger":{"type":"schedule","detail":"Every Friday afternoon"},"actions":[{"type":"ai.generate","detail":"Suggest focus blocks for next week around existing meetings"},{"type":"calendar.create","detail":"Add the focus blocks to the calendar"}]}},{"id":"make-a-tough-decision-with-a-clear-comparison","t":"Make a tough decision with a clear comparison","d":"Lay out your options and get a simple scoring table, the trade-offs in plain words and questions to settle what matters most.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"When you're stuck between two or more choices","steps":[{"h":"Write down the options","b":"List each option and what you know about it, plus what you care about most (cost, time, stress, family, growth)."},{"h":"Ask for a comparison","b":"Paste this prompt into your AI assistant.","p":"Help me decide between these options: [list options with key facts]. What matters to me, in order: [your priorities]. 1) Ask me up to 3 questions first if anything important is missing. 2) Then make a table scoring each option 1 to 5 on each priority, weighted by my order, with a total. 3) Describe the biggest trade-off of each option in one sentence. 4) Tell me what would have to be true for each option to be the right one. Don't make the decision for me."},{"h":"Sleep on it","b":"Read the results the next morning. If the top score feels wrong, that tells you something about what you really want."}],"example":"Options: Job A (more pay, 1hr commute) vs Job B (less pay, hybrid). Weighted totals: A 31, B 36. Trade-off A: £6k more but 10 hrs a week travelling. B is right if flexibility for school pick-ups matters more than savings this year.","tips":["For big money, health or legal decisions, use this to clarify your thinking, then check with a qualified professional."],"auto":{"trigger":{"type":"manual","detail":"User lists options and priorities"},"actions":[{"type":"ai.generate","detail":"Score each option and explain the trade-offs"},{"type":"doc.create","detail":"Save the comparison for later"}]}},{"id":"set-up-friendly-whatsapp-business-auto-replies","t":"Set up friendly WhatsApp Business auto-replies","d":"Write a welcome message, an out-of-hours away message and a set of quick replies so WhatsApp customers always get a helpful first response.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","WhatsApp"],"when":"Once, then update when your hours or offers change","steps":[{"h":"List what people message you about","b":"Scroll through recent WhatsApp chats and note the 5 to 8 questions that come up most, such as opening hours, prices, booking and delivery."},{"h":"Ask your AI assistant to write the messages","b":"Paste this prompt into ChatGPT, Claude or Gemini.","p":"I run [business type] and use WhatsApp Business. My opening hours: [hours]. Common questions: [list]. Write: 1) a greeting message for first-time chatters (under 40 words), 2) an away message for outside hours that says when I'll reply and where to find urgent info (under 40 words), 3) a quick reply for each common question (under 50 words each), with a short shortcut word for each, like /hours or /prices. Tone: friendly, local, British English. Use [brackets] where I need to add details."},{"h":"Add them in WhatsApp Business","b":"In the WhatsApp Business app, open Business tools and set up the Greeting message, Away message and Quick replies. Paste each message and its shortcut."},{"h":"Test it from another phone","b":"Ask a friend to message you, then try typing / in a chat to check your quick replies appear."}],"example":"Away message: Thanks for your message! We're closed right now but will reply by 10am tomorrow. Opening times and prices are on our catalogue. /booking: You can book a slot here [link]. Pick any time that suits and you'll get a confirmation straight away.","tips":["These features are in the free WhatsApp Business app, not regular WhatsApp, so switch if you're using your personal account for work.","Keep the away message honest about reply times; a promise you keep beats a fast one you miss."],"auto":{"trigger":{"type":"manual","detail":"Owner updates hours or offers"},"actions":[{"type":"ai.generate","detail":"Rewrite greeting, away and quick reply messages with the new details"},{"type":"notify","detail":"Remind the owner to paste them into WhatsApp Business"}]}},{"id":"decide-quickly-whether-a-tender-is-worth-bidding-for","t":"Decide quickly whether a tender is worth bidding for","d":"A short summary of a tender or request for proposal with deadlines, requirements, scoring and a clear bid or no-bid checklist.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Drive"],"when":"When a tender or big client brief lands in your inbox","steps":[{"h":"Collect the documents","b":"Save the tender documents, usually PDFs, into one Google Drive folder so nothing gets lost."},{"h":"Upload and ask for a summary","b":"Upload the files to ChatGPT, Claude or Gemini (or connect your Drive if your plan allows) and use this prompt.","p":"Summarise this tender for a small business deciding whether to bid. Give: 1) what the buyer wants in 5 bullet points, 2) all deadlines, including clarification questions, as a table, 3) must-have requirements (insurance, certifications, turnover, experience), 4) how bids are scored, with weightings, 5) the budget or contract value if stated, 6) anything unusual or risky. Then score our fit from 1 to 10 against our profile: [your size, experience, certifications, capacity] with reasons. Quote page numbers for each key point. If something isn't in the documents, say 'not stated'."},{"h":"Check the key facts in the original","b":"Open the pages the AI quoted for deadlines and must-haves and confirm them yourself."},{"h":"Make the call","b":"If any must-have is missing or the deadline is too tight, pass and note why so you can spot better tenders next time."}],"example":"Buyer: council seeks a caterer for 12 community events. Deadline: 5pm 14 March (questions by 3 March). Must-haves: £5m public liability, food hygiene rating 4+. Scoring: quality 60%, price 40%. Value: about £18,000. Risk: 30-day payment terms. Fit: 7/10, meets all must-haves but tight staffing in June.","tips":["Check the tender's rules on confidentiality before uploading documents to an AI tool.","Insurance and legal requirements are worth confirming with your broker or adviser before you commit."],"auto":{"trigger":{"type":"new_file","detail":"Tender documents are added to the Tenders folder"},"actions":[{"type":"ai.extract","detail":"Pull out deadlines, requirements, scoring and value"},{"type":"ai.generate","detail":"Score fit and write a bid or no-bid summary"},{"type":"calendar.create","detail":"Add the tender deadlines to the calendar"}]}},{"id":"decide-what-good-looks-like-before-reading-cvs","t":"Decide what good looks like before reading CVs","d":"A fair scoring sheet with clear criteria and what each score means, agreed before you see any applications, so every candidate is judged the same way.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Sheets"],"when":"Before the closing date of every vacancy","steps":[{"h":"Pick 4 to 6 criteria from the job ad","b":"Use the must-haves from your advert, such as 'experience handling customer complaints'. Avoid vague ones like 'good culture fit'."},{"h":"Ask AI to turn them into a rubric","b":"Paste your criteria into your AI assistant with this prompt.","p":"Create a scoring rubric for shortlisting candidates for [job title]. Criteria: [list]. For each criterion, describe what a score of 1 (no evidence), 2 (some evidence), 3 (clear evidence) and 4 (strong, repeated evidence) looks like, with a short example of the kind of evidence that counts. Make sure every criterion relates to the job itself, and point out any that could unfairly disadvantage people because of age, sex, disability, race, religion or other protected characteristics. Format as a table I can paste into a spreadsheet."},{"h":"Build the scoring sheet","b":"Paste the rubric into a Google Sheet tab, and make a second tab with a row per candidate, a column per criterion, a total, and a notes column for evidence."},{"h":"Agree it with anyone else involved","b":"If others are shortlisting with you, agree the rubric together and score separately before comparing."}],"example":"Criterion: Handling unhappy customers. 1 - no mention. 2 - mentions customer-facing work. 3 - describes resolving a complaint. 4 - several examples, including calming a tense situation and a result. Candidate C-03: 3 (evidence: 'resolved delivery complaints in a busy retail store').","tips":["Give candidates a code, like C-01, and score before looking at names, photos or ages where you can.","A person must make every shortlisting decision; the rubric is there to make human judgement more consistent."],"auto":{"trigger":{"type":"manual","detail":"Manager confirms the job's must-have criteria"},"actions":[{"type":"ai.generate","detail":"Create a 1 to 4 scoring rubric for each criterion"},{"type":"ai.classify","detail":"Flag criteria that may be unfair or not job-related"},{"type":"sheet.append","detail":"Set up the scoring sheet with rubric and candidate rows"}]}},{"id":"turn-customer-reviews-into-social-proof-posts","t":"Turn customer reviews into social proof posts","d":"Your best reviews become eye-catching quote graphics and captions that show new customers why people love you.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Canva"],"when":"Once a month","steps":[{"h":"Collect your best reviews","b":"Copy five to ten recent reviews from Google, your shop or emails. Use only the reviewer's first name or initials."},{"h":"Pick the strongest lines","b":"Paste the reviews into your AI assistant with this prompt.","p":"Here are customer reviews for [business]: [paste reviews, first names only]. 1) Pick the 5 most persuasive and pull out a short quote from each (max 20 words, using their exact words, no changes to meaning). 2) For each, note which worry it answers for a new customer (price, quality, trust, speed...). 3) Write a caption for each (under 50 words) that adds context and ends with a gentle call to action. Output as a numbered list: Quote | Name | Worry answered | Caption."},{"h":"Design quote graphics","b":"In Canva, search for a 'testimonial' or 'quote' template, add the quote and first name, and duplicate it for the others so they match."},{"h":"Share them through the month","b":"Post one a week. Check the reviewer is happy to be featured if the review came from a private email."}],"example":"Quote: 'They fixed in an hour what another firm couldn't in a week.' - Priya | Worry: speed | Caption: 'When your laptop dies the day before a deadline, every hour counts. Book a same-day repair through the link in bio.'","tips":["Never edit a quote to say something the customer didn't; shortening is fine, rewording isn't."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each month"},"actions":[{"type":"ai.extract","detail":"Pull the best short quotes from new reviews"},{"type":"ai.generate","detail":"Write a caption for each quote"},{"type":"list.add","detail":"Add four quote posts to the month's content list"}]}},{"id":"find-real-customer-problems-to-write-about-online","t":"Find real customer problems to write about online","d":"A list of the questions and frustrations people share in public forums about your field, turned into article and product ideas.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Sheets"],"when":"Once a quarter, or when you're short of ideas","steps":[{"h":"Find where people talk","b":"Search Google for your topic plus 'forum' or 'reddit', and look at community groups and question sites where your customers ask for help."},{"h":"Copy the discussions","b":"Copy the text of 10 to 20 relevant threads or questions. Leave out usernames and anything personal."},{"h":"Ask the AI to find patterns","b":"Paste the text into your AI assistant with this prompt.","p":"Here are public forum posts where people discuss [topic]: [paste, usernames removed]. Identify: 1) the 10 most common problems or questions, ranked by how often they appear; 2) the exact words people use to describe each (short quotes); 3) what they've already tried that didn't work; 4) for each problem, one article title I could write and one product or service idea for [business]. Output as a table."},{"h":"Save the best ideas","b":"Paste the table into Google Sheets and add the ideas to your content plan."}],"example":"Problem: 'My sourdough is always flat' (seen 14 times) | People say 'pancake', 'no oven spring' | Tried: more yeast, hotter oven | Article: 'Flat sourdough? It's probably your proving time' | Product idea: proving basket starter kit.","tips":["Use the customers' own phrases in your headings; they're the words people type into search."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each quarter"},"actions":[{"type":"web.fetch","detail":"Collect public forum threads on the topic"},{"type":"ai.extract","detail":"Pull out recurring problems and phrases"},{"type":"sheet.append","detail":"Add problems and article ideas to the ideas sheet"}]}},{"id":"find-video-ideas-people-in-your-niche-want","t":"Find video ideas people in your niche want","d":"A list of 20 video ideas based on what people actually search for on YouTube, with suggested titles and the angle to take.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":15,"tools":["YouTube","AI assistant"],"when":"When planning your next batch of videos","steps":[{"h":"Collect YouTube search suggestions","b":"Type your topic into the YouTube search bar slowly and note the suggestions. Try adding 'how to', 'best', 'for beginners' and 'vs'. Also note titles of popular recent videos in your niche."},{"h":"Ask the AI to turn them into ideas","b":"Paste what you found into your AI assistant with this prompt.","p":"My YouTube channel covers [topic] for [audience]. Here are YouTube search suggestions and popular video titles I found: [paste]. Give me 20 video ideas as a table: Working title (under 60 characters), The question it answers, My angle (how I can make it different given [your experience or style]), Format (tutorial, review, story, list), Difficulty to film (easy/medium/hard). Group them into 3-4 themes. Don't copy existing titles."},{"h":"Pick three to film","b":"Choose the easiest-to-film ideas from your strongest theme and add them to your calendar."}],"example":"Theme: Beginner baking. 'Why your cakes sink in the middle (and the fix)' | answers 'cake sinking' | angle: test 3 common causes side by side | Tutorial | Easy. 'Bread maker vs by hand: a real taste test' | Review | Medium.","tips":["Check YouTube Studio's Research tab, if your channel has it, to see what your own viewers are searching for."],"auto":{"trigger":{"type":"schedule","detail":"First of each month"},"actions":[{"type":"web.fetch","detail":"Gather search suggestions for the channel topic"},{"type":"ai.generate","detail":"Turn them into 20 grouped video ideas"},{"type":"sheet.append","detail":"Add ideas to the video plan sheet"}]}},{"id":"find-out-what-real-people-say-about-something","t":"Find out what real people say about something","d":"Paste forum threads and comments about a product, place or topic and get a summary of common opinions, recurring problems and useful tips.","cat":"Research & News","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"When you want honest opinions, not adverts","steps":[{"h":"Find two or three busy threads","b":"Search the web for your topic plus 'forum' or 'reddit' and open a few long, recent discussions."},{"h":"Copy the comments","b":"Copy the text of each thread into a single document. Note the date of each thread."},{"h":"Ask for a digest","b":"Paste it all into your AI assistant with this prompt.","p":"Below are online discussions about [topic]. Summarise what people actually say: 1) the most common opinions, with roughly how many commenters share each, 2) recurring problems or complaints, 3) practical tips people recommend, 4) any disagreements, 5) comments that seem like adverts or from people with something to sell. Use short quotes as evidence. These are personal opinions, not facts, so label them that way. [paste threads]"},{"h":"Weigh it up","b":"Treat this as a sense of the crowd, not proof. Forum posts can be old, one-sided or wrong, so check key facts elsewhere."}],"example":"Common view (about 12 of 20 commenters): the campsite is lovely but the showers are cold after 8am. Tip: book pitches 40-45 for shade. Disagreement: how dog-friendly it is. Possible advert: one user linking to a rental site in every post.","tips":["Remove usernames before pasting if you plan to share the summary with others."],"auto":{"trigger":{"type":"manual","detail":"User names a topic or shares thread links"},"actions":[{"type":"web.fetch","detail":"Read the discussion threads"},{"type":"ai.summarize","detail":"Group common opinions, problems and tips"},{"type":"notify","detail":"Send the digest to the user"}]}},{"id":"turn-handwritten-notes-into-a-tidy-typed-document","t":"Turn handwritten notes into a tidy typed document","d":"Photograph handwritten notes, whiteboards or old letters and get clean, organised typed text you can edit, search and share.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":5,"tools":["Phone camera","AI assistant","Google Docs"],"when":"After a workshop, lecture or brainstorm","steps":[{"h":"Take clear photos","b":"Photograph each page straight on in good light, with the whole page in frame. One photo per page works best."},{"h":"Ask for a transcription","b":"Upload the photos to your AI assistant with this prompt.","p":"Transcribe the handwriting in these photos exactly, in page order. Then underneath, give me a tidied version: fix obvious spelling slips, organise it under clear headings, turn lists into bullet points, and pull out any action items or dates into a separate list. Mark any words you can't read as [unclear] rather than guessing. Don't add anything that isn't in the notes."},{"h":"Check the [unclear] bits","b":"Look at the original pages for anything marked [unclear] and fill it in."},{"h":"Save it","b":"Paste the tidied version into a Google Doc and give it a dated title so it's easy to search for."}],"example":"Workshop notes, 6 Nov. Ideas for spring fair: plant swap, kids' trail, local band [unclear name]. Budget: approx £600. Actions: Sam to call the school about the field by 20 Nov; book PA system.","tips":["If the notes are about other people (for example patients or pupils), remove names before uploading."],"auto":{"trigger":{"type":"new_file","detail":"Photos of notes are uploaded"},"actions":[{"type":"ai.extract","detail":"Transcribe the handwriting"},{"type":"ai.generate","detail":"Organise into headings and actions"},{"type":"doc.create","detail":"Save the typed notes as a document"}]}},{"id":"write-down-how-you-do-a-task-just-once","t":"Write down how you do a task, just once","d":"Talk through a recurring admin task and get a clear step-by-step guide, so anyone can cover it when you're away.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":15,"tools":["Voice notes","AI assistant","Google Docs"],"when":"Next time you do a recurring task","steps":[{"h":"Talk it through as you work","b":"Next time you do the task (like paying suppliers or closing up for the month), record a voice note describing each step as you go, including the little checks you do."},{"h":"Turn it into a guide","b":"Many phones can transcribe voice notes, or you can upload the recording to your AI assistant. Paste the transcript with this prompt.","p":"Turn this transcript of me doing [task name] into a step-by-step guide someone else could follow. Format: Purpose (1 line), When to do it, What you need (logins, files, tools, but never actual passwords), Numbered steps (one action each), Checks before finishing, What to do if something goes wrong, Who to ask. Keep my exact details (amounts, deadlines, app names). List any steps that seem missing or unclear at the end. [paste transcript]"},{"h":"Test it","b":"Ask a colleague or family member to follow the guide without your help. Fix any step where they get stuck."},{"h":"Store it where people look","b":"Save it in a shared Google Docs or Notion folder called 'How we do things' and add the date you last checked it."}],"example":"How to pay suppliers (Fridays). You need: banking app access, bills sheet. Steps: 1) Open the bills sheet and filter Paid? = No. 2) Pay anything due before next Friday. 3) Check bank details match the last payment; if they changed, phone the supplier first. Ask: Sam.","tips":["Never write passwords into the guide; say where they're kept, such as your password manager."],"auto":{"trigger":{"type":"manual","detail":"User shares a voice note of a task"},"actions":[{"type":"ai.summarize","detail":"Turn the transcript into a step-by-step guide"},{"type":"doc.create","detail":"Save the guide in the shared process folder"}]}},{"id":"write-a-clear-repair-request-your-landlord-can-t-ignore","t":"Write a clear repair request your landlord can't ignore","d":"Turn your notes and photos about a problem at home into a calm, dated repair request with a clear deadline.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera","Gmail"],"when":"When something needs fixing and it's not your job","steps":[{"h":"Gather the facts","b":"Take dated photos of the problem and note when it started, how it affects you and any earlier times you reported it."},{"h":"Draft the request","b":"Paste your notes into your AI assistant with this prompt.","p":"Write a polite, firm email to my [landlord/letting agent/managing agent] about [problem, e.g. a leak under the kitchen sink]. Facts: it started on [date], it is causing [effects], and I previously reported it on [dates and how]. I've attached photos. Ask for a repair date by [date], mention access times that suit me [times], and ask them to confirm in writing. Keep it under 200 words, factual and without threats. Add a clear subject line."},{"h":"Send it and keep a copy","b":"Send it from your email with photos attached, and save it in a folder called 'Home repairs' so you have a dated record."},{"h":"Follow up if needed","b":"If you hear nothing by the deadline, ask the assistant for a short follow-up email referring to your first one."}],"example":"Subject: Repair request - kitchen sink leak, Flat 2. Dear Ms Rowe, Since 3 March there has been a leak under the kitchen sink, which is now damaging the cupboard base. I reported this by phone on 5 March. Photos attached. Please could you confirm a repair date by 17 March...","tips":["For disputes about your rights as a tenant, check your country's official housing advice service or a qualified adviser."],"auto":{"trigger":{"type":"manual","detail":"User describes a repair problem"},"actions":[{"type":"email.draft","detail":"Draft a dated repair request with a deadline"},{"type":"calendar.create","detail":"Add a follow-up reminder on the deadline date"}]}},{"id":"plan-a-family-trip-around-naps-and-snack-stops","t":"Plan a family trip around naps and snack stops","d":"Get a child-friendly itinerary that fits nap times, meal times and short attention spans, with backups for meltdowns.","cat":"Travel","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant"],"when":"When planning a trip with young children","steps":[{"h":"Write down your children's rhythms","b":"Note each child's age, nap times, bedtime, meal times and what keeps them happy."},{"h":"Ask for a family-friendly plan","b":"Paste this prompt into your AI assistant.","p":"Plan a [number]-day trip to [destination] for [adults] adults and children aged [ages]. Naps: [times]. Bedtime: [time]. They love [interests] and struggle with [e.g. long queues, car journeys over an hour]. For each day: one main activity in the morning, a calm option during naps, playgrounds or open spaces nearby, places with baby changing and family-friendly food, and a backup if it rains or someone's had enough. Include travel day tips for the journey there."},{"h":"Check facilities and prices","b":"Look up each place's official website for family tickets, buggy access, opening times and whether booking is needed."}],"example":"Day 1: 9:30 aquarium (buggy friendly, under-3s free - check site), 11:45 lunch at the cafe on site. 12:30-2pm nap in the buggy on a park walk. 3pm playground by the harbour. Backup: soft play near the hotel. Journey: leave after breakfast, stop every 90 mins.","tips":["Build in one completely unplanned half-day: children rarely keep to a schedule on holiday."],"auto":{"trigger":{"type":"manual","detail":"User enters destination and children's routines"},"actions":[{"type":"ai.generate","detail":"Create a family itinerary around naps and meals"},{"type":"doc.create","detail":"Save the plan as a trip document"}]}},{"id":"make-the-most-of-a-short-gp-appointment","t":"Make the most of a short GP appointment","d":"Turn your notes into a clear one-page summary of what's going on and the questions you want to ask your doctor.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"The day before a doctor's appointment","steps":[{"h":"Jot down what you've noticed","b":"Write in your own words what's been happening, when it started, what makes it better or worse and what you've tried. Leave out your name and date of birth."},{"h":"Organise it into a summary","b":"Paste your notes into your AI assistant with this prompt.","p":"Help me prepare for a [length, e.g. 10-minute] GP appointment. Here are my notes: [notes]. Don't diagnose or suggest treatments. Organise my notes into: 1) a 3-sentence summary I can read out at the start; 2) a timeline of when things started and changed; 3) current medicines and supplements I mentioned; 4) the 3 most important questions to ask, plus 3 optional ones. Keep it to one page in plain English."},{"h":"Take it with you","b":"Save it in your notes app or print it, and add the doctor's answers to the same note during or after the appointment."}],"example":"Summary: For 3 weeks I've had headaches most afternoons, worse on screen days. Paracetamol helps a little. Sleep has been poor. Timeline: started 14 Oct... Questions: 1) What could be causing this? 2) Is there anything I should track? 3) When should I come back?","tips":["Use AI only to organise your notes. Your GP or another qualified professional is the right person to diagnose and advise.","Be careful sharing health details with AI tools; leave out names, dates of birth and NHS or insurance numbers."],"auto":{"trigger":{"type":"calendar_event","detail":"The day before a doctor's appointment"},"actions":[{"type":"notify","detail":"Remind the user to write down symptoms and questions"},{"type":"ai.summarize","detail":"Organise notes into a summary and question list"}]}},{"id":"find-and-cancel-subscriptions-you-forgot-about","t":"Find and cancel subscriptions you forgot about","d":"A complete list of every recurring payment you have, what each costs per year, and ready-written cancellation messages for the ones you don't use.","cat":"Money","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Gmail"],"when":"Twice a year, or when money feels tight","steps":[{"h":"Gather the evidence","b":"Export three months of card and bank transactions, and search your email for words like subscription, renewal, membership and receipt."},{"h":"Remove sensitive details","b":"Delete account and card numbers from anything you paste. Keep merchant names, dates and amounts."},{"h":"Ask the AI to spot the repeats","b":"Paste the transactions and any renewal emails into your AI assistant with this prompt.","p":"Below are three months of my transactions and some renewal emails. Find every payment that looks recurring (monthly, yearly or weekly). Make a table with: service name, how often it charges, amount each time, cost per year, and the date it next renews if you can tell. Sort by yearly cost, highest first. Then ask me which ones I actually use, one question at a time. [paste transactions and emails]"},{"h":"Decide what stays","b":"Answer the AI's questions honestly. For anything you're dropping, ask it to write a short, polite cancellation message or tell you the usual place to cancel, such as the app store subscription settings."},{"h":"Put renewals in your calendar","b":"For subscriptions you keep, add a reminder a week before each yearly renewal so you get a chance to decide again."}],"example":"Found 9 recurring payments, £742 a year. Top: Streaming bundle £215, Cloud storage x2 (£24 + £60, you have two), Fitness app £96 (last opened in June), Magazine £48. Cancel the duplicate storage and fitness app: saves £156 a year.","tips":["Subscriptions bought through your phone are usually cancelled in your Apple or Google account settings, not in the app itself.","Check for free trials that quietly became paid ones."],"auto":{"trigger":{"type":"schedule","detail":"Every six months"},"actions":[{"type":"ai.extract","detail":"Find recurring payments in recent transactions and receipts"},{"type":"sheet.update","detail":"Update the subscriptions list with yearly costs"},{"type":"calendar.create","detail":"Add a reminder a week before each yearly renewal"}]}},{"id":"make-flashcards-from-anything-you-re-learning","t":"Make flashcards from anything you're learning","d":"A ready-to-import set of flashcards from your notes, a chapter or a vocab list, for apps like Anki or Quizlet.","cat":"Learning","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Sheets"],"when":"Whenever you finish a chapter or topic","steps":[{"h":"Collect the material","b":"Copy the notes, chapter summary or word list you want to learn."},{"h":"Generate the cards","b":"Paste it into your AI assistant with this prompt.","p":"Turn the material below into 25 flashcards for [subject and level]. Each card should test one idea only. Front: a clear question or prompt (not just a single word unless it's vocabulary). Back: a short answer, under 25 words. Include a few cards that ask 'why' or 'what's the difference between' rather than just facts. Return the cards as two columns separated by a comma: Front,Back, with no header and no numbering, so I can import them into a flashcard app. [paste material]"},{"h":"Check and tidy","b":"Read through the cards, delete any that are wrong or not useful, and fix anything that doesn't match your course."},{"h":"Import into your flashcard app","b":"Paste the list into a Google Sheet, export as CSV, and import it into a flashcard app such as Anki or Quizlet, which both support importing lists."}],"example":"What does a 'stakeholder' mean in a business case?,Anyone affected by or able to affect a decision What's the difference between weather and climate?,Weather is day to day; climate is the pattern over decades madrugar,to get up very early","tips":["Fewer, better cards beat hundreds of rushed ones.","Ask it to avoid commas inside answers if your import keeps splitting cards in the wrong place."],"auto":{"trigger":{"type":"new_file","detail":"A new chapter of notes is saved"},"actions":[{"type":"ai.generate","detail":"Create flashcards in front and back format"},{"type":"sheet.append","detail":"Add the cards to the flashcard sheet"},{"type":"notify","detail":"Tell the user the deck is ready to import"}]}},{"id":"explore-a-career-change-using-skills-you-already-have","t":"Explore a career change using skills you already have","d":"A list of realistic new career paths based on your skills and interests, with what each involves and small first steps to test it.","cat":"Careers","side":"life","lvl":"Beginner","mins":25,"tools":["AI assistant","Google Docs"],"when":"When you're thinking about a change","steps":[{"h":"Take stock","b":"Write down your jobs so far, what you enjoyed and disliked in each, skills people ask you for help with, and any practical limits such as income or location."},{"h":"Ask for options","b":"Paste your notes into your AI assistant with this prompt.","p":"I'm considering a career change. Here's my background: [paste notes]. My practical limits: [for example must earn at least X, can't relocate, can study part-time]. 1) List my transferable skills with evidence from my background. 2) Suggest 6 realistic career paths that use those skills, from a small step to a bigger leap. For each: what the work involves day to day, typical entry routes, any qualifications usually needed, and how my skills fit. 3) For my top 3, suggest a small, low-risk way to test it in the next month, such as a short course, volunteering or talking to someone in the role. Be honest about challenges."},{"h":"Check the facts","b":"Look up entry requirements and pay on official career service websites or real job ads, since these vary by country and change."},{"h":"Try one small step","b":"Pick one test from the list and put a date in your calendar to do it."}],"example":"Transferable skills: scheduling (managed rotas for 15 staff), calm with upset people, training new starters. Paths: 1) Practice manager in healthcare, 2) HR assistant, 3) Learning and development coordinator... Test HR: shadow your current HR team for a day.","tips":["Talking to one person already doing the job tells you more than hours of reading.","A careers adviser, often free through public services, can help check the plan."],"auto":{"trigger":{"type":"manual","detail":"User shares their background and limits"},"actions":[{"type":"ai.generate","detail":"Map transferable skills to career paths"},{"type":"doc.create","detail":"Save the career options and test steps"},{"type":"calendar.create","detail":"Schedule the first test step"}]}},{"id":"plan-a-trip-itinerary-that-suits-everyone","t":"Plan a trip itinerary that suits everyone","d":"A day-by-day trip plan with realistic timings, food stops and rainy-day options, built around the people you're travelling with.","cat":"Personal Assistant","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Maps","Google Docs"],"when":"A few weeks before a trip","steps":[{"h":"Note the basics","b":"Write down where, when, who's going (with ages), budget, how you'll get around, and must-dos for each person."},{"h":"Ask for a draft plan","b":"Paste your notes into your AI assistant with this prompt.","p":"Plan a [number]-day trip to [place] from [dates]. Travellers: [for example 2 adults, kids aged 6 and 9, a grandparent who can't walk far]. Budget: [level]. Getting around: [car / public transport / walking]. Must-dos: [list]. For each day, give a morning, afternoon and evening plan with realistic travel times, a break or downtime, a food idea at a sensible price, and one rainy-day alternative. Don't pack the days too full. End with a packing list and things to book in advance."},{"h":"Check it on a map","b":"Look up each place in Google Maps to check opening times, travel times and that it still exists. Save the places to a list in Maps."},{"h":"Save and share","b":"Paste the final plan into Google Docs and share it with your travel group."}],"example":"Day 1 (Fri): Arrive 2pm, check in. 4pm: beach walk and rock pools (5 min walk). 6pm: fish and chips on the harbour (£). Rainy option: aquarium. Day 2: 10am steam railway (book ahead), picnic at the top station, afternoon rest at the cottage...","tips":["AI can suggest places that have closed or changed hours, so always check before you go.","Add one free afternoon. Trips feel better with breathing room."],"auto":{"trigger":{"type":"calendar_event","detail":"A holiday is four weeks away"},"actions":[{"type":"ai.generate","detail":"Draft a day-by-day itinerary"},{"type":"doc.create","detail":"Save and share the itinerary"},{"type":"list.add","detail":"Add things to book to the to-do list"}]}},{"id":"follow-up-on-emails-nobody-has-answered","t":"Follow up on emails nobody has answered","d":"Never lose track of unanswered emails: get reminded after a few days and send a friendly nudge that actually gets a reply.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":10,"tools":["Gmail","Outlook","AI assistant"],"when":"Three working days after an important email goes unanswered","steps":[{"h":"Set a reminder when you send","b":"In Gmail, snooze your sent email or turn on Nudges in settings so it reappears if there's no reply. In Outlook, flag the sent message with a follow-up date."},{"h":"When it comes back, draft a nudge","b":"Paste your original email into your AI assistant with this prompt.","p":"I sent the email below [number] days ago to [who they are] and haven't had a reply. Write a short, friendly follow-up under 60 words that: doesn't sound annoyed, restates the one thing I need from them, makes it easy to answer (offer a yes/no or two options), and gives a gentle date. Give me two versions: one casual, one more formal. Original email: [paste email]"},{"h":"Reply in the same thread","b":"Send the nudge as a reply to your original email so they have the context, and set another reminder for a week later."}],"example":"Hi Lena, just floating this back to the top of your inbox. Could you let me know by Thursday whether the 3pm slot works? A quick yes or no is perfect. Thanks, Ali","tips":["A specific question gets more replies than 'just checking in'.","If two nudges get nothing, try a different channel, like a quick call."],"auto":{"trigger":{"type":"schedule","detail":"Daily check for sent emails with no reply after 3 working days"},"actions":[{"type":"ai.generate","detail":"Write a short, friendly follow-up"},{"type":"email.draft","detail":"Save it as a draft reply in the original thread"},{"type":"notify","detail":"Tell the user a nudge is ready to review"}]}},{"id":"turn-a-voice-recording-into-tidy-notes","t":"Turn a voice recording into tidy notes","d":"Record a conversation, lecture or your own thoughts on your phone and get organised notes with key points and next steps.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":10,"tools":["Voice notes","AI assistant","Notes app"],"when":"After an in-person meeting, call or idea walk","steps":[{"h":"Record with your phone","b":"Use your phone's voice recorder app. Ask permission before recording anyone else, and keep the phone close to whoever is speaking."},{"h":"Get a transcript","b":"Many phone recorder apps now transcribe automatically. If yours doesn't, upload the audio file to ChatGPT or Gemini, which can work with audio on many plans."},{"h":"Turn it into notes","b":"Paste the transcript or attach the recording with this prompt.","p":"Turn this recording transcript into clear notes. Context: [e.g. meeting with landlord about repairs]. Give me: 1) A title and date line. 2) Key points as bullets, grouped by topic. 3) Anything agreed, with who agreed it. 4) Next steps with owners and dates. 5) Any numbers, prices or dates mentioned, listed separately so I can check them. Don't add anything that wasn't said. [paste transcript]"},{"h":"Save it","b":"Paste the notes into your notes app or a shared doc, and add any dates to your calendar."}],"example":"Meeting with landlord - 9 Nov. Key points: boiler service booked; damp in back bedroom. Agreed: landlord to send a contractor (landlord). Next steps: contractor visit by 23 Nov; I'll send photos by Tue. Numbers: rent review in March; quote £350 for guttering.","tips":["Always get consent before recording others, and delete recordings once you have your notes if they contain personal details."],"auto":{"trigger":{"type":"new_file","detail":"A new voice recording is saved"},"actions":[{"type":"ai.summarize","detail":"Transcribe and turn the recording into structured notes"},{"type":"doc.create","detail":"Save the notes as a document"},{"type":"calendar.create","detail":"Add any agreed dates to the calendar"}]}},{"id":"write-a-checklist-for-jobs-you-do-again-and-again","t":"Write a checklist for jobs you do again and again","d":"Describe a task you repeat and get a step-by-step checklist anyone can follow, so nothing gets forgotten and others can help.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Docs","Notion"],"when":"Whenever you notice you're doing the same job for the third time","steps":[{"h":"Talk through how you do it","b":"Type or voice-record yourself explaining the task from start to finish, including the bits you usually forget."},{"h":"Turn it into a checklist","b":"Paste your description into your AI assistant with this prompt.","p":"Turn my description into a clear checklist for [task] that someone new could follow. Include: what it's for in one line; what you need before starting; numbered steps, each one action starting with a verb; warnings for common mistakes; how to know it's done properly; and how long it usually takes. Use plain words, no jargon. Then list any steps that seem missing or unclear. My description: [paste]"},{"h":"Save and test it","b":"Put the checklist in a shared Google Doc or Notion page. Next time, follow it exactly and fix anything that's wrong."}],"example":"Closing the café on Sundays (20 min). Need: keys, cash bag. 1. Turn off the coffee machine and run the clean cycle. 2. Count the till and record totals in the cash book. 3. Wipe and stack chairs... Warning: Don't switch off the fridge circuit. Done when: alarm is set and green light shows.","tips":["Add photos of tricky bits, like which switch to press; they save a lot of explaining."],"auto":{"trigger":{"type":"manual","detail":"User describes a repeated task"},"actions":[{"type":"ai.generate","detail":"Turn the description into a step-by-step checklist"},{"type":"doc.create","detail":"Save the checklist in the shared procedures folder"}]}},{"id":"save-ten-perfect-replies-to-your-most-common-questions","t":"Save ten perfect replies to your most common questions","d":"A set of polished Gmail templates you can drop into any email in two clicks, written once with AI and reused for months.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Gmail"],"when":"Set up once, use every day","steps":[{"h":"Turn on templates in Gmail","b":"In Gmail's settings, look in the Advanced tab for Templates and switch them on, then save changes."},{"h":"List your top ten questions","b":"Write down the ten things you answer most often, plus the key facts for each."},{"h":"Write them all in one go","b":"Paste your list into your AI assistant with this prompt.","p":"Write 10 email reply templates for [business name], a [type of business]. For each, give: a short template name, a subject line, and a body under 100 words. Questions and facts: [paste list]. Style: warm, clear, British English, sign off as [your name]. Start each with 'Hi [Name],' and use [square brackets] for anything I'll fill in each time, such as order numbers or dates. End each with one clear next step."},{"h":"Save each as a template","b":"Open a new email, paste one reply, then use the three-dot menu at the bottom of the compose window and choose Templates, then Save draft as template. Name it to match."},{"h":"Use and tweak them","b":"When replying, insert a template from the same menu, fill in the brackets and add one personal line at the top."}],"example":"Template: Delivery delay Hi [Name], Thanks for checking in. Your order [number] is with the courier and running about [X] days behind. Here's your tracking link: [link]. If it hasn't arrived by [date], reply to this email and I'll send a replacement. Best, Priya","tips":["Always add one line that's specific to the customer so it never feels canned.","In Outlook, use My Templates or Quick Parts for the same thing."],"auto":{"trigger":{"type":"new_email","detail":"A customer asks a common question"},"actions":[{"type":"ai.classify","detail":"Match the question to one of the saved templates"},{"type":"email.draft","detail":"Create a reply from the template with blanks filled where known"}]}},{"id":"get-confident-answers-to-tricky-sales-objections","t":"Get confident answers to tricky sales objections","d":"Practise handling 'it's too expensive' and other common pushback with an AI role-play partner, and leave with a cheat sheet of honest answers.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant"],"when":"Before an important pitch, or whenever you feel rusty","steps":[{"h":"List the objections you hear","b":"Write down the five things people say when they don't buy, such as price, timing, 'we already have someone' or 'I need to think about it'."},{"h":"Get a cheat sheet","b":"Paste this prompt into your AI assistant.","p":"I sell [product/service] to [type of customer] at around [price]. Common objections I hear: [list]. For each, give me: what the person might really mean, one question to understand it better, and a short, honest reply (under 50 words) in a natural, non-pushy British tone. Never suggest pressure tactics or misleading claims. Then put it all in a one-page table I can keep beside me."},{"h":"Role-play a real conversation","b":"In the same chat, ask: 'Now play a sceptical [job title] at a [business type]. Push back with my objections one at a time and wait for my reply. After 5 exchanges, tell me what I did well and what to improve.' Type or use voice mode to answer."},{"h":"Save your best lines","b":"Copy the cheat sheet and your best answers into your notes app for your next call."}],"example":"'It's too expensive.' Might mean: unsure of the value, or comparing to a cheaper quote. Ask: 'What are you comparing it with?' Reply: 'That's fair. The difference is that ours includes aftercare for a year, so there are no surprise call-out fees. Would it help if I broke down the cost?'","tips":["Voice mode in ChatGPT or Gemini makes the role-play feel much closer to a real call.","If you hear the same objection a lot, it may be telling you something about your offer, not your pitch."],"auto":{"trigger":{"type":"manual","detail":"User starts a practice session"},"actions":[{"type":"ai.generate","detail":"Write an objection cheat sheet for the user's offer"},{"type":"ai.generate","detail":"Role-play a sceptical buyer and give feedback"},{"type":"doc.create","detail":"Save the cheat sheet"}]}},{"id":"write-a-clear-workplace-policy-in-plain-english","t":"Write a clear workplace policy in plain English","d":"A first draft of a short, readable staff policy, such as remote working or AI use, ready for you to check with an HR professional.","cat":"HR & Hiring","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"When your team needs a rule written down","steps":[{"h":"Decide what the policy must say","b":"Note what you already do in practice, what problems you want to avoid and any decisions you've made, like core hours or which tools staff may use."},{"h":"Ask AI for a plain-English draft","b":"Paste this prompt into your AI assistant.","p":"Draft a [topic, e.g. remote working / using AI tools at work / expenses] policy for [business], a [size and type] business in [country]. What we already do and want: [paste notes]. Structure: Purpose (2 lines), Who it applies to, The rules (numbered, plain English), What staff can expect from us, What to do if something goes wrong, Who to ask, and Review date. Under 700 words, friendly but clear, British English. After the draft, list any legal points in [country] I should check with an HR or employment law professional, and any common policy topics I've not covered."},{"h":"Get it checked","b":"Have the draft reviewed by an HR adviser or employment solicitor, especially anything about pay, discipline, data or contracts."},{"h":"Share it and explain it","b":"Save the final version in Google Docs, share it with the team and talk it through at a team meeting, inviting questions."}],"example":"Using AI tools at work 1. You may use approved AI tools (currently ChatGPT Team) for drafting and research. 2. Never paste customer names, contact details or financial information into AI tools. 3. Check AI output before using it; you're responsible for the final work. Review date: January 2027.","tips":["Shorter policies get read; aim for two pages or less.","AI doesn't know current law in your area for certain, so treat the legal checklist as questions for your adviser."],"auto":{"trigger":{"type":"manual","detail":"Manager requests a new policy"},"actions":[{"type":"ai.generate","detail":"Draft a plain-English policy and legal-check list"},{"type":"doc.create","detail":"Save the draft for professional review"},{"type":"calendar.create","detail":"Add a review date reminder"}]}},{"id":"turn-a-blog-post-into-a-swipeable-carousel","t":"Turn a blog post into a swipeable carousel","d":"Your existing article becomes a 7 to 10 slide Instagram or LinkedIn carousel with a hook, clear points and a final call to action.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Canva"],"when":"After publishing a new article","steps":[{"h":"Get the slide text","b":"Paste your article into your AI assistant with this prompt.","p":"Turn this article into a carousel of [7-10] slides for [Instagram or LinkedIn]. Article: [paste]. Slide 1: a hook of max 8 words that promises a clear benefit. Slides 2 to second-last: one idea each, a headline of max 6 words and a supporting line of max 20 words. Last slide: a call to action to [read the full post, follow, book]. Also write a caption of under 80 words. Output as a numbered list. Keep facts exactly as in the article."},{"h":"Pick a carousel template in Canva","b":"Search Canva for 'carousel' and choose a template in the right size (square or portrait 4:5). Swap in your brand colours and fonts."},{"h":"Fill in the slides","b":"Paste each slide's text in, keeping it big and readable on a phone. Download as PNGs for Instagram, or as a PDF for a LinkedIn document post."},{"h":"Post with the caption","b":"Upload the slides in order and add the caption. Link to the full article in your bio or the first comment."}],"example":"Slide 1: 'Five mistakes that slow down your laptop'. Slide 2: 'Too many startup apps' / 'Every app that opens at login eats memory before you've started.' ... Slide 8: 'Want the full checklist? Link in bio.'","tips":["Make one carousel template once and duplicate it each time to keep a consistent look."],"auto":{"trigger":{"type":"new_file","detail":"New article added to the blog folder"},"actions":[{"type":"ai.generate","detail":"Write carousel slide text and caption"},{"type":"doc.create","detail":"Save the slide text for designing in Canva"},{"type":"notify","detail":"Tell the user the carousel copy is ready"}]}},{"id":"bring-an-old-blog-post-up-to-date","t":"Bring an old blog post up to date","d":"A refresh plan for a dated article: what's out of date, what to add, a new title and intro, so it can work harder for you again.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"When a popular post is more than a year old","steps":[{"h":"Pick a post worth refreshing","b":"Choose one that used to get visits or matters to customers. Copy its full text and note when it was written."},{"h":"Ask for a refresh plan","b":"Paste the article into an AI assistant with web search on, using this prompt.","p":"This article was published in [year] for [audience]: [paste]. Today is [date]. 1) List anything that's likely out of date (prices, rules, products, links, statistics) and what to check. 2) Suggest 2-3 new sections readers would expect now. 3) Point out anything to cut. 4) Write a new title, a new 80-word introduction and a short 'Updated [month year]' note. Search the web to check current facts and give links for anything you suggest changing."},{"h":"Update and republish","b":"Make the changes in a Google Doc copy first, verify each fact through the links, then update the post on your site. Keep the same web address so you don't lose existing visitors."}],"example":"Out of date: 'MOT costs up to £54.85' - check the current maximum on GOV.UK. Add: section on electric car MOTs. Cut: paragraph about a closed garage. New title: MOT Checklist for 2026: What Gets Checked and How to Pass.","tips":["Keeping the same page address matters; changing it can lose the visitors it already attracts."],"auto":{"trigger":{"type":"schedule","detail":"Monthly, pick the oldest popular post"},"actions":[{"type":"web.fetch","detail":"Read the post and check current facts"},{"type":"ai.generate","detail":"Write a refresh plan, new title and intro"},{"type":"doc.create","detail":"Save the refresh plan for editing"}]}},{"id":"get-clean-product-photos-with-the-background-removed","t":"Get clean product photos with the background removed","d":"Phone photos of your products turned into clean cut-outs on white or brand-coloured backgrounds, ready for your shop and posts.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":15,"tools":["Phone camera","Canva"],"when":"When adding new products","steps":[{"h":"Shoot in good light","b":"Place the product near a window on a plain surface and take a few photos from the same height. Wipe the lens first."},{"h":"Remove the background","b":"On an iPhone you can press and hold the product in the Photos app to lift it out of the picture. In Canva, the background remover is under Edit on a photo if your plan includes it. Many Android phones have a similar tool in their photo editor."},{"h":"Place it on a clean background","b":"In Canva, make a square design in white or your brand colour, drop in the cut-out, add a soft shadow, and duplicate the design for each product so they match."},{"h":"Write alt text while you're there","b":"Ask your AI assistant for a one-line description of each photo for your shop's image description field.","p":"Write alt text (under 125 characters) for this product photo for [shop name]. Product: [name, colour, material]. Describe what's visible, plainly, for someone using a screen reader. Don't start with 'image of'."}],"example":"Before: candle on a cluttered kitchen counter. After: candle centred on a cream square with a soft shadow, matching the other 11 products. Alt text: 'Amber glass jar candle with a wooden lid and a kraft paper label.'","tips":["Check the cut-out edges at full size; fine details like fur or lace sometimes need a second go."],"auto":{"trigger":{"type":"new_file","detail":"New product photo added to the shop photos folder"},"actions":[{"type":"ai.generate","detail":"Write alt text for the photo"},{"type":"file.save","detail":"Save the cut-out alongside the original"},{"type":"notify","detail":"Remind the user to place it on the shop template"}]}},{"id":"get-a-researched-report-on-any-question-with-sources","t":"Get a researched report on any question, with sources","d":"Use your assistant's deep research mode to get a sourced report on a big question, then check the sources so you can trust what you share.","cat":"Research & News","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"When you need to understand a topic properly","steps":[{"h":"Turn on the research mode","b":"ChatGPT, Gemini and Claude each have a research option that searches many sites and writes a report; look for 'Deep research' or 'Research' near the message box. If your plan doesn't include it, use normal web search mode and ask the same question."},{"h":"Give it a clear brief","b":"The more specific you are, the better the report. Paste this and fill in the brackets.","p":"Research this question: [your question]. Context: I am [who you are] and I need this to [decide / explain / plan something]. Focus on [country or region] and sources from the last [2] years. Structure the report as: 1) a short answer up front, 2) the main findings with a source link for each, 3) where sources disagree, 4) what is still uncertain, 5) a list of all sources with their publisher and date. Prefer official, academic and established news sources over blogs."},{"h":"Check the sources","b":"Open at least the three sources the report leans on most. Confirm they exist, say what the report claims and are recent enough. AI research tools can misquote or link to the wrong page."},{"h":"Keep the report and your notes","b":"Copy the report into a Google Doc and add a line at the top saying which sources you checked and when."}],"example":"Short answer: heat pumps can work in older homes, but most need better insulation first. Findings: a government field trial found... (link, 2024). Disagreement: installer groups and consumer groups give different running-cost figures. Uncertain: long-term costs beyond 10 years.","tips":["If a source link is broken or doesn't mention the claim, ask the assistant to find a different source or remove the claim."],"auto":{"trigger":{"type":"manual","detail":"User asks a research question"},"actions":[{"type":"web.fetch","detail":"Search and read relevant sources"},{"type":"ai.generate","detail":"Write a structured report with linked sources"},{"type":"doc.create","detail":"Save the report to a document"}]}},{"id":"clean-up-a-messy-spreadsheet-in-minutes","t":"Clean up a messy spreadsheet in minutes","d":"Get a step-by-step clean-up plan for messy data, from duplicates and mixed date formats to inconsistent names, with formulas you can paste in.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Excel","Google Sheets"],"when":"Before you analyse or share a spreadsheet","steps":[{"h":"Make a backup copy","b":"Duplicate the sheet tab or file before you change anything, so you can always go back."},{"h":"Show the AI a sample","b":"Copy the header row and about 20 typical rows (including the messy ones) and paste them with this prompt.","p":"Here is a sample of my spreadsheet in [Excel / Google Sheets]. It has about [number] rows. Find the data problems: duplicates, inconsistent spellings (e.g. 'Ltd' vs 'Limited'), mixed date formats, numbers stored as text, extra spaces and blank cells. For each problem, give me: what it is, which column, and the exact step or formula to fix it in [Excel / Google Sheets], explained for a beginner. Number the steps in the order I should do them. [paste sample]"},{"h":"Fix one problem at a time","b":"Follow the steps in order. Use built-in tools where it suggests them, such as removing duplicates and trimming spaces from the Data menu in Google Sheets or the Data tab in Excel."},{"h":"Check the row count","b":"Compare the number of rows before and after. If lots disappeared, check the duplicates really were duplicates."}],"example":"1) Column B has extra spaces: in a new column use =TRIM(B2), fill down, then paste as values. 2) Dates in column D mix 03/04/26 and 2026-04-03: select D and set the format to Date... 3) 46 duplicate rows by email: remove duplicates on column C.","tips":["Use made-up or trimmed sample rows if the real data includes customer details; the AI only needs to see the pattern."],"auto":{"trigger":{"type":"new_file","detail":"User uploads a spreadsheet to clean"},"actions":[{"type":"ai.classify","detail":"Find duplicates, format problems and blanks"},{"type":"ai.generate","detail":"Write ordered clean-up steps and formulas"},{"type":"file.save","detail":"Save a cleaned copy alongside the original"}]}},{"id":"hand-your-accountant-tidy-records-at-year-end","t":"Hand your accountant tidy records at year end","d":"Get a personalised checklist of what to gather for your accountant, plus a summary of your records and the questions to ask them.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Sheets","Google Drive"],"when":"A month before your accounts or tax return are due","steps":[{"h":"Describe your business","b":"Write down your business type (sole trader, partnership or limited company), what you sell, whether you're VAT registered, and which bookkeeping app or spreadsheet you use."},{"h":"Get a checklist","b":"Paste this into your AI assistant.","p":"I run a [business type] in [country] selling [what you do]. I'm [VAT registered / not VAT registered] and keep records in [app or spreadsheet]. My year end is [date]. Create a checklist of the records and documents an accountant would typically ask for at year end, grouped by: income, expenses, bank and loans, assets and equipment, staff (if any), home or vehicle use, and other. For each item, say why it's needed in one line. Finish with 8 questions I should ask my accountant. This is to help me organise, not tax advice."},{"h":"Gather into one folder","b":"Create a shared Google Drive or OneDrive folder for the year and work through the checklist, ticking items off as you add them."},{"h":"Summarise your figures","b":"Optionally, paste your income and expense totals by category and ask for a one-page summary showing anything that looks different from last year, so you're ready to explain it."},{"h":"Send it with your questions","b":"Share the folder and your questions with your accountant. They will tell you what's actually allowable and what you owe."}],"example":"Income: sales invoices and platform payout reports (to confirm turnover). Expenses: receipts, phone and broadband bills (to split business use)... Questions: 'Can I claim for part of my home as an office?' 'Should I register for VAT next year?'","tips":["Your accountant has the final say on what's allowable. Use AI to organise, not to decide tax treatment.","Share files through a secure folder link rather than as email attachments."],"auto":{"trigger":{"type":"schedule","detail":"One month before year end"},"actions":[{"type":"ai.generate","detail":"Create a year-end records checklist"},{"type":"list.add","detail":"Add each item to the user's to-do list"},{"type":"notify","detail":"Remind the user to share the folder with their accountant"}]}},{"id":"plan-a-veg-patch-that-suits-your-space","t":"Plan a veg patch that suits your space","d":"Get a simple growing plan for your garden, balcony or windowsill, with what to sow each month for your climate.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera"],"when":"Late winter, before the growing season","steps":[{"h":"Measure and photograph your space","b":"Note the size of your bed, pots or windowsill, which way it faces and how many hours of sun it gets."},{"h":"Ask for a growing plan","b":"Attach a photo to your AI assistant and paste this prompt.","p":"I want to grow vegetables and herbs in [space and size, e.g. two 60cm balcony planters facing south] in [town or region and country]. I get about [hours] of sun and can spend [time] a week. We like eating [foods]. I'm a [beginner/experienced] grower. Suggest [5-8] easy crops, a simple layout, and a month-by-month calendar of when to sow, plant out and harvest each one. Note anything that needs protecting from frost or slugs."},{"h":"Put sowing dates in your calendar","b":"Add a reminder for each sowing and planting-out date so you don't miss the window."}],"example":"Planter 1: cherry tomatoes (sow indoors March, plant out late May) with basil. Planter 2: cut-and-come-again salad (sow every 3 weeks Apr-Aug), radishes. March: sow tomatoes on a sunny windowsill. May: harden off seedlings for a week before planting out.","tips":["Local frost dates vary, so check with a local garden centre or your national gardening society's website."],"auto":{"trigger":{"type":"schedule","detail":"Every February 1st"},"actions":[{"type":"ai.generate","detail":"Create the year's growing plan from saved garden details"},{"type":"calendar.create","detail":"Add sowing and planting reminders"}]}},{"id":"write-a-strong-claim-for-a-delayed-or-cancelled-flight","t":"Write a strong claim for a delayed or cancelled flight","d":"Turn your flight details into a clear, polite compensation or refund claim with the facts the airline needs.","cat":"Travel","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail"],"when":"After a delay, cancellation or lost bag","steps":[{"h":"Collect the facts","b":"Note the flight number, date, booking reference, scheduled and actual arrival time, what the airline told you and any receipts for food, hotels or taxis."},{"h":"Check whether you may be entitled","b":"Look at the airline's own claims page and your country's aviation regulator or consumer advice site, as passenger rights depend on the route, airline and cause."},{"h":"Draft the claim","b":"Paste your facts into your AI assistant with this prompt.","p":"Write a polite, clear claim to [airline] about flight [number] on [date], booking reference [ref]. What happened: [scheduled arrival time, actual arrival time, reason given, or cancellation details]. Expenses: [list with amounts]. Ask for [compensation under the rules that apply to this flight / refund / reimbursement of expenses], list the attached receipts, and ask for a reply within [14] days. Keep it under 250 words and don't overstate what I'm owed."},{"h":"Submit and keep records","b":"Use the airline's official claim form if it has one, pasting your text in, and save a copy with the date you sent it."}],"example":"Subject: Claim - flight AB123, 12 Aug, ref XY7K2P. Our flight was scheduled to arrive at 14:05 but arrived at 18:50 due to a technical problem. We bought meals while waiting (receipts attached, total 38.60). Please review our eligibility for compensation and reimburse these costs...","tips":["Be wary of claims companies that take a large cut; you can usually claim directly for free."],"auto":{"trigger":{"type":"manual","detail":"User enters flight disruption details"},"actions":[{"type":"email.draft","detail":"Draft the compensation or refund claim"},{"type":"calendar.create","detail":"Add a reminder to chase if no reply in 14 days"}]}},{"id":"never-miss-a-dose-with-simple-medication-reminders","t":"Never miss a dose with simple medication reminders","d":"Set up reminders on your phone for each medicine, using exactly what your pharmacist or the label says.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":10,"tools":["Reminders app","AI assistant"],"when":"When you start a new medicine","steps":[{"h":"Read the label and leaflet","b":"Write down each medicine's name, when to take it and any instructions like 'with food', exactly as the label or your pharmacist says."},{"h":"Turn it into a daily timetable","b":"Paste your list into your AI assistant with this prompt. It's only for organising times, not for changing anything.","p":"Turn these medicine instructions into a simple daily timetable. Use only what I've written and don't change or add doses: [paste names, times and instructions exactly from the labels]. I wake at [time], eat meals at [times] and go to bed at [time]. Output a table with time, medicine, and instructions (e.g. with food). List anything that's unclear for me to ask my pharmacist about."},{"h":"Set recurring reminders","b":"Create a daily repeating reminder in your phone's reminders or clock app for each time slot. iPhone users can also use the Medications section of the Health app."},{"h":"Ask your pharmacist","b":"Take the 'unclear' list to your pharmacist and update the reminders if they suggest changes."}],"example":"08:00 - Medicine A, 1 tablet, with breakfast. 13:00 - Medicine B, after lunch. 22:00 - Medicine A, 1 tablet. Ask pharmacist: can Medicine B be taken at the same time as my vitamin D?","tips":["Never change a dose because of an AI answer; always check with your pharmacist, GP or prescriber.","Avoid sharing your full medication list in AI tools unless you're comfortable with it; you can use 'Medicine A' and 'Medicine B' instead."],"auto":{"trigger":{"type":"schedule","detail":"At each scheduled medicine time"},"actions":[{"type":"notify","detail":"Remind the user which medicine to take and how"}]}},{"id":"plan-for-the-year-s-irregular-expenses","t":"Plan for the year's irregular expenses","d":"A month-by-month list of the yearly costs that usually catch you out, like car tax, insurance and birthdays, with a monthly amount to set aside.","cat":"Money","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Calendar"],"when":"Once a year, ideally in January","steps":[{"h":"Brainstorm your yearly costs","b":"Jot down anything that doesn't happen monthly: insurance renewals, car service, school trips, birthdays, holidays, subscriptions, festive spending."},{"h":"Let the AI fill the gaps","b":"Paste your list into your AI assistant with this prompt.","p":"Help me plan for irregular costs over the next 12 months. My household is [describe: adults, children and ages, car or no car, pets, renting or owning]. Here are the yearly costs I know about, with rough amounts and months: [list]. First, suggest other common irregular costs for a household like mine that I may have forgotten, and ask me to confirm amounts. Then make a 12-month table showing what's due each month, the yearly total, and the amount I'd need to set aside every month to cover them evenly."},{"h":"Set aside the monthly amount","b":"Set up a regular transfer of that monthly figure into a separate savings pot if your bank offers one."},{"h":"Add reminders","b":"Put each big cost in your calendar a month ahead, so you have time to shop around before renewals."}],"example":"Yearly irregular total: £3,480 = £290 a month. Jan: Home insurance £240. Mar: Car service £220, Mum's birthday £50. Aug: School uniform £150. Sep: Car tax £190. Dec: Festive spending £600...","tips":["Shopping around a month before insurance renewals is often cheaper than auto-renewing.","Update the list each year with what you actually spent."],"auto":{"trigger":{"type":"schedule","detail":"Every January"},"actions":[{"type":"ai.generate","detail":"Build the year's irregular expense plan"},{"type":"calendar.create","detail":"Add a reminder a month before each big cost"},{"type":"sheet.update","detail":"Update the sinking-fund tracker"}]}},{"id":"get-feedback-on-an-essay-before-you-hand-it-in","t":"Get feedback on an essay before you hand it in","d":"Honest, specific feedback on your essay's argument, structure and clarity, without the AI rewriting it for you.","cat":"Learning","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Google Docs"],"when":"A few days before a deadline","steps":[{"h":"Check the rules first","b":"Make sure your school, college or course allows AI feedback. Many allow feedback but not AI-written work."},{"h":"Share the essay and brief","b":"Copy your draft and the assignment question or marking criteria."},{"h":"Ask for feedback, not a rewrite","b":"Paste both into your AI assistant with this prompt.","p":"Act as a fair, encouraging teacher. Here is the assignment question and marking criteria: [paste]. Here is my draft essay: [paste]. Don't rewrite my essay or add new paragraphs. Instead give me: 1) what's working well (3 points), 2) the 3 most important improvements, each pointing to a specific paragraph, 3) whether my argument actually answers the question, 4) any paragraphs that are unclear or off-topic, and 5) a rough sense of which marking band it fits and what would move it up. Ask me questions where my point isn't clear."},{"h":"Revise it yourself","b":"Make the changes in your own words in your document, then ask for a second, shorter round of feedback on the parts you changed."}],"example":"Working well: clear opening, good use of the 1832 Reform Act as evidence. Improve: 1) Paragraph 3 describes events but doesn't link back to the question 'how far'. 2) Your conclusion introduces a new point. 3) Add a counter-argument. Band: likely upper middle.","tips":["Submitting AI-written work as your own can break academic rules. Use it as a critic, not a ghostwriter.","Remove your name and student number before pasting."],"auto":{"trigger":{"type":"manual","detail":"Student shares a draft and brief"},"actions":[{"type":"ai.generate","detail":"Give structured feedback against the criteria"},{"type":"doc.create","detail":"Save feedback beside the draft"},{"type":"notify","detail":"Remind the student to revise before the deadline"}]}},{"id":"send-a-thoughtful-thank-you-after-every-interview","t":"Send a thoughtful thank-you after every interview","d":"A short, personal follow-up email drafted the same day as your interview, mentioning something specific you discussed.","cat":"Careers","side":"life","lvl":"Intermediate","mins":10,"tools":["Gmail","Google Calendar","AI assistant"],"when":"Within a day of each interview","steps":[{"h":"Make quick notes straight after","b":"Right after the interview, record a voice note or jot down who you met, what you talked about, and anything you wish you'd said."},{"h":"Set a same-day reminder","b":"When you add an interview to your calendar, add a second short event an hour after it ends called 'Send thank-you email'."},{"h":"Draft the email","b":"Paste your notes into your AI assistant with this prompt.","p":"Write a short thank-you email after my interview for [role] at [organisation] with [interviewer names]. Notes from the interview: [paste notes]. Keep it under 120 words, warm and professional. Mention one specific thing we discussed, briefly add [one point I forgot to make, if any], and restate my interest. No grovelling or over-the-top language. Give a subject line too."},{"h":"Send from your email","b":"Paste the draft into a new email in Gmail or Outlook, check names are spelled correctly, and send it."}],"example":"Subject: Thank you - Volunteer Coordinator interview Hi Priya and Tom, thank you for your time today. I enjoyed hearing about the plans for the new food bank hub, and it made me even more keen to help build the volunteer team. One thing I didn't mention: I'm trained in safeguarding...","tips":["Use a voice note straight after the interview while details are fresh.","If you didn't get the interviewer's email, send it to the recruiter or HR contact and ask them to pass it on."],"auto":{"trigger":{"type":"calendar_event","detail":"An interview event ends"},"actions":[{"type":"notify","detail":"Remind the user to record interview notes"},{"type":"ai.generate","detail":"Draft a personal thank-you email"},{"type":"email.draft","detail":"Save the draft in the user's email"}]}},{"id":"capture-tasks-and-reminders-with-a-quick-voice-note","t":"Capture tasks and reminders with a quick voice note","d":"Speak a rambling voice note on the go and get back a neat list of tasks, reminders and shopping items ready to add to your phone.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":10,"tools":["Voice notes","AI assistant","Reminders app"],"when":"Whenever you remember something on the go","steps":[{"h":"Record as things come to you","b":"Use your phone's voice recorder, or talk straight into your AI assistant's app. Say everything, like 'need to call the vet, buy milk, Sam's party is on the 14th'."},{"h":"Turn it into lists","b":"Paste the transcript or speak directly to your AI assistant, followed by this prompt.","p":"Turn what I just said into three lists. TASKS: each with a short title, a due date if I mentioned one, and who it's for. CALENDAR: any events with date and time. SHOPPING: items grouped by type. Keep each line short enough for a reminders app. If something is unclear, list it under CHECK rather than guessing. Today is [day and date]."},{"h":"Add them to your apps","b":"Copy tasks into your phone's Reminders or to-do app, events into your calendar, and shopping items into your list app. Some assistants can add reminders directly if you've connected them."},{"h":"Make it a habit","b":"Do it at the same moment each day, such as when you get in the car or after the school run."}],"example":"TASKS: Call vet about Max's jab (by Fri). Return library books (Sat). CALENDAR: Sam's party, Sat 14 Dec, 2pm. SHOPPING: Dairy - milk, butter. Other - birthday card, wrapping paper. CHECK: 'that thing for Mum', what was it?","tips":["Use your phone's built-in voice assistant to set single reminders instantly, and save this recipe for longer brain dumps.","Never record while driving unless it's fully hands-free."],"auto":{"trigger":{"type":"new_file","detail":"A new voice note is saved"},"actions":[{"type":"ai.extract","detail":"Split the note into tasks, events and shopping"},{"type":"list.add","detail":"Add tasks and shopping items to lists"},{"type":"calendar.create","detail":"Add any events to the calendar"}]}},{"id":"build-a-set-of-ready-made-replies-you-can-reuse","t":"Build a set of ready-made replies you can reuse","d":"Get polished templates for the emails you write over and over, saved in Gmail or Outlook and ready in two clicks.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Gmail","Outlook"],"when":"Once, then add to it whenever you write the same email twice","steps":[{"h":"List your repeat emails","b":"Think of the five emails you write most, such as sending prices, booking confirmations, saying you're running late, or declining a request."},{"h":"Have AI write the templates","b":"Paste your list and an example of each (if you have one) into your AI assistant.","p":"Write reusable email templates for these situations: [list your 5 situations]. I am [your role or business]. My tone is [e.g. friendly and professional]. For each template give: a short name, a subject line, and a body under 120 words with [SQUARE BRACKETS] for anything I need to fill in, such as [NAME] or [DATE]. Keep the language plain British English and end each with a clear next step."},{"h":"Turn on templates in your email app","b":"In Gmail, switch on Templates in settings (under Advanced), then save each draft as a template. In Outlook, use My Templates or Quick Parts to save them."},{"h":"Use and improve them","b":"Insert a template, replace the brackets and send. If you keep changing the same sentence, update the saved template."}],"example":"Name: Price list request. Subject: Our prices for [SERVICE]. Body: Hi [NAME], thanks for getting in touch. Our current prices are attached. Most clients choose [PACKAGE], which includes [WHAT'S INCLUDED]. Would you like to book a quick call this week to talk it through?","tips":["Always do a final search for '[' before sending so no placeholders slip through."],"auto":{"trigger":{"type":"manual","detail":"User asks for a set of templates"},"actions":[{"type":"ai.generate","detail":"Write templates for each repeat situation"},{"type":"doc.create","detail":"Save all templates in one reference document"}]}},{"id":"research-the-people-and-company-before-a-call","t":"Research the people and company before a call","d":"Get a quick, sourced background brief on a company or organisation before a sales call, interview or partnership chat.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":10,"tools":["AI assistant","LinkedIn","Google Calendar"],"when":"Before every sales call or interview","steps":[{"h":"Note what you know","b":"Write down the organisation's name and website, and the job titles of the people you're meeting."},{"h":"Ask for a researched brief","b":"Use an AI assistant with web search switched on and paste this prompt.","p":"Search the web and give me a short brief on [organisation name, website] before my [sales call / interview / meeting] on [date]. Include: what they do in two sentences, size and location, recent news from the last 6 months, likely priorities or challenges, and 3 smart questions I could ask that show I've done my homework. Link to your sources and say clearly when you couldn't find something."},{"h":"Check the key facts","b":"Click through to two or three of the sources to make sure the details are current, and look at the people's public LinkedIn profiles yourself."},{"h":"Keep it with the meeting","b":"Paste the brief into the calendar event description so it's in front of you during the call."}],"example":"Riverside Bakeries: family-run bakery chain, 14 shops across the South West. News: opened two cafés in Oct; hiring for a head of operations. Likely priorities: staffing new sites, reducing waste. Ask: 'How are you handling stock across the new cafés?'","tips":["Stick to business information that's public; don't dig into people's private lives.","AI search can mix up companies with similar names, so check the website matches."],"auto":{"trigger":{"type":"calendar_event","detail":"One day before a call with an external guest"},"actions":[{"type":"web.fetch","detail":"Look up the organisation's website and recent news"},{"type":"ai.summarize","detail":"Write a short brief with questions to ask"},{"type":"notify","detail":"Send the brief to the user"}]}},{"id":"plan-your-whole-week-in-15-minutes","t":"Plan your whole week in 15 minutes","d":"Every Sunday, get a realistic week plan with your top three goals, tasks placed around your commitments and time set aside for rest.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Calendar","Outlook Calendar","Reminders app"],"when":"Every Sunday evening","steps":[{"h":"Gather your week","b":"Copy or screenshot next week's calendar and your current to-do list."},{"h":"Ask for a week plan","b":"Paste both into your AI assistant with this prompt.","p":"Help me plan next week. My calendar: [paste or attach]. My to-do list: [paste]. Other things I want to fit in: [e.g. 3 gym sessions, call a friend]. My energy is best in the [morning/afternoon/evening]. Give me: 1) My top 3 goals for the week. 2) A day-by-day plan putting tasks into free gaps, hardest tasks in my best hours, and no day with more than [5] hours of tasks. 3) What I should move to the following week if things slip. 4) One thing to say no to."},{"h":"Block the big tasks","b":"Add the top three goals as time blocks in your calendar so they don't get squeezed out."},{"h":"Set a recurring reminder","b":"Create a weekly reminder or calendar event every Sunday at the same time called 'Plan my week'."}],"example":"Goals: Submit grant application; get boiler serviced; two evenings off. Mon: 9-11 grant draft; book boiler. Tue: gym 7am; grant budget. Wed: evening off. Thu: send grant to Jess for review. Fri: submit grant. Move if needed: clear garage. Say no to: Thursday drinks.","tips":["Plan only about 70% of your free time; the rest catches the things that always come up."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 6pm"},"actions":[{"type":"notify","detail":"Remind the user to plan their week"},{"type":"ai.generate","detail":"Build a day-by-day plan from the calendar and to-do list"},{"type":"calendar.create","detail":"Add time blocks for the top three goals"}]}},{"id":"build-a-ready-to-use-faq-from-your-old-emails","t":"Build a ready-to-use FAQ from your old emails","d":"Turn the questions customers keep asking into a tidy FAQ document with clear answers you can paste into emails, your website or chats.","cat":"Customer Support","side":"work","lvl":"Beginner","mins":30,"tools":["AI assistant","Gmail","Google Docs"],"when":"Once, then refresh every few months","steps":[{"h":"Gather 20 to 30 typical questions","b":"Search your inbox for words like 'how do I', 'when will' and 'can I' and copy the questions into one document. Remove names, emails and order numbers as you go."},{"h":"Add your current answers","b":"Under each question, add a rough note of what you usually say, even if it's messy. Include prices, delivery times and policies as they are today."},{"h":"Ask your AI assistant to organise it","b":"Paste your notes into ChatGPT, Claude or Gemini with this prompt.","p":"Here is a list of questions my customers ask and my rough answers: [paste]. My business: [one line about what you sell or do]. Turn this into a customer FAQ. 1) Merge duplicate questions. 2) Group them under 4 to 7 headings (for example Orders, Delivery, Payments, Returns). 3) Write each answer in plain British English, under 60 words, friendly and specific. 4) Keep all facts exactly as I gave them and mark anything unclear with [CHECK]. 5) At the end, list 5 questions customers probably ask that are missing from my list."},{"h":"Check and save it","b":"Fix every [CHECK] item, then save the FAQ in Google Docs where your whole team can find it. Pin a link in your bookmarks."}],"example":"Delivery How long does delivery take? Most orders arrive in 2 to 4 working days. You'll get a tracking link by email as soon as it ships. Returns Can I return a sale item? Yes, within 14 days, as long as it's unused. [CHECK: do personalised items count?]","tips":["Date the document and update it whenever a price or policy changes, so nobody gives out old answers.","The 'missing questions' list is great material for your website's help page."],"auto":{"trigger":{"type":"schedule","detail":"Every three months"},"actions":[{"type":"notify","detail":"Remind the owner to gather new customer questions"},{"type":"ai.generate","detail":"Merge new questions into the FAQ and flag anything out of date"},{"type":"doc.create","detail":"Save the refreshed FAQ as a new dated version"}]}},{"id":"create-a-free-guide-that-brings-in-new-leads","t":"Create a free guide that brings in new leads","d":"A short, genuinely useful checklist or guide your ideal clients will swap their email for, written with AI and designed in Canva.","cat":"Sales & Leads","side":"work","lvl":"Beginner","mins":60,"tools":["AI assistant","Canva","Mailchimp"],"when":"Once, then share it for months","steps":[{"h":"Choose a problem worth solving","b":"Pick one specific question your clients always ask before they buy, such as 'How do I prepare my garden for a landscaper?'"},{"h":"Get topic ideas and an outline","b":"Paste this prompt into your AI assistant.","p":"I'm a [your job] helping [ideal client]. Suggest 5 ideas for a free one-to-three page guide or checklist they'd happily give their email for. For each: title, the problem it solves, and why it leads naturally to hiring me. Then, for the idea I choose ([pick one or 'the best one']), write the full content: a clear title, a one-line promise, 7 to 10 practical steps or checklist items with a sentence each, one short example, and a friendly closing line inviting them to [book a call / reply]. British English, no fluff."},{"h":"Design it in Canva","b":"Pick a guide or checklist template in Canva, paste the content in, add your logo and colours, and download it as a PDF."},{"h":"Set up the sign-up","b":"Create a sign-up form in Mailchimp (or your email tool) and send the guide in the welcome email. Make it clear people are joining your mailing list."}],"example":"Title: The 10-minute pre-survey checklist for your loft conversion. Promise: Save a second visit and get an accurate quote first time. Items: 1. Measure the highest point of the loft... 6. Photograph the water tank... Closing: Ready for your free survey? Book here.","tips":["Fact-check every tip yourself; your guide is your reputation.","Only send people what they signed up for, and keep the unsubscribe link in every email."],"auto":{"trigger":{"type":"form_submitted","detail":"Someone signs up for the free guide"},"actions":[{"type":"email.send","detail":"Send the welcome email with the guide attached"},{"type":"sheet.append","detail":"Add the new subscriber to the lead list"}]}},{"id":"write-up-interviews-consistently-and-fairly","t":"Write up interviews consistently and fairly","d":"Turn your interview notes or transcript into a write-up that sets out evidence for each criterion, so the panel can compare candidates on facts.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":15,"tools":["Google Meet","AI assistant","Google Docs"],"when":"Straight after each interview","steps":[{"h":"Ask permission before recording","b":"Only record or use AI note-taking if the candidate agrees, and tell them how long the recording will be kept. If they say no, take written notes; it mustn't affect their chances."},{"h":"Get the notes or transcript","b":"Use Google Meet's 'Take notes for me', Zoom AI Companion or Teams recap if your plan includes it, or type up your handwritten notes. Remove the candidate's name and use their code."},{"h":"Ask AI to organise the evidence","b":"Paste the notes into your AI assistant with this prompt.","p":"Here are notes from an interview for [job title], candidate [code]. Criteria: [list]. Organise the notes into a write-up with one section per criterion: what the candidate said (quote where possible), and gaps or questions to follow up. Do not give a score, recommendation or overall opinion. Do not mention accent, appearance, nervousness, age, family or anything outside the criteria. If notes are unclear, say so. Notes: [paste]."},{"h":"Score it yourself and compare","b":"Each interviewer scores against the rubric on their own before discussing. Save the write-up in a private Google Doc with restricted sharing."}],"example":"Candidate C-02, Bookkeeper Accuracy with figures: 'I reconcile 3 bank accounts weekly and found a £1,200 duplicate payment last year.' Using Xero: described bank rules and VAT returns. Follow up: no mention of payroll. Communication: explained a tricky issue to a client clearly.","tips":["The hiring decision must be made by people, using the scores and their own judgement, never by an AI.","Interview notes are personal data and candidates can ask to see them, so keep them factual and professional."],"auto":{"trigger":{"type":"calendar_event","detail":"An interview event ends"},"actions":[{"type":"ai.summarize","detail":"Organise notes into evidence per criterion without scoring"},{"type":"doc.create","detail":"Save a private write-up for the hiring panel"},{"type":"notify","detail":"Remind each interviewer to score separately"}]}},{"id":"fill-a-month-of-social-posts-in-one-sitting","t":"Fill a month of social posts in one sitting","d":"A ready-to-use content calendar in a spreadsheet with dates, themes, captions and image ideas for a whole month of posts.","cat":"Marketing & Social","side":"work","lvl":"Beginner","mins":25,"tools":["AI assistant","Google Sheets"],"when":"Last week of each month","steps":[{"h":"List what's coming up","b":"Write down next month's events, offers, launches, holidays and anything seasonal for your customers. Five or six items is plenty."},{"h":"Ask for a calendar as a table","b":"Paste this into your AI assistant with your details.","p":"Create a social media content calendar for [month and year] for [business name], a [type of business] serving [audience]. We post [number] times a week on [platforms]. Key dates and offers: [list]. Mix the posts roughly 40% helpful tips, 30% behind the scenes, 20% customer stories, 10% offers. Output a table with columns: Date, Day, Platform, Theme, Post caption (under 60 words), Image or video idea, Call to action. Use British English and no hype words."},{"h":"Paste it into Google Sheets","b":"Copy the table and paste it into a new Google Sheet. It usually lands in neat columns; if not, ask the assistant to give it as comma-separated text and use Paste special."},{"h":"Add a status column","b":"Add a column called Status with options like Idea, Drafted, Scheduled, Posted, so you can see your progress at a glance."}],"example":"Tue 3 Mar | Instagram | Tip | 'Three ways to make your lunch break count...' | Flat lay of a packed lunch | Save this for later. Fri 6 Mar | Facebook | Offer | 'Mother's Day gift sets now in...' | Gift set on shop counter | Order by 25 March.","tips":["Keep last month's sheet and tell the assistant which posts did best, so next month leans into what works."],"auto":{"trigger":{"type":"schedule","detail":"On the 25th of each month"},"actions":[{"type":"notify","detail":"Ask the user for next month's key dates and offers"},{"type":"ai.generate","detail":"Build the month's content calendar"},{"type":"sheet.append","detail":"Add each post as a row with status Idea"}]}},{"id":"write-a-clear-help-guide-or-faq-page","t":"Write a clear help guide or FAQ page","d":"A step-by-step help article or FAQ page that answers what customers keep asking, written so anyone can follow it.","cat":"Content & Writing","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"When the same question keeps coming in","steps":[{"h":"Explain it in your own words","b":"Write or say roughly how you'd talk a customer through it, including any common mistakes."},{"h":"Ask for a structured guide","b":"Paste your explanation into your AI assistant with this prompt.","p":"Turn this into a help guide for customers of [business] who are [describe them, e.g. not confident with technology]. Topic: [topic]. My explanation: [paste]. Format: a one-line summary of what they'll achieve; what they need before starting; numbered steps, one action each, under 25 words per step; a 'If something goes wrong' section with the 3 most likely problems and fixes; and 5 FAQs with short answers. Use plain words, no jargon, British English. Mark anything you're unsure about with [CHECK]."},{"h":"Test it on someone","b":"Ask a friend or colleague who doesn't know the process to follow the guide. Wherever they get stuck, add a clearer step."},{"h":"Publish and link to it","b":"Add it to your website and save the link as a quick reply for email or chat so you can send it in seconds."}],"example":"Summary: Set up your new smart thermostat in about 10 minutes. You'll need: your Wi-Fi password, the app. Step 1: Turn off the heating at the boiler... If something goes wrong: 'The app can't find the thermostat' - move your phone closer and try again.","tips":["Add a 'Last checked' date at the bottom and review the guide whenever your product or process changes."],"auto":{"trigger":{"type":"manual","detail":"User describes a process"},"actions":[{"type":"ai.generate","detail":"Write the step-by-step guide and FAQs"},{"type":"doc.create","detail":"Create the help guide document"},{"type":"notify","detail":"Remind the user to test it with someone"}]}},{"id":"turn-a-podcast-episode-into-show-notes-and-clips","t":"Turn a podcast episode into show notes and clips","d":"From one episode transcript, get show notes, chapter times, quotable moments and a list of short clips worth cutting for social.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","YouTube"],"when":"After recording each episode","steps":[{"h":"Get a transcript","b":"Use the transcript from your recording or hosting tool, or upload the episode to YouTube as unlisted and copy the automatic captions from YouTube Studio."},{"h":"Ask for show notes and clip picks","b":"Paste the transcript into your AI assistant with this prompt.","p":"Here's the transcript of my podcast episode: [paste]. Show: [name] for [audience]. Guest: [name, if any]. Give me: 1) 3 episode title options; 2) show notes: a 100-word summary and 5 bullet key takeaways; 3) chapter markers with timestamps; 4) 5 clips of 30-60 seconds for social media, each with start and end time, why it works on its own, and a hook line for on-screen text; 5) 3 short quotes, word for word. Only use what's in the transcript."},{"h":"Cut the clips","b":"Use the timestamps to trim clips in your phone editor, Canva or YouTube Shorts' tools, and add the hook as on-screen text."}],"example":"Title: Why Small Charities Burn Out (and How to Stop It). Clip 2: 14:32-15:20, guest explains 'the volunteer cliff' - works alone because it's a complete story. Hook: 'Every charity hits this at year three.'","tips":["Let your guest know you'll be sharing clips, and send them the links so they can share too."],"auto":{"trigger":{"type":"new_file","detail":"New episode transcript saved"},"actions":[{"type":"ai.summarize","detail":"Write show notes and chapters"},{"type":"ai.extract","detail":"Pick five clips and three quotes with timestamps"},{"type":"doc.create","detail":"Save the episode pack"}]}},{"id":"turn-a-pile-of-articles-into-an-ai-research-notebook","t":"Turn a pile of articles into an AI research notebook","d":"Load your articles, PDFs and links into NotebookLM and ask questions answered only from your sources, with citations you can click.","cat":"Research & News","side":"work","lvl":"Beginner","mins":15,"tools":["NotebookLM","Google Drive"],"when":"When you're researching one topic over several weeks","steps":[{"h":"Gather your sources","b":"Collect the articles, reports and PDFs you trust on the topic. Save PDFs to a Google Drive folder so they're in one place."},{"h":"Create a notebook","b":"Open NotebookLM (free with a Google account), create a new notebook and add your sources: upload files, pick them from Drive or paste website links."},{"h":"Ask questions from your sources","b":"Type questions in the chat. Answers come with numbered citations that jump to the exact passage. Try this to start.","p":"Using only these sources, give me: 1) the 5 main themes across them, 2) where the sources agree and disagree, 3) the key figures or statistics with which source each comes from, 4) the questions these sources don't answer about [my specific question]."},{"h":"Click the citations","b":"Check a few citations to make sure the answer matches the passage. It sticks to your sources, but it can still misread them."},{"h":"Save useful answers","b":"Save good answers as notes in the notebook so your findings build up as you go."}],"example":"Themes: 1) four-day week trials report lower sick leave [1][3]; 2) mixed effects on customer response times [2]... Disagreement: [1] reports productivity up; [4] found no change. Not covered: effects on very small teams under 5 people.","tips":["Only upload documents you're allowed to share with an online tool; keep confidential work files out unless your workplace approves it."],"auto":{"trigger":{"type":"new_file","detail":"A source is added to the research folder"},"actions":[{"type":"ai.summarize","detail":"Summarise the new source"},{"type":"ai.generate","detail":"Update the list of themes and open questions"},{"type":"doc.create","detail":"Save findings to the research notes"}]}},{"id":"fill-in-long-application-forms-faster","t":"Fill in long application forms faster","d":"Get clear draft answers for long application or registration forms, matched to word limits and written from your own facts.","cat":"Documents & Data","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Docs"],"when":"When you face a long form, grant or application","steps":[{"h":"Copy the questions out","b":"Paste every question and its word limit into a Google Doc. It's easier to work on outside the form."},{"h":"Gather your facts","b":"Under the questions, jot down the real facts: dates, numbers, achievements, your reasons. Bullet points are fine."},{"h":"Ask for drafts","b":"Paste the questions and your facts into your AI assistant with this prompt.","p":"Help me answer this application for [what it is]. Below are the questions with word limits, and my notes. For each question, write a draft answer that: uses only the facts in my notes, stays under the word limit (show the word count), answers exactly what is asked, and sounds like a real person in plain English. Where my notes don't give enough to answer well, write [NEED: what's missing] instead of making something up. Questions: [paste] My notes: [paste]"},{"h":"Fill the gaps and make it yours","b":"Add anything marked [NEED], change phrases that don't sound like you, and check every fact before copying the answers into the form."}],"example":"Q3 (max 150 words): Why do you need this funding? Draft (128 words): 'Our community garden has grown from 12 to 40 regular volunteers since 2024, but our only shed was damaged in the March storm...' [NEED: the quote for the replacement shed].","tips":["Don't paste passport, National Insurance or bank numbers into an AI chat. Add those directly to the form yourself."],"auto":{"trigger":{"type":"manual","detail":"User shares form questions and their notes"},"actions":[{"type":"ai.generate","detail":"Draft answers within each word limit"},{"type":"doc.create","detail":"Save the drafts with gaps marked"}]}},{"id":"draft-clear-terms-and-conditions-for-your-services","t":"Draft clear terms and conditions for your services","d":"Get a first draft of simple terms covering payment, cancellations and responsibilities, written plainly and ready for a solicitor to check.","cat":"Small Business Admin","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Word","Google Docs"],"when":"When you start out, or when your terms are out of date","steps":[{"h":"Decide your rules","b":"Jot down how you work: deposits, payment deadlines, cancellation and rescheduling, what happens if something goes wrong, and how you handle complaints."},{"h":"Ask for a plain draft","b":"Paste this prompt and your notes.","p":"Draft simple, plain-English terms and conditions for [business type] providing [services] to [consumers / businesses] in [country]. Use my rules below. Include sections on: quotes and bookings, payment and deposits, cancellations and rescheduling, what's included, customer responsibilities, our responsibilities, complaints, and changes to these terms. Use short sentences and numbered clauses. Add [CHECK WITH SOLICITOR] next to anything that involves legal rights, liability or refunds, because consumer law varies. My rules: [paste notes]"},{"h":"Read it as a customer","b":"Read the draft from your customer's point of view. Is it fair and easy to understand? Edit anything that doesn't sound like you."},{"h":"Have a solicitor check it","b":"Send the draft to a solicitor before you use it. Customers have legal rights you can't sign away, and a professional will make sure your terms are enforceable."}],"example":"3. Cancellations. 3.1 You can cancel or move your booking free of charge up to 48 hours before. 3.2 If you cancel with less than 48 hours' notice, we keep your deposit [CHECK WITH SOLICITOR]. 4. Payment. 4.1 The balance is due within 7 days of the job being completed.","tips":["Many trade associations offer template terms for members, which are worth comparing with your draft."],"auto":{"trigger":{"type":"manual","detail":"User shares their business rules"},"actions":[{"type":"ai.generate","detail":"Draft numbered terms with legal checks flagged"},{"type":"doc.create","detail":"Save the draft for solicitor review"}]}},{"id":"batch-cook-a-week-of-meals-in-one-afternoon","t":"Batch cook a week of meals in one afternoon","d":"Get a step-by-step cooking order for one session that fills your freezer, with labels and reheating notes.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"Before a busy week or a weekend cook-up","steps":[{"h":"Decide what you want to make","b":"Pick how many portions you need, how long you can cook for, and how much freezer space you have."},{"h":"Ask for a batch cooking plan","b":"Paste this prompt into your AI assistant.","p":"Plan a [3]-hour batch cooking session that makes [number] portions of [4] different freezer-friendly meals for [number] people. Equipment: [oven, hob rings, slow cooker, etc.]. Avoid [allergies/dislikes]. Give me: 1) one shopping list; 2) a timed cooking order that overlaps tasks so the oven and hob are always in use; 3) how to cool and portion each meal; 4) label text with the meal name, date made and reheating instructions."},{"h":"Save the labels and plan","b":"Keep the plan in your notes app and copy the label text onto freezer tape or a marker on each tub."}],"example":"0:00 Oven on, chop all onions at once. 0:15 Chilli and bolognese start on the hob. 0:30 Tray of roasted veg in the oven... Label: Veggie chilli - made 9 Nov - defrost overnight, reheat until piping hot throughout.","tips":["Cool food quickly and freeze it within a couple of hours; check official food safety guidance for how long frozen meals keep."],"auto":{"trigger":{"type":"manual","detail":"User asks for a batch cook plan"},"actions":[{"type":"ai.generate","detail":"Create a timed cooking order, shopping list and labels"},{"type":"list.add","detail":"Add ingredients to the shopping list"}]}},{"id":"ask-the-right-questions-for-accessible-travel","t":"Ask the right questions for accessible travel","d":"Get a checklist of questions to send hotels, airlines and attractions so access needs are met before you arrive.","cat":"Travel","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Gmail"],"when":"Before booking a trip with access needs","steps":[{"h":"Describe the needs","b":"Note the access needs for your trip in practical terms, such as using a wheelchair, limited walking, sight loss or needing quiet spaces. Share only what's needed."},{"h":"Get tailored questions","b":"Paste this prompt into your AI assistant.","p":"I'm planning a trip to [destination] for [who]. Access needs: [practical description, e.g. uses a manual wheelchair, can manage 2 steps with help]. Create: 1) questions to ask the hotel (room, bathroom, lifts, entrance, parking); 2) what to arrange with the airline and airport (assistance booking, mobility equipment); 3) questions for attractions; 4) a short, friendly email template I can send to each. Flag anything that should be confirmed in writing."},{"h":"Send and save the replies","b":"Email the questions to each place and save their written replies in one folder, so you can show them on arrival if needed."}],"example":"Hotel: Is there step-free access from the street to reception? Door width of the accessible room? Roll-in shower or bath? Height of the bed? Airline: book assistance at least 48 hours before (check airline site), can the wheelchair go in the hold free of charge? Get this in writing.","tips":["Ask for photos of the accessible room and bathroom: descriptions like 'accessible' vary a lot."],"auto":{"trigger":{"type":"manual","detail":"User describes access needs and destination"},"actions":[{"type":"ai.generate","detail":"Create tailored access questions for each provider"},{"type":"email.draft","detail":"Draft an enquiry email for each hotel or venue"}]}},{"id":"wind-down-for-better-sleep-with-a-sleep-diary","t":"Wind down for better sleep with a sleep diary","d":"Keep a two-week sleep diary and get a calm bedtime routine built around what you find, ready to share with your GP.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"When you've been sleeping badly","steps":[{"h":"Keep a simple diary","b":"For two weeks, note in your notes app each morning: bedtime, rough time you fell asleep, wake-ups, wake time, caffeine and screens in the evening, and how rested you feel out of 5."},{"h":"Look for patterns","b":"Paste the diary into your AI assistant with this prompt.","p":"Here is my 2-week sleep diary: [paste diary]. Don't diagnose anything. Please: 1) summarise my average bedtime, wake time and how rested I felt; 2) point out patterns, like late caffeine or screens on bad nights; 3) suggest a simple 30-minute wind-down routine and 3 small changes based on general sleep hygiene advice; 4) give me a tidy summary I could show my GP."},{"h":"Try the routine for two weeks","b":"Set a phone reminder for the start of your wind-down, and keep the diary going to see if things change."}],"example":"Average: in bed 23:40, asleep around 00:20, up 06:45, rested 2.4/5. Pattern: worst nights followed coffee after 3pm or phone in bed. Wind-down from 22:45: dim lights, phone charging in the kitchen, warm shower, 15 mins reading.","tips":["If poor sleep goes on for weeks, or you snore heavily or feel very sleepy in the day, talk to your GP."],"auto":{"trigger":{"type":"schedule","detail":"Every morning at 7:30am for 2 weeks"},"actions":[{"type":"notify","detail":"Prompt the user to log last night's sleep"},{"type":"ai.summarize","detail":"After 14 days, summarise patterns and suggest a routine"}]}},{"id":"prepare-for-a-conversation-with-a-financial-adviser","t":"Prepare for a conversation with a financial adviser","d":"A one-page summary of your situation and a clear list of questions, so a paid appointment with an adviser or free money service goes further.","cat":"Money","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"Before any money appointment","steps":[{"h":"Jot down your situation","b":"In rough notes, list your income, regular costs, savings, debts and what you want help with. Totals are enough, you don't need account details."},{"h":"Turn notes into a brief","b":"Paste your notes into your AI assistant with this prompt.","p":"I have an appointment with [a financial adviser / a free debt advice service / my bank / a pension guidance service] about [topic]. Here are my rough notes: [paste]. Turn this into a one-page summary with headings: About me, Income, Regular outgoings, Savings, Debts, What I want to achieve, What's worrying me. Then list 8 to 10 clear questions I should ask, including questions about fees, risks and alternatives. Also list documents I should bring. Don't give me advice yourself, help me prepare."},{"h":"Save it as a document","b":"Paste the result into Google Docs or Word, correct anything that isn't right, and print or share it before the appointment."},{"h":"Take notes during the meeting","b":"Use the questions as a checklist and write the answers next to each one."}],"example":"Goal: understand whether to overpay my mortgage or build savings first. Questions: 1) What are your fees and how are you paid? 2) What would you need to know to recommend either option? 3) Are there penalties for overpaying? Bring: latest mortgage statement, payslips, savings totals.","tips":["Check an adviser is properly registered with your country's financial regulator before you share anything.","Use totals, not account numbers, when preparing with AI."],"auto":{"trigger":{"type":"calendar_event","detail":"An event tagged money appointment is three days away"},"actions":[{"type":"notify","detail":"Remind the user to update their notes"},{"type":"ai.generate","detail":"Create the one-page summary and question list"},{"type":"doc.create","detail":"Save the brief as a document"}]}},{"id":"remember-more-of-the-books-you-read","t":"Remember more of the books you read","d":"A short summary of each book in your own words, the ideas worth keeping and a few questions to discuss, saved in one reading log.","cat":"Learning","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notion"],"when":"When you finish a book or chapter","steps":[{"h":"Jot down what you remember","b":"Right after finishing, write five rough bullet points: what it was about, what stuck with you, and any quotes you marked."},{"h":"Turn it into a reading note","b":"Paste your bullets into your AI assistant with this prompt.","p":"I just finished [book title] by [author]. Here's what I remember: [paste notes]. Using mainly my notes, help me write a reading note with: a 3-sentence summary in plain words, the 3 ideas or moments I seem to value most, one thing I might do differently because of this book, and 3 discussion questions. Then ask me 2 questions to help me remember more. Don't invent details about the book that I haven't mentioned; if you're unsure about something, say so."},{"h":"Save it in your reading log","b":"Paste the result into a Notion page, Google Doc or notes app called Reading log, one entry per book."},{"h":"Review at the end of the year","b":"Ask the AI to read your whole log and tell you the themes that come up most."}],"example":"Summary: A family running a seaside guesthouse faces one last summer before selling. What stuck: the grandmother's letters, the idea that small routines hold a family together. Try: Sunday dinners without phones. Discuss: Was selling the right choice?","tips":["Working from your own notes helps you remember far better than reading an AI summary of the book.","AI can mix up plot details of less famous books, so trust your notes over its memory."],"auto":{"trigger":{"type":"manual","detail":"User finishes a book and adds notes"},"actions":[{"type":"ai.summarize","detail":"Turn rough notes into a reading log entry"},{"type":"doc.create","detail":"Add the entry to the reading log"},{"type":"notify","detail":"Send a yearly themes summary in December"}]}},{"id":"shortlist-the-best-jobs-from-your-alerts-each-week","t":"Shortlist the best jobs from your alerts each week","d":"A weekly ranked shortlist of the job alerts that genuinely match what you want, so you spend time applying rather than scrolling.","cat":"Careers","side":"life","lvl":"Intermediate","mins":20,"tools":["LinkedIn","Gmail","AI assistant"],"when":"Once a week","steps":[{"h":"Set up job alerts","b":"Turn on email job alerts on LinkedIn and one or two other job sites you use, with your target role and location."},{"h":"Collect alerts in one label","b":"In Gmail's settings, under Filters, send emails from those job sites to a label called Job alerts, skipping the inbox if you like."},{"h":"Write down what you want","b":"List your must-haves (salary range, location, hours, sector) and nice-to-haves once, in a note you can reuse."},{"h":"Rank the week's jobs","b":"Copy the week's alert emails into your AI assistant with this prompt.","p":"Here are this week's job alert emails and my criteria. Must-haves: [list]. Nice-to-haves: [list]. Deal-breakers: [list]. My background in one line: [summary]. List every job mentioned, remove duplicates, and score each from 1 to 10 for fit. Return a table sorted by score with: Job title, Employer, Location, Salary if shown, Score, One-line reason. Then pick the top 3 and say what I should emphasise in each application. [paste alerts]"},{"h":"Apply to the top few","b":"Open the original listings for your top picks and check the details before applying, as alert emails can be incomplete."}],"example":"1) Community Engagement Officer, Riverside Trust, hybrid, £29k: 9/10, matches events and volunteering background. 2) Events Assistant, City Arts, £26k: 7/10, lower pay but strong sector fit. Removed 14 duplicates and 6 that need driving licence.","tips":["Fewer, well-matched applications usually do better than many rushed ones.","Always check the original listing, as salaries and closing dates in alerts may be missing or out of date."],"auto":{"trigger":{"type":"schedule","detail":"Every Sunday evening"},"actions":[{"type":"ai.extract","detail":"Pull jobs from the week's alert emails"},{"type":"ai.classify","detail":"Score each job against the user's criteria"},{"type":"notify","detail":"Send the ranked shortlist"}]}},{"id":"keep-a-simple-journal-and-see-your-patterns","t":"Keep a simple journal and see your patterns","d":"A nightly two-minute journal prompt, plus a monthly reflection that shows what lifted your mood and what drained you.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":15,"tools":["Reminders app","Notes app","AI assistant"],"when":"Every evening, plus monthly","steps":[{"h":"Set a nightly reminder","b":"Create a recurring reminder at a time that suits you, such as 9:30pm, called 'Two-minute journal'."},{"h":"Answer three short questions","b":"In one running note, add today's date and answer: What went well? What was hard? How did I feel, from 1 to 10? Voice notes transcribed into text work too."},{"h":"Reflect monthly","b":"At the end of each month, copy the month's entries into your AI assistant with this prompt.","p":"Here are my journal entries for [month]. Read them gently and give me: 1) my average mood score and how it changed over the month, 2) the things that seem to lift my mood, 3) the things that seem to drain me, 4) any patterns by day of the week, and 5) two small, kind experiments I could try next month. Be warm and non-judgemental. This is for reflection, not diagnosis. [paste entries]"},{"h":"Try one experiment","b":"Pick one suggestion and add it to your reminders for the coming month."}],"example":"October average mood: 6.4, rising from 5.8 to 7.1. Lifted by: walks at lunch (mentioned 9 times), calls with your sister. Drained by: late Sunday emails, skipped breakfasts. Experiment: no work email after 7pm on Sundays.","tips":["Journals are very personal. Remove names and only share what you're comfortable with an AI service seeing.","If low mood lasts or feels overwhelming, please speak to your GP or a mental health service. AI is not a substitute for support."],"auto":{"trigger":{"type":"schedule","detail":"Every evening, plus the last day of each month"},"actions":[{"type":"notify","detail":"Send the nightly journal prompt"},{"type":"file.save","detail":"Save the entry to the journal note"},{"type":"ai.summarize","detail":"Write a monthly mood and patterns reflection"}]}},{"id":"clear-out-newsletters-you-never-read","t":"Clear out newsletters you never read","d":"End up with a short list of newsletters worth keeping and a quick plan to unsubscribe from the rest.","cat":"Email & Inbox","side":"work","lvl":"Beginner","mins":20,"tools":["Gmail","Outlook","AI assistant"],"when":"Once a quarter","steps":[{"h":"Find who's emailing you","b":"In Gmail, look for 'Manage subscriptions' in the left menu if your account has it, or search for the word unsubscribe. In Outlook, search for unsubscribe and sort by sender."},{"h":"Copy the list of senders","b":"Write down or copy the sender names and roughly how often they arrive."},{"h":"Let AI help you decide","b":"Paste your list into your AI assistant with this prompt.","p":"Here's a list of newsletters and marketing emails I get, with how often: [paste list]. What I care about right now: [e.g. local events, my running club, deals on kids' clothes]. Sort them into three groups: Keep (useful and I'd miss it), Keep but filter out of my inbox (occasionally useful), and Unsubscribe. Give one short reason for each. Put the Unsubscribe list first."},{"h":"Unsubscribe in one sitting","b":"Use the unsubscribe link at the top of each email in Gmail or Outlook. For the 'filter' group, set up a filter or rule to send them to a Reading label or folder."}],"example":"Unsubscribe (14): Shoe outlet daily deals, three old webinar lists, travel site you used once. Keep but filter (6): supermarket offers, two shops. Keep (4): Running club news, local library events, school newsletter, Sunday book review.","tips":["Only use unsubscribe links from brands you recognise; for spammy senders, mark as spam instead."],"auto":{"trigger":{"type":"schedule","detail":"First Saturday of every quarter"},"actions":[{"type":"ai.classify","detail":"Sort newsletter senders into keep, filter and unsubscribe"},{"type":"notify","detail":"Send the unsubscribe list to the user"}]}},{"id":"find-out-where-your-week-s-time-really-goes","t":"Find out where your week's time really goes","d":"Get a breakdown of your calendar by type of meeting, plus three practical changes to win back a few hours a week.","cat":"Meetings & Calendar","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Google Calendar","Outlook Calendar"],"when":"Once a month","steps":[{"h":"Copy two weeks of your calendar","b":"Switch to the week or schedule view and copy or screenshot the last two weeks, including meeting titles and times."},{"h":"Ask for an audit","b":"Paste or attach it with this prompt. Shorten any sensitive meeting titles first.","p":"Analyse my calendar for the last two weeks: [paste or attach]. My working hours are [hours]. My most important goals right now are [goals]. Give me: 1) Hours spent per category (1:1s, team meetings, external, admin, focus time, other) in a table. 2) Recurring meetings that could be shorter, less frequent or replaced by a written update. 3) The longest stretch of free time each day. 4) Three specific changes I could make next week, with the hours each would save."},{"h":"Make one change this week","b":"Pick the easiest suggestion, such as shortening a recurring meeting from 60 to 30 minutes, and change it in your calendar today."}],"example":"Team meetings: 9.5 hrs. 1:1s: 4 hrs. External: 3 hrs. Focus time: 2 hrs. Suggestions: make Friday wrap-up a written update (saves 1 hr); shorten weekly ops to 30 min (saves 2 hrs over 2 weeks); block Tue and Thu 9-11 as focus time.","tips":["Google Calendar's Time Insights panel and Outlook's Viva Insights (if available) give you similar numbers automatically."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of every month"},"actions":[{"type":"web.fetch","detail":"Read the last two weeks of calendar events"},{"type":"ai.classify","detail":"Group events into meeting categories"},{"type":"ai.generate","detail":"Suggest three changes to free up time"},{"type":"notify","detail":"Send the audit to the user"}]}},{"id":"look-back-on-your-month-and-plan-the-next","t":"Look back on your month and plan the next","d":"Answer five quick questions and get a short monthly review: what went well, what didn't and three focus points for next month.","cat":"Planning & Productivity","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Notes app","Google Calendar"],"when":"Last Sunday of every month","steps":[{"h":"Scroll back through your month","b":"Look at your calendar, photos and to-do lists from the last four weeks to jog your memory."},{"h":"Talk it through with AI","b":"Paste this prompt and answer the questions it asks, one at a time.","p":"Run a monthly review with me. Ask me these questions one at a time and wait for each answer: 1) What went well this month? 2) What didn't go to plan, and why? 3) What drained my energy? 4) What gave me energy? 5) What do I want more of next month? Then write a summary with: 3 wins, 2 lessons, and 3 specific focus points for [next month], each with one small action I can put in my calendar. Keep it encouraging and honest."},{"h":"Schedule the focus points","b":"Add each small action to your calendar for next month, and save the summary in a 'Monthly reviews' note."},{"h":"Make it recurring","b":"Create a monthly repeating calendar event so the review happens without you having to remember."}],"example":"Wins: Finished the website refresh; ran 3 times a week; booked summer holiday. Lessons: Saying yes to Saturday work wore me out. Focus for December: Protect weekends (block Saturdays); finish online course (2 x 30 min a week); call Gran fortnightly.","tips":["Read last month's summary before you start, so you can see whether last month's focus points happened."],"auto":{"trigger":{"type":"schedule","detail":"Last Sunday of every month at 7pm"},"actions":[{"type":"notify","detail":"Remind the user to do their monthly review"},{"type":"ai.generate","detail":"Ask the review questions and write the summary"},{"type":"calendar.create","detail":"Add next month's focus actions"}]}},{"id":"start-each-day-with-a-summary-of-overnight-messages","t":"Start each day with a summary of overnight messages","d":"A five-minute morning routine that summarises new customer emails, ranks what's urgent and suggests who should handle each one.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":15,"tools":["Gmail","AI assistant","Google Calendar"],"when":"Every working morning","steps":[{"h":"Group your support emails","b":"Make sure customer emails get a label such as Support, using a Gmail filter on your support address or common words."},{"h":"Set a daily calendar slot","b":"Add a recurring 15-minute Google Calendar event each working morning called 'Overnight support check'."},{"h":"Use built-in AI if you have it","b":"If your plan includes Gemini in Gmail, open the Support label, open the Gemini side panel and ask it to summarise unread emails in this label. Otherwise copy the emails into your AI assistant."},{"h":"Ask for a ranked list","b":"Use this prompt with whichever AI you're using.","p":"Here are customer emails received since [time yesterday]: [paste, or refer to the unread emails in my Support label]. Give me a table with: sender first name, one-line summary, category, urgency (High/Medium/Low) and suggested owner from this team: [names and what they handle]. Put High urgency first. Mark High if the customer is waiting on a delivery today, has been charged wrongly, or is threatening to leave. Then list any that could be answered with a standard reply."},{"h":"Hand out the work","b":"Share the table in your team chat or just work down it yourself, starting at the top."}],"example":"High: Ellie - charged twice for order - Billing - Owner: Sam. High: Dev - wedding cake order for Saturday, no confirmation - Orders - Owner: Mia. Medium: Kofi - asks about gluten-free options - Product - Owner: Mia. Standard reply possible: 3 delivery-time questions.","tips":["Copilot in Outlook can do the same summary if your plan includes it.","Check your workplace AI policy before pasting customer emails into an AI assistant."],"auto":{"trigger":{"type":"schedule","detail":"Every weekday at 8:30am"},"actions":[{"type":"ai.summarize","detail":"Summarise unread Support emails from overnight"},{"type":"ai.classify","detail":"Rank by urgency and suggest an owner"},{"type":"message.send","detail":"Post the ranked list to the team chat"}]}},{"id":"turn-every-sales-call-into-clear-next-steps","t":"Turn every sales call into clear next steps","d":"After each call, get a summary of what the prospect needs, their concerns, agreed actions and a ready-to-send follow-up email.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":10,"tools":["Zoom","AI assistant","Gmail"],"when":"Straight after every sales call","steps":[{"h":"Ask before you record","b":"Tell the prospect at the start that you'd like to take notes with an AI tool and check they're happy. If not, take handwritten notes instead."},{"h":"Get the notes or transcript","b":"If your plan includes Zoom AI Companion or Google Meet's 'Take notes for me', switch it on for the call. Otherwise, record a voice note of your key points right after the call."},{"h":"Turn them into a summary and email","b":"Paste the transcript, AI notes or your voice note text into your AI assistant with this prompt.","p":"Here are notes from a sales call with [prospect role] at [company]: [paste]. Give me: 1) Their situation in 3 lines, 2) Needs and goals, 3) Concerns or objections, word-for-word where possible, 4) Budget and timing if mentioned, 5) Agreed next steps with who and when, 6) My honest read of how likely they are to buy and why. Then write a follow-up email under 150 words that thanks them, recaps what we agreed in bullet points and confirms the next step. British English."},{"h":"Send and log it","b":"Send the follow-up the same day and paste the summary into your lead sheet or CRM notes."}],"example":"Needs: shopfront signage before July opening. Concern: 'last sign company was months late'. Budget: around £1,800. Next steps: I send 3 design ideas by Fri; they confirm sizes by Wed. Likelihood: high, firm deadline and budget. Email: 'Thanks for your time today, Raj. As agreed...'","tips":["Always check AI meeting notes for names and numbers before sending them to a client.","Store notes on prospects securely and delete them if the deal doesn't go ahead and you no longer need them."],"auto":{"trigger":{"type":"calendar_event","detail":"A sales call in the calendar ends"},"actions":[{"type":"ai.summarize","detail":"Summarise needs, concerns and agreed actions from the notes"},{"type":"email.draft","detail":"Draft a follow-up email to the prospect"},{"type":"sheet.update","detail":"Add the summary to the lead's row"}]}},{"id":"answer-staff-questions-from-your-own-handbook","t":"Answer staff questions from your own handbook","d":"A private AI workspace loaded with your staff handbook and policies, so you or your team get quick, accurate answers with the source section named.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Drive"],"when":"Whenever someone asks 'what's our policy on...?'","steps":[{"h":"Collect up-to-date documents","b":"Gather your handbook, holiday rules, expenses process and other policies from Google Drive. Make sure none contain individual staff details."},{"h":"Create a workspace","b":"Set up a Project in ChatGPT or Claude, or a Gem in Gemini, and upload the documents. Use a business or team plan if you'll share it with staff, and check your workplace AI policy first."},{"h":"Add clear instructions","b":"Paste this into the workspace's instructions.","p":"You answer staff questions about policies at [business] using only the uploaded documents. For each answer: give a short, plain-English answer, then name the document and section it comes from. If the documents don't cover the question, say 'This isn't covered in our policies, please ask [name/role]'. Never guess, never give legal advice, and don't comment on individual cases such as someone's pay, performance or health; refer those to [name/role]. British English, friendly."},{"h":"Test it with real questions","b":"Ask ten questions you get often and check each answer against the handbook before you rely on it."},{"h":"Update when policies change","b":"Replace old files in the workspace the same day a policy changes, and note the date in the instructions."}],"example":"Q: Can I carry over unused holiday? A: Yes, up to 5 days into the next holiday year, which must be used by the end of March. Source: Staff Handbook, section 4.3 'Holiday carry-over'. Q: Can I get a pay rise? A: This isn't covered in our policies, please ask Jo in the office.","tips":["Personal issues like sickness, grievances or pay should always go to a person, not an AI.","Keep the handbook itself as the official version; the AI is just a quicker way to find things in it."],"auto":{"trigger":{"type":"message_received","detail":"A staff member asks a policy question"},"actions":[{"type":"ai.generate","detail":"Answer from the uploaded handbook and name the section"},{"type":"notify","detail":"Pass questions not covered to the named person"}]}},{"id":"write-a-weekly-linkedin-post-from-your-notes","t":"Write a weekly LinkedIn post from your notes","d":"Keep a running list of thoughts in Notion and turn the best one into a polished LinkedIn post every week, scheduled ahead.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":20,"tools":["Notion","AI assistant","LinkedIn"],"when":"Every Monday morning","steps":[{"h":"Set up an ideas page in Notion","b":"Create a Notion database called LinkedIn ideas with columns for Idea, Story or example, and Status. Add anything that comes up during your week."},{"h":"Pick one idea and draft it","b":"Copy your chosen idea and example into your AI assistant with this prompt. If your Notion plan includes Notion AI you can run it right inside the page.","p":"Write a LinkedIn post from this idea: [idea]. Real example from my work: [example]. I am a [job title] who helps [audience]. Structure: a one-line hook that states a surprising point; the story in 3-4 short paragraphs; one practical lesson readers can use today; a closing question. 150-220 words. No emoji, no hashtags in the body, up to 3 hashtags at the end. British English, plain and warm, no buzzwords."},{"h":"Edit it into your own words","b":"Change at least one sentence so it sounds like you speaking. Remove anything that names a client without their permission."},{"h":"Schedule it on LinkedIn","b":"When writing a post on LinkedIn, use the clock icon to schedule it for a time your audience is online, such as Tuesday mid-morning. Mark the idea as Posted in Notion."}],"example":"Hook: 'The best proposal I ever wrote was one page long.' Story: a client who skimmed a 20-page deck... Lesson: lead with the decision you need from them. Question: 'What's the shortest document that ever won you work?' #consulting #writing","tips":["Keep client stories anonymous unless you have written permission to name them."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8am"},"actions":[{"type":"web.fetch","detail":"Read the newest idea marked Ready in the Notion database"},{"type":"ai.generate","detail":"Draft the LinkedIn post"},{"type":"notify","detail":"Send the draft to the user to edit and schedule"}]}},{"id":"get-a-morning-digest-of-news-in-your-field","t":"Get a morning digest of news in your field","d":"A short daily briefing with the five stories that matter for your job or industry, each summarised in two lines with a link.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":10,"tools":["AI assistant"],"when":"Every weekday morning","steps":[{"h":"Decide what you want to follow","b":"List your industry, two or three topics, any sources you trust, and what you want to skip."},{"h":"Create a scheduled task","b":"In ChatGPT, if your plan includes scheduled tasks, ask it to run this every weekday at 7.30am. It will notify you when the digest is ready. Gemini also offers scheduled actions on some plans.","p":"Every weekday, search for the most important news from the last 24 hours about [industry/topics] relevant to [your role] in [country]. Prefer [trusted sources]. Skip [topics to ignore]. Give me 5 items: headline, two-line summary, why it matters to someone in my role, and the link. Then one line: 'Worth writing about:' with a content idea if any story suits my audience of [audience]."},{"h":"Test it and tighten it","b":"Read the first few digests and reply with changes like 'fewer big-company stories, more UK small business'. Update the task's prompt to match."},{"h":"No scheduled tasks? Use a fallback","b":"Save the prompt in your notes app and run it each morning in any AI assistant with web search, or set up Google Alerts for your topics."}],"example":"1. New rules on cookie banners from 1 Jan - affects every small business website; check your site's consent pop-up. (link) 2. Card fees cut for small retailers... Worth writing about: 'What the new cookie rules mean for your shop website.'","tips":["Click through before sharing any story; summaries can miss nuance or mix up dates."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 7.30am"},"actions":[{"type":"web.fetch","detail":"Search news from the last 24 hours on chosen topics"},{"type":"ai.summarize","detail":"Pick and summarise the top five stories"},{"type":"notify","detail":"Send the digest to the user"}]}},{"id":"create-a-set-of-matching-images-for-your-brand","t":"Create a set of matching images for your brand","d":"A reusable style recipe and a batch of AI-made images that all look like they belong together, for posts, blogs and slides.","cat":"Video, Image & Voice","side":"work","lvl":"Beginner","mins":20,"tools":["AI assistant","Canva"],"when":"When you need images and have no photos","steps":[{"h":"Describe your look","b":"Note your brand colours, the mood you want and two or three images you like the style of (described in words, not copied)."},{"h":"Write a style recipe","b":"Ask your AI assistant for a reusable style description, then use it for every image. ChatGPT and Gemini can create images directly; Canva's AI image tools work too.","p":"Create a reusable image style description for [business], whose brand feels [3 words] with colours [colours]. The style should suit [use: social posts, blog headers]. Give me: a one-paragraph style recipe (medium, lighting, colour palette, composition, level of detail, what to avoid). Then use it to create an image of: [first subject]. After that, I'll ask for more images using the same style."},{"h":"Make the rest in the same chat","b":"In the same conversation, ask for each new subject 'in the same style'. Keeping one chat helps the images stay consistent."},{"h":"Add text in Canva","b":"Bring the images into Canva to add headlines and your logo, so text is crisp and spelled correctly."}],"example":"Style recipe: soft watercolour illustration, warm morning light, palette of sage green, cream and terracotta, simple compositions with lots of space, no text, no realistic faces. Images: a teapot on a windowsill; a bike by a garden gate; hands holding a seed packet.","tips":["Don't ask for images in the style of a named living artist or with real people's faces, and check your AI tool's terms for commercial use."],"auto":{"trigger":{"type":"manual","detail":"User describes the brand look and subjects"},"actions":[{"type":"ai.generate","detail":"Write a reusable style recipe"},{"type":"ai.generate","detail":"Create images for each subject in that style"},{"type":"file.save","detail":"Save the images to the brand folder"}]}},{"id":"check-if-your-accounts-were-in-a-data-breach","t":"Check if your accounts were in a data breach","d":"Find out whether your email address has turned up in known data breaches and get a simple, ordered plan to secure the accounts that matter.","cat":"Research & News","side":"work","lvl":"Beginner","mins":15,"tools":["AI assistant","Notes app"],"when":"Now, then whenever you get a breach alert","steps":[{"h":"Check your email address","b":"Visit the free site Have I Been Pwned and enter your email address. You can also sign up there to be emailed if it appears in a future breach."},{"h":"List the breaches found","b":"Write down the name of each breached site and what was exposed (for example email, passwords, phone numbers). Don't paste any actual passwords anywhere."},{"h":"Get an action plan","b":"Paste the list (site names and exposed data only) into your AI assistant with this prompt.","p":"My email appeared in these data breaches: [site name - data exposed - year]. I don't use a password manager yet [change if you do]. Give me a prioritised action plan: 1) which accounts to secure first and why, 2) step-by-step what to do for each (change password, turn on two-step verification, check recovery details), 3) scams I should watch for given what was exposed, 4) how to set up a password manager in simple steps. Don't ask me for any passwords."},{"h":"Work through the list","b":"Start with your email, banking and anything that stores payment details. Tick items off in your notes app as you go."}],"example":"Priority 1: your email account - it's the key to resetting everything else. Change the password and turn on two-step verification. Priority 2: the shopping site (2021 breach exposed passwords) - change it, and anywhere you reused it. Watch for: fake delivery texts using your phone number.","tips":["Never type a password into an AI chat. Genuine services will never ask you to share one there."],"auto":{"trigger":{"type":"new_email","detail":"A data breach notification arrives"},"actions":[{"type":"ai.extract","detail":"Pull out the breached site and data exposed"},{"type":"ai.generate","detail":"Write a prioritised security checklist"},{"type":"list.add","detail":"Add each action to the user's to-do list"}]}},{"id":"turn-survey-responses-into-clear-themes-and-actions","t":"Turn survey responses into clear themes and actions","d":"Collect answers with Google Forms or Microsoft Forms, then get the main themes, standout quotes and suggested actions from the comments.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":20,"tools":["Google Forms","Google Sheets","AI assistant"],"when":"When a survey or feedback form closes","steps":[{"h":"Send responses to a sheet","b":"In Google Forms, open the Responses tab and link it to a Google Sheet. Microsoft Forms can open responses in Excel."},{"h":"Remove personal details","b":"Make a copy of the sheet and delete columns with names, emails or anything that identifies people."},{"h":"Ask for themes","b":"Copy the response columns into your AI assistant (or upload the file) with this prompt.","p":"Below are [number] responses to a survey about [topic]. For the open-text answers: 1) group them into 5 to 8 themes, with the number of responses in each, 2) give 2 short representative quotes per theme, 3) note any urgent or serious issues separately. For the rating questions, give the average and the spread. Finish with 5 suggested actions ranked by how many people they would help. Base everything on the responses; don't invent quotes. [paste responses]"},{"h":"Check the counts","b":"Scan the sheet for a couple of themes to make sure the numbers are roughly right, then share the summary with your team."}],"example":"Themes: Parking (31 responses) - 'I circle for 15 minutes every Saturday'. Opening hours (22) - 'Please open before 9'. Friendly staff (40, positive)... Average rating 4.1/5. Action 1: trial an 8:30 opening on weekdays.","tips":["Run the same prompt each time you repeat the survey so you can compare themes over time."],"auto":{"trigger":{"type":"form_submitted","detail":"Survey closes or reaches a target number of responses"},"actions":[{"type":"ai.classify","detail":"Group open-text answers into themes"},{"type":"ai.summarize","detail":"Write themes, quotes, averages and actions"},{"type":"doc.create","detail":"Save the summary report"}]}},{"id":"turn-receipt-photos-into-a-tidy-expenses-sheet","t":"Turn receipt photos into a tidy expenses sheet","d":"Snap receipts as you go and turn them into a spreadsheet with date, supplier, amount, VAT and category, ready for your bookkeeper.","cat":"Small Business Admin","side":"work","lvl":"Intermediate","mins":15,"tools":["Phone camera","AI assistant","Google Sheets"],"when":"Weekly, or whenever receipts pile up","steps":[{"h":"Photograph receipts straight away","b":"Lay each receipt flat in good light and take a photo. Keep them in one phone album or a Drive folder called 'Receipts'."},{"h":"Set up your expenses sheet","b":"Create a Google Sheet with columns: Date, Supplier, Description, Net, VAT, Total, Category, Payment method."},{"h":"Extract the details","b":"Once a week, upload the photos to your AI assistant with this prompt.","p":"Extract the details from each receipt photo into a table with columns: Date (DD/MM/YYYY), Supplier, Description, Net, VAT, Total, Suggested category (choose from: [your categories, e.g. Materials, Fuel, Travel, Office, Software, Meals]), Payment method. Copy amounts exactly as printed. If VAT isn't shown separately, leave it blank rather than calculating it. Add a 'Check' column and write 'yes' for any receipt that's blurry or unclear."},{"h":"Paste and check","b":"Paste the table into your sheet and check totals against the photos, especially any marked 'Check'."},{"h":"Keep the originals","b":"Keep the receipt photos (and paper copies if needed) for as long as your tax authority requires. Your accountant can tell you how long."}],"example":"04/11/2026 | Fixings Direct | Screws and wall plugs | 18.33 | 3.67 | 22.00 | Materials | Card 06/11/2026 | Station Garage | Diesel | 50.00 | 10.00 | 60.00 | Fuel | Card","tips":["Categories are suggestions only. Ask your accountant which categories and VAT treatment apply to your business.","If you use Xero or QuickBooks, their mobile apps can capture receipts directly, which may suit you better."],"auto":{"trigger":{"type":"new_file","detail":"A receipt photo is added to the Receipts folder"},"actions":[{"type":"ai.extract","detail":"Read date, supplier, amounts and VAT"},{"type":"ai.classify","detail":"Suggest an expense category"},{"type":"sheet.append","detail":"Add a row to the expenses sheet"}]}},{"id":"host-a-dinner-without-the-last-minute-panic","t":"Host a dinner without the last-minute panic","d":"Get a menu, shopping list and backwards cooking timeline so everything is ready at the same time.","cat":"Food & Home","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Reminders app"],"when":"A few days before you host","steps":[{"h":"Note your guests and limits","b":"Write down how many people are coming, their dietary needs, your budget and what kitchen equipment you have."},{"h":"Get a menu and timeline","b":"Paste this prompt into your AI assistant.","p":"I'm hosting [number] people for [lunch/dinner] on [day] and want to eat at [time]. Dietary needs: [vegetarian, gluten-free, etc.]. Budget: about [amount]. I have [one oven, four hobs]. Suggest a [3]-course menu where most things can be made ahead. Then give me: 1) a shopping list by aisle; 2) a make-ahead list for the day before; 3) a timeline for the day counting backwards from serving time, including when to set the table."},{"h":"Set timeline reminders","b":"Add the key timeline points as reminders on your phone, like 'Potatoes in oven' at 6:10pm."}],"example":"Menu: mushroom & lentil pie (everyone, GF pastry), honey-roast carrots, lemon posset. Day before: make possets, fill pie. 5:30pm pie in oven. 6:10pm carrots in. 6:45pm greens on. 7:00pm serve. Shopping: veg - 1kg carrots, 500g chestnut mushrooms...","tips":["Ask guests about allergies in advance and keep the packaging so you can check ingredients if asked."],"auto":{"trigger":{"type":"manual","detail":"User enters guest numbers and serving time"},"actions":[{"type":"ai.generate","detail":"Create a menu, shopping list and backwards timeline"},{"type":"notify","detail":"Send timeline reminders on the day"}]}},{"id":"get-told-when-flight-prices-drop","t":"Get told when flight prices drop","d":"Track the flights you're watching and gather price alerts in one email label so you book at a good moment.","cat":"Travel","side":"life","lvl":"Intermediate","mins":15,"tools":["Google Flights","Gmail","AI assistant"],"when":"When you're flexible about when to book","steps":[{"h":"Turn on price tracking","b":"Search your route in Google Flights (or Skyscanner or Kayak) while signed in and switch on price tracking for your dates or any dates."},{"h":"Label the alerts","b":"In Gmail's settings, under Filters, create a filter for emails from the price alert sender that applies a 'Flight alerts' label and skips the inbox."},{"h":"Decide when to book","b":"When an alert looks good, paste the details into your AI assistant with this prompt.","p":"I'm watching flights from [origin] to [destination] for [dates or flexibility] for [number] people. Here are the recent price alerts: [paste prices and dates]. My budget is [amount] and I need [baggage needs]. Summarise how the price has moved, work out the true cost including bags and seat fees I've listed, and give me a simple checklist of things to confirm before booking. Don't predict future prices as fact."},{"h":"Book on the official site","b":"Check the final price, baggage rules and change policy on the airline's or booking site's page before paying."}],"example":"Price history: 186 (2 Oct) to 162 (18 Oct) to 149 (today) per person. True cost for 2 with one 23kg bag: 149 x 2 + 45 bag = 343. Check: is the bag per flight or per return? Seat fees? Change policy?","tips":["No one can reliably predict flight prices, so set a price you're happy with and book when it's reached."],"auto":{"trigger":{"type":"new_email","detail":"A flight price alert lands in the 'Flight alerts' label"},"actions":[{"type":"ai.extract","detail":"Pull the route, dates and new price"},{"type":"sheet.append","detail":"Log the price to a tracking sheet"},{"type":"notify","detail":"Alert the user if the price is below their target"}]}},{"id":"prep-a-week-of-healthy-lunches-in-an-hour","t":"Prep a week of healthy lunches in an hour","d":"Get a simple meal prep plan with balanced lunches, a shopping list and storage tips for the working week.","cat":"Health & Fitness","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Notes app"],"when":"Sunday, before the working week","steps":[{"h":"Note your preferences","b":"Write down what you like, what you avoid, whether you can reheat at work and how long you want to spend prepping."},{"h":"Ask for a prep plan","b":"Paste this prompt into your AI assistant.","p":"Plan 5 healthy, filling work lunches I can prep in about [60] minutes on Sunday. I [can/can't] reheat at work. I like [foods] and avoid [foods or allergies]. Aim for plenty of vegetables, some protein and wholegrains in each. Give me: 1) two or three base recipes I can mix and match; 2) one shopping list by aisle; 3) the prep order step by step; 4) how to store each lunch and which to eat first."},{"h":"Save the plan","b":"Keep the plan and list in your notes app, and note which lunches you enjoyed for next time."}],"example":"Base 1: chickpea, roasted veg & quinoa bowl. Base 2: chicken, brown rice & greens with a peanut-free satay sauce. Prep: 0:00 oven on, veg in; 0:10 grains on... Eat first: chicken bowls Mon-Tue, chickpea bowls Wed-Fri. Keep dressings separate.","tips":["For specific nutrition needs, such as diabetes or a medical diet, ask your GP or a registered dietitian rather than relying on AI."],"auto":{"trigger":{"type":"schedule","detail":"Saturdays at 11am"},"actions":[{"type":"ai.generate","detail":"Plan 5 prep-ahead lunches and a prep order"},{"type":"list.add","detail":"Add the ingredients to the shopping list"}]}},{"id":"build-a-simple-monthly-budget-that-fits-your-life","t":"Build a simple monthly budget that fits your life","d":"A realistic budget built from your actual income and spending, with a set amount for bills, everyday spending and savings.","cat":"Money","side":"life","lvl":"Beginner","mins":25,"tools":["AI assistant","Google Sheets"],"when":"Once, then review monthly","steps":[{"h":"Write down your monthly income","b":"Note your take-home pay and any other regular money coming in, such as benefits or side income. Use the amount that actually lands in your account."},{"h":"List your fixed costs","b":"Write down rent or mortgage, bills, loan repayments, insurance and childcare. Rough figures are fine to start."},{"h":"Ask the AI to draft the budget","b":"Paste your numbers into your AI assistant with this prompt.","p":"Help me build a monthly budget. My take-home income is [amount]. My fixed costs are: [list with amounts]. My typical spending on groceries, transport, eating out and fun is roughly: [list or 'not sure']. My goals are [for example: build a small emergency fund, stop using my overdraft]. Create a budget table with categories, monthly amount, and weekly amount for flexible categories. Keep it realistic, not strict. Show what's left over and suggest where it could go. Then give me the table in a format I can paste into Google Sheets."},{"h":"Paste it into a sheet","b":"Paste the table into a new Google Sheet and add a column for what you actually spent each month."},{"h":"Review after one month","b":"At month end, paste your actual spending back in and ask the AI which categories need adjusting so the budget stays realistic."}],"example":"Income £2,400. Fixed: Rent £900, Bills £210, Phone £25, Travelcard £140. Flexible: Groceries £280 (£65/week), Eating out £100, Personal £80. Savings: Emergency fund £200. Buffer £465 for irregular costs like gifts and car repairs.","tips":["Include a line for irregular costs like birthdays and car repairs. Budgets fail when these surprise you.","This is a planning tool, not financial advice. For debt or major decisions, speak to a qualified adviser or a free debt charity."],"auto":{"trigger":{"type":"schedule","detail":"Last day of each month"},"actions":[{"type":"notify","detail":"Remind the user to fill in actual spending"},{"type":"ai.summarize","detail":"Compare budget vs actual and suggest adjustments"},{"type":"sheet.update","detail":"Update next month's budget amounts"}]}},{"id":"find-out-what-your-child-is-learning-this-term","t":"Find out what your child is learning this term","d":"A friendly summary of your child's school topics, with simple ways to support them at home and questions to ask at parents' evening.","cat":"Learning","side":"life","lvl":"Beginner","mins":10,"tools":["AI assistant","Phone camera"],"when":"At the start of each school term","steps":[{"h":"Collect the school info","b":"Gather the term's topic letter, curriculum overview or newsletter. Take photos of paper copies."},{"h":"Remove names","b":"Crop out your child's name, teacher names and the school's details if you'd rather not share them."},{"h":"Ask for a parent-friendly summary","b":"Attach the documents to your AI assistant and use this prompt.","p":"This is my [age]-year-old's topic overview for this term in [year or grade]. Summarise it for a busy parent: what they're learning in each subject in plain words, any key words or methods they'll use, and 2 or 3 simple, fun ways I can support each subject at home in under 15 minutes (for example everyday conversations, games, trips, books). Also suggest 4 questions I could ask the teacher at parents' evening."},{"h":"Pin it somewhere visible","b":"Save the summary in your notes app or print it for the fridge so the whole family can use it."}],"example":"Maths: fractions and telling the time. Try: cutting pizza into halves and quarters; asking 'how long until dinner?' Science: plants. Try: growing cress on the windowsill. Ask teacher: How can I help with times tables in the way you teach them?","tips":["Ask it for book suggestions on the term's topics, then check your local library.","Avoid sharing photos with your child's face or full name."],"auto":{"trigger":{"type":"new_email","detail":"An email from school with a topic letter arrives"},"actions":[{"type":"ai.summarize","detail":"Summarise the term's topics for parents"},{"type":"ai.generate","detail":"Suggest home activities and teacher questions"},{"type":"doc.create","detail":"Save the summary to the family notes"}]}},{"id":"walk-into-every-interview-with-a-research-brief","t":"Walk into every interview with a research brief","d":"A one-page brief on the organisation, the role and your best examples, ready in your calendar before each interview.","cat":"Careers","side":"life","lvl":"Intermediate","mins":20,"tools":["Google Calendar","AI assistant","Google Docs"],"when":"Two days before each interview","steps":[{"h":"Add interviews to your calendar","b":"Put each interview in Google Calendar or Outlook Calendar with the company, role and a link to the job ad in the description."},{"h":"Gather public information","b":"Read the organisation's website About page, recent news and the job ad. Copy anything useful. AI assistants that can search the web can help, but check what they find."},{"h":"Build the brief","b":"Paste the material and your CV into your AI assistant with this prompt.","p":"Create a one-page interview brief. Role: [paste job ad]. What I've found about the organisation: [paste website text and news]. My CV: [paste, without contact details]. Include: what the organisation does and its current priorities in 3 bullets, what the role really needs in 5 bullets, my 4 best matching examples from my CV with the requirement each one shows, 3 likely tough questions with notes on how I could answer, and 5 thoughtful questions I could ask them. Use only facts from what I've pasted."},{"h":"Attach it to the event","b":"Save the brief as a Google Doc or Word file and attach or link it in the calendar event so it's there on the day."}],"example":"Riverside Trust: runs 3 community centres, just won funding for a youth programme. Role needs: event planning, volunteer management, reporting. Your example: organised 6 summer fun days with 40 volunteers. Ask them: 'How will success in the youth programme be measured?'","tips":["Check the organisation's own website for the latest facts. AI can mix up organisations with similar names.","Read the brief once the night before, not five minutes before."],"auto":{"trigger":{"type":"calendar_event","detail":"An event with 'interview' in the title is two days away"},"actions":[{"type":"web.fetch","detail":"Gather the organisation's public information"},{"type":"ai.generate","detail":"Build a one-page interview brief"},{"type":"doc.create","detail":"Save the brief and link it to the event"}]}},{"id":"turn-school-and-club-emails-into-calendar-events","t":"Turn school and club emails into calendar events","d":"Dates buried in school newsletters and club emails become calendar events with reminders, so nothing like non-uniform day sneaks up on you.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":20,"tools":["Gmail","Google Calendar","AI assistant"],"when":"Whenever a school or club email arrives","steps":[{"h":"Label the emails","b":"In Gmail's settings, under Filters, create a filter for emails from the school and clubs and give them a label such as Kids. In Outlook, a rule can move them to a folder."},{"h":"Pull out the dates","b":"When a newsletter arrives, copy its text into your AI assistant with this prompt.","p":"Read this school or club email and list every date, deadline or event. For each one, give: date, time if mentioned, title (short, for a calendar), who it's for, what we need to do or bring, and whether it needs a reply, form or payment by a deadline. Return a table sorted by date. Then list any action I need to take this week. [paste email]"},{"h":"Add them to the calendar","b":"Add each event to your family calendar. Gmail sometimes offers to add events it spots in emails too, so check for that first."},{"h":"Set reminders for deadlines","b":"For forms, payments and things to bring, set the reminder for the evening before so there's time to prepare."}],"example":"Fri 22 Nov | All day | Non-uniform day | Both children | Bring £1 each Wed 27 Nov | 3:30pm | Year 3 class assembly | Ellie | Parents welcome By Mon 25 Nov | Trip consent and £8 via school app | Max | Action needed","tips":["Avoid pasting children's full names. The AI doesn't need them.","If your plan includes Gemini in Gmail, you can ask it to find dates in your Kids label directly."],"auto":{"trigger":{"type":"new_email","detail":"A new email arrives in the Kids label"},"actions":[{"type":"ai.extract","detail":"Find dates, deadlines and things to bring"},{"type":"calendar.create","detail":"Add each event with an evening-before reminder"},{"type":"notify","detail":"Flag any action needed this week"}]}},{"id":"get-a-morning-briefing-of-what-matters-in-your-inbox","t":"Get a morning briefing of what matters in your inbox","d":"Start each day with a short list of emails that need a reply, emails you can skim and anything with a deadline.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":15,"tools":["AI assistant","Gmail","Outlook","Reminders app"],"when":"Every weekday morning","steps":[{"h":"Connect your AI assistant to your email","b":"Use Gemini in Gmail, Copilot in Outlook, or the Gmail connector in ChatGPT or Claude if your plan includes it. Check your workplace AI policy before connecting a work account."},{"h":"Save your briefing prompt","b":"Keep this prompt in your notes app so you can paste it each morning.","p":"Look at the emails I received since [yesterday at 5pm]. Give me a briefing in three sections: 1) Needs my reply today: sender, subject, what they want, in one line each. 2) Deadlines or dates mentioned: what, when, and who it's from. 3) Safe to skim or archive: grouped by type (newsletters, receipts, notifications). Ignore anything from [senders to ignore]. Keep the whole briefing under 200 words."},{"h":"Set a daily reminder","b":"Add a recurring weekday reminder at the time you start work, linking to your saved prompt."},{"h":"Use the free fallback if you can't connect","b":"Select the subject lines and senders from your inbox list, copy them, and paste them into your AI assistant with the same prompt."}],"example":"Needs reply: Priya (school office) - confirm trip consent by Wed. Tom (supplier) - approve revised quote. Deadlines: Council tax direct debit changes 1 Dec. Skim: 6 newsletters, 3 delivery updates, 2 receipts.","tips":["AI can miss things, so glance at your unread count once after the briefing.","Tell it which people always matter (your boss, your child's school) so they're never lumped into 'skim'."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 8am"},"actions":[{"type":"ai.summarize","detail":"Summarise emails received since the last briefing"},{"type":"ai.classify","detail":"Sort into reply today, deadlines and skim"},{"type":"notify","detail":"Send the briefing to the user"}]}},{"id":"get-a-2-minute-summary-of-every-meeting","t":"Get a 2-minute summary of every meeting","d":"Finish each video call with a short summary of what was discussed, what was decided and who's doing what, without taking notes.","cat":"Meetings & Calendar","side":"work","lvl":"Intermediate","mins":15,"tools":["Zoom","Google Meet","Microsoft Teams","AI assistant"],"when":"After every video meeting","steps":[{"h":"Switch on your app's note-taker","b":"Use Zoom AI Companion's meeting summary, Google Meet's 'Take notes for me' or Teams Copilot's recap, if your plan includes it. Tell attendees at the start that notes are being taken."},{"h":"Or save the transcript","b":"If you don't have an AI note-taker, turn on transcription or captions where available and download or copy the transcript after the call."},{"h":"Ask for a structured summary","b":"Paste the transcript or the app's own notes into your AI assistant with this prompt. Remove anything confidential first and follow your workplace AI policy.","p":"Summarise this meeting transcript. Meeting: [title], attendees: [names]. Give me: 1) Three-sentence summary. 2) Decisions made. 3) Action items as a table: task, owner, deadline (write 'not set' if none was agreed). 4) Open questions to carry to next time. Use only what was actually said; don't invent owners or dates. Transcript: [paste]"},{"h":"Share it while it's fresh","b":"Paste the summary into the meeting chat, a shared doc or an email to attendees within the hour."}],"example":"Summary: Agreed the spring newsletter goes out 3 March with 4 articles. Decisions: drop the printed version. Actions: Write intro - Kemi - 20 Feb. Gather photos - Dan - 24 Feb. Book printer quote - not set. Open: who approves final copy?","tips":["AI note-takers sometimes mishear names and numbers, so skim the action table before sharing.","Check everyone is comfortable being recorded, especially with external guests."],"auto":{"trigger":{"type":"calendar_event","detail":"A video meeting ends"},"actions":[{"type":"ai.summarize","detail":"Summarise the transcript into decisions and actions"},{"type":"doc.create","detail":"Save the summary in the meeting notes folder"},{"type":"email.draft","detail":"Draft a recap email to attendees"}]}},{"id":"get-a-planning-nudge-from-your-ai-assistant-every-monday","t":"Get a planning nudge from your AI assistant every Monday","d":"Your AI assistant checks in each Monday with a short planning routine, so you start the week with priorities instead of a pile.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":10,"tools":["AI assistant","Notes app"],"when":"Every Monday morning","steps":[{"h":"Find scheduled tasks in your assistant","b":"ChatGPT has scheduled tasks and Gemini has scheduled actions on some plans. If yours doesn't, set a recurring phone reminder that links to a saved prompt instead."},{"h":"Create the weekly check-in","b":"Ask your assistant to schedule this message for every Monday at your chosen time.","p":"Every Monday at [8:30am], send me a weekly kick-off. Ask me three questions: 1) What are the 3 outcomes that would make this week a success? 2) What's the one thing I've been putting off? 3) What's already in the diary that needs prep? Remind me of my longer-term goals: [your goals]. Also include one short, practical productivity tip that fits someone who [describe your work or life]. Keep it under 120 words."},{"h":"Reply with your answers","b":"When the message arrives, answer the questions in the same chat and ask it to turn your answers into a week's to-do list."},{"h":"Review on Friday","b":"On Friday, return to the same chat and ask how you did against Monday's outcomes."}],"example":"Good morning! Week of 10 Nov. 1) What 3 outcomes would make this week a success? 2) What have you been putting off? 3) What needs prep? Your goals: launch the Etsy shop, run 10k by March. Tip: batch all your product photos into one session.","tips":["Update your longer-term goals in the scheduled task each quarter so the reminders stay relevant."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8:30am"},"actions":[{"type":"message.send","detail":"Send the weekly kick-off questions"},{"type":"ai.generate","detail":"Turn the user's answers into a week's to-do list"}]}},{"id":"get-an-ai-helper-that-drafts-replies-from-your-policies","t":"Get an AI helper that drafts replies from your policies","d":"Set up a private AI workspace that knows your FAQ and policies, so every reply draft uses your real prices, rules and tone.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Docs"],"when":"Every time you answer a customer question","steps":[{"h":"Prepare your reference documents","b":"Collect your FAQ, returns policy, delivery info and price list into one or two documents. Make sure none of them contain customer details."},{"h":"Create a workspace in your AI assistant","b":"Use a Project in ChatGPT or Claude, or a Gem in Gemini, depending on what your plan includes. Upload your documents as its files or knowledge."},{"h":"Give it standing instructions","b":"Paste this into the workspace's instructions box so it behaves the same way every time.","p":"You help me reply to customers of [business name], which [what you do]. Always answer using only the uploaded documents. If the answer isn't in them, say 'I don't know from your documents' and suggest what I should check. Write in British English, warm and short (under 120 words), using the customer's first name if I give it. Never invent prices, dates or policies. After each draft, list in one line any facts you used and which document they came from."},{"h":"Use it for each new question","b":"Paste the customer's question with personal details removed and ask for a reply. Check the facts line before you copy the draft into your email or chat."},{"h":"Keep its knowledge current","b":"When a policy or price changes, replace the old file in the workspace straight away."}],"example":"Hi Sam, yes, you can swap the size for free within 30 days. Just pop it back in the original bag with the returns slip, and we'll send the new size as soon as it arrives. Facts used: free exchanges within 30 days (Returns policy, section 2).","tips":["Check your workplace AI policy before uploading business documents.","Keep the AI as your drafting helper, not a bot talking to customers directly, until you've tested it for a few weeks."],"auto":{"trigger":{"type":"message_received","detail":"A new customer question arrives"},"actions":[{"type":"ai.generate","detail":"Draft a reply using only the business's uploaded policies"},{"type":"notify","detail":"Show the draft and the facts used for a person to approve"}]}},{"id":"know-which-leads-to-call-first","t":"Know which leads to call first","d":"Score every lead in your spreadsheet against your own simple criteria, with a short reason, so you spend time on the people most likely to buy.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":20,"tools":["Google Sheets","AI assistant"],"when":"Weekly, or when new leads pile up","steps":[{"h":"Write down what a great lead looks like","b":"List 4 to 6 signs of a good fit, like budget size, location, how they found you and how soon they need help. Note one or two deal-breakers too."},{"h":"Copy your unscored leads","b":"Copy the lead rows from your sheet, including any notes or form answers. Leave out personal phone numbers and emails, as the AI doesn't need them."},{"h":"Ask AI to score them","b":"Paste the rows and your criteria into your AI assistant.","p":"Score these sales leads from 1 to 10 using my criteria. Good signs: [list]. Deal-breakers: [list]. Leads: [paste rows with an ID for each]. Return a table: Lead ID, Score, Hot/Warm/Cold, One-line reason, Suggested next step. Only use information in the rows; if something important is missing, lower the confidence and say what to ask. Put Hot leads first."},{"h":"Add the scores to your sheet","b":"Paste the Score and Reason columns back next to each lead using the IDs. Sort by score and colour Hot leads with conditional formatting."},{"h":"Use your judgement","b":"Treat scores as a starting point. If you know something the AI doesn't, change the score."}],"example":"L-104 | 9 | Hot | Needs a new website by March, budget £3k+, referred by a client | Call today. L-107 | 4 | Cold | Student project, no budget mentioned | Send helpful guide. L-110 | 6 | Warm | Good fit but no timeline | Ask when they want to start.","tips":["Look back after a month: did Hot leads really buy? Adjust your criteria if not.","If your plan includes Gemini in Google Sheets, you can ask it in the side panel instead of copying rows out."],"auto":{"trigger":{"type":"new_row","detail":"A new lead is added to the sheet"},"actions":[{"type":"ai.classify","detail":"Score the lead against the user's criteria"},{"type":"sheet.update","detail":"Write score, rating and reason into the row"},{"type":"notify","detail":"Alert the user about Hot leads"}]}},{"id":"book-interviews-without-endless-email-back-and-forth","t":"Book interviews without endless email back-and-forth","d":"Candidates pick their own interview slot from your calendar and get a clear invitation with everything they need to know.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":25,"tools":["Google Calendar","Gmail","AI assistant"],"when":"Whenever you invite candidates to interview","steps":[{"h":"Create a booking page","b":"In Google Calendar, create an appointment schedule for interview slots, if your plan includes it, or use Calendly's free plan. Add a buffer between slots so you can write notes."},{"h":"Write the invitation with AI","b":"Ask your AI assistant to write a friendly, complete invitation.","p":"Write an interview invitation email for [job title] at [business]. Include: congratulations on being shortlisted, the interview format ([video on Google Meet / in person at address]), length ([45] minutes), who they'll meet ([names and roles]), what we'll cover, whether there's a task, a link to book a slot [booking link] by [date], a request to tell us about any adjustments they need, and who to contact with questions. Under 180 words, warm and clear, British English."},{"h":"Save it as a template","b":"Turn on Templates in Gmail's settings under Advanced, then save the email as a template for this role."},{"h":"Send to shortlisted candidates","b":"Send the invitation individually or with each candidate in BCC, so no one sees anyone else's email address."}],"example":"Hi [Name], thank you for applying for Bookkeeper at Hartley & Co. We'd love to invite you to a 45-minute video interview with Sarah (Office Manager) and me. We'll talk through your experience and a short spreadsheet exercise. Please book a time here by Friday 12th: [link]. Let us know if you need any adjustments.","tips":["Booking pages show your free slots, so check you're only offering times you can really do.","Send a short reminder the day before; it cuts no-shows."],"auto":{"trigger":{"type":"new_row","detail":"A candidate is marked Shortlisted in the hiring sheet"},"actions":[{"type":"email.draft","detail":"Prepare the interview invitation with the booking link"},{"type":"calendar.create","detail":"Hold the interview once the candidate books"},{"type":"notify","detail":"Remind the candidate the day before"}]}},{"id":"announce-new-shop-products-on-social-media","t":"Announce new shop products on social media","d":"Each time you add a product to your Shopify store, you get a ready caption, hashtags and a photo idea to announce it.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":20,"tools":["Shopify","AI assistant","Instagram","Canva"],"when":"Whenever you add a new product","steps":[{"h":"Copy the product details","b":"From the product page in your Shopify admin, copy the title, description, price and any key details like sizes or materials."},{"h":"Write the announcement","b":"Paste the details into your AI assistant with this prompt. If you use Shopify Magic in your admin, it can help with the product description itself.","p":"Write social posts announcing this new product for [shop name], which sells [what you sell] to [audience]. Product details: [paste]. Give me: 1) an Instagram caption (under 90 words, opens with what problem it solves or how it feels to use, mentions the price, ends with 'link in bio'); 2) a Facebook version (under 60 words); 3) 6 hashtags customers would really search; 4) two photo ideas I can shoot at home. Don't add features that aren't in the details."},{"h":"Make the image","b":"Use your own product photo in a Canva template, adding a small 'New' label for a consistent look."},{"h":"Post and tag the product","b":"If you've connected Shopify's Facebook and Instagram sales channel, you can tag the product in your Instagram post so people can tap through to buy."}],"example":"Instagram: 'Cold hands on the school run? Our new merino fingerless gloves keep you warm and still let you use your phone. Six colours, £24. Link in bio.' Hashtags: #merinowool #handmadegloves #winteraccessories ...","tips":["Keep a note of which product posts led to sales in Shopify's analytics, and ask the assistant to write more like those."],"auto":{"trigger":{"type":"new_row","detail":"New product added to the shop"},"actions":[{"type":"ai.generate","detail":"Write Instagram and Facebook announcement posts"},{"type":"doc.create","detail":"Save captions and photo ideas"},{"type":"notify","detail":"Tell the user the announcement is ready to post"}]}},{"id":"save-and-summarise-articles-into-a-notion-library","t":"Save and summarise articles into a Notion library","d":"Every article you save lands in a Notion reading library with a short summary, key points and tags, so you can find it when writing.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":20,"tools":["Notion","AI assistant"],"when":"Whenever you read something useful","steps":[{"h":"Create a reading database","b":"In Notion, make a database called Reading library with properties: Title, Link, Summary, Key points, Tags, Date saved."},{"h":"Install the Notion Web Clipper","b":"Add Notion's Web Clipper to your browser or use the Share button on your phone to send pages straight into the Reading library."},{"h":"Summarise each article","b":"If your plan includes Notion AI, ask it to fill in the summary on the page. Otherwise copy the article text into your AI assistant with this prompt.","p":"Summarise this article for my writing library. Article: [paste]. Give: 1) a 2-sentence summary; 2) 3-5 key points as bullets; 3) any useful statistics with where they came from; 4) one quote worth keeping, word for word; 5) 3 tags from this list: [your tags]. Keep it under 150 words."},{"h":"Use it when you write","b":"Before writing, filter the library by tag to pull together your research quickly."}],"example":"Title: Why four-day weeks work for some teams | Summary: A UK trial found most firms kept the shorter week... | Key points: productivity held steady; burnout fell... | Quote: '...' | Tags: work culture, research, HR","tips":["Keep the original link so you can always go back to the source before quoting it."],"auto":{"trigger":{"type":"new_row","detail":"New page added to the Reading library"},"actions":[{"type":"web.fetch","detail":"Read the article at the saved link"},{"type":"ai.summarize","detail":"Write summary, key points and quote"},{"type":"sheet.update","detail":"Fill in the summary and tags on the page"}]}},{"id":"turn-photos-of-paper-notes-into-a-spreadsheet","t":"Turn photos of paper notes into a spreadsheet","d":"Snap handwritten lists, sign-up sheets or printed tables on your phone and get a clean, editable Google Sheet back in minutes.","cat":"Video, Image & Voice","side":"work","lvl":"Intermediate","mins":10,"tools":["Phone camera","AI assistant","Google Sheets"],"when":"Whenever you have information stuck on paper","steps":[{"h":"Take clear photos","b":"Lay the page flat in good light and photograph it straight on. Your phone's document scanner (in the Notes app or Google Drive app) gives the flattest result."},{"h":"Ask the AI to read it into a table","b":"Attach the photos to your AI assistant with this prompt.","p":"Read the attached photo(s) of [what it is, e.g. a handwritten stock count] and turn it into a table with these columns: [column names]. Keep the original order. If a word or number is hard to read, give your best guess followed by [?]. Don't fill in anything that isn't on the page. After the table, list every [?] item so I can check it."},{"h":"Paste into Google Sheets","b":"Copy the table into a Google Sheet. Check every [?] item against the paper, and spot-check a few numbers."},{"h":"Keep the original","b":"Save the photo in a Google Drive folder next to the sheet in case you need to check it again later."}],"example":"Stock count: Item | Size | Qty. 'Kraft bags' | Large | 140. 'Tissue paper' | A3 | 12 packs [?]. 'Ribbon - gold' | 10m | 6. Check: 'Tissue paper' qty could be 12 or 17.","tips":["For sign-up sheets or forms with names, phone numbers or health details, check your privacy rules and your workplace AI policy before uploading."],"auto":{"trigger":{"type":"new_file","detail":"Photo added to the Scans folder"},"actions":[{"type":"ai.extract","detail":"Read the page into a table and flag unclear items"},{"type":"sheet.append","detail":"Add the rows to the matching sheet"},{"type":"notify","detail":"List items that need checking"}]}},{"id":"get-a-morning-news-briefing-on-topics-you-choose","t":"Get a morning news briefing on topics you choose","d":"Set up a daily briefing from your AI assistant that rounds up news on your chosen topics, with links so you can read further.","cat":"Research & News","side":"work","lvl":"Intermediate","mins":10,"tools":["AI assistant","Reminders app"],"when":"Every weekday at 7am","steps":[{"h":"Pick three to five topics","b":"Be specific: 'electric van grants in the UK' works better than 'cars'. Write them in a note so you can tweak them later."},{"h":"Create a scheduled task","b":"If your plan includes it, ChatGPT's scheduled tasks and Gemini's scheduled actions can run a prompt for you each day and notify you. Paste this prompt and set the time.","p":"Every weekday, search the news from the last 24 hours on these topics: [topic 1], [topic 2], [topic 3]. For each topic give up to 3 stories as: headline, one-sentence summary, why it matters to [who I am, e.g. a small café owner], publisher, date and link. Skip opinion pieces unless clearly labelled. If there is no real news on a topic, say 'nothing new' rather than filling space."},{"h":"Free fallback","b":"No scheduled tasks? Set a recurring 7am reminder in your Reminders app and paste the same prompt into an assistant with web search each morning."},{"h":"Click before you quote","b":"Treat the briefing as a pointer, not the final word. Open the link before you share or act on any story, as dates and details can be wrong."}],"example":"Café trade: 1) Milk prices expected to rise 4p a litre (Farming Weekly, 9 Nov, link). Why it matters: your latte margin. 2) Council opens applications for outdoor seating permits (Local Gazette, 8 Nov, link). Energy grants: nothing new.","tips":["After a week, reply with which stories were useful and which weren't, and ask it to adjust."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 7am"},"actions":[{"type":"web.fetch","detail":"Search news from the last 24 hours for each topic"},{"type":"ai.summarize","detail":"Write up to 3 short items per topic with links"},{"type":"notify","detail":"Send the briefing to the user"}]}},{"id":"combine-two-spreadsheets-that-share-a-column","t":"Combine two spreadsheets that share a column","d":"Match up two lists, such as customers and orders, by a shared column, with a formula you understand and a check for anything that didn't match.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":20,"tools":["Excel","Google Sheets","AI assistant"],"when":"When information you need is split across two files","steps":[{"h":"Put both lists in one file","b":"Copy each list into its own tab in the same spreadsheet. Make sure both have a column that matches, such as an email or order number."},{"h":"Describe the match","b":"Paste this prompt into your AI assistant, along with the header rows of each tab.","p":"I'm using [Excel / Google Sheets]. Tab '[tab 1 name]' has columns: [list]. Tab '[tab 2 name]' has columns: [list]. Both share [matching column]. I want to add [column(s) to bring across] from [tab 2] into [tab 1]. Give me: the formula (use XLOOKUP if available, otherwise VLOOKUP or INDEX/MATCH), which cell to put it in, how to fill it down, how to show 'Not found' instead of an error, and how to count how many rows didn't match. Explain each step simply."},{"h":"Fill it down and check","b":"Add the formula, fill it down, then filter for 'Not found'. These are usually spelling differences or extra spaces in the matching column."},{"h":"Fix the mismatches","b":"Tidy the matching column (for example with TRIM or by fixing typos) and the formula will update automatically."}],"example":"In Customers!E2: =XLOOKUP(B2, Orders!A:A, Orders!D:D, \"Not found\"). Fill down to row 540. Count of unmatched: =COUNTIF(E:E, \"Not found\") gives 17. Most were emails with trailing spaces or typos.","tips":["Emails and codes are better matching columns than names, which are often spelled differently."],"auto":{"trigger":{"type":"manual","detail":"User shares two lists to combine"},"actions":[{"type":"ai.generate","detail":"Write the lookup formula and steps"},{"type":"sheet.update","detail":"Add matched columns to the main list"},{"type":"notify","detail":"Report how many rows didn't match"}]}},{"id":"catch-every-supplier-invoice-email-in-one-place","t":"Catch every supplier invoice email in one place","d":"Automatically label incoming invoice emails, then log them weekly in a sheet with supplier, amount and due date so nothing gets paid late.","cat":"Small Business Admin","side":"work","lvl":"Intermediate","mins":25,"tools":["Gmail","Google Sheets","AI assistant"],"when":"Whenever a new invoice email arrives, plus a weekly log-up","steps":[{"h":"Create an invoice filter","b":"In Gmail's settings, under Filters, create a filter for emails containing words like 'invoice' or 'statement' that have an attachment, and apply the label 'Invoices to pay'. In Outlook, create a rule that moves them to a folder."},{"h":"Set up a bills sheet","b":"Make a Google Sheet with columns: Received, Supplier, Invoice no., Amount, Due date, Paid?, Notes."},{"h":"Log them each week","b":"Once a week, open the label, upload the invoice PDFs to your AI assistant and paste this prompt.","p":"Extract these details from each attached invoice into a table: Received date, Supplier, Invoice number, Amount (including VAT), Due date (DD/MM/YYYY), Payment details shown (yes/no). Copy everything exactly as printed. If a due date isn't shown, write 'not stated'. Do not include bank account numbers in your answer."},{"h":"Paste and sort","b":"Paste the rows into your sheet and sort by due date. Pay or schedule anything due in the next 7 days."},{"h":"Watch for fake invoices","b":"If an invoice comes from a new sender or a supplier's bank details have changed, phone the supplier on a number you already have before paying."}],"example":"10/11 | Greenway Packaging | INV-5521 | £418.80 | 24/11/2026 | No | 10/11 | Brightline Electric | 88213 | £96.00 | 01/12/2026 | No | Direct debit - check","tips":["Check what your filter catches for the first couple of weeks and add or remove keywords as needed."],"auto":{"trigger":{"type":"new_email","detail":"An email with an invoice attachment arrives"},"actions":[{"type":"email.label","detail":"Label it Invoices to pay"},{"type":"ai.extract","detail":"Pull out supplier, number, amount and due date"},{"type":"sheet.append","detail":"Add a row to the bills sheet"},{"type":"notify","detail":"Alert the user to invoices due within 7 days"}]}},{"id":"keep-one-shared-shopping-list-for-the-whole-family","t":"Keep one shared shopping list for the whole family","d":"Set up a shared list everyone adds to by voice or tap, sorted into aisles so the shop is quicker.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":15,"tools":["Reminders app","AI assistant","WhatsApp"],"when":"Set up once, use every day","steps":[{"h":"Create a shared list","b":"In your phone's reminders or notes app, make a list called 'Shopping' and share it with your household. Apple Reminders has a grocery list type that sorts items into sections, and Google Keep lists can also be shared."},{"h":"Turn on voice adding","b":"Check your phone's voice assistant settings so saying 'add milk to my shopping list' goes into the shared list. Show everyone how it works."},{"h":"Tidy the list before you shop","b":"If your list app doesn't sort by aisle, copy the list into your AI assistant with this prompt.","p":"Here's my shopping list: [paste list]. Remove duplicates, combine similar items (for example 'milk' and 'semi-skimmed'), and group everything by supermarket section in this order: [fruit and veg, bakery, meat and fish, dairy, frozen, tins and dry goods, household]. Flag anything vague, like 'snacks', so I can check what was meant."},{"h":"Agree a simple house rule","b":"Post a short message in the family WhatsApp group: 'If you finish it, add it.' This one habit does most of the work."}],"example":"Fruit & veg: bananas, 2 peppers, spinach. Dairy: milk x2 (merged 'milk' and 'semi-skimmed'), cheddar. Frozen: peas. Household: bin bags. Check: 'snacks' - added by Sam, ask what kind.","tips":["Give children their own way to add items, like a magnet whiteboard, and add those to the list when you shop."],"auto":{"trigger":{"type":"message_received","detail":"A household member sends 'add [item]' in the family chat"},"actions":[{"type":"list.add","detail":"Add the item to the shared shopping list"},{"type":"ai.classify","detail":"Sort the item into a supermarket section"}]}},{"id":"keep-every-booking-for-a-trip-in-one-place","t":"Keep every booking for a trip in one place","d":"Pull flight, hotel and car hire confirmations from your inbox into one tidy trip document you can open offline.","cat":"Travel","side":"life","lvl":"Intermediate","mins":20,"tools":["Gmail","Google Docs","AI assistant","Google Calendar"],"when":"Once your main bookings are made","steps":[{"h":"Find the confirmation emails","b":"Search your inbox for words like 'booking confirmation', 'itinerary' or 'reservation', and give each one a label or folder named after the trip."},{"h":"Build a summary","b":"Copy the key parts of each email (remove payment card details) into your AI assistant with this prompt.","p":"Here are my booking confirmations for a trip to [destination]: [paste text]. Create a single trip summary in date order with: date and time (local time), what it is, booking reference, address, check-in or check-out times, what's included, cancellation deadline and contact number. Then list anything missing, like a transfer from the airport on [date], and anything with a tight connection."},{"h":"Save it for offline use","b":"Paste the summary into a Google Docs or Word file and make it available offline, or save it as a PDF on your phone."},{"h":"Check your calendar","b":"Gmail can add flight and hotel bookings to Google Calendar automatically if it's turned on in settings; otherwise, add the key times yourself."}],"example":"Fri 14 Jun 06:40 Flight EZ123 to Lisbon, ref K7PQ2X, bag drop closes 05:55. 13:00 Check in Casa Azul, Rua das Flores 12, free cancel until 7 Jun. Missing: transfer from airport to hotel. Tight: car hire collection 09:00 Sun after late Sat checkout.","tips":["Never paste full card numbers or passport numbers into an AI tool.","Double-check the times against the original emails, especially time zones."],"auto":{"trigger":{"type":"new_email","detail":"A booking confirmation email arrives"},"actions":[{"type":"ai.extract","detail":"Pull date, time, reference, address and cancellation terms"},{"type":"doc.create","detail":"Add the booking to the trip summary document"},{"type":"calendar.create","detail":"Add the booking time to the calendar"}]}},{"id":"go-from-walking-to-running-5k-in-your-calendar","t":"Go from walking to running 5k in your calendar","d":"Get a gentle run-walk plan towards your first 5k, with every session added to your calendar so you just turn up.","cat":"Health & Fitness","side":"life","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Calendar"],"when":"When you're ready to start running","steps":[{"h":"Pick your days","b":"Choose three days a week with at least one rest day between runs, and a realistic time of day."},{"h":"Ask for a run-walk plan","b":"Paste this prompt into your AI assistant.","p":"I'd like to build up to running 5k without stopping. Right now I can [e.g. walk briskly for 30 minutes / run for 1 minute]. I can run on [days] at [time] for about [minutes]. Create a [9]-week run-walk plan with 3 sessions a week. For each session: warm-up walk, run and walk intervals, cool-down, and one tip. Build up gently, include a repeat week if I need it, and list signs I should rest instead."},{"h":"Add every session to your calendar","b":"Create calendar events for each session in Google Calendar or Outlook Calendar, with the intervals in the event description so you can read them on your phone."},{"h":"Log how it felt","b":"After each run, add a word to the event notes, like 'easy' or 'tough'. If a week feels too hard, repeat it."}],"example":"Week 1, Run 1 (Mon 7am): 5-min brisk walk. Then run 60 sec, walk 90 sec x 8. 5-min cool-down walk. Tip: run slowly enough to talk. Week 4, Run 2: run 5 mins, walk 2 mins x 3... Rest if: sharp pain, dizziness, or you're unwell.","tips":["Check with your GP before starting if you have a heart, lung or joint condition."],"auto":{"trigger":{"type":"manual","detail":"User chooses running days and start date"},"actions":[{"type":"ai.generate","detail":"Create a 9-week run-walk plan"},{"type":"calendar.create","detail":"Add each session with its intervals to the calendar"}]}},{"id":"log-receipts-by-snapping-a-photo","t":"Log receipts by snapping a photo","d":"Every receipt you photograph ends up as a tidy row in a spending sheet with the date, shop, amount and category.","cat":"Money","side":"life","lvl":"Intermediate","mins":15,"tools":["AI assistant","Phone camera","Google Sheets","Google Drive"],"when":"Whenever you get a paper receipt","steps":[{"h":"Set up your sheet and folder","b":"Create a Google Sheet with columns Date, Shop, Amount, Category, Notes. Make a Google Drive folder called Receipts for the photos."},{"h":"Snap receipts as you go","b":"Photograph receipts flat and in good light, and save them to the Receipts folder from your phone. Do a batch once a week if that's easier."},{"h":"Turn photos into rows","b":"Once a week, attach that week's receipt photos to your AI assistant with this prompt.","p":"Read each of these receipt photos. For each one, give me a row with: Date (DD/MM/YYYY), Shop, Total amount, Category (choose from: Groceries, Household, Eating out, Transport, Kids, Health, Gifts, Work expense, Other), and a one-line note of the main items. Return a table only, one row per receipt, with columns in that order. If you can't read a value, write CHECK instead of guessing."},{"h":"Paste into your sheet","b":"Copy the table and paste it into your sheet. Fix any cell marked CHECK by looking at the photo."},{"h":"Get a weekly total","b":"Add a simple total at the bottom, or ask the AI to summarise spending by category from your sheet each month."}],"example":"12/11/2026 | FreshMart | £34.20 | Groceries | Milk, bread, chicken, veg 13/11/2026 | City Parking | £6.50 | Transport | 2 hours parking 14/11/2026 | Corner Cafe | £8.90 | Eating out | Two coffees, croissant","tips":["Faded thermal receipts can be misread, so photograph them soon after you get them.","Keep work-expense receipts in a separate folder so claims are easy later."],"auto":{"trigger":{"type":"new_file","detail":"A photo is added to the Receipts folder"},"actions":[{"type":"ai.extract","detail":"Read date, shop, total and items from the receipt"},{"type":"ai.classify","detail":"Assign a spending category"},{"type":"sheet.append","detail":"Add a row to the spending sheet"}]}},{"id":"prepare-a-confident-talk-or-presentation","t":"Prepare a confident talk or presentation","d":"A clear outline for a school or work presentation, speaker notes and a practice session where AI asks you the tough questions.","cat":"Learning","side":"life","lvl":"Beginner","mins":20,"tools":["AI assistant","Google Docs"],"when":"A week before you present","steps":[{"h":"Gather your material","b":"Collect the brief, time limit, audience and your rough ideas or research."},{"h":"Build the outline","b":"Paste your material into your AI assistant with this prompt.","p":"Help me plan a [length]-minute presentation on [topic] for [audience]. My main points and research: [paste]. Create an outline with: an opening hook, 3 main sections with the key point and one example each, a short conclusion, and timing for each part. Then write brief speaker notes for each section in bullet points, not a full script, using my own points. Suggest what to put on each slide in 10 words or fewer."},{"h":"Write it in your voice","b":"Copy the outline into Google Docs or Word and rewrite the notes so they sound like you."},{"h":"Rehearse with questions","b":"Ask the AI: 'Now be my audience. Ask me 5 challenging questions one at a time about this talk, then give feedback on my answers.' Answer out loud if you can, using voice mode."}],"example":"Hook (30s): 'Every year our town throws away the weight of 40 buses in food.' Section 1 (1.5 min): Where food waste happens. Example: supermarket best-before dates. Slide: 'Most waste happens at home'. Likely question: 'Isn't this the supermarkets' fault?'","tips":["Practising answers out loud is the best cure for nerves.","Check any statistics the AI suggests against a reliable source before you use them."],"auto":{"trigger":{"type":"calendar_event","detail":"A presentation event is seven days away"},"actions":[{"type":"notify","detail":"Remind the user to start planning"},{"type":"ai.generate","detail":"Create an outline and speaker notes"},{"type":"doc.create","detail":"Save the outline as a document"}]}},{"id":"keep-every-job-application-organised-in-one-place","t":"Keep every job application organised in one place","d":"A job search tracker that's updated from your emails, showing where you've applied, what stage you're at and who to follow up with.","cat":"Careers","side":"life","lvl":"Intermediate","mins":25,"tools":["Gmail","Google Sheets","AI assistant"],"when":"Weekly during a job search","steps":[{"h":"Create your tracker","b":"Make a Google Sheet with columns: Date applied, Company, Role, Where found, Stage (Applied, Interview, Offer, Rejected), Contact, Next step, Follow-up date."},{"h":"Label job emails","b":"In Gmail's settings, under Filters, create a filter for words like 'application', 'interview' and 'your candidacy' and apply a Job search label. In Outlook, a rule can move them to a folder."},{"h":"Update the tracker weekly","b":"Once a week, copy new emails from the label into your AI assistant with this prompt.","p":"Here are this week's job search emails. For each one, extract: company, role, what the email is (confirmation, interview invite, rejection, request for info), any date or deadline, contact name, and the next step for me. Return a table with columns: Company, Role, Stage, Contact, Next step, Follow-up date. If an email needs a reply, say so in Next step. [paste emails]"},{"h":"Paste and follow up","b":"Update your sheet with the new rows. Set a follow-up date about a week after applying if you've heard nothing."}],"example":"Brightside Charity | Volunteer Coordinator | Interview | Priya (HR) | Reply to confirm 21 Nov 10am | 18 Nov Northgate Council | Admin Officer | Rejected | - | Ask for feedback | - Peak Outdoors | Store Supervisor | Applied | - | Follow up if no reply | 25 Nov","tips":["A tracker stops good leads slipping through the cracks when you're applying to lots of roles.","If your plan includes Gemini in Gmail, you can ask it to summarise the Job search label instead of pasting emails."],"auto":{"trigger":{"type":"new_email","detail":"A new email arrives in the Job search label"},"actions":[{"type":"ai.classify","detail":"Work out the stage: confirmation, interview, rejection or request"},{"type":"sheet.update","detail":"Update or add the matching row in the tracker"},{"type":"calendar.create","detail":"Add interview dates and follow-up reminders"}]}},{"id":"plan-the-family-s-week-in-one-shared-view","t":"Plan the family's week in one shared view","d":"A Sunday summary of who needs to be where each day, who's doing pick-ups and what to prepare, shared with the whole household.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Calendar","WhatsApp","AI assistant"],"when":"Every Sunday evening","steps":[{"h":"Create a shared family calendar","b":"In Google Calendar, create a new calendar called Family and share it with the other adults in the household. Add clubs, appointments and work trips as recurring events."},{"h":"Copy next week's events","b":"On Sunday, open the Family calendar in week view and copy the events, or take a screenshot."},{"h":"Ask for a family plan","b":"Paste or attach next week's events in your AI assistant with this prompt.","p":"Here's our family calendar for next week. Household: [for example 2 adults (A and B), children aged 7 and 11]. For each day, list: who needs to be where and when, who is doing drop-off and pick-up (flag any day where nobody is assigned or two things clash), and anything to prepare the night before (kit, forms, money, packed lunch). End with a short list of clashes to sort and a shopping or prep list for the week. Format it to fit nicely in a WhatsApp message."},{"h":"Share it","b":"Post the plan in your family WhatsApp group and sort out any clashes together."}],"example":"MON: Swimming 5pm (Ellie) - A picks up. Pack: goggles, towel. TUE: Dentist 3:30 (Max) - CLASH: B has a work call until 4. WED: Non-uniform day, £1. THU: B away overnight. Prep list: Wed £1 coin, Fri cake for bake sale.","tips":["Use initials rather than full names and avoid sharing school names with the AI.","Colour-code each person's events in the calendar so clashes are easier to spot."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 7pm"},"actions":[{"type":"web.fetch","detail":"Read next week's family calendar"},{"type":"ai.generate","detail":"Create a daily plan and flag clashes"},{"type":"message.send","detail":"Post the plan to the family group chat"}]}},{"id":"turn-emails-into-a-clear-to-do-list","t":"Turn emails into a clear to-do list","d":"Get every request buried in your inbox pulled into one list with deadlines, then sent straight to your task app.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":15,"tools":["Gmail","Outlook","AI assistant","Reminders app"],"when":"At the end of each working day","steps":[{"h":"Flag emails that need action","b":"As you read, star emails in Gmail or flag them in Outlook. Flagged Outlook emails show up in Microsoft To Do, and in Gmail you can use 'Add to Tasks' from the email menu."},{"h":"Pull out the actual tasks","b":"At day's end, copy the starred or flagged emails into your AI assistant with this prompt.","p":"Read these emails and list every task I need to do. For each give: the task starting with a verb, who it's for, the deadline (or 'no deadline'), and a time estimate (5 min, 30 min, 1 hr+). Merge duplicates. Sort by deadline, then by quickest first. Put anything that just needs a one-line reply in a separate 'Quick replies' list at the top. [paste emails]"},{"h":"Add them to your task app","b":"Copy the list into Google Tasks, Microsoft To Do, Reminders or your notes app, adding the deadlines as due dates."},{"h":"Clear the stars","b":"Unstar or unflag the emails once they're on your list so your inbox shows only new things."}],"example":"Quick replies: Confirm Tues lunch with Ola. Tasks: Send updated quote to Greenway Builders - Fri 14 Nov - 30 min. Book van MOT - by 20 Nov - 5 min. Review draft brochure from Leo - no deadline - 1 hr+.","tips":["Anything taking under two minutes, just do it now instead of listing it."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 5pm"},"actions":[{"type":"ai.extract","detail":"Pull tasks, deadlines and time estimates from flagged emails"},{"type":"list.add","detail":"Add each task to the user's to-do list with its due date"},{"type":"email.label","detail":"Remove the flag once a task is added"}]}},{"id":"run-better-one-to-ones-with-a-shared-running-doc","t":"Run better one-to-ones with a shared running doc","d":"Keep one shared document for every one-to-one, with an agenda that builds itself and a quick AI summary of progress each month.","cat":"Meetings & Calendar","side":"work","lvl":"Intermediate","mins":20,"tools":["Google Docs","Google Calendar","AI assistant","Word"],"when":"Every one-to-one meeting","steps":[{"h":"Create the running doc","b":"Make a Google Doc or Word file shared with the other person, titled with both names. Add the newest meeting at the top each time."},{"h":"Get a good template","b":"Ask your AI assistant for a structure you can copy for each meeting.","p":"Create a simple template for a recurring [weekly / fortnightly] one-to-one between [role] and [role]. Include sections for: wins since last time, topics from each person, blockers, feedback both ways, actions with owners and dates, and one 'bigger picture' question that rotates each week. Give me 8 rotating bigger-picture questions too. Keep headings short."},{"h":"Link it to the meeting","b":"Attach the doc to the recurring calendar event so both of you can add topics during the week."},{"h":"Review progress monthly","b":"Once a month, paste the last four meetings into your AI assistant and ask for themes, repeated blockers and actions that haven't been done."}],"example":"18 Nov. Wins: launched the new booking form. Topics (Ella): training budget. Topics (Raj): holiday cover in Dec. Blockers: waiting on IT access. Actions: Raj - chase IT - Wed. Ella - send course options - Fri. Big question: What's one thing you'd change about how we work?","tips":["Agree together what goes in the shared doc; keep sensitive or HR matters out of it and in proper channels."],"auto":{"trigger":{"type":"calendar_event","detail":"The day before each one-to-one"},"actions":[{"type":"doc.create","detail":"Add a new dated section from the template to the running doc"},{"type":"notify","detail":"Remind both people to add topics"},{"type":"ai.summarize","detail":"Monthly: summarise themes and open actions"}]}},{"id":"set-up-a-project-board-in-minutes","t":"Set up a project board in minutes","d":"Describe your project and get a ready-made board of cards in Trello or Notion, sorted into To do, Doing and Done.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":20,"tools":["AI assistant","Trello","Notion"],"when":"When starting a project with several people or moving parts","steps":[{"h":"Ask AI for the card list","b":"Paste this prompt into your AI assistant.","p":"I'm setting up a project board for [project]. Team: [names and roles]. Deadline: [date]. Give me a list of 15 to 25 cards. Each card is one line in this format: [task starting with a verb] - [owner] - [due date]. Group them under these list headings: Backlog, This week, Waiting on others. Keep tasks small enough to finish in a day or less. Then suggest 3 to 5 labels (e.g. Design, Admin, Urgent) and which cards get which."},{"h":"Create the board","b":"Make a new Trello board or a Notion board database with the lists Backlog, This week, Doing, Waiting on others and Done."},{"h":"Paste the cards in","b":"In Trello, paste several lines into a new card and it offers to create one card per line. In Notion, paste the list into a board and each line becomes a card. Then set owners and due dates."},{"h":"Agree how you'll use it","b":"Ask everyone to move their own cards as they work, and spend five minutes each week reviewing the board together."}],"example":"This week: Confirm venue booking - Ana - 14 Nov. Draft invite wording - Ben - 15 Nov. Backlog: Order name badges - Ana - 28 Nov. Waiting on others: Catering quote from supplier - Ben - 18 Nov. Labels: Venue, Comms, Admin, Urgent.","tips":["Limit 'Doing' to two or three cards per person; it keeps work flowing instead of half-done."],"auto":{"trigger":{"type":"manual","detail":"User describes a new project"},"actions":[{"type":"ai.generate","detail":"Write a list of task cards with owners and due dates"},{"type":"list.add","detail":"Create the cards on the project board"},{"type":"notify","detail":"Tell the team the board is ready"}]}},{"id":"sort-your-support-inbox-into-labels-automatically","t":"Sort your support inbox into labels automatically","d":"Gmail filters that file incoming customer emails into Refunds, Delivery, Bugs and Other, so you can deal with the urgent ones first.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":25,"tools":["Gmail","AI assistant"],"when":"Runs every time an email arrives","steps":[{"h":"Decide your categories","b":"Pick 4 to 6 labels that match the work, for example Refunds, Delivery, Technical, Sales and Other. Create them in Gmail from the left sidebar."},{"h":"Get keyword lists from AI","b":"Paste a handful of real subject lines (no names or addresses) and this prompt into your AI assistant.","p":"I want Gmail filters that sort customer emails into these labels: [list labels]. Here are example subject lines and first sentences from each type: [paste examples]. For each label, give me a list of 8 to 12 words or short phrases to put in a Gmail filter's 'Has the words' box, joined with OR, in a format I can paste straight in. Avoid words so common they'd catch everything. Then list any emails from my examples that might be caught by two filters, and suggest which should win."},{"h":"Create a filter for each label","b":"In Gmail, click the search options icon in the search bar, paste one keyword list into 'Has the words', then choose Create filter and tick Apply the label. Repeat for each category."},{"h":"Check it for a week","b":"Look at what lands in each label daily. Move anything misfiled and add its words to the right filter in Gmail's settings, under Filters."}],"example":"Refunds: refund OR \"money back\" OR chargeback OR \"return my\" OR cancel OR overcharged Delivery: tracking OR courier OR \"not arrived\" OR \"where is my\" OR delayed OR dispatch","tips":["Don't tick 'Skip the inbox' at first; keep everything visible until you trust the filters.","Outlook users can do the same with Rules, found in Outlook's settings under Mail."],"auto":{"trigger":{"type":"new_email","detail":"Any new email to the support address"},"actions":[{"type":"ai.classify","detail":"Decide whether it is a refund, delivery, technical, sales or other request"},{"type":"email.label","detail":"Apply the matching label"},{"type":"notify","detail":"Alert the owner if it looks urgent"}]}},{"id":"reply-to-new-enquiries-before-your-competitors-do","t":"Reply to new enquiries before your competitors do","d":"Website or social enquiries land in a sheet, you get an instant alert, and a ready-made personal reply is waiting to send.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Forms","Google Sheets","Gmail","AI assistant"],"when":"Every time someone fills in your enquiry form","steps":[{"h":"Make an enquiry form","b":"Create a Google Form asking for name, email, what they need, budget range, timing and how they found you. Add a line on how you'll use their details."},{"h":"Send responses to a sheet and turn on alerts","b":"In the form's Responses tab, link it to a Google Sheet and switch on email notifications for new responses. On your phone, allow Gmail notifications so you see them fast."},{"h":"Write a reply template with AI","b":"Ask your AI assistant for a first-reply template you can personalise quickly.","p":"Write a first reply to a new enquiry for [business], which offers [services]. Use [brackets] for their name, what they asked for and timing. It should: thank them, show I've read their request with one specific line, give one helpful piece of information about [price range / process], and offer two ways forward (a 15-minute call via [booking link] or a reply with more details). Under 120 words, British English, warm and professional. Also write a 40-word version for WhatsApp or text."},{"h":"Save it as a Gmail template","b":"Turn on Templates in Gmail's settings under Advanced, then save the reply as a template so you can insert it in one click."},{"h":"Aim to reply within the hour","b":"When an alert arrives, open the sheet, insert your template, fill in the brackets and send."}],"example":"Hi Hannah, thanks for getting in touch about a garden redesign for your back patio this spring. Most patio projects like yours start from £2,500, depending on materials. Easiest next step: book a free 15-minute call here [link], or reply with a couple of photos and I'll suggest some ideas.","tips":["Speed matters: people often go with whoever answers first.","Keep the sheet private, since it contains people's contact details."],"auto":{"trigger":{"type":"form_submitted","detail":"A new enquiry form is submitted"},"actions":[{"type":"sheet.append","detail":"Log the enquiry with date and source"},{"type":"ai.generate","detail":"Personalise the first-reply template"},{"type":"email.draft","detail":"Create the reply draft for the user"},{"type":"notify","detail":"Send a push alert about the new enquiry"}]}},{"id":"give-every-new-starter-a-great-first-week","t":"Give every new starter a great first week","d":"A day-by-day onboarding plan for a new team member, turned into a Trello board with tasks for you, the starter and their buddy.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Trello"],"when":"A week before someone starts","steps":[{"h":"Describe the role and your workplace","b":"Note what the job involves, who they'll work with, which systems they'll use and anything they must do in week one, such as safety training."},{"h":"Ask AI for the plan","b":"Paste this prompt into your AI assistant.","p":"Create an onboarding plan for a new [job title] joining [business], a team of [size]. Role details: [paste]. Give: 1) a before-day-one checklist (equipment, logins, paperwork, welcome message), 2) a day-by-day plan for week 1 with a mix of learning, meeting people and one small real task, 3) goals for the end of week 2, month 1 and month 3, 4) who owns each task: manager, buddy, or new starter. Keep it realistic for a small business and not overloaded. Format as lists I can turn into cards."},{"h":"Build the board","b":"Create a Trello board with lists for Before day one, Week 1, Month 1 and Month 3. Add each task as a card, assign people and set due dates."},{"h":"Copy it next time","b":"Once it works, use Trello's option to make the board a template or copy it, so each new starter gets the same good experience."}],"example":"Before day one: laptop set up (Manager), send welcome message with first-day details (Manager), pick a lunch spot (Buddy). Day 1: tour, meet the team, set up email. Day 3: shadow two customer calls. Day 5: handle one simple order alone; end-of-week chat. Month 1 goal: running the morning orders.","tips":["Add a 'questions so far' card the starter can add to all week; it shows what to explain better next time.","Notion or a shared Google Doc works just as well if your team doesn't use Trello."],"auto":{"trigger":{"type":"calendar_event","detail":"A new starter's start date is 7 days away"},"actions":[{"type":"ai.generate","detail":"Create a tailored onboarding plan for the role"},{"type":"list.add","detail":"Add onboarding tasks as cards with owners and due dates"},{"type":"notify","detail":"Tell the manager and buddy their tasks"}]}},{"id":"get-a-monthly-social-media-results-summary","t":"Get a monthly social media results summary","d":"A one-page summary of what worked on your social accounts last month, what didn't, and three changes to try next month.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":25,"tools":["Google Sheets","AI assistant","Instagram"],"when":"First working day of each month","steps":[{"h":"Gather last month's numbers","b":"Open the insights or analytics area of each platform (Instagram, Facebook via Meta Business Suite, LinkedIn page analytics). Note reach, engagement and follows for each post, or export them if the platform offers a download."},{"h":"Put them in one sheet","b":"Paste them into a Google Sheet with columns: Date, Platform, Post topic, Format, Reach, Likes, Comments, Shares, Saves, Link clicks."},{"h":"Ask for the summary","b":"Copy the table into your AI assistant with this prompt.","p":"Here are last month's social media results for [business]: [paste table]. Our goal is [goal, e.g. bookings, website visits]. Give me: 1) a 3-sentence overview; 2) the top 3 posts and what they have in common (topic, format, timing); 3) the weakest 3 and a likely reason; 4) month-on-month change if I've included last month; 5) three specific experiments for next month. Use only the numbers given; don't invent any. Plain English, one page."},{"h":"Act on one change","b":"Pick one of the experiments and add it to next month's content calendar."}],"example":"Overview: reach up 18%, but link clicks flat. Top posts were all short videos posted before 9am. Weakest: three offer posts with stock images. Try: film two behind-the-scenes clips a week; post offers with real photos; test a Tuesday 8am slot.","tips":["Keep every month in the same sheet on separate tabs so you can ask the assistant to spot trends over a quarter."],"auto":{"trigger":{"type":"schedule","detail":"1st of each month at 9am"},"actions":[{"type":"notify","detail":"Remind the user to export last month's numbers"},{"type":"ai.summarize","detail":"Summarise results and suggest experiments"},{"type":"doc.create","detail":"Save the monthly results summary"}]}},{"id":"turn-customer-questions-into-a-bank-of-article-ideas","t":"Turn customer questions into a bank of article ideas","d":"Questions customers email you are gathered in one Gmail label, and once a month they become a ranked list of articles to write.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":20,"tools":["Gmail","AI assistant","Google Sheets"],"when":"Ongoing, reviewed monthly","steps":[{"h":"Create a Questions label","b":"In Gmail, make a label called Content questions. Whenever a customer asks something interesting, add the label to that email."},{"h":"Use a filter for common subjects","b":"If questions often come through your website contact form, set up a Gmail filter (in settings, under Filters) for that form's emails to apply the label automatically."},{"h":"Turn them into ideas monthly","b":"Once a month, copy just the questions (no names or email addresses) into your AI assistant with this prompt.","p":"Here are questions customers asked [business] this month: [paste questions only]. Group similar questions together. For each group give: how many times it came up, a clear article title, a one-line summary of the answer, and whether it suits a blog post, FAQ entry, short video or email. Rank them by how many customers it would help. Output as a table."},{"h":"Add them to your plan","b":"Paste the table into a Google Sheet called Article ideas and pick the top two to write next."}],"example":"Asked 6 times: 'Can I pause my subscription?' -> FAQ: How to pause or skip a box. Asked 4 times: 'Is the packaging recyclable?' -> Blog: Where every bit of our packaging goes. Asked 3 times: 'Which coffee for a cafetiere?' -> Short video.","tips":["Strip out names, addresses and order numbers before pasting customer emails into any AI tool."],"auto":{"trigger":{"type":"new_email","detail":"Email labelled Content questions"},"actions":[{"type":"ai.extract","detail":"Pull out the question without personal details"},{"type":"sheet.append","detail":"Add the question to the ideas sheet"},{"type":"ai.classify","detail":"Monthly, group questions and rank article ideas"}]}},{"id":"turn-a-rambling-voice-note-into-tasks-and-events","t":"Turn a rambling voice note into tasks and events","d":"Talk through your week on a walk, and get back a tidy to-do list plus calendar events for anything with a date or time.","cat":"Video, Image & Voice","side":"work","lvl":"Intermediate","mins":15,"tools":["Voice notes","AI assistant","Google Calendar","Reminders app"],"when":"Whenever your head is full","steps":[{"h":"Record your thoughts","b":"Use your phone's voice recorder and just talk: what you need to do, who to call, deadlines, ideas. Many phones now transcribe recordings automatically (for example Voice Memos on recent iPhones or Recorder on Pixel)."},{"h":"Get the text into your assistant","b":"Copy the transcript, or upload the audio file to an AI assistant that accepts audio. You can also speak directly using the assistant's voice mode."},{"h":"Ask it to sort everything","b":"Use this prompt.","p":"Here's a transcript of me thinking out loud: [paste]. Today is [day and date]. Sort it into: 1) Tasks, each starting with a verb, with a suggested due date if I mentioned one, grouped by Work, Home, Errands; 2) Calendar events with title, date, start time and length (only if I said a time or day); 3) Ideas to keep; 4) anything unclear I should decide. Don't add tasks I didn't mention."},{"h":"Add them to your apps","b":"Add the events to Google Calendar and the tasks to your reminders app. If your assistant is connected to Google Calendar (Gemini can be), you can ask it to create the events for you, then check them."}],"example":"Work: Send Lucy the revised quote (Tue). Home: Book boiler service. Errands: Return parcel to the post office. Events: Dentist, Thu 14 Nov 9:30, 45 mins. Ideas: Winter newsletter about energy saving. Unclear: 'sort the van' - service or clean?","tips":["Don't record other people's conversations without their knowledge; this is for your own voice."],"auto":{"trigger":{"type":"new_file","detail":"New voice note saved"},"actions":[{"type":"ai.extract","detail":"Pull tasks, events and ideas from the transcript"},{"type":"calendar.create","detail":"Create events for anything with a date and time"},{"type":"list.add","detail":"Add tasks to the reminders list"}]}},{"id":"turn-google-alerts-into-one-tidy-weekly-digest","t":"Turn Google Alerts into one tidy weekly digest","d":"Collect Google Alerts on your name, business or industry in one Gmail label, then get a weekly AI digest of what actually matters.","cat":"Research & News","side":"work","lvl":"Intermediate","mins":15,"tools":["Gmail","AI assistant","Google Calendar"],"when":"Every Friday afternoon","steps":[{"h":"Create your alerts","b":"Go to Google Alerts, type a search phrase (your business name in quotes, a competitor, an industry term) and choose to receive results once a week by email."},{"h":"Send alerts to a label","b":"In Gmail's settings, under Filters, create a filter for emails from googlealerts-noreply@google.com, apply the label 'Alerts' and tick 'Skip the inbox'."},{"h":"Book a weekly 15-minute slot","b":"Add a recurring Friday event in Google Calendar called 'Alerts digest'."},{"h":"Ask for a digest","b":"Open the Alerts label, copy the week's emails into your AI assistant (or use Gemini in Gmail if your plan includes it) with this prompt.","p":"Below are this week's Google Alerts emails about [topics]. Make a digest: 1) the 3 items that matter most to [my business / role] and why, 2) any mention of [my business name] and whether it is positive, negative or neutral, 3) everything else as one line each, 4) items that look like duplicates or spam, which I can ignore. Keep the original link for every item. [paste alerts]"},{"h":"Check before you react","b":"Open the original article for anything you plan to respond to. Alerts can pick up a different business with the same name."}],"example":"Top 3: 1) New planning rules for shopfront signs (link) - affects your refit. 2) Rival bakery opening on High St in Jan (link). 3) Food hygiene rating changes (link). Mentions of Crumb & Co: 1 positive review in a local blog. Ignore: 4 duplicates.","tips":["Put exact phrases in quotes in Google Alerts to cut down on irrelevant results."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3pm"},"actions":[{"type":"email.label","detail":"Gather the week's Google Alerts emails"},{"type":"ai.summarize","detail":"Rank the top items and flag mentions of the business"},{"type":"notify","detail":"Send the weekly digest"}]}},{"id":"gather-key-details-from-many-documents-into-one-table","t":"Gather key details from many documents into one table","d":"Upload a batch of similar documents, like CVs, quotes or proposals, and get one comparison table with the same details pulled from each.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Sheets","Google Drive"],"when":"When you need to compare a stack of similar documents","steps":[{"h":"Put the documents in one folder","b":"Save them in a Google Drive or OneDrive folder and give each a clear file name."},{"h":"Decide what to compare","b":"List the five to ten details you want from every document, such as price, start date and experience."},{"h":"Extract the details","b":"Upload the documents to your AI assistant (in batches of about five if there are many) with this prompt.","p":"For each attached document, extract these details: [detail 1], [detail 2], [detail 3], [add more]. Output one table with a row per document and a column per detail, plus a 'File name' column and a 'Notes' column for anything unusual. Copy values exactly as written. If a detail isn't in a document, write 'not stated'. Don't rank or judge them yet."},{"h":"Paste into a sheet and check","b":"Copy the table into Google Sheets. Check two or three rows against the original documents before you rely on it."},{"h":"Compare and decide","b":"Sort and filter the sheet yourself. The decision is yours; the table just saves the retyping."}],"example":"File | Price | Start date | Warranty | Notes Quote_Ashby.pdf | £4,200 | 12 Jan | 10 yrs | Excludes skip hire Quote_Rowan.pdf | £3,950 | 2 Feb | not stated | Valid 14 days only","tips":["For CVs, remove names and contact details first if you want a fairer, blind first look."],"auto":{"trigger":{"type":"new_file","detail":"Documents are added to a comparison folder"},"actions":[{"type":"ai.extract","detail":"Pull the chosen details from each document"},{"type":"sheet.append","detail":"Add one row per document to the comparison sheet"},{"type":"notify","detail":"Flag documents with missing details"}]}},{"id":"never-miss-a-renewal-licence-or-filing-deadline","t":"Never miss a renewal, licence or filing deadline","d":"Build a calendar of your business's renewals and key deadlines, with reminders set early enough to act, so nothing lapses by accident.","cat":"Small Business Admin","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Google Calendar","Google Sheets"],"when":"Set up once, review every quarter","steps":[{"h":"Get a starting list","b":"Ask your AI assistant which kinds of deadlines a business like yours usually has.","p":"I run a [business type and size, e.g. one-person café, limited company] in [country]. List the kinds of recurring renewals, licences, registrations and filing deadlines a business like mine typically needs to track, grouped by: tax and accounts, insurance, licences and permits, health and safety, vehicles, data protection, website and software, contracts and leases. For each: what it is, how often it usually comes up, and who usually issues it. Mark which ones I must confirm with my accountant, solicitor or the official body, because rules vary."},{"h":"Fill in your real dates","b":"Check your documents and official accounts for the actual dates, then list them in a Google Sheet: Item, Due date, Repeats, Who to contact, Document location."},{"h":"Add calendar reminders","b":"Create a Google Calendar event for each deadline, set to repeat, with notifications one month and one week before. Put the document link in the description."},{"h":"Review each quarter","b":"Set a recurring quarterly event to check the sheet for anything new or changed."}],"example":"Public liability insurance - renews 14 Feb each year - reminder 14 Jan. Premises licence - annual fee due 3 June. VAT return - quarterly, dates from your accountant. Van MOT - 22 Aug. Domain name - auto-renews 9 Oct; check card on file.","tips":["Treat the AI list as a starting point only. Confirm every deadline with your accountant, solicitor or the official body."],"auto":{"trigger":{"type":"new_row","detail":"A deadline is added to the renewals sheet"},"actions":[{"type":"calendar.create","detail":"Create a repeating event with early reminders"},{"type":"notify","detail":"Alert the user a month before each deadline"}]}},{"id":"share-the-housework-fairly-with-a-weekly-rota","t":"Share the housework fairly with a weekly rota","d":"Get a fair cleaning rota that suits everyone's age and schedule, with each person's jobs added to the family calendar.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Calendar"],"when":"Set up once, refresh each school term","steps":[{"h":"List the jobs and the people","b":"Write down every regular job (bins, bathroom, hoovering, laundry, dishwasher) and who lives in the house, including children's ages and busy days."},{"h":"Ask for a fair rota","b":"Paste your list into your AI assistant with this prompt.","p":"Create a weekly household cleaning rota. People: [names, ages and busy days]. Jobs and how often: [list jobs, e.g. bins - weekly Thursday, bathroom - weekly, hoover downstairs - twice a week]. Give age-appropriate jobs to children, balance the total time so it feels fair, rotate the least popular jobs, and keep each person's daily load under [20] minutes. Output a table by day and person, plus a total minutes per person per week."},{"h":"Add jobs to the calendar","b":"Create a recurring event for each person's jobs in a shared Google Calendar or Outlook Calendar, so reminders pop up on their phone."},{"h":"Review after two weeks","b":"Ask everyone what's working, then tell the assistant what to swap and ask for an updated rota."}],"example":"Mon: Alex (14) - empty dishwasher (10m); Priya - hoover downstairs (15m). Thu: Sam (9) - recycling out with a grown-up (5m)... Weekly totals: Priya 95m, Tom 90m, Alex 60m, Sam 30m. Bathroom rotates between Tom and Priya.","tips":["Swapping jobs is fine, but agree that swaps get written on the rota so nothing gets missed."],"auto":{"trigger":{"type":"schedule","detail":"First day of each school term"},"actions":[{"type":"ai.generate","detail":"Rebuild the rota from current jobs and schedules"},{"type":"calendar.create","detail":"Create recurring job reminders for each person"}]}},{"id":"split-holiday-costs-fairly-with-friends","t":"Split holiday costs fairly with friends","d":"Track shared trip spending in a simple sheet that shows who paid what and who owes whom at the end.","cat":"Travel","side":"life","lvl":"Intermediate","mins":20,"tools":["Google Sheets","AI assistant","WhatsApp"],"when":"Before and during a group trip","steps":[{"h":"Create a shared sheet","b":"Make a Google Sheets file with columns: Date, What, Paid by, Amount, Currency, Split between. Share it with everyone on the trip."},{"h":"Log spending as you go","b":"Whoever pays adds a row straight away. Post the link in the group WhatsApp chat so it's easy to find."},{"h":"Settle up at the end","b":"Copy the rows into your AI assistant with this prompt, then double-check the totals in the sheet.","p":"Here's our shared trip spending: [paste rows]. Convert everything to [home currency] at [exchange rate]. Work out each person's fair share, given that some costs were only split between some people as shown. Then give the smallest number of payments needed to settle up, as 'X pays Y [amount]'. Show your working in a table so we can check it."},{"h":"Share the result","b":"Paste the settle-up list into the group chat and mark each payment as done."}],"example":"Total: 1,284. Fair shares: Ava 341, Ben 341, Cara 301 (skipped the boat trip), Dev 301. Payments: Ben pays Ava 96. Dev pays Cara 52. Dev pays Ava 41. Done in 3 payments.","tips":["Agree before the trip whether drinks and individual meals are shared, to avoid awkward conversations later."],"auto":{"trigger":{"type":"new_row","detail":"A new expense is added to the trip sheet"},"actions":[{"type":"ai.generate","detail":"Recalculate balances and who owes whom"},{"type":"message.send","detail":"Post a running balance to the group chat"}]}},{"id":"build-habits-that-stick-with-a-weekly-check-in","t":"Build habits that stick with a weekly check-in","d":"Track a few daily habits in a simple sheet and get a friendly weekly review with one small thing to try next week.","cat":"Health & Fitness","side":"life","lvl":"Intermediate","mins":20,"tools":["Google Sheets","AI assistant","Reminders app"],"when":"Daily ticks, weekly review on Sundays","steps":[{"h":"Pick two or three habits","b":"Choose small habits you can tick yes or no, like '10-minute walk', 'water with every meal' or 'phone out of bedroom'."},{"h":"Make a tracking sheet","b":"Create a Google Sheets or Excel file with a column for the date, one for each habit and one for a short note. Add a daily phone reminder to fill it in."},{"h":"Review the week","b":"Every Sunday, copy the last seven rows into your AI assistant with this prompt.","p":"Here's my habit tracker for the last week: [paste rows]. My habits are [habits] and my reason for them is [why they matter to me]. Give me: 1) a short, encouraging summary of what went well; 2) any pattern you notice, for example which days were harder; 3) one small, specific change to try next week; 4) whether to keep, shrink or swap any habit. Keep it under 150 words and don't lecture."},{"h":"Adjust and carry on","b":"Make the one change it suggests and keep going. Small, steady wins matter more than perfect weeks."}],"example":"Good week: you walked 6 of 7 days, and phone-out-of-bedroom stuck 5 nights. Pattern: Wednesdays slipped both times, probably the late shift. Try: a 10-minute walk at lunch on Wednesdays instead. Keep all three habits.","tips":["Start smaller than you think you need to; two tiny habits you keep beat five you drop."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 6pm"},"actions":[{"type":"ai.summarize","detail":"Review the week's habit rows and spot patterns"},{"type":"notify","detail":"Send the weekly review and one change to try"}]}},{"id":"spot-price-rises-and-unusual-charges-each-month","t":"Spot price rises and unusual charges each month","d":"A monthly check that compares this month's bills and regular payments with last month and flags anything that went up or looks new.","cat":"Money","side":"life","lvl":"Intermediate","mins":15,"tools":["AI assistant","Google Sheets"],"when":"Monthly, after your statement arrives","steps":[{"h":"Export two months of transactions","b":"Download this month's and last month's transactions from your banking app as a CSV or spreadsheet."},{"h":"Remove account details","b":"Delete any columns with account numbers, card numbers or balances you don't want to share."},{"h":"Ask for a comparison","b":"Paste both months into your AI assistant with this prompt.","p":"Here are my transactions for [last month] and [this month]. Compare them and list: 1) regular payments that increased, with old and new amounts and the difference, 2) payments that appear for the first time and look recurring, 3) any charge that looks unusual, duplicated or like a fee (overdraft, late payment, foreign transaction). Present each list as a table. Then suggest which ones I should query and draft a short message for the first one. Last month: [paste] This month: [paste]"},{"h":"Follow up","b":"Contact the company or your bank about anything you don't recognise. If you suspect fraud, call your bank straight away using the number on your card."}],"example":"Increased: Mobile £18 to £21.50 (+£3.50), Streaming £10.99 to £12.99 (+£2). New recurring: 'PhotoCloud' £2.99. Unusual: Two charges of £14.20 from TakeAway Co on 3 Nov, possible duplicate. Query first: duplicate takeaway charge.","tips":["If you see a charge you truly don't recognise, contact your bank before anyone else.","Keeping a sheet of last month's regular payments makes the comparison quicker."],"auto":{"trigger":{"type":"new_file","detail":"A new statement export is saved to the Statements folder"},"actions":[{"type":"ai.extract","detail":"Compare regular payments with last month"},{"type":"ai.classify","detail":"Flag increases, new recurring payments and unusual fees"},{"type":"notify","detail":"Send the list of items to query"}]}},{"id":"learn-a-practical-skill-with-a-30-day-plan","t":"Learn a practical skill with a 30-day plan","d":"A day-by-day plan for learning something new, like cooking, drawing, a spreadsheet skill or an instrument, with free resources and small daily tasks.","cat":"Learning","side":"life","lvl":"Intermediate","mins":15,"tools":["AI assistant","YouTube","Google Calendar"],"when":"When you start learning something new","steps":[{"h":"Pick one skill and a goal","b":"Be specific: not 'learn guitar' but 'play three songs with basic chords'."},{"h":"Ask for a plan","b":"Paste this prompt into your AI assistant.","p":"Create a 30-day plan for me to learn [skill]. My goal by day 30: [goal]. My starting level: [describe]. I can spend [minutes] a day, [days] a week. Equipment I have: [list]. Break it into 4 weekly themes. For each day, give: one small task, how long it takes, and what kind of free resource to search for (for example 'search YouTube for beginner G chord tutorial'). Include a short practice log question each day, and a mini test at the end of each week."},{"h":"Find your resources","b":"Search YouTube or your library app using the suggestions. Don't rely on the AI for specific video links, as they can be out of date."},{"h":"Schedule practice","b":"Add a recurring Google Calendar event at your practice time, with the day's task in the description."},{"h":"Check in weekly","b":"At the end of each week, tell the AI how it went and ask it to adjust the next week."}],"example":"Week 1: Basics. Day 1 (15 min): Learn to hold the guitar and tune it. Search: 'beginner guitar tuning app tutorial'. Log: what felt awkward? Day 2: Learn E minor chord... Week 1 test: switch between Em and G 10 times in a minute.","tips":["Short daily practice beats one long weekend session.","If you miss a day, just carry on. Ask the AI to compress the plan if needed."],"auto":{"trigger":{"type":"schedule","detail":"Daily at practice time"},"actions":[{"type":"notify","detail":"Send today's task and practice time"},{"type":"sheet.append","detail":"Log what the user practised"},{"type":"ai.generate","detail":"Adjust next week's plan from the log"}]}},{"id":"plan-a-strong-first-90-days-in-a-new-job","t":"Plan a strong first 90 days in a new job","d":"A week-by-week plan for your first three months covering who to meet, what to learn and early wins, with check-ins in your calendar.","cat":"Careers","side":"life","lvl":"Intermediate","mins":25,"tools":["AI assistant","Google Calendar","Notion"],"when":"The week before you start","steps":[{"h":"Gather what you know","b":"Collect the job description, notes from your interviews and anything your new manager has shared."},{"h":"Draft the plan","b":"Paste it into your AI assistant with this prompt.","p":"I'm starting as [job title] at [type of organisation] on [date]. Job description and interview notes: [paste]. Create a 30-60-90 day plan. For each phase: main goals, people I should meet and what to ask them, things to learn, and one realistic early win. Then make a list of 10 questions to ask my manager in our first one-to-one. Finally, suggest 3 check-in points with my manager and what to bring to each. Keep it practical, not corporate."},{"h":"Put it somewhere you'll use it","b":"Save the plan in Notion, Google Docs or OneNote, and tick things off as you go."},{"h":"Book your check-ins","b":"Add reminders in your calendar at day 30, 60 and 90 to review the plan and prepare for check-ins with your manager."}],"example":"Days 1-30: Learn. Meet: your manager, the two team leads, the finance contact. Ask each: 'What would make my role a success for you?' Early win: tidy up the shared rota folder. Day 30 check-in: bring what you've learned and two ideas.","tips":["Listen more than you suggest in your first month. Ideas land better once you understand why things are done as they are.","Don't paste confidential information from your new employer into an AI tool without checking their policy."],"auto":{"trigger":{"type":"manual","detail":"User adds their start date and job details"},"actions":[{"type":"ai.generate","detail":"Create a 30-60-90 day plan"},{"type":"doc.create","detail":"Save the plan as a checklist"},{"type":"calendar.create","detail":"Add day 30, 60 and 90 check-ins"}]}},{"id":"never-miss-a-renewal-or-expiry-date","t":"Never miss a renewal or expiry date","d":"One list of every important renewal, such as passports, car tax, insurance and warranties, with calendar reminders well before each one.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Sheets","Google Calendar","AI assistant"],"when":"Set up once, update when things change","steps":[{"h":"List everything that expires","b":"Go through your documents and emails: passports, driving licence, car tax and service, insurance policies, TV licence, phone contracts, warranties, prescriptions, pet vaccinations."},{"h":"Let the AI find what you've missed","b":"Paste your list into your AI assistant with this prompt.","p":"Here's my list of household renewals and expiry dates: [list with dates]. My household: [for example 2 adults, 1 child, a car, a dog, renting]. Suggest any common renewals I've missed for a household like mine. Then create a table with: Item, Who it's for, Expiry or renewal date, How far ahead to start (for example passports 3 months, insurance 4 weeks), Reminder date, and Notes. Sort by reminder date and format it so I can paste it into Google Sheets."},{"h":"Create your tracker","b":"Paste the table into a Google Sheet called Life admin. Don't store full document numbers in it."},{"h":"Add calendar reminders","b":"Add each reminder date to your calendar as an event, with yearly repeats for annual renewals."}],"example":"Car insurance | Car | 14 Jan | Start 4 weeks ahead | Reminder 17 Dec | Compare quotes before auto-renewal Passport | Child | 3 May | Start 3 months ahead | Reminder 3 Feb | Needs new photo Boiler service | Home | 20 Mar | 3 weeks | 27 Feb |","tips":["Leave out passport and policy numbers. The dates are all you need for reminders.","Some countries require several months left on a passport to travel, so check your destination's rules early."],"auto":{"trigger":{"type":"new_row","detail":"A new item is added to the Life admin sheet"},"actions":[{"type":"ai.generate","detail":"Work out a sensible reminder date"},{"type":"calendar.create","detail":"Add a repeating calendar reminder"},{"type":"notify","detail":"Send the reminder with what to prepare"}]}},{"id":"keep-every-invoice-and-receipt-in-one-tidy-place","t":"Keep every invoice and receipt in one tidy place","d":"Have invoice emails labelled as they arrive, then turn them into a monthly spreadsheet of supplier, date and amount in minutes.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":25,"tools":["Gmail","Google Drive","Google Sheets","AI assistant"],"when":"Set up once, then at the end of each month","steps":[{"h":"Create an invoices filter","b":"In Gmail, search for words like invoice OR receipt OR 'payment confirmation', then create a filter from that search that applies an 'Invoices' label. Outlook users can make a rule that moves them to an Invoices folder."},{"h":"Save attachments monthly","b":"At month end, open the label and save each PDF to a Google Drive or OneDrive folder named by month, such as 'Invoices 2026-11'."},{"h":"Extract the details with AI","b":"Upload the PDFs (or paste the email text) into your AI assistant with this prompt. Remove bank details first if they're not needed.","p":"Extract the following from each invoice or receipt I've attached: supplier name, invoice number, invoice date (DD/MM/YYYY), due date if shown, amount before tax, tax, total, currency, and a one-word category from this list: [e.g. Software, Travel, Supplies, Utilities, Other]. Return a table with one row per document, in date order. If a value isn't on the document, write 'not shown' rather than guessing."},{"h":"Paste into your spreadsheet","b":"Copy the table into a Google Sheet or Excel file with one tab per month, and spot-check the totals against two or three originals."}],"example":"02/11/2026 | Brightline Hosting | INV-2231 | £18.00 | VAT £3.60 | £21.60 | Software. 05/11/2026 | Kettle & Co Stationers | 8841 | £42.50 | VAT £8.50 | £51.00 | Supplies.","tips":["Always check AI-extracted amounts against the original before using them for tax or accounts, and ask your accountant if you're unsure how to categorise something.","If you use Xero or QuickBooks, they have their own email-in addresses for bills that may save you this step."],"auto":{"trigger":{"type":"new_email","detail":"An email with an invoice or receipt arrives"},"actions":[{"type":"email.label","detail":"Label it Invoices"},{"type":"file.save","detail":"Save the attachment to this month's invoices folder"},{"type":"ai.extract","detail":"Pull supplier, date, invoice number and totals"},{"type":"sheet.append","detail":"Add a row to the invoices spreadsheet"}]}},{"id":"let-people-book-time-with-you-without-the-back-and-forth","t":"Let people book time with you without the back-and-forth","d":"Share one booking link so clients or colleagues pick a free slot themselves, with a clear page explaining what each meeting is for.","cat":"Meetings & Calendar","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Calendar","Calendly","AI assistant"],"when":"Set up once, share whenever someone asks to meet","steps":[{"h":"Pick your booking tool","b":"Use Google Calendar's appointment schedules, Outlook's Bookings if your plan includes it, or Calendly's free plan. Each connects to your calendar so booked slots are blocked out."},{"h":"Write your booking page with AI","b":"Paste this prompt into your AI assistant to get the wording.","p":"I'm setting up an online booking page for [your service or role]. Meeting types: [e.g. 15-min intro call, 45-min consultation]. For each, write: a clear name, a 2-sentence description of who it's for and what happens, what to prepare, and up to 3 short questions to ask when booking (e.g. 'What would you like to cover?'). Also write a one-line confirmation message. Friendly, plain British English."},{"h":"Set your rules","b":"Choose the hours you're bookable, add buffer time between meetings, set a minimum notice period and limit how many bookings you'll take per day."},{"h":"Share the link","b":"Add the link to your email signature, website or replies, then book a test slot yourself to check it works."}],"example":"15-minute intro call: A quick chat to see if we're a good fit for your garden project. Bring a few photos of the space. Booking question: 'What would you like help with?' Confirmation: 'Thanks, you're booked in! I'll call you on the number you gave.'","tips":["A 15-minute buffer after each meeting stops your day becoming back-to-back."],"auto":{"trigger":{"type":"form_submitted","detail":"Someone books a slot on the booking page"},"actions":[{"type":"calendar.create","detail":"Add the booking to the calendar"},{"type":"email.send","detail":"Send a confirmation with what to prepare"},{"type":"ai.summarize","detail":"Summarise the booker's answers into prep notes"}]}},{"id":"track-your-habits-in-a-simple-spreadsheet","t":"Track your habits in a simple spreadsheet","d":"Get a habit tracker with tick boxes, streak counts and a weekly score, built in Google Sheets or Excel with AI's help.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":25,"tools":["Google Sheets","Excel","AI assistant"],"when":"Set up once, tick off daily","steps":[{"h":"Choose a few habits","b":"Pick three to five habits, such as drinking water, a 20-minute walk or reading before bed. Fewer is better."},{"h":"Ask AI to design the sheet","b":"Paste this prompt into your AI assistant.","p":"Help me build a habit tracker in [Google Sheets / Excel]. Habits: [list]. Layout: dates down column A for [month], one column per habit with checkboxes. Give me step-by-step instructions, including: how to insert checkboxes, a formula for a weekly completion percentage per habit, a formula for the current streak for each habit, and conditional formatting to colour completed days green. Explain each formula in one plain sentence and tell me exactly which cell to put it in."},{"h":"Build it step by step","b":"Follow the instructions, copying each formula into the cell it names. If something shows an error, paste the error back to your AI assistant and ask what to fix."},{"h":"Keep it handy","b":"Add the sheet to your phone's home screen through the Sheets or Excel app and set a daily reminder to tick it off."}],"example":"Columns: Date | Water | Walk | Read | Bed by 11. Row 10 Nov: ticked, ticked, unticked, ticked. Weekly score: Water 86%, Walk 71%, Read 43%, Bed by 11 57%. Current streak: Water 6 days.","tips":["Missing a day is normal; aim for 'never twice in a row' rather than a perfect streak."],"auto":{"trigger":{"type":"schedule","detail":"Every evening at 9pm"},"actions":[{"type":"notify","detail":"Remind the user to tick off today's habits"},{"type":"ai.summarize","detail":"On Sundays, summarise the week's progress"}]}},{"id":"spot-the-problems-your-customers-complain-about-most","t":"Spot the problems your customers complain about most","d":"A simple complaints log in a spreadsheet plus a monthly AI review that shows your top issues, trends and the fixes worth making first.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":25,"tools":["Google Sheets","AI assistant","Google Calendar"],"when":"Log as you go, review on the first Monday of each month","steps":[{"h":"Create a complaints log","b":"Make a sheet with columns: Date, Channel, Category, What went wrong, What we did, Resolved (Yes/No). Add a dropdown for Category using Data validation in the Data menu."},{"h":"Log every complaint briefly","b":"Add one row per complaint in a sentence. Leave out names, emails and order numbers so the sheet stays safe to share."},{"h":"Set a monthly reminder","b":"Create a recurring Google Calendar event on the first Monday of each month called 'Complaints review'."},{"h":"Ask AI to find the patterns","b":"Copy the last month's rows and paste them into your AI assistant with this prompt.","p":"Here is my customer complaints log for [month]: [paste rows]. Columns: Date, Channel, Category, What went wrong, What we did, Resolved. Please: 1) give a table of complaint types with counts, most common first, 2) say what changed compared to last month: [paste last month's top 3 or 'first month'], 3) pick the 3 problems where one fix would prevent the most complaints, and suggest a practical, low-cost fix for each, 4) flag any complaint left unresolved for more than 7 days. Keep it under 300 words."},{"h":"Pick one fix","b":"Choose one change to make this month and note it at the top of the sheet so you can see if complaints drop."}],"example":"Top issues in March: Late delivery (11), Wrong size sent (6), Website checkout error (4). Change: late delivery up from 5. Best fix: add a dispatch-date note on product pages during busy weeks. Unresolved over 7 days: 2 (rows 14, 22).","tips":["Excel works just as well; use a drop-down list for Category so the counts stay tidy.","Share the one-paragraph summary with your team; it's often the push needed to fix a long-running issue."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each month at 9am"},"actions":[{"type":"ai.summarize","detail":"Count and rank complaint types from the log"},{"type":"ai.generate","detail":"Suggest the three most valuable fixes"},{"type":"doc.create","detail":"Save the monthly complaints review"},{"type":"notify","detail":"Send the summary to the owner"}]}},{"id":"start-genuine-conversations-with-prospects-on-linkedin","t":"Start genuine conversations with prospects on LinkedIn","d":"Personal connection notes and a short message plan for your best prospects, tracked in a simple Notion list so nobody slips through.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":30,"tools":["LinkedIn","AI assistant","Notion"],"when":"A few times a week, 15 minutes at a time","steps":[{"h":"Make a simple tracker","b":"In Notion, create a database with columns: Name, Company, Profile link, Why them, Status (To connect, Connected, Talking, Not now) and Next step date."},{"h":"Pick five people at a time","b":"Choose prospects who post or comment regularly. Note one thing from their recent posts or profile in the Why them column."},{"h":"Write personal notes with AI","b":"Paste your notes into your AI assistant with this prompt.","p":"I help [type of customer] with [what you do]. For each person below, write: 1) a LinkedIn connection note under 250 characters that mentions the specific thing I noticed and has no sales pitch, 2) a first message to send a few days after they accept, under 60 words, that offers something useful (an idea, an article, a question about their work), and 3) a natural second message for a week later. People: [name, role, what I noticed]. British English, friendly, no flattery, no 'I'd love to pick your brain'."},{"h":"Send them by hand","b":"Copy each note into LinkedIn yourself and update the Status in Notion. Don't use tools that automate LinkedIn, as LinkedIn's rules don't allow them."},{"h":"Follow your next-step dates","b":"Open a Notion view filtered to today's next-step dates each time you sit down to do LinkedIn."}],"example":"Connection note: 'Hi Amara, your post on running a café with two kids under five really struck a chord. Would be good to connect.' Message 1 (after accepting): 'Thanks for connecting! You mentioned staffing rotas eat your Sundays; here's a free template one of my clients uses...'","tips":["Comment thoughtfully on their posts for a week before connecting; it makes the note feel natural.","Keep notes factual and work-related; your tracker should never hold anything you wouldn't be happy for them to see."],"auto":{"trigger":{"type":"new_row","detail":"A prospect is added to the LinkedIn tracker"},"actions":[{"type":"ai.generate","detail":"Write a connection note and two follow-up messages"},{"type":"sheet.update","detail":"Save the drafts and set the next-step date"},{"type":"notify","detail":"Remind the user when a follow-up is due"}]}},{"id":"hear-what-your-team-really-thinks-anonymously","t":"Hear what your team really thinks, anonymously","d":"A short anonymous pulse survey for your team and an AI summary of themes and suggestions, without anyone being identified.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":30,"tools":["Microsoft Forms","Excel","AI assistant"],"when":"Every three months","steps":[{"h":"Write good questions","b":"Ask your AI assistant for a short, balanced survey.","p":"Write an anonymous team pulse survey for a [size] person [type of business]. 6 to 8 questions, taking under 5 minutes. Include: 4 rating questions (1 to 5) on workload, support from managers, communication and feeling valued; 2 open questions ('What's one thing we should keep doing?' and 'What's one thing we should change?'); and an optional open comment box. Avoid questions about role, age, location or anything else that could identify people in a small team. Add a 2-line intro explaining it's anonymous and what we'll do with the results."},{"h":"Build it in Microsoft Forms","b":"Create the form and set it so names aren't recorded (in Forms, choose that anyone can respond, or turn off recording names). Responses collect in Excel automatically."},{"h":"Share it and give a deadline","b":"Send the link to the team in Teams or email with a one-week deadline and a reminder halfway through."},{"h":"Summarise with AI","b":"Copy the responses from Excel into your AI assistant and ask for averages, the main themes from comments with counts, and 3 suggested actions. Remove any comment that names someone before pasting."},{"h":"Share what you'll do","b":"Tell the team what came up and the one or two changes you'll make. This is what keeps people answering next time."}],"example":"Results (14 of 16 responded): Workload 2.9, Manager support 4.1, Communication 3.2, Feeling valued 3.8. Themes: Friday rush is stressful (7), weekly team huddle helps (6), unclear who covers holidays (4). Actions: publish holiday cover rota; add a Thursday prep slot.","tips":["In very small teams, only report results when at least 5 people have answered, so no one can be identified.","Google Forms with Google Sheets works the same way if you don't use Microsoft 365."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each quarter"},"actions":[{"type":"message.send","detail":"Send the anonymous survey link to the team"},{"type":"ai.summarize","detail":"After the deadline, summarise scores and comment themes"},{"type":"doc.create","detail":"Create a results summary for the manager to share"}]}},{"id":"schedule-a-week-of-instagram-and-facebook-posts-at-once","t":"Schedule a week of Instagram and Facebook posts at once","d":"Design your images in Canva, write captions with AI and queue a full week of Instagram and Facebook posts in about half an hour.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":35,"tools":["AI assistant","Canva","Instagram"],"when":"Once a week, same time each week","steps":[{"h":"Pick this week's topics","b":"Choose three to five topics from your content calendar or from questions customers asked this week."},{"h":"Write the captions in one go","b":"Paste this prompt into your AI assistant.","p":"Write [number] Instagram and Facebook captions for [business name], a [type of business]. Topics: [list topics]. For each: a first line that makes people stop scrolling, 40-80 words, one clear call to action, and 3-5 hashtags that real customers in [your area or niche] would search. Also suggest a short headline (max 6 words) to put on the image. Number them and use British English."},{"h":"Make matching images in Canva","b":"Open a Canva Instagram post template, add your headline, then duplicate the page for each post so they all match. Download them as PNGs."},{"h":"Schedule them in Meta Business Suite","b":"Open Meta Business Suite (free for linked Facebook Pages and Instagram business accounts), create a post, add the image and caption, choose both Facebook and Instagram, and pick a date and time to schedule."}],"example":"Mon 8am: 'Your boiler is trying to tell you something.' + image 'Winter boiler check'. Wed 12pm: 'Meet Sam, who's been with us 6 years...' Fri 5pm: 'This weekend only: free gas safety check with every service.' All queued in Business Suite.","tips":["If your Canva plan includes the Content Planner, you can schedule straight from Canva instead.","Only use photos you took or have rights to, and ask customers before featuring them."],"auto":{"trigger":{"type":"schedule","detail":"Every Monday at 9am"},"actions":[{"type":"ai.generate","detail":"Write captions and image headlines for the week's topics"},{"type":"file.save","detail":"Save captions alongside the Canva designs"},{"type":"calendar.create","detail":"Block 30 minutes to schedule the posts"}]}},{"id":"turn-your-newsletter-notes-into-a-finished-email","t":"Turn your newsletter notes into a finished email","d":"Bullet notes from your week become a friendly, well-structured newsletter ready to send from Mailchimp, with subject line options.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":25,"tools":["Notes app","AI assistant","Mailchimp"],"when":"Every week or month, before your send day","steps":[{"h":"Keep a running notes list","b":"Through the week, add quick bullets to one note: news, a tip, a customer story, links you found and anything coming up."},{"h":"Draft the newsletter","b":"Paste your notes into your AI assistant with this prompt (add your voice guide if you have one).","p":"Turn these notes into a newsletter for [business], read by [audience]. Notes: [paste]. Structure: a warm 2-3 sentence opening; 3-4 short sections each with a heading and 60-100 words; one featured offer or call to action: [CTA]; a friendly sign-off from [name]. Also give 5 subject lines (under 45 characters) and a preview line. British English, plain, no hype words. Keep links where I've put them."},{"h":"Build it in Mailchimp","b":"Create a new email campaign from a saved template in Mailchimp, paste each section into the content blocks, and add images."},{"h":"Test and schedule","b":"Send yourself a test email, check it on your phone, then schedule it for your usual send time."}],"example":"Subject: 'The week the oven broke (and what we baked instead)'. Opening: 'It's been an eventful week at the bakery...' Sections: New winter menu, Meet our Saturday team, Tip: keeping bread fresh. CTA: Pre-order Christmas stollen.","tips":["Only email people who opted in, and keep the unsubscribe link in every send."],"auto":{"trigger":{"type":"schedule","detail":"Thursdays at 2pm before a Friday send"},"actions":[{"type":"web.fetch","detail":"Read the week's newsletter notes"},{"type":"ai.generate","detail":"Write the newsletter and subject lines"},{"type":"email.draft","detail":"Create a draft campaign for review"}]}},{"id":"keep-your-youtube-channel-organised-with-playlists-and-sched","t":"Keep your YouTube channel organised with playlists and schedules","d":"Raw videos in a Google Drive folder go through a simple checklist to be uploaded, scheduled and added to the right playlist every time.","cat":"Video, Image & Voice","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Drive","YouTube","Google Sheets","AI assistant"],"when":"Every time a video is finished","steps":[{"h":"Set up folders and a tracker","b":"Create Google Drive folders: To upload, Uploaded. Make a Google Sheet with columns: Video file, Title, Playlist, Publish date, Status."},{"h":"Plan your playlists","b":"Ask your AI assistant to suggest playlists from your video list.","p":"Here's a list of my YouTube videos and their topics: [paste titles]. My channel is about [topic] for [audience]. Suggest 4-6 playlists that would help a new viewer binge-watch, each with a name (under 40 characters), a 2-sentence description, and which videos go in it, in the best viewing order. Put each video in at least one playlist."},{"h":"Create the playlists","b":"In YouTube Studio, create each playlist with its description. When uploading new videos, you can choose the playlist on the details screen."},{"h":"Upload and schedule from the tracker","b":"For each finished video in To upload, upload it in YouTube Studio, set visibility to Schedule, add it to its playlist, then move the file to Uploaded and update the sheet."}],"example":"Playlists: 'Start here: allotment basics' (6 videos), 'Growing veg in pots' (5), 'Allotment year: month by month' (12). Tracker: 'Planting garlic.mp4' | Planting Garlic in Autumn | Allotment year | Sat 16 Nov 9am | Scheduled.","tips":["Put your best video first in each playlist; it's the one most new viewers will see."],"auto":{"trigger":{"type":"new_file","detail":"Video added to the To upload folder"},"actions":[{"type":"ai.classify","detail":"Suggest the right playlist for the video"},{"type":"sheet.append","detail":"Add the video to the tracker with a publish date"},{"type":"notify","detail":"Remind the user to upload and schedule it"}]}},{"id":"keep-a-research-log-you-can-actually-trust","t":"Keep a research log you can actually trust","d":"Record every useful fact with its source, date and whether you've verified it, so your research is reliable and easy to cite later.","cat":"Research & News","side":"work","lvl":"Intermediate","mins":15,"tools":["Google Sheets","AI assistant"],"when":"Whenever you're researching for a project, essay or decision","steps":[{"h":"Set up the log","b":"Create a Google Sheet with columns: Date found, Claim or fact, Exact quote, Source name, Link, Source type, Verified? (Yes/No/Partly), Notes."},{"h":"Extract facts from what you read","b":"When you read something useful, paste it into your AI assistant with this prompt and copy the result into your sheet.","p":"From the text below, extract up to [8] specific facts or claims that relate to [my research question]. Output as a table with columns: Claim (one sentence, in your words), Exact quote, Source name, Source type (official, academic, news, blog, company). Only include claims that are actually in the text. Source: [name and link] [paste text]"},{"h":"Verify the important ones","b":"For each claim you plan to rely on, find a second independent source or the original data. Mark it Yes, No or Partly in the Verified column."},{"h":"Ask for gaps","b":"Every so often, paste the sheet back into your AI assistant and ask: 'Which claims rest on only one source, and what is missing to answer my question?'"}],"example":"Row: 12 Nov | 1 in 4 small firms use AI tools weekly | 'one in four firms...' | Business Survey 2026 | link | Official | Partly - figure is for firms with 10+ staff | Check the micro-business breakdown.","tips":["Copy the exact quote, not just a summary. It makes checking and citing much quicker later."],"auto":{"trigger":{"type":"manual","detail":"User shares text and its source"},"actions":[{"type":"ai.extract","detail":"Extract claims, quotes and source details"},{"type":"sheet.append","detail":"Add each claim as a row marked unverified"},{"type":"notify","detail":"Remind the user to verify key claims"}]}},{"id":"create-an-assistant-that-knows-your-own-handbook","t":"Create an assistant that knows your own handbook","d":"Set up a custom AI helper loaded with your guides or policies, so you and your team get answers based on your own documents.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Google Drive"],"when":"When the same questions come up again and again","steps":[{"h":"Choose your documents","b":"Pick the up-to-date files you want it to know: a handbook, price list, FAQs or process guides. Remove anything confidential or out of date."},{"h":"Create the custom assistant","b":"Depending on your assistant and plan: create a custom GPT in ChatGPT, a Project in Claude, or a Gem in Gemini. Each lets you upload files and add standing instructions."},{"h":"Add clear instructions","b":"Paste this into the instructions box.","p":"You answer questions about [organisation or topic] using only the uploaded documents. For every answer: give the answer in plain English, then name the document and section it came from. If the documents don't cover the question, say 'I can't find that in our documents. Please ask [contact person or team].' Never guess at prices, dates, policies or legal matters. Keep answers under [150] words unless asked for more."},{"h":"Test it with real questions","b":"Ask ten questions you already know the answers to. If it gets one wrong, check whether the document is unclear and fix the document."},{"h":"Share and keep it updated","b":"Share it with your team if your plan allows, and replace the files whenever the documents change."}],"example":"Q: How much holiday can I carry over? A: You can carry over up to 5 days, and they must be used by 31 March (Staff Handbook, section 4.3). Q: Can I expense a new laptop? A: I can't find that in our documents. Please ask the office manager.","tips":["Check your workplace's AI policy before uploading company documents, and never upload staff or customer personal data."],"auto":{"trigger":{"type":"message_received","detail":"A team member asks a question"},"actions":[{"type":"ai.generate","detail":"Answer from the uploaded documents with a source"},{"type":"message.send","detail":"Reply with the answer or who to ask"}]}},{"id":"sort-bank-transactions-into-categories-for-bookkeeping","t":"Sort bank transactions into categories for bookkeeping","d":"Get your bank transactions grouped into sensible categories, then set up rules in Xero or QuickBooks so regular payments sort themselves.","cat":"Small Business Admin","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Excel","Xero","QuickBooks"],"when":"Monthly, or when setting up bookkeeping","steps":[{"h":"Export your transactions","b":"Download last month's business bank statement as a CSV or Excel file from your online banking."},{"h":"Remove private details","b":"Delete the account number and balance columns. Keep date, description and amount."},{"h":"Ask for categories","b":"Upload the file or paste the rows into your AI assistant with this prompt.","p":"Below are my business bank transactions. Suggest a category for each from this list: [your categories, e.g. Sales, Materials, Fuel, Rent, Software, Bank fees, Drawings, Other]. Output a table: Date, Description, Amount, Suggested category, Confidence (high/medium/low). Then list the payees that appear every month, and for each suggest a simple rule (e.g. 'Description contains PHONECO -> Telephone'). Mark anything that could be personal or mixed use as low confidence. [paste transactions]"},{"h":"Set up bank rules","b":"Xero and QuickBooks both let you create bank rules that categorise regular payments automatically. Add rules for the high-confidence regular payees."},{"h":"Ask your accountant about the low ones","b":"Send the low-confidence items to your accountant or bookkeeper. They'll know the right treatment."}],"example":"03/11 | SPARKY WHOLESALE | -£212.40 | Materials | High 05/11 | ACME CLOUD SUBS | -£18.00 | Software | High 07/11 | ONLINE MARKETPLACE | -£34.99 | Other | Low - could be personal Rule: description contains 'ACME CLOUD' -> Software.","tips":["Your accountant should agree your categories and check anything tax-related before you rely on them."],"auto":{"trigger":{"type":"new_file","detail":"A bank statement export is saved"},"actions":[{"type":"ai.classify","detail":"Suggest a category and confidence for each transaction"},{"type":"sheet.append","detail":"Save categorised rows to the bookkeeping sheet"},{"type":"notify","detail":"Send low-confidence items for accountant review"}]}},{"id":"never-forget-the-boiler-service-or-smoke-alarm-test","t":"Never forget the boiler service or smoke alarm test","d":"Build a year-round home maintenance calendar with reminders for servicing, safety checks and seasonal jobs.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Calendar"],"when":"Set up once a year","steps":[{"h":"Describe your home","b":"Note your type of home, heating, whether you rent or own, and any garden, gutters, chimney or appliances that need care."},{"h":"Get a maintenance schedule","b":"Paste this prompt into your AI assistant.","p":"I live in a [type of home, e.g. 1930s semi] in [country/region], which I [rent/own]. Heating: [gas boiler/heat pump/other]. Other features: [garden, gutters, chimney, loft, appliances]. Create a 12-month home maintenance calendar with: job, month, how often, rough time it takes, and whether I can do it myself or need a professional. Include safety checks like smoke and carbon monoxide alarms. If I rent, mark which jobs are usually the landlord's responsibility so I can check my tenancy agreement."},{"h":"Add recurring reminders","b":"Create a recurring event in Google Calendar or Outlook Calendar for each job, set to repeat monthly or yearly, with a reminder a week before for jobs that need booking."},{"h":"Keep a record","b":"Add a note to each event when the job is done, such as the engineer's name and cost, for warranties or selling later."}],"example":"Monthly: test smoke and CO alarms (2 mins, DIY). March: clean gutters (DIY or pro). September: boiler service (Gas Safe engineer, book in August). November: bleed radiators, check loft insulation. Renting? Boiler service is usually the landlord's job.","tips":["Gas and electrical work must be done by a qualified, registered professional, never by following AI steps."],"auto":{"trigger":{"type":"schedule","detail":"Every January 2nd"},"actions":[{"type":"ai.generate","detail":"Refresh the year's maintenance schedule"},{"type":"calendar.create","detail":"Add recurring reminders for each job"}]}},{"id":"sort-passports-visas-and-insurance-before-you-travel","t":"Sort passports, visas and insurance before you travel","d":"Get a pre-trip admin checklist with dated reminders, so passport expiry and entry rules don't catch you out.","cat":"Travel","side":"life","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Calendar","Notes app"],"when":"As soon as you book a trip abroad","steps":[{"h":"Gather your details","b":"Note each traveller's nationality, passport expiry date, destination, travel dates and any medical needs. Don't paste passport numbers."},{"h":"Ask for an admin checklist","b":"Paste this prompt into your AI assistant.","p":"I'm travelling from [home country] to [destination, including any stopovers] from [date] to [date]. Travellers: [nationalities, ages, passport expiry dates]. Make a pre-trip admin checklist covering: passport validity, visas or travel authorisations, travel insurance, health requirements, driving licence or permits if hiring a car, money and cards, phone roaming, and documents for children travelling with one parent. For each item, say what to check, the official source to check it on (for example my government's travel advice site or the destination's embassy), and how many weeks before travel to do it."},{"h":"Check each item officially","b":"Go through the checklist using official government and embassy websites only, as entry rules change and AI may be out of date."},{"h":"Add dated reminders","b":"Put each task in Google Calendar or Outlook Calendar with a reminder, working back from your departure date."}],"example":"8 weeks before: check passports - Mia's expires Aug 2027, check the destination's validity rule. 6 weeks: check if an electronic travel authorisation is needed (government site). 4 weeks: buy travel insurance, check it covers Sam's asthma. 1 week: tell bank, check roaming.","tips":["Only trust official government and embassy websites for entry requirements and visas."],"auto":{"trigger":{"type":"calendar_event","detail":"A new trip is added to the calendar"},"actions":[{"type":"ai.generate","detail":"Create a pre-trip admin checklist with deadlines"},{"type":"calendar.create","detail":"Add a reminder for each task"}]}},{"id":"keep-your-family-s-health-details-in-one-safe-place","t":"Keep your family's health details in one safe place","d":"Create one private record of allergies, vaccinations, medicines and appointments for everyone you care for.","cat":"Health & Fitness","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Docs","Google Calendar","AI assistant"],"when":"Set up once, update after appointments","steps":[{"h":"Create a private document","b":"Make a Google Docs or Word file stored in your own account, not a shared folder, and turn on two-step verification for that account."},{"h":"Get a simple template","b":"Ask your AI assistant for a structure, then fill in the real details yourself in the document, not in the chat.","p":"Create a blank template for a family health record I'll fill in myself. For each person include sections for: allergies and reactions, current medicines (name, dose, who prescribed), vaccinations with dates, ongoing conditions, past operations, GP and dentist contact, upcoming appointments, and notes from recent appointments. Add a short 'emergency summary' box at the top of each person's section. Use headings and tables, with placeholder text only."},{"h":"Fill it in from official records","b":"Copy details from red books, vaccination records, prescription labels and your GP surgery's app or patient portal."},{"h":"Link appointments","b":"Add appointments to Google Calendar or Outlook Calendar and put the appointment notes in the record afterwards."}],"example":"Emergency summary - Leo (7): Allergic to penicillin (rash). Inhaler: blue, as needed. GP: Riverside Surgery. Vaccinations: preschool booster 03/2023. Upcoming: asthma review 12 Jan. Last notes: nurse said to bring the inhaler to every review.","tips":["Keep real health details in your own private document, not in AI chats, and be careful who you share it with.","Ask your GP surgery or pharmacist if anything in the record is unclear."],"auto":{"trigger":{"type":"calendar_event","detail":"After a family member's health appointment"},"actions":[{"type":"notify","detail":"Remind the user to add notes from the appointment"},{"type":"doc.create","detail":"Open the family health record at that person's section"}]}},{"id":"never-miss-a-bill-due-date-again","t":"Never miss a bill due date again","d":"Bills arriving by email are automatically labelled, and each one becomes a calendar reminder a few days before it's due.","cat":"Money","side":"life","lvl":"Intermediate","mins":20,"tools":["Gmail","Google Calendar","AI assistant"],"when":"Whenever a new bill email arrives","steps":[{"h":"Make a Bills label and filter","b":"In Gmail's settings, under Filters, create a filter for emails from your energy, water, phone, council and other billers, and have it apply a label called Bills. Outlook users can do the same with a rule that moves them to a Bills folder."},{"h":"Check the Bills label weekly","b":"Once a week, open the Bills label and copy the text of any new bills."},{"h":"Pull out the key dates","b":"Paste the bill emails into your AI assistant with this prompt.","p":"Here are my latest bill emails. For each bill, extract: company, amount due, due date, whether it's paid by direct debit or needs me to pay manually, and any reference I need. Present as a table sorted by due date. Then write one calendar reminder title for each manual bill, in the format: Pay [company] [amount] - due [date]. [paste emails, with account numbers removed]"},{"h":"Add reminders to your calendar","b":"Create a calendar event two or three days before each manual payment date using the titles the AI gave you, with a notification switched on."}],"example":"Bills this month: WaterCo | £38.40 | due 18 Nov | Direct debit Council tax | £142 | due 1 Dec | Direct debit Broadband Plus | £29.99 | due 22 Nov | Manual, ref BP-xxxx Reminder: Pay Broadband Plus £29.99 - due 22 Nov","tips":["Remove account numbers before pasting bill emails into an AI assistant.","If your plan includes Gemini in Gmail, you can ask it to summarise your Bills label directly instead of copying and pasting."],"auto":{"trigger":{"type":"new_email","detail":"A new email lands in the Bills label"},"actions":[{"type":"ai.extract","detail":"Pull company, amount and due date from the bill"},{"type":"calendar.create","detail":"Add a reminder three days before the due date"},{"type":"sheet.append","detail":"Log the bill in a household bills sheet"}]}},{"id":"build-a-revision-timetable-you-can-actually-stick-to","t":"Build a revision timetable you can actually stick to","d":"A realistic week-by-week revision plan that fits around school, work and family, added straight into your calendar.","cat":"Learning","side":"life","lvl":"Intermediate","mins":25,"tools":["AI assistant","Google Calendar"],"when":"Six to eight weeks before exams","steps":[{"h":"List your exams and topics","b":"Write down each subject, exam date, the topics in it, and how confident you feel on each from 1 to 5."},{"h":"Note your available time","b":"Write down roughly when you're free each day, and any days that are off-limits, such as sports nights or shifts."},{"h":"Ask for a plan","b":"Paste everything into your AI assistant with this prompt.","p":"Make me a revision timetable from [start date] to my last exam. Exams and dates: [list]. Topics and my confidence (1 to 5): [list]. My free time: [describe]. Rules: sessions of [30-45] minutes with short breaks, no more than [3] hours a day, a day off each week, more time on low-confidence topics, and revisit each topic at least twice with growing gaps. Finish each week with a practice paper. Give me a table with: Date, Time, Subject, Topic, Activity (for example flashcards, past paper, summary sheet)."},{"h":"Put it in your calendar","b":"Add the sessions to Google Calendar as events. You can ask the AI to format them as a list of titles and times to make this quicker."},{"h":"Review on Sundays","b":"Each Sunday, tell the AI what you managed and what slipped, and ask it to adjust the next week."}],"example":"Mon 18 Nov 4:30-5:15pm | Maths | Quadratics (confidence 2) | Worked examples + 5 practice questions Mon 5:30-6:15pm | History | Causes of WW1 | Make a mind map Sat 23 Nov 10-11:30am | Maths | Practice paper 1 | Timed","tips":["Plan for less than you think you can do. A plan you keep beats a perfect one you abandon.","Mixing subjects in a day helps memory more than doing one subject for hours."],"auto":{"trigger":{"type":"manual","detail":"User enters exams and free time"},"actions":[{"type":"ai.generate","detail":"Create a spaced revision timetable"},{"type":"calendar.create","detail":"Add each session to the calendar"},{"type":"notify","detail":"Send a Sunday prompt to review the week"}]}},{"id":"prepare-to-ask-for-a-pay-rise-or-promotion","t":"Prepare to ask for a pay rise or promotion","d":"A clear, evidence-based case for a pay rise or promotion, plus a plan for the conversation and how to respond to common answers.","cat":"Careers","side":"life","lvl":"Intermediate","mins":30,"tools":["AI assistant","Google Docs","Google Calendar"],"when":"A few weeks before your pay review","steps":[{"h":"Collect your evidence","b":"Gather your wins, extra responsibilities taken on, positive feedback and any salary research for your role."},{"h":"Build your case","b":"Paste it all into your AI assistant with this prompt.","p":"Help me prepare to ask my manager for [a pay rise to X / promotion to Y role]. My current role and pay: [details]. Evidence: [paste wins, feedback, extra responsibilities]. Salary research: [paste]. Create: 1) a one-page summary of my case with 3 strongest points, 2) a short opening I could say in the meeting, 3) likely responses (for example 'there's no budget', 'not this year', 'what else would you do?') with calm replies to each, and 4) a fallback ask if the answer is no, such as a review date, training or a clear path. Use only the evidence I've given."},{"h":"Book the meeting","b":"Ask your manager for a dedicated meeting rather than raising it in passing. Put the date in your calendar with your summary attached."},{"h":"Rehearse","b":"Ask the AI to play your manager and practise the conversation a couple of times."}],"example":"Case: 1) Took on rota planning for 2 sites since March. 2) Trained 4 new staff. 3) Similar roles locally advertised at £2,000 to £3,000 more. Opening: 'I'd like to talk about my pay, given how my role has grown this year.' If no budget: 'Could we agree a review in six months with clear targets?'","tips":["Lead with what you've done for the team, not personal costs.","Get any agreed next steps confirmed in a short email afterwards."],"auto":{"trigger":{"type":"calendar_event","detail":"Pay review season starts in three weeks"},"actions":[{"type":"web.fetch","detail":"Read the user's wins log"},{"type":"ai.generate","detail":"Build a case summary and conversation plan"},{"type":"doc.create","detail":"Save the case document"}]}},{"id":"get-your-email-inbox-under-control","t":"Get your email inbox under control","d":"A tidy inbox with filters that sort newsletters, receipts and updates automatically, plus a plan for clearing the backlog.","cat":"Personal Assistant","side":"life","lvl":"Intermediate","mins":40,"tools":["Gmail","Outlook","AI assistant"],"when":"Once, then a quick monthly tidy","steps":[{"h":"List your most frequent senders","b":"Scroll through your last few weeks of email and jot down the senders that show up most, such as shops, newsletters, banks, school and social media."},{"h":"Ask for a filing plan","b":"Paste the list into your AI assistant with this prompt.","p":"Help me organise my personal email. Here are my most frequent senders and roughly how often they email: [list]. Suggest 5 to 7 simple labels or folders (for example Receipts, Newsletters, Bills, Family and school, Travel). Assign each sender to one, and say whether it should skip the inbox or stay in it. Suggest which newsletters I might unsubscribe from based on how often they arrive. Then give me a 15-minute-a-day plan to clear my backlog over a week. Keep the instructions general enough for Gmail or Outlook."},{"h":"Create the filters or rules","b":"In Gmail's settings, under Filters, or in Outlook's rules, create one rule per label using the senders the AI grouped. Start with the biggest groups."},{"h":"Unsubscribe as you go","b":"Use the unsubscribe link at the top or bottom of newsletters you no longer read."},{"h":"Clear the backlog","b":"Follow the daily plan. Archiving old emails in bulk by date is usually safe and much faster than deleting one by one."}],"example":"Labels: Receipts (online shops, takeaway apps: skip inbox), Newsletters (6 senders: skip inbox, unsubscribe from 3), Bills (energy, phone: stay in inbox), Family and school (school, clubs: stay in inbox, star). Day 1: archive everything older than 1 year.","tips":["Be cautious with unsubscribe links in emails you don't recognise. For suspicious ones, mark as spam instead.","Don't share email content with an AI tool, just sender names, for this recipe."],"auto":{"trigger":{"type":"new_email","detail":"Any new email arrives"},"actions":[{"type":"ai.classify","detail":"Match the email to a label"},{"type":"email.label","detail":"Apply the label and archive if it skips the inbox"},{"type":"notify","detail":"Send a monthly list of unread newsletters to consider unsubscribing"}]}},{"id":"get-one-weekly-digest-of-all-your-newsletters","t":"Get one weekly digest of all your newsletters","d":"Newsletters skip your inbox all week, then on Sunday you get one short digest of the best bits with links to read more.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":25,"tools":["Gmail","Outlook","AI assistant"],"when":"Every Sunday","steps":[{"h":"Route newsletters to a Reading label","b":"Create a Gmail filter (or Outlook rule) for your newsletter senders that applies a 'Reading' label or moves them to a Reading folder, skipping the inbox."},{"h":"Collect the week's issues","b":"On Sunday, open the Reading label, select the week's emails and copy their text, or forward them to yourself as one email."},{"h":"Ask for a digest","b":"Paste them into your AI assistant with this prompt. If your assistant is connected to your email, ask it to read the Reading label directly.","p":"Make me a weekly digest from these newsletters. My interests: [your interests]. For each newsletter give: its name, the 1 to 3 items most relevant to me in one line each, and mark anything time-sensitive (events, sales ending, deadlines) with 'DATE:'. Finish with 'Worth reading in full' listing at most 2 issues and why. Skip adverts and sponsored sections. [paste newsletters]"},{"h":"Save the digest and archive","b":"Paste the digest into your notes app, add any dates to your calendar, then archive the week's newsletters in one go."}],"example":"Garden Notes: plant garlic before mid-Dec; frost-proof pot guide. Town Events: DATE: Christmas market Sat 6 Dec. Money Weekly: energy price cap changes in Jan. Worth reading in full: Garden Notes, for the bulb planting calendar.","tips":["Ask it to say 'nothing new this week' for a newsletter rather than padding the digest."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 9am"},"actions":[{"type":"ai.summarize","detail":"Summarise the week's newsletters by the user's interests"},{"type":"calendar.create","detail":"Add any dated events found"},{"type":"email.send","detail":"Send the digest to the user"}]}},{"id":"plan-a-team-or-group-event-without-the-chaos","t":"Plan a team or group event without the chaos","d":"Collect everyone's availability and preferences in one form, then get a plan, a timeline and invites drafted for you.","cat":"Meetings & Calendar","side":"work","lvl":"Intermediate","mins":40,"tools":["Google Forms","Google Sheets","AI assistant","Google Calendar"],"when":"When you're organising a team day, party or get-together","steps":[{"h":"Make a quick sign-up form","b":"Ask your AI assistant to write the questions, then build them in Google Forms or Microsoft Forms.","p":"I'm organising [event] for about [number] people around [date range]. Budget: [budget]. Write a short sign-up form with no more than 7 questions covering: which dates work (multiple choice), dietary needs, accessibility needs, activity preferences from these options [options], and anything else they'd like us to know. Make each question one line and friendly."},{"h":"Collect answers in a sheet","b":"Send the form link to everyone and link the responses to a Google Sheet. Give a clear closing date."},{"h":"Get a plan from the answers","b":"Copy the response sheet into your AI assistant (remove names if you don't need them) and ask it to pick the best date, summarise dietary and access needs, and build a timeline of tasks counting back from the event."},{"h":"Send invites and reminders","b":"Create a calendar invite for the chosen date, with the agenda and location, and add your own task deadlines as reminders."}],"example":"Best date: Thu 11 Dec (18 of 22 available). Needs: 4 vegetarian, 1 gluten-free, 1 step-free access. Top activity: escape room then dinner. Timeline: book venue by 21 Nov, send invite 24 Nov, confirm numbers 4 Dec, final reminder 10 Dec.","tips":["Keep health and dietary answers private to the organisers and delete the sheet after the event."],"auto":{"trigger":{"type":"form_submitted","detail":"Each time someone fills in the sign-up form"},"actions":[{"type":"sheet.append","detail":"Add their answers to the event sheet"},{"type":"ai.summarize","detail":"Update the best date and needs summary"},{"type":"calendar.create","detail":"Create the event invite once the form closes"}]}},{"id":"create-a-personal-assistant-that-knows-your-priorities","t":"Create a personal assistant that knows your priorities","d":"Set up a saved AI helper that already knows your roles, goals and preferences, so every planning chat starts from where you are.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":25,"tools":["AI assistant","Google Docs"],"when":"Set up once, then use daily","steps":[{"h":"Write a short 'about me' page","b":"In a Google Doc, note your roles (work and home), current goals, regular commitments, working hours and how you like information presented. Leave out anything sensitive."},{"h":"Create the helper","b":"Make a custom GPT in ChatGPT, a Project in Claude or a Gem in Gemini. Upload your page and paste these instructions.","p":"You are my personal planning assistant. Use the attached 'about me' page for context. When I ask for help: keep answers short and practical; always connect suggestions to my current goals; suggest no more than 3 priorities a day; warn me if I'm overloading a day or week; ask a question if a request is vague. When I say 'plan my day', 'plan my week' or 'brain dump', use the matching format: timeline, day-by-day table, or sorted list. British English."},{"h":"Test it with real requests","b":"Try 'plan my week' and 'brain dump' with your real tasks and adjust the instructions if the answers aren't quite right."},{"h":"Refresh it monthly","b":"Update your 'about me' page when your goals or routines change, and re-upload it."}],"example":"You: plan my day. Assistant: Today (Tue): 3 priorities linked to your goals: 1) Draft course module 2 (goal: launch course in Jan). 2) Call accountant. 3) Gym at 6pm. Warning: You have 5 hours of meetings, so module 2 may need to move to Wed morning.","tips":["Turn on the assistant's memory feature if you're comfortable with it, but check what it has saved now and then."],"auto":{"trigger":{"type":"manual","detail":"User asks their planning assistant for help"},"actions":[{"type":"ai.generate","detail":"Answer using the user's saved goals and preferences"},{"type":"list.add","detail":"Add agreed priorities to the to-do list"}]}},{"id":"turn-support-requests-into-an-organised-to-do-list","t":"Turn support requests into an organised to-do list","d":"A simple online help form that drops every request into a spreadsheet with a status column, plus email alerts when a new one arrives.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Forms","Google Sheets","AI assistant"],"when":"Runs every time someone submits the form","steps":[{"h":"Design the form with AI","b":"Ask your AI assistant to suggest the questions so you get what you need first time.","p":"I'm making a customer support request form for [business type]. Suggest 5 to 7 questions that would let me solve most problems without emailing back. For each: the exact question wording, the best answer type (short answer, paragraph, dropdown, multiple choice, file upload) and dropdown options where relevant. Include a question on urgency. Keep it quick to fill in on a phone, and only ask for personal details I truly need."},{"h":"Build it in Google Forms","b":"Create a new form, add the questions, and add one line at the top saying how you'll use their details and how fast you reply."},{"h":"Link it to a sheet and turn on alerts","b":"In the form's Responses tab, link it to a new Google Sheet. In the same tab's menu, turn on email notifications for new responses."},{"h":"Add tracking columns","b":"In the sheet, add columns for Status (New, In progress, Done) and Owner, using a dropdown. Use Format, then Conditional formatting, to colour urgent requests red."},{"h":"Share the link","b":"Put the form link in your email signature, website contact page and WhatsApp away message."}],"example":"Row 23: 14/05 10:12 | Order issue | Urgency: High | 'Parcel says delivered but not here' | Status: New | Owner: Tom. Row 24: 14/05 11:40 | Product question | Low | 'Is the large bag waterproof?' | Status: Done | Owner: Ana.","tips":["Microsoft Forms and Excel can do the same if your business uses Microsoft 365.","Only share the sheet with people who need it, because it holds customers' contact details."],"auto":{"trigger":{"type":"form_submitted","detail":"A customer submits the support form"},"actions":[{"type":"sheet.append","detail":"Add the request as a new row with status New"},{"type":"ai.classify","detail":"Set urgency and category"},{"type":"notify","detail":"Email the team about urgent requests"}]}},{"id":"keep-track-of-every-deal-in-a-simple-spreadsheet","t":"Keep track of every deal in a simple spreadsheet","d":"A ready-made sales tracker with stages, values, follow-up dates and red alerts for overdue leads, designed with AI in an afternoon.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":40,"tools":["Google Sheets","AI assistant","Google Calendar"],"when":"Set up once, check every morning","steps":[{"h":"Ask AI to design your tracker","b":"Paste this prompt into your AI assistant to plan the sheet.","p":"Design a simple sales pipeline tracker in Google Sheets for a [type of business] with about [number] active leads. Give me: 1) the columns in order with a one-line purpose each (include Stage, Deal value, Last contact, Next step, Next step date, Source), 2) the dropdown options for Stage, 3) step-by-step instructions to add those dropdowns and to colour rows red when Next step date is before today, written for a beginner, 4) a summary tab layout showing total value per stage, with the exact formulas to use (for example SUMIF). Keep it to what a one-person business needs."},{"h":"Build the sheet","b":"Follow the instructions in Google Sheets: add the columns, the Stage dropdown via Data validation, and the red overdue rule via Conditional formatting."},{"h":"Add your current leads","b":"Enter every open conversation, even small ones, with a next step and a date."},{"h":"Make checking it a habit","b":"Create a recurring 10-minute Google Calendar event each morning with the sheet's link in it, and work through anything red."}],"example":"Stages: New, Contacted, Call booked, Proposal sent, Won, Lost. Row: Bloom Florist | Proposal sent | £1,200 | Last contact 03/06 | Next: chase proposal | 10/06 (red, overdue). Summary: Proposal sent £6,400 across 5 deals; Won this month £2,100.","tips":["Write the next step as an action ('Send revised quote'), not a status ('Waiting').","Excel works the same way; ask the AI for Excel instructions instead."],"auto":{"trigger":{"type":"schedule","detail":"Every weekday at 8am"},"actions":[{"type":"ai.summarize","detail":"List overdue next steps and deals by stage"},{"type":"notify","detail":"Send the user today's follow-up list"}]}},{"id":"check-applications-against-your-criteria-fairly","t":"Check applications against your criteria fairly","d":"AI pulls the relevant evidence from each anonymised CV into a table, so you can score every candidate against the same criteria yourself.","cat":"HR & Hiring","side":"work","lvl":"Intermediate","mins":40,"tools":["AI assistant","Google Drive","Google Sheets"],"when":"After the closing date, before shortlisting","steps":[{"h":"Check your rules first","b":"Check your workplace policy and local law on using AI with candidate data. In the UK and EU, you should tell applicants if AI helps in the process, for example in your privacy notice or job ad."},{"h":"Anonymise the applications","b":"Save CVs in a private Google Drive folder. Before using AI, give each one a code (C-01, C-02) and remove names, contact details, photos, dates of birth and addresses."},{"h":"Ask AI to find evidence, not to rank","b":"Upload or paste a few anonymised CVs at a time with this prompt.","p":"I'm shortlisting for [job title]. Criteria: [paste criteria from your rubric]. For each anonymised application below, make a table with one row per criterion: Candidate code, Criterion, Evidence found (quote the exact words from the CV), and 'No evidence found' where relevant. Do not score, rank, or recommend candidates. Do not comment on gaps in employment, age, gender, nationality, schools or anything not in my criteria. Applications: [paste]."},{"h":"Score them yourself","b":"Use the evidence table alongside the original CV to fill in your scoring sheet. Read each original, because AI can miss or misread things."},{"h":"Check for bias and tidy up","b":"Before finalising, look at who you've shortlisted and ask whether anyone was marked down for something unrelated to the job. Delete the AI chats and copies once you're done, in line with your data retention policy."}],"example":"C-04 | Managing a busy rota | 'Created weekly rotas for a team of 12 across two sites' C-04 | Food hygiene | 'Level 2 Food Hygiene certificate (2024)' C-04 | Supervising staff | No evidence found C-05 | Managing a busy rota | 'Covered shift planning when manager was on leave'","tips":["Candidate data is personal data: use a business AI account with training on your data turned off, and only share what's needed.","Never let AI make or rank the decision; it can repeat hidden biases from its training."],"auto":{"trigger":{"type":"new_file","detail":"An anonymised application is added to the shortlisting folder"},"actions":[{"type":"ai.extract","detail":"Quote evidence from the application for each criterion"},{"type":"sheet.append","detail":"Add the evidence rows to the scoring sheet"},{"type":"notify","detail":"Remind the hiring manager to score and decide in person"}]}},{"id":"write-a-full-launch-pack-for-a-new-product","t":"Write a full launch pack for a new product","d":"One brief becomes a launch email, a week of social posts and a short announcement for your website, all saying the same thing.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":40,"tools":["AI assistant","Mailchimp","Google Docs"],"when":"Two weeks before a launch or sale","steps":[{"h":"Write a one-paragraph brief","b":"Cover what it is, who it's for, the price, the launch date and the one reason someone should care. This keeps every piece consistent."},{"h":"Generate the pack","b":"Paste your brief into your AI assistant with this prompt.","p":"Using this launch brief: [brief], write a launch pack for [business]. 1) Email: 3 subject line options (under 45 characters), a preview line, and a 150-word email with one button label. 2) Five social posts for the launch week: teaser (3 days before), launch day, customer benefit, behind the scenes, last chance. Each under 70 words with an image idea. 3) A 60-word website banner announcement. Keep the price, date and claims exactly as in the brief. British English, warm, no hype words."},{"h":"Put it in one document","b":"Paste everything into a Google Doc so you can check it, share it with anyone helping, and fix any detail in one place."},{"h":"Load the email into Mailchimp","b":"Create a new email campaign in Mailchimp, paste in the text, pick a subject line and schedule it for launch morning."},{"h":"Schedule the social posts","b":"Add the five posts to your scheduler or a calendar reminder for each day of launch week."}],"example":"Subject: 'Our winter blend is back'. Email: 'It sold out in nine days last year...' Teaser post: 'Something warm is coming Thursday.' Banner: 'Winter Blend returns 14 Nov - pre-order now, £9.50 a bag.'","tips":["Only send emails to people who signed up to hear from you, and keep the unsubscribe link Mailchimp adds."],"auto":{"trigger":{"type":"form_submitted","detail":"User fills in the launch brief form"},"actions":[{"type":"ai.generate","detail":"Write email, social posts and banner text"},{"type":"doc.create","detail":"Create the launch pack document"},{"type":"calendar.create","detail":"Add a reminder for each launch-week post"}]}},{"id":"sort-and-tag-all-your-old-blog-posts","t":"Sort and tag all your old blog posts","d":"A spreadsheet of every past post with consistent categories, tags and a note on which ones need updating or merging.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Sheets","AI assistant"],"when":"Once a year, or before a website refresh","steps":[{"h":"List your posts","b":"Most blog platforms can export a list of posts, or you can copy titles and links from your blog's archive page. Paste them into Google Sheets with columns: Title, Link, Date, Short description."},{"h":"Decide your categories","b":"Pick 5 to 8 broad categories that match what your readers care about. Fewer is better."},{"h":"Ask the AI to tag them","b":"Copy the sheet rows into your AI assistant with this prompt (do it in batches of about 50).","p":"Here is a list of blog posts: [paste Title, Date, Short description]. My categories are: [list]. For each post, give: Title | Best category | 3 tags (lowercase, reuse the same tags across posts where possible) | Status: Keep, Update (if it looks dated or thin), or Merge (if it overlaps another post, say which). Output as a table in the same order."},{"h":"Paste back and apply","b":"Paste the results into new columns next to your list, then update the categories and tags in your blog editor, starting with the most-visited posts."}],"example":"'10 spring garden jobs' (2019) | Seasonal guides | spring, planting, lawn | Update: mentions a product no longer sold. 'Spring lawn care tips' (2021) | Seasonal guides | spring, lawn | Merge with '10 spring garden jobs'.","tips":["Keep tag lists short; 20 to 30 tags across a whole blog is usually plenty."],"auto":{"trigger":{"type":"new_row","detail":"New post added to the blog list sheet"},"actions":[{"type":"ai.classify","detail":"Pick a category and tags"},{"type":"ai.generate","detail":"Flag whether to keep, update or merge"},{"type":"sheet.update","detail":"Write category, tags and status into the row"}]}},{"id":"make-a-narrated-explainer-video-in-canva","t":"Make a narrated explainer video in Canva","d":"A short slideshow-style video with your own voiceover, captions and music, made in Canva from an AI-written script.","cat":"Video, Image & Voice","side":"work","lvl":"Intermediate","mins":45,"tools":["AI assistant","Canva","Phone camera"],"when":"When you need to explain something simply","steps":[{"h":"Write a scene-by-scene script","b":"Paste this into your AI assistant.","p":"Write a script for a [60-90]-second explainer video about [topic] for [audience]. Split it into 6-8 scenes. For each scene: the voiceover (max 25 words, plain spoken English), a short on-screen headline (max 6 words), and a visual idea that I can make in Canva with icons, photos or simple shapes. End with a call to action: [CTA]."},{"h":"Build the scenes in Canva","b":"Start a Canva video design, add one page per scene, and use templates, icons and your own photos. Add the headlines as big, readable text."},{"h":"Record the voiceover","b":"Use Canva's record option to narrate each page, or record on your phone's voice recorder in a quiet room and upload the audio. Your own voice builds more trust than a synthetic one."},{"h":"Add captions and music","b":"Turn on Canva's auto captions if offered on your plan, or type the voiceover as text. Pick a quiet track from Canva's audio library."},{"h":"Export and share","b":"Download as MP4 and upload to YouTube, your website or social channels."}],"example":"Scene 1: 'Recycling bins confusing? You're not alone.' Visual: three coloured bins. Scene 3: 'Rinse it, squash it, lid on.' Visual: icon sequence. Scene 7: 'Download the bin calendar at our website.' Final: 75 seconds, captions on.","tips":["Only use music, photos and footage you have the rights to; Canva's library is licensed for use in your designs, subject to its terms.","If you include anyone else's face or voice, get their permission first."],"auto":{"trigger":{"type":"manual","detail":"User enters an explainer topic"},"actions":[{"type":"ai.generate","detail":"Write a scene-by-scene script with visuals"},{"type":"doc.create","detail":"Save the script for building in Canva"},{"type":"calendar.create","detail":"Book 45 minutes to build and record"}]}},{"id":"notice-what-s-changed-on-competitors-websites-each-month","t":"Notice what's changed on competitors' websites each month","d":"Once a month, check a few competitor pages and get a clear summary of new prices, products and messages compared with last time.","cat":"Research & News","side":"work","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Docs","Google Calendar"],"when":"First Monday of each month","steps":[{"h":"Choose the pages to watch","b":"Pick three to five competitors and the pages that matter: pricing, services and their news or blog page. List the links in a Google Doc called 'Competitor watch'."},{"h":"Set a monthly reminder","b":"Add a recurring Google Calendar event for the first Monday of the month with the doc linked in the description."},{"h":"Capture this month's pages","b":"Copy the text of each page (or ask an assistant with web browsing to read the links) and paste it under a dated heading in your doc."},{"h":"Compare with last month","b":"Paste last month's notes and this month's text into your AI assistant with this prompt.","p":"Compare last month's and this month's notes on my competitors below. For each competitor list: 1) price changes (old price to new price), 2) new or removed products or services, 3) changes in headline messages or offers, 4) anything that suggests a new direction. Then give me the top 3 changes that matter for [my business] and one idea for how I could respond to each. Only report changes you can see in the text; do not guess. Last month: [paste] This month: [paste]"},{"h":"Save the summary","b":"Paste the summary at the top of that month's section so you build up a history."}],"example":"Greenleaf Gardens: lawn care plan up from £25 to £29/month; new 'hedge and tidy' bundle added. HedgeHogs Ltd: homepage now leads with 'next-day quotes'. Top change: two rivals now offer bundles - consider a spring bundle.","tips":["Keep the raw page text as well as the summary, so you can check the AI's comparison if something looks off."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each month at 9am"},"actions":[{"type":"web.fetch","detail":"Read each competitor page on the list"},{"type":"ai.generate","detail":"Compare with last month and list changes"},{"type":"doc.create","detail":"Add a dated summary to the competitor watch doc"}]}},{"id":"give-your-files-a-tidy-findable-naming-system","t":"Give your files a tidy, findable naming system","d":"Get a simple folder structure and naming rules for your Google Drive or OneDrive, plus a list of which files go where.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Google Drive","OneDrive","Google Calendar"],"when":"Once, then a quick tidy every month","steps":[{"h":"List what you have","b":"Make a quick list of your main folders and some typical file names. You can type them out or take screenshots of your folders."},{"h":"Ask for a structure","b":"Paste your list into your AI assistant with this prompt.","p":"Here is a list of my current folders and file names in [Google Drive / OneDrive]. I use them for [what you do, e.g. running a small bookkeeping business]. Suggest: 1) a folder structure no more than 3 levels deep, 2) a naming rule for files (e.g. YYYY-MM-DD Client Document-type), with 5 examples, 3) a table showing where each of my current files should go and its new name, 4) 3 simple habits to keep it tidy. Keep it simple enough to stick to. [paste list]"},{"h":"Create the folders and move files","b":"Create the new folders in Drive or OneDrive, then move and rename files in batches, starting with the ones you use most."},{"h":"Set a monthly tidy reminder","b":"Add a recurring 15-minute calendar event to file anything left in your Downloads or main folder."}],"example":"Structure: 01 Clients > [Client name] > Invoices / Contracts / Correspondence. 02 Admin > Insurance / Tax / Banking. 03 Templates. Naming: 2026-11-04 Parker Bakery Invoice 112. Move 'scan0042.pdf' to 02 Admin > Insurance as '2026-03-01 Van Insurance Certificate'.","tips":["Starting each file name with the date (YYYY-MM-DD) keeps files in date order automatically."],"auto":{"trigger":{"type":"new_file","detail":"A file is added to the main folder"},"actions":[{"type":"ai.classify","detail":"Work out the right folder for the file"},{"type":"ai.generate","detail":"Suggest a name using the naming rule"},{"type":"file.save","detail":"Move and rename the file after approval"}]}},{"id":"turn-website-quote-requests-into-tidy-tracked-jobs","t":"Turn website quote requests into tidy, tracked jobs","d":"Collect quote requests through a simple form, log them in a sheet automatically, and draft a helpful first reply for each one.","cat":"Small Business Admin","side":"work","lvl":"Intermediate","mins":30,"tools":["Google Forms","Google Sheets","AI assistant","Gmail"],"when":"Whenever a quote request comes in","steps":[{"h":"Build a quote request form","b":"In Google Forms or Microsoft Forms, ask for: name, email, phone, postcode, what they need, size or quantity, ideal date and budget range. Link it from your website and social profiles."},{"h":"Link responses to a sheet","b":"In Google Forms, open Responses and link to a Google Sheet. Turn on email notifications for new responses from the Responses tab's menu."},{"h":"Draft a first reply","b":"When a request arrives, paste the details into your AI assistant with this prompt.","p":"A customer sent this quote request for my [business type]: [paste form response]. Draft a friendly reply email that: thanks them by first name, confirms what they need in one line, asks for any missing details I need to quote properly (list them), gives my usual next step ([e.g. a free 15-minute call / a site visit]) and when they can expect the quote. Under 120 words. Don't give a price."},{"h":"Track each request","b":"Add columns to the sheet for Status (New, Replied, Quoted, Won, Lost) and Quote value, and update them as you go."}],"example":"Hi Amira, thanks for getting in touch about a garden office base. To quote accurately, could you send: rough dimensions of the area, whether there's access for a mini-digger, and a photo from the gate. I can then visit on Tuesday or Thursday. You'll have your quote within 3 working days of the visit. Best, Dan","tips":["Say on the form how you'll use people's details, and only collect what you need to quote."],"auto":{"trigger":{"type":"form_submitted","detail":"A new quote request form is submitted"},"actions":[{"type":"sheet.append","detail":"Log the request with status New"},{"type":"ai.extract","detail":"Spot details missing for a quote"},{"type":"email.draft","detail":"Draft a reply asking for missing details"},{"type":"notify","detail":"Alert the user to the new request"}]}},{"id":"keep-your-pet-s-care-on-track-with-shared-reminders","t":"Keep your pet's care on track with shared reminders","d":"Set up reminders for flea, worming, vaccinations and vet visits that everyone at home can see.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":20,"tools":["AI assistant","Google Calendar","Notes app"],"when":"Set up once, update after each vet visit","steps":[{"h":"Gather your pet's records","b":"Find your pet's vaccination card, last flea and worming dates and the products the vet recommended."},{"h":"Turn it into a care schedule","b":"Paste the details into your AI assistant with this prompt.","p":"Help me organise my pet's routine care. Pet: [species, breed, age, weight]. Last vaccination: [date and type]. Flea treatment: [product and date, and how often the vet said]. Worming: [product, date, frequency]. Other: [nail trims, grooming, dental checks, insurance renewal]. Create a 12-month schedule table with date, task and notes, using only the frequencies I've given. Don't recommend products or doses. Add a short list of questions to ask the vet at the next check-up."},{"h":"Add shared reminders","b":"Create recurring events in a shared Google Calendar or Outlook Calendar so everyone at home sees when the next treatment is due."},{"h":"Keep a care note","b":"Save a note with the vet's number, insurance policy number, microchip number and any allergies, so it's handy in an emergency."}],"example":"Bramble (cat, 4): Flea - 1st of each month. Worming - every 3 months: 10 Jan, 10 Apr, 10 Jul, 10 Oct. Booster - 18 May (book 2 weeks before). Insurance renews 1 Sept. Ask vet: is her weight OK? Should we brush her teeth?","tips":["Always follow your vet's advice on products and doses. The AI is only for organising dates."],"auto":{"trigger":{"type":"calendar_event","detail":"A pet care task is due"},"actions":[{"type":"notify","detail":"Remind the household the task is due today"},{"type":"message.send","detail":"Post the reminder in the family chat"}]}},{"id":"plan-a-road-trip-with-sensible-stops","t":"Plan a road trip with sensible stops","d":"Get a road trip route broken into comfortable driving days, with breaks, overnight stops and things to see on the way.","cat":"Travel","side":"life","lvl":"Intermediate","mins":25,"tools":["AI assistant","Google Maps"],"when":"A few weeks before a road trip","steps":[{"h":"Set your limits","b":"Decide your start and end points, how many days you have and the most driving you want to do in a day."},{"h":"Ask for a route plan","b":"Paste this prompt into your AI assistant.","p":"Plan a road trip from [start] to [end] over [number] days for [who, including children or pets]. Maximum driving per day: [hours], with a break at least every [2] hours. We like [interests]. For each day give: route, approximate driving time, a good place for a break, one or two things to see, and an area to stay overnight. Note any toll roads, low-emission zones or ferry crossings I should check, and the best day to rest."},{"h":"Build the route in Google Maps","b":"Add each day's stops as a route with multiple destinations in Google Maps, and save the places to a list so they're on your phone."},{"h":"Check the rules","b":"Look up toll, clean-air zone and ferry details on official sites, as charges and rules change."}],"example":"Day 1: Bristol to Portsmouth (2h10), break at a services near Salisbury, ferry evening crossing (book ahead). Day 2: Caen to Saint-Malo (2h30), walk the ramparts. Check: French toll roads, Crit'Air sticker for some cities.","tips":["Driving times from AI are estimates; Google Maps on the day will give you live traffic."],"auto":{"trigger":{"type":"manual","detail":"User enters start, end and number of days"},"actions":[{"type":"ai.generate","detail":"Split the route into driving days with stops"},{"type":"doc.create","detail":"Save the road trip plan"}]}},{"id":"share-caring-for-a-parent-with-your-siblings","t":"Share caring for a parent with your siblings","d":"Keep one shared calendar and running note of a parent's appointments, medicines and who's doing what each week.","cat":"Health & Fitness","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Calendar","Google Docs","WhatsApp","AI assistant"],"when":"Set up once, update weekly","steps":[{"h":"Agree it with your parent","b":"Talk to your parent first about what they're happy to share, and with whom. It's their information."},{"h":"Create a shared calendar","b":"Make a new Google Calendar or Outlook Calendar just for their care, and share it with the family. Add appointments, prescription collection days and visits, with who is going."},{"h":"Keep a running care note","b":"Create a shared Google Docs or Word file for updates after each appointment and visit, so everyone knows the latest."},{"h":"Send a weekly update","b":"Each week, paste the latest notes (using first names only) into your AI assistant with this prompt and share the result in the family WhatsApp group.","p":"Here are this week's care notes for my parent: [paste notes, first names only]. Write a short, kind family update with: how they're doing, appointments and outcomes this week, anything that's changed, next week's calendar, and who's covering what. Then list any gaps where no one is down to help. Don't add any medical advice or interpretation."}],"example":"Mum's week: in good spirits, walked to the shop twice. Tuesday: GP review, blood pressure tablets unchanged. Next week: Thu 10:30 eye clinic (Raj driving), prescription pick-up Fri (Sarah). Gap: no one free for Sunday lunch visit yet.","tips":["Keep the calendar and notes shared only with close family, and check your parent is comfortable with what's written.","Questions about treatment should go to their GP or care team."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 6pm"},"actions":[{"type":"ai.summarize","detail":"Summarise the week's care notes and next week's calendar"},{"type":"message.send","detail":"Post the update to the family group chat"}]}},{"id":"keep-side-hustle-income-and-costs-organised","t":"Keep side-hustle income and costs organised","d":"A simple running record of what your side work earns and costs, with a monthly summary ready for when you sort out your tax.","cat":"Money","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Sheets","Gmail","AI assistant"],"when":"Weekly, plus a monthly summary","steps":[{"h":"Create a side-hustle sheet","b":"Make a Google Sheet with two tabs: Income (Date, Client or platform, Description, Amount) and Costs (Date, Supplier, What for, Amount, Receipt link)."},{"h":"Label related emails","b":"In Gmail's settings, under Filters, set up a filter that labels emails from your selling platforms, payment services and suppliers as Side hustle."},{"h":"Turn emails into rows weekly","b":"Once a week, copy the new emails from that label into your AI assistant with this prompt.","p":"Here are this week's emails about my side business selling [what you do]. Extract every sale, payment received, fee and purchase. Return two tables: INCOME (Date, Client or platform, Description, Amount) and COSTS (Date, Supplier, What for, Amount). Include platform fees as costs. Use DD/MM/YYYY dates. Don't guess amounts: write CHECK if unclear. [paste emails]"},{"h":"Paste and check","b":"Paste each table into the matching tab, and save receipts to a Google Drive folder with a link in the Costs tab."},{"h":"Run a monthly summary","b":"At month end, ask the AI to total income, costs and profit by month from your sheet. Check what records your country's tax service expects, and speak to an accountant if you're unsure."}],"example":"November: Income £640 (14 sales via craft marketplace, 2 commissions). Costs £187 (materials £122, platform fees £41, postage £24). Profit £453. Year to date profit: £3,210.","tips":["Many countries have a threshold before side income must be declared. Check your official tax website or an accountant rather than relying on the AI.","Keep business and personal spending in separate accounts if you can. It makes this far easier."],"auto":{"trigger":{"type":"new_email","detail":"A new email arrives in the Side hustle label"},"actions":[{"type":"ai.extract","detail":"Pull out sales, fees and purchases"},{"type":"sheet.append","detail":"Add rows to the Income or Costs tab"},{"type":"ai.summarize","detail":"Send a monthly profit summary"}]}},{"id":"track-your-progress-towards-a-qualification","t":"Track your progress towards a qualification","d":"A simple tracker of modules, deadlines and grades for a course, with a weekly summary of what's due and how you're doing.","cat":"Learning","side":"life","lvl":"Intermediate","mins":30,"tools":["Google Sheets","Google Calendar","AI assistant"],"when":"Weekly, through your course","steps":[{"h":"Get your course details","b":"Collect the course handbook or module list with assignment deadlines and how each is weighted."},{"h":"Build the tracker with AI","b":"Paste the details into your AI assistant with this prompt.","p":"Turn this course information into a tracker table I can paste into Google Sheets. Columns: Module, Assessment, Type (essay, exam, project), Weighting %, Due date, Status (Not started / In progress / Submitted / Marked), Grade, Notes. Sort by due date. Then list all deadlines as calendar entries in the format: [Due date] - [Module]: [Assessment]. Here's the course info: [paste]"},{"h":"Add deadlines to your calendar","b":"Paste the tracker into Google Sheets and add each deadline to Google Calendar, with a reminder two weeks before."},{"h":"Do a weekly check-in","b":"Each week, update the Status column and paste the sheet into your AI assistant, asking: 'What's due in the next 3 weeks, what should I start now, and what's my average grade so far?'"}],"example":"Next 3 weeks: Module 2 Essay (30%) due 29 Nov, status In progress. Module 3 Quiz (10%) due 6 Dec, Not started: start this week. Average so far: 64% across 3 marked pieces.","tips":["Calendar reminders two weeks ahead give you time to ask tutors questions.","Always confirm deadlines in your official course portal, since dates can change."],"auto":{"trigger":{"type":"schedule","detail":"Monday mornings"},"actions":[{"type":"web.fetch","detail":"Read the course tracker sheet"},{"type":"ai.summarize","detail":"List upcoming deadlines and progress"},{"type":"notify","detail":"Send the weekly course summary"}]}},{"id":"keep-a-wins-log-for-your-next-review","t":"Keep a wins log for your next review","d":"A running record of your achievements captured in seconds each week, turned into a clear summary when your appraisal comes round.","cat":"Careers","side":"life","lvl":"Advanced","mins":30,"tools":["Google Forms","Google Sheets","Google Calendar","AI assistant"],"when":"Every Friday, plus before reviews","steps":[{"h":"Create a quick wins form","b":"Make a Google Form with three questions: What went well this week? Any result or feedback? Anything I learned? Link it to a Google Sheet so answers are saved automatically."},{"h":"Add a Friday reminder","b":"Create a recurring Google Calendar event every Friday afternoon with the form link in it, or save the form to your phone's home screen."},{"h":"Fill it in weekly","b":"Spend two minutes each Friday. Small things count: a thank-you email, a fixed problem, a new skill."},{"h":"Summarise before your review","b":"Before your appraisal, copy the sheet rows into your AI assistant with this prompt.","p":"Here's my weekly wins log for the last [period]. My job is [title] and my objectives this year were: [list]. Group my wins under each objective, plus an 'Other contributions' section. For each, write one clear, factual bullet with any numbers or feedback included. Highlight my 3 strongest achievements and suggest 2 development goals based on what I learned. Use only what's in the log, nothing invented. [paste log]"},{"h":"Bring it to your review","b":"Edit the summary in your own words and share it with your manager before the meeting."}],"example":"Objective 1: Improve customer response times. - Rewrote three email templates, cutting average reply time from 2 days to same day (Feb). - Praised by area manager in team meeting (Apr). Strongest wins: templates, training two new starters, covering the supervisor role for three weeks.","tips":["Check your workplace's rules before putting work details into an AI assistant, and leave out customer names.","A wins log also helps on tough weeks, when you need reminding what you've done."],"auto":{"trigger":{"type":"form_submitted","detail":"A weekly wins form is submitted"},"actions":[{"type":"sheet.append","detail":"Save the entry to the wins log"},{"type":"ai.classify","detail":"Tag the win against the user's objectives"},{"type":"ai.summarize","detail":"Create a review summary before each appraisal"}]}},{"id":"start-each-day-with-a-personal-morning-briefing","t":"Start each day with a personal morning briefing","d":"A short morning note with your appointments, the weather, top three tasks and anything you need to remember, waiting when you wake up.","cat":"Personal Assistant","side":"life","lvl":"Advanced","mins":30,"tools":["AI assistant","Google Calendar","Gmail"],"when":"Every weekday morning","steps":[{"h":"Decide what you want in it","b":"Pick what's useful: today's calendar, weather for your town, top tasks, birthdays, and anything urgent in your inbox."},{"h":"Connect your calendar and email","b":"In your AI assistant's settings, look for options to connect Google or Microsoft apps. Only connect what you're comfortable with it reading."},{"h":"Create a scheduled briefing","b":"If your plan includes scheduled tasks in ChatGPT or scheduled actions in Gemini, set one up for 7am on weekdays with this prompt.","p":"Give me my morning briefing for today in under 150 words. Include: 1) weather for [town] and whether I need a coat or umbrella, 2) my calendar for today with times, and anything I need to bring or prepare, 3) any emails from the last 24 hours that look urgent or need a reply today, by sender and one-line summary, 4) reminders: [list standing things, for example bins on Tuesday, swimming kit on Thursday]. End with my top 3 priorities based on the above. Keep it calm and practical."},{"h":"Use the free fallback","b":"If scheduling isn't available, save the prompt in your notes, set a daily phone reminder, and paste in your calendar for the day when it goes off."},{"h":"Fine-tune after a week","b":"Tell the assistant what was useful and what to drop so the briefing gets shorter and better."}],"example":"Tuesday: 9°C, showers after 3pm, take an umbrella. 9:30 Dentist (bring appointment card). 2pm Team call. 6pm Parents' evening. Emails: school asked to confirm trip consent by Thursday. Reminders: bins out tonight. Top 3: trip consent, prep for team call, buy birthday card for Gran.","tips":["Review which apps you've connected now and then, and disconnect any you no longer need.","Keep standing reminders in the prompt itself so they appear every week without extra effort."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 7am"},"actions":[{"type":"web.fetch","detail":"Get today's weather and calendar"},{"type":"ai.summarize","detail":"Pick out urgent emails from the last 24 hours"},{"type":"ai.generate","detail":"Write a short briefing with top 3 priorities"},{"type":"notify","detail":"Send the briefing to the user's phone"}]}},{"id":"sort-incoming-email-into-labels-automatically","t":"Sort incoming email into labels automatically","d":"Get a set of email filters that file receipts, newsletters and notifications into their own labels or folders, so your inbox shows people.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Gmail","Outlook"],"when":"Once, then tweak monthly","steps":[{"h":"List your noisiest senders","b":"Scroll back through a week of email and write down the senders and subject words that crowd your inbox, such as 'order', 'receipt' or a shop's name."},{"h":"Ask AI to design your filing system","b":"Paste your list into your AI assistant with this prompt.","p":"I want to tidy my [Gmail / Outlook] inbox with filters. Here are senders and subject words that clutter it: [paste list]. Suggest no more than 6 labels/folders (e.g. Receipts, Newsletters, Notifications, Travel). For each, give: the label name, the exact sender addresses or words to match, and whether it should skip the inbox or stay in it. Present it as a table I can follow one row at a time. Flag anything that might catch important personal emails by mistake."},{"h":"Create the filters or rules","b":"In Gmail, search for the senders, then choose 'Create filter' from the search options and apply a label. In Outlook, right-click a message and create a rule to move it to a folder."},{"h":"Check after a week","b":"Look in each label once and move anything misfiled back. Ask your AI assistant to adjust the rule if something keeps landing in the wrong place."}],"example":"Receipts | from: orders@, receipts@, subject 'your order' | skip inbox. Newsletters | from: hello@freshbakes.co, news@runclub.org | skip inbox. Notifications | from: no-reply@ | skip inbox. Travel | subject 'booking confirmation' | keep in inbox.","tips":["Start with skipping the inbox only for senders you're sure about; you can always widen it later.","Gmail's built-in Promotions and Updates tabs already do some of this, so build on them rather than fighting them."],"auto":{"trigger":{"type":"new_email","detail":"Any new email arrives"},"actions":[{"type":"ai.classify","detail":"Decide if it is a receipt, newsletter, notification, travel or personal"},{"type":"email.label","detail":"Apply the matching label and archive if it is low priority"}]}},{"id":"set-up-a-family-calendar-that-keeps-everyone-in-sync","t":"Set up a family calendar that keeps everyone in sync","d":"Create one family calendar with colour-coded people, every term date and regular activity added, and reminders that go to the right person.","cat":"Meetings & Calendar","side":"work","lvl":"Intermediate","mins":40,"tools":["Google Calendar","AI assistant","WhatsApp"],"when":"Set up once, then each new school term","steps":[{"h":"Create a shared calendar","b":"In Google Calendar, create a new calendar called 'Family' and share it with each adult, or use Google's family group calendar. Outlook and iPhone users can share a calendar in a similar way."},{"h":"Turn your schedule into events","b":"Gather term dates, clubs and regular appointments, then ask your AI assistant to organise them.","p":"Help me set up our family calendar. People: [names and ages]. Here are term dates, clubs and regular commitments: [paste or attach school letters and notes]. Give me a table of events with: title starting with the person's name (e.g. 'Mia - Swimming'), day/date, time, repeat pattern (weekly, termly, one-off), location, who's doing the drop-off or pick-up, and a reminder time. Flag any clashes where one adult is needed in two places."},{"h":"Add events and assign colours","b":"Create each event, using repeating events for weekly clubs, and give each person's events their own colour so the week is easy to read."},{"h":"Sort the clashes","b":"Look at the flagged clashes together and agree who covers what, then message the plan in your family WhatsApp group."}],"example":"Mia - Swimming | Tues 17:00-18:00 weekly in term | Leisure Centre | Drop: Dad, Pick: Mum | remind 16:15. Leo - Football | Sat 9:30 | Park | Dad. Clash: Thu 3 Dec - parents' evening 17:30 and Leo's cubs 18:00, both need Mum.","tips":["Add an end date to term-time repeating events so they don't carry on through the holidays."],"auto":{"trigger":{"type":"new_file","detail":"A new school letter or timetable is added"},"actions":[{"type":"ai.extract","detail":"Pull out events, times and who's responsible"},{"type":"calendar.create","detail":"Add the events to the family calendar"},{"type":"message.send","detail":"Post any clashes to the family group chat"}]}},{"id":"turn-a-big-goal-into-a-12-week-plan","t":"Turn a big goal into a 12-week plan","d":"Set one meaningful goal for the next three months and get weekly milestones, scheduled check-ins and a way to track progress.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":30,"tools":["AI assistant","Google Calendar","Google Sheets","Notion"],"when":"At the start of each quarter","steps":[{"h":"Pick one goal","b":"Choose a single goal you can make real progress on in 12 weeks, such as launching a side business, getting fitter or finishing a qualification."},{"h":"Ask for a 12-week plan","b":"Paste this prompt into your AI assistant.","p":"Help me turn this goal into a 12-week plan: [goal]. Start date: [date]. Time available: [hours per week]. Where I'm starting from: [current situation]. Give me: 1) A clear, measurable version of the goal. 2) Milestones for weeks 4, 8 and 12. 3) A table of 12 weeks, each with a focus and 2 or 3 specific actions. 4) The 3 most likely obstacles and how to handle each. 5) A 5-minute weekly check-in question list."},{"h":"Put it in a tracker","b":"Copy the 12-week table into Google Sheets, Excel or Notion with a 'done' column for each action."},{"h":"Schedule the check-ins","b":"Create a recurring weekly 15-minute calendar event for 12 weeks called 'Goal check-in', with the check-in questions in the description."}],"example":"Goal: Run 5k without stopping by 2 Feb. Week 4: Run 2 x 5 min. Week 8: Run 15 min. Week 12: 5k parkrun. Week 1: 3 x walk/run sessions (1 min run, 2 min walk). Obstacle: dark evenings, so plan lunchtime runs on Tue and Thu.","tips":["For fitness or health goals, check with your GP first if you have any medical conditions."],"auto":{"trigger":{"type":"schedule","detail":"Weekly check-in for 12 weeks"},"actions":[{"type":"notify","detail":"Send the weekly check-in questions"},{"type":"sheet.update","detail":"Record this week's progress"},{"type":"ai.generate","detail":"Adjust the next week's actions based on progress"}]}},{"id":"turn-a-recorded-walkthrough-into-a-customer-help-guide","t":"Turn a recorded walkthrough into a customer help guide","d":"Record yourself explaining a fix on Zoom, then turn the transcript into a clear step-by-step help article customers can follow alone.","cat":"Customer Support","side":"work","lvl":"Intermediate","mins":30,"tools":["Zoom","AI assistant","Google Docs"],"when":"When you keep explaining the same thing over and over","steps":[{"h":"Record a short walkthrough","b":"Start a Zoom meeting on your own, share your screen and talk through the task as if a customer were watching. Turn on recording with an audio transcript if your plan includes it."},{"h":"Get the transcript","b":"Download the transcript from your Zoom recordings once it's ready. On a free plan, use your phone's voice recorder app with transcription, or type rough notes as you go."},{"h":"Turn it into a guide","b":"Paste the transcript into your AI assistant with this prompt.","p":"Here is a transcript of me explaining how to [task] for customers of [product/service]: [paste]. Turn it into a help article. Include: a clear title, a one-sentence 'what you'll need', numbered steps (one action each, under 25 words), a note where a screenshot would help written as [Screenshot: what it shows], a 'If it doesn't work' section with 3 common fixes, and a short summary at the top. Remove filler words and anything I said that was a mistake. British English, friendly, no jargon."},{"h":"Add screenshots and publish","b":"Paste the guide into Google Docs, add the screenshots where marked, and share the link or copy it to your website's help page."}],"example":"How to reset your booking password You'll need: the email you booked with. 1. Go to the booking page and tap 'Log in'. 2. Tap 'Forgotten password'. [Screenshot: login screen] 3. Check your inbox for an email from us... If it doesn't work: check spam, use the original email, or contact us.","tips":["Walk through the guide yourself on a phone before sharing; it shows any missed step fast.","Make sure no customer details are visible on screen while recording."],"auto":{"trigger":{"type":"new_file","detail":"A new recording transcript appears in the help-guides folder"},"actions":[{"type":"ai.generate","detail":"Turn the transcript into a step-by-step help article"},{"type":"doc.create","detail":"Create a draft guide document with screenshot markers"},{"type":"notify","detail":"Let the owner know the draft is ready to check"}]}},{"id":"build-a-list-of-local-businesses-to-approach","t":"Build a list of local businesses to approach","d":"A tidy spreadsheet of local businesses in your target area, gathered from Google Maps and cleaned up by AI, ready for careful outreach.","cat":"Sales & Leads","side":"work","lvl":"Intermediate","mins":45,"tools":["Google Maps","Google Sheets","AI assistant"],"when":"When you want new local clients","steps":[{"h":"Search Google Maps for your ideal customer","b":"Search for a business type in an area, such as 'dog groomers in Bristol'. Open each result and note the name, website, phone, rating and anything that shows they need you."},{"h":"Paste your rough notes into a sheet","b":"Don't worry about tidiness; paste names, links and notes into a Google Sheet as you go. Aim for 20 to 40 businesses."},{"h":"Ask AI to clean and sort it","b":"Copy the rough rows into your AI assistant with this prompt.","p":"Here are rough notes on local businesses I might sell to: [paste]. I offer [what you sell]. Turn this into a table with columns: Business name, Website, Phone, Google rating, Number of reviews, Fit score (1 to 5), Reason for score, Opening idea. Score higher if [signs they need you, e.g. no website, low review count, outdated photos]. Remove duplicates, keep my facts exactly as written, and put 'unknown' rather than guessing missing details. Sort by Fit score, highest first."},{"h":"Paste the table back into your sheet","b":"Paste the AI's table into a new tab, then add columns for Contacted (date) and Outcome."},{"h":"Contact the top ten first","b":"Start with the best-fit businesses, using their public business contact details and a personal message."}],"example":"1. Paws & Bubbles | pawsbubbles.co.uk | 0117 xxx | 4.8 (12 reviews) | Fit 5 | Great reviews but no online booking | Opening idea: 'Your reviews are brilliant; shall I show how online booking could fill your quiet Tuesdays?'","tips":["Collect it by hand rather than with scraping tools; it's slower but keeps you within Google's terms and gives you better notes.","Only store business contact details, and delete businesses that ask not to be contacted."],"auto":{"trigger":{"type":"manual","detail":"User chooses a business type and area"},"actions":[{"type":"web.fetch","detail":"Look up public business listings for the area"},{"type":"ai.classify","detail":"Score each business for fit and note why"},{"type":"sheet.append","detail":"Add the cleaned leads to the lead sheet"}]}},{"id":"manage-holiday-requests-without-clashes-or-confusion","t":"Manage holiday requests without clashes or confusion","d":"Staff request leave through a form, you see clashes highlighted in a sheet, get an alert, and approved days go straight onto a shared team calendar.","cat":"HR & Hiring","side":"work","lvl":"Advanced","mins":50,"tools":["Google Forms","Google Sheets","Google Calendar","AI assistant"],"when":"Every time someone asks for time off","steps":[{"h":"Create the request form","b":"Make a Google Form with: name (dropdown of staff), first day off, last day off, type of leave (holiday, unpaid, other) and an optional note. Turn on email notifications for new responses."},{"h":"Set up the sheet with AI help","b":"Link the form to a Google Sheet, then ask your AI assistant for the formulas you need.","p":"My Google Sheet of holiday requests has these columns: A Timestamp, B Name, C First day, D Last day, E Leave type, F Note. Give me beginner-friendly, step-by-step instructions to: 1) add column G 'Working days' that counts weekdays between C and D (using NETWORKDAYS), 2) add column H 'Status' with a dropdown of Pending, Approved, Declined, 3) highlight a row orange if its dates overlap with another Approved request, using a custom formula in conditional formatting, 4) make a summary tab showing each person's approved days so far this year against an allowance of [number] days. Give the exact formulas and say where to paste them."},{"h":"Make a shared team calendar","b":"Create a separate Google Calendar called Team holidays and share it with staff as view-only."},{"h":"Approve and add to the calendar","b":"When an alert arrives, check for orange clashes, set the Status, reply to the person, and add approved leave as an all-day event on the team calendar."},{"h":"Check balances monthly","b":"Look at the summary tab once a month and remind anyone who has lots of leave left."}],"example":"New request: Marta | 12 to 16 Aug | Holiday | 5 working days | Pending (orange: overlaps with Dan, Approved 14 to 21 Aug). Summary: Marta 9 of 28 days used; Dan 17 of 28. Team holidays calendar: 'Dan - holiday' 14 to 21 Aug.","tips":["Keep 'other' leave notes brief and private; sickness and family reasons are sensitive personal data.","Check that formulas work with a few test requests before you share the form with the team."],"auto":{"trigger":{"type":"form_submitted","detail":"A staff member submits a leave request"},"actions":[{"type":"sheet.append","detail":"Add the request with working days calculated"},{"type":"ai.classify","detail":"Check for clashes with approved leave"},{"type":"notify","detail":"Alert the manager to approve or decline"},{"type":"calendar.create","detail":"Add approved leave to the team holiday calendar"}]}},{"id":"plan-seasonal-posts-for-a-local-trade-business","t":"Plan seasonal posts for a local trade business","d":"A season's worth of useful tips, reminders and offers for a local trade like a garage, plumber or gardener, with matching images ready to schedule.","cat":"Marketing & Social","side":"work","lvl":"Intermediate","mins":40,"tools":["AI assistant","Canva","Instagram"],"when":"At the start of each season","steps":[{"h":"Note what customers need this season","b":"Write down the jobs that spike this time of year (for a garage: winter tyres, batteries, MOTs) and any offers you want to push."},{"h":"Ask for a season of posts","b":"Paste this into your AI assistant.","p":"I run a [trade] business in [town]. The next 12 weeks are [season]. Common jobs now: [list]. Offers: [list]. Write 12 weekly social posts: mostly practical tips customers can do themselves, plus 3 offers and 2 'meet the team' posts. For each: week number, headline for the image (max 6 words), caption (50-80 words, local and friendly), call to action (call, book online, pop in), and a photo idea I can take on my phone. British English."},{"h":"Snap the photos on your phone","b":"Take a batch of photos in one go at work: your van, tools, team and finished jobs. Ask team members before photographing them."},{"h":"Make images in Canva","b":"Drop each photo into one Canva template with the headline on top, then duplicate for each week."},{"h":"Schedule them","b":"Use Meta Business Suite to schedule all 12 to Facebook and Instagram, or add a weekly reminder to post them yourself."}],"example":"Week 3: 'Is your battery winter ready?' Caption: 'Cold mornings are hard on car batteries. If your engine sounds sluggish, pop in to our Station Road garage for a free 5-minute test.' Photo: tester clipped to a battery.","tips":["Blur or crop out customer number plates and house numbers in job photos."],"auto":{"trigger":{"type":"schedule","detail":"First day of each season"},"actions":[{"type":"ai.generate","detail":"Write 12 weeks of seasonal posts and photo ideas"},{"type":"sheet.append","detail":"Add the posts to the content calendar"},{"type":"notify","detail":"Remind the user to take the photo batch"}]}},{"id":"write-a-customer-success-story-from-an-interview","t":"Write a customer success story from an interview","d":"A recorded chat with a happy customer becomes a polished case study with a headline, the challenge, the result and approved quotes.","cat":"Content & Writing","side":"work","lvl":"Intermediate","mins":45,"tools":["Zoom","AI assistant","Google Docs"],"when":"After a project goes well","steps":[{"h":"Get permission and record","b":"Ask the customer if they're happy to be featured and recorded. Hold a 20-minute Zoom or Google Meet call about their situation before, what you did and what changed."},{"h":"Get the transcript","b":"If your plan includes Zoom AI Companion, Meet's 'Take notes for me' or transcripts, download the transcript after the call. Otherwise record on your phone with permission and use its transcription feature."},{"h":"Draft the case study","b":"Paste the transcript into your AI assistant with this prompt.","p":"Write a customer case study from this interview transcript: [paste]. Customer: [name and company, as approved]. Our service: [what you did]. Structure: headline with the main result (under 12 words); 2-sentence summary; The challenge (80 words); What we did (100 words); The results (80 words, use only numbers mentioned in the transcript); 2-3 direct quotes using their exact words. Mark anything that needs confirming with [CONFIRM]. British English, factual, no exaggeration."},{"h":"Send it for approval","b":"Put the draft in a Google Doc and share it with the customer to check quotes and numbers before you publish anything."}],"example":"Headline: How Green Lane Vets Cut Missed Appointments by a Third. Challenge: 1 in 8 bookings were no-shows... Results: no-shows fell from 12% to 8% in three months. Quote: 'The reminders just work, and clients actually like them.' [CONFIRM] staff hours saved.","tips":["Always get written approval from the customer before publishing, and delete the recording if they ask."],"auto":{"trigger":{"type":"new_file","detail":"Interview transcript saved to the case studies folder"},"actions":[{"type":"ai.extract","detail":"Pull out challenge, actions, results and quotes"},{"type":"ai.generate","detail":"Write the case study draft"},{"type":"doc.create","detail":"Create a shareable document for customer approval"}]}},{"id":"film-a-month-of-short-videos-in-one-session","t":"Film a month of short videos in one session","d":"Plan, film and schedule eight or more short videos from one afternoon of filming, spread across the month on YouTube Shorts and Reels.","cat":"Video, Image & Voice","side":"work","lvl":"Intermediate","mins":60,"tools":["AI assistant","Phone camera","YouTube","Google Calendar"],"when":"Once a month","steps":[{"h":"Plan the batch","b":"Ask your AI assistant for a set of scripts that can all be filmed in one place.","p":"Plan [8] short vertical videos (20-45 seconds) for [business/channel] about [topics], aimed at [audience]. All must be filmable in [location] in one afternoon with one phone. For each: title, 2-second hook, 3-5 shot script with spoken lines, props needed, and outfit changes if any. Then give a filming order that groups videos by setup to save time, and a posting schedule of 2 a week."},{"h":"Prepare and film","b":"Gather the props list, set up near good light, and film in the suggested order. Name each clip with the video number as you go."},{"h":"Edit in a batch","b":"Edit all the videos in one sitting in your phone's editor or Canva, using the same caption style and ending."},{"h":"Schedule them","b":"Upload to YouTube Studio and set each to Schedule with a date and time. For Instagram, schedule Reels in Meta Business Suite or the Instagram app if your account offers scheduling."},{"h":"Book next month's session","b":"Add a recurring monthly event to Google Calendar for your filming afternoon."}],"example":"Filming order: kitchen counter (videos 1, 4, 6), garden (2, 7), front door (3, 5, 8). Schedule: Tue and Fri at 6pm through November. Total: 8 Shorts, 3 hours filming, 2 hours editing.","tips":["Film a few extra hooks for each video; you can swap them later if one doesn't perform."],"auto":{"trigger":{"type":"schedule","detail":"Last Monday of each month"},"actions":[{"type":"ai.generate","detail":"Plan scripts, filming order and posting schedule"},{"type":"calendar.create","detail":"Book filming and editing sessions"},{"type":"calendar.create","detail":"Add a reminder for each scheduled post"}]}},{"id":"build-a-shortlist-of-local-businesses-in-a-spreadsheet","t":"Build a shortlist of local businesses in a spreadsheet","d":"Use Google Maps and your AI assistant to build a tidy spreadsheet of local suppliers, venues or tradespeople, with ratings, websites and notes.","cat":"Research & News","side":"work","lvl":"Intermediate","mins":25,"tools":["Google Maps","AI assistant","Google Sheets"],"when":"When you need to find and compare local options","steps":[{"h":"Search Google Maps","b":"Search for what you need near you, for example 'commercial cleaners near Bristol'. Open the 10 to 15 most relevant results."},{"h":"Copy the basics","b":"For each one, copy the name, rating, number of reviews, website and phone number from the listing into a note. Screenshots of the listings also work."},{"h":"Ask AI to tidy it into a table","b":"Paste your notes or attach the screenshots with this prompt.","p":"Turn the notes below into a table with these columns: Business name, Area, Google rating, Number of reviews, Website, Phone, Services mentioned, Notes. Use only the information I've given you and leave a cell blank if it's missing; do not guess phone numbers or websites. Then add a 'Shortlist?' column with Yes for the best [5] for [my need, e.g. weekly office cleaning, 2,000 sq ft], and explain your choices underneath. [paste notes]"},{"h":"Paste into Google Sheets","b":"Copy the table into a new Google Sheet. Check each phone number and website against the Maps listing before you call."},{"h":"Add your own notes as you call","b":"Add columns for 'Quote', 'Availability' and 'Gut feel' and fill them in as you speak to each business."}],"example":"Shortlist: Sparkle Pro Cleaning (4.8, 212 reviews, offices and retail), BrightDesk Services (4.6, 89 reviews, out-of-hours), Clearwater Facilities (4.7, 140 reviews)... Excluded: Tidy Homes (domestic only).","tips":["Only use business contact details listed publicly, and don't add individuals' personal numbers."],"auto":{"trigger":{"type":"manual","detail":"User describes what they need and where"},"actions":[{"type":"web.fetch","detail":"Find matching local businesses"},{"type":"ai.extract","detail":"Pull out name, rating, website and phone"},{"type":"sheet.append","detail":"Add each business as a row"},{"type":"ai.classify","detail":"Mark the best matches for the shortlist"}]}},{"id":"build-a-team-knowledge-base-people-can-search","t":"Build a team knowledge base people can search","d":"Gather your team's how-tos and policies into Notion so anyone can find answers fast, written up clearly from your messy notes.","cat":"Documents & Data","side":"work","lvl":"Intermediate","mins":60,"tools":["Notion","AI assistant","Google Docs"],"when":"Set up once, then add to it weekly","steps":[{"h":"List the questions people keep asking","b":"Spend a week noting every 'how do I...' or 'where is...' question on your team. These become your first pages."},{"h":"Create a simple structure","b":"In Notion, make a page called 'Team handbook' with sub-pages for each area, such as Customers, Tools, Money and HR."},{"h":"Turn messy notes into clear pages","b":"Paste existing documents or emails into your AI assistant with this prompt, then copy the result into Notion.","p":"Turn the notes below into a clear knowledge-base article titled '[title]'. Format: a one-line summary, 'When to use this', numbered steps, 'Who to ask', and 'Last checked: [date]'. Keep it short, use plain language, and keep every specific detail (names of tools, amounts, deadlines) exactly as written. List anything that seems out of date or contradictory at the end. [paste notes]"},{"h":"Let people ask questions","b":"If your plan includes Notion AI, people can ask questions and get answers drawn from your pages. If not, Notion's search finds pages by keyword."},{"h":"Keep it fresh","b":"Give each page an owner and set a recurring reminder to check it every three months."}],"example":"Article: How to process a refund. Summary: refunds under £50 can be approved by anyone on the team. Steps: 1) Find the order in Shopify. 2) Click Refund... Who to ask: Priya (over £50). Last checked: 9 Nov 2026. Possibly out of date: mentions the old returns address.","tips":["Keep passwords and personal staff details out of the knowledge base; say where they're kept instead."],"auto":{"trigger":{"type":"new_file","detail":"A process note is added to the handbook inbox"},"actions":[{"type":"ai.generate","detail":"Rewrite the note as a structured article"},{"type":"doc.create","detail":"Create the page in the knowledge base"},{"type":"notify","detail":"Ask the page owner to review it"}]}},{"id":"see-your-monthly-money-position-on-one-page","t":"See your monthly money position on one page","d":"Each month, get a one-page summary of money in, money out, unpaid invoices and upcoming bills, built from your own figures.","cat":"Small Business Admin","side":"work","lvl":"Advanced","mins":45,"tools":["Google Sheets","AI assistant","Google Calendar","Gmail"],"when":"First Monday of each month","steps":[{"h":"Keep a simple money sheet","b":"In Google Sheets or Excel, keep tabs for Sales (or invoices sent), Expenses, Unpaid invoices and Upcoming bills. If you use Xero or QuickBooks, export their summary reports instead."},{"h":"Book a monthly money hour","b":"Create a recurring calendar event on the first Monday called 'Money check' with the sheet linked."},{"h":"Ask for a one-page summary","b":"Copy the month's totals and lists (no bank account numbers) into your AI assistant with this prompt.","p":"Using the figures below for [month], write a one-page money summary for my small business: 1) money in, money out and the difference, compared with last month, 2) unpaid invoices, oldest first, with how many days overdue, 3) bills due in the next 30 days and their total, 4) the 3 biggest expense categories and any that changed by more than 20%, 5) 3 questions I should look into or ask my accountant. Show your sums so I can check them. Describe the figures only; don't give financial advice. [paste figures]"},{"h":"Check and act","b":"Check the sums, chase the oldest unpaid invoices and make sure there's enough set aside for upcoming bills."},{"h":"Email it to yourself or a partner","b":"Paste the summary into an email to yourself or your business partner so you have a record of each month."}],"example":"October: in £8,420, out £6,180, difference +£2,240 (Sept +£1,310). Unpaid: Harper & Co £960 (38 days), Mill Lane Gym £420 (12 days). Bills next 30 days: £2,035 incl. van insurance £640. Materials up 34%. Ask accountant: how much to set aside for tax?","tips":["For decisions about tax, borrowing or pricing, talk to your accountant. The summary helps you ask the right questions."],"auto":{"trigger":{"type":"schedule","detail":"First Monday of each month at 9am"},"actions":[{"type":"ai.summarize","detail":"Write the monthly money summary from the sheet"},{"type":"ai.classify","detail":"Flag overdue invoices and big changes"},{"type":"email.send","detail":"Email the summary to the user"}]}},{"id":"see-where-your-food-money-really-goes-each-month","t":"See where your food money really goes each month","d":"Photograph supermarket receipts and build a simple spreadsheet showing your monthly spend by category and shop.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":25,"tools":["Phone camera","AI assistant","Google Sheets"],"when":"After each big shop, reviewed monthly","steps":[{"h":"Make a food spending sheet","b":"Create a Google Sheets or Excel file with columns: Date, Shop, Category, Item, Amount."},{"h":"Snap each receipt","b":"After a shop, take a flat, well-lit photo of the receipt before it fades or gets lost."},{"h":"Turn the receipt into rows","b":"Attach the photo to your AI assistant with this prompt, then paste the result into your sheet.","p":"Read this supermarket receipt and turn it into a table I can paste into a spreadsheet, with columns: Date, Shop, Category, Item, Amount. Use these categories only: [fresh produce, meat and fish, dairy, bakery, store cupboard, snacks and drinks, ready meals, household, baby and pets, alcohol]. Apply any discounts to the right items. Leave out card numbers and loyalty numbers. Show the receipt total at the end so I can check it matches."},{"h":"Review once a month","b":"At the end of the month, paste your rows back into the assistant and ask: 'Summarise my food spend by category, compare it with last month and suggest 3 realistic ways to cut 10%.'"}],"example":"October: 412 total. Fresh produce 88, Meat & fish 96, Snacks & drinks 71 (up 18 on Sept), Ready meals 44... Ideas: swap two ready meals a week for batch-cooked portions, buy snacks in multipacks, use the loyalty app's weekly offers.","tips":["Always check the total matches the receipt, as faded print can be misread.","Never paste bank statements with full account numbers into an AI tool."],"auto":{"trigger":{"type":"new_file","detail":"A receipt photo is added to a 'Receipts' folder"},"actions":[{"type":"ai.extract","detail":"Read items, prices and categories from the receipt"},{"type":"sheet.append","detail":"Add the rows to the food spending sheet"},{"type":"ai.summarize","detail":"On the last day of the month, summarise spend by category"}]}},{"id":"agree-a-group-trip-everyone-s-happy-with","t":"Agree a group trip everyone's happy with","d":"Collect everyone's budget, dates and wishes with a quick form, then get a fair summary and three trip options to vote on.","cat":"Travel","side":"life","lvl":"Intermediate","mins":25,"tools":["Google Forms","Google Sheets","AI assistant","WhatsApp"],"when":"At the start of planning a group trip","steps":[{"h":"Make a short form","b":"Create a Google Forms or Microsoft Forms survey asking for available dates, maximum budget, must-haves, deal-breakers and preferred trip style. Responses go into a sheet automatically."},{"h":"Share it in the group","b":"Post the form link in the group WhatsApp chat with a deadline for answers."},{"h":"Summarise the answers","b":"Copy the responses from the sheet into your AI assistant with this prompt.","p":"Here are survey answers from [number] friends planning a trip together: [paste responses]. Summarise: dates that work for everyone or most people, the budget that works for the person with the lowest budget, shared must-haves, and any deal-breakers. Then suggest 3 trip options that fit, each with destination type, rough cost per person and why it suits the group. Don't name people when listing budgets."},{"h":"Vote on it","b":"Post the three options in the chat and use WhatsApp's poll feature to decide."}],"example":"Dates: 12-15 June works for all 6. Budget to plan around: 350 per person. Shared must-haves: somewhere warm, a pool, good food. Deal-breaker: no early flights. Options: 1) Villa in the Algarve (approx 330pp). 2) Lake Garda apartment (approx 340pp). 3) UK coast cottage with hot tub (approx 210pp).","tips":["Keeping budgets anonymous makes it easier for people to be honest about what they can afford."],"auto":{"trigger":{"type":"form_submitted","detail":"A friend submits the trip survey"},"actions":[{"type":"sheet.append","detail":"Add the response to the trip sheet"},{"type":"ai.summarize","detail":"Once everyone has answered, summarise and suggest 3 options"},{"type":"message.send","detail":"Post the options to the group chat"}]}},{"id":"stay-on-top-of-repeat-prescriptions-and-check-ups","t":"Stay on top of repeat prescriptions and check-ups","d":"Gather health admin emails in one label, track repeat prescriptions in a sheet and get reminders before you run out.","cat":"Health & Fitness","side":"life","lvl":"Advanced","mins":40,"tools":["Gmail","Google Sheets","Google Calendar","AI assistant"],"when":"Set up once, runs every month","steps":[{"h":"Label health admin emails","b":"In Gmail's settings, under Filters, create filters for emails from your GP surgery, pharmacy, dentist and optician that apply a 'Health admin' label. Outlook users can do this with rules."},{"h":"Make a prescription tracker","b":"Create a Google Sheets or Excel file with columns: Medicine (or a nickname), Quantity supplied, Date collected, Days it lasts, Reorder by, Notes."},{"h":"Work out reorder dates","b":"Paste the rows into your AI assistant with this prompt and copy the dates back into the sheet. You can also use a simple formula: date collected plus days it lasts, minus 7.","p":"Here are my repeat prescriptions: [paste rows using nicknames]. For each, work out the date I'll run out and a 'reorder by' date [7] days before, allowing for weekends. Then list my upcoming routine check-ups from these notes: [e.g. dentist every 6 months, last visit 3 May; eye test every 2 years, last March 2025]. Output one table sorted by date. Don't comment on the medicines themselves."},{"h":"Add calendar reminders","b":"Create a Google Calendar or Outlook Calendar event for each reorder date and check-up, set to repeat where it makes sense."},{"h":"Review monthly","b":"Once a month, check the 'Health admin' label for anything new and update the sheet."}],"example":"Inhaler (blue): collected 1 Nov, lasts 30 days, reorder by 24 Nov. Tablets (morning): collected 5 Nov, 56 days, reorder by 23 Dec. Dentist check-up due 3 Nov - overdue, book now. Eye test due March 2027.","tips":["Use nicknames for medicines in AI tools if you'd rather not share them, and keep the sheet private.","Follow your GP or pharmacist's advice on how early to reorder; some surgeries need several working days."],"auto":{"trigger":{"type":"new_email","detail":"An email arrives in the 'Health admin' label"},"actions":[{"type":"ai.extract","detail":"Pull any appointment, collection or reminder dates"},{"type":"sheet.update","detail":"Update the prescription and check-up tracker"},{"type":"calendar.create","detail":"Add reorder and appointment reminders"}]}},{"id":"get-a-weekly-money-check-in-without-opening-a-spreadsheet","t":"Get a weekly money check-in without opening a spreadsheet","d":"Every Sunday a short note arrives showing how your spending compares with your budget and what's coming up next week.","cat":"Money","side":"life","lvl":"Advanced","mins":45,"tools":["AI assistant","Google Sheets","Google Calendar"],"when":"Every Sunday evening","steps":[{"h":"Keep a spending sheet","b":"Use a Google Sheet with tabs for Budget (category and monthly limit) and Spending (date, description, amount, category). The receipt or bank-export recipes can fill it."},{"h":"Put bills in your calendar","b":"Make sure upcoming bills and paydays are in Google Calendar as events, so they can be included in the check-in."},{"h":"Write your check-in prompt","b":"Save this prompt in your notes so you can reuse it each week.","p":"Here is my budget and this month's spending so far, plus next week's calendar of bills and paydays. Write a short weekly money check-in (under 150 words) with: 1) spending so far vs budget for each category, marked on track, close or over; 2) how much flexible money is left for the rest of the month and per week; 3) bills and paydays coming next week; 4) one practical, friendly suggestion. No financial advice, no lecturing. Budget: [paste] Spending: [paste] Next week: [paste]"},{"h":"Schedule it","b":"If your AI assistant offers scheduled tasks and can read your connected Google apps, set this to run every Sunday. Otherwise set a Sunday reminder and paste the latest figures in yourself."},{"h":"Adjust as you go","b":"If the check-in keeps flagging the same category, change your budget for it so it reflects real life."}],"example":"Week 2 check-in: Groceries £180 of £280 (close). Eating out £95 of £100 (nearly there). Transport £60 of £140 (on track). Flexible left: £210, about £70 a week. Next week: phone bill £25 Tue, payday Fri. Tip: plan two batch-cook nights to stay under on groceries.","tips":["Only connect your AI assistant to your Google account if you're comfortable with it reading those files, and never store account numbers in the sheet.","Keep the tone kind. You're more likely to keep reading a note that doesn't scold you."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 6pm"},"actions":[{"type":"web.fetch","detail":"Read the budget and spending sheet"},{"type":"ai.summarize","detail":"Compare spending with budget and list next week's bills"},{"type":"notify","detail":"Send the weekly check-in"}]}},{"id":"get-a-spaced-review-reminder-for-what-you-learned","t":"Get a spaced review reminder for what you learned","d":"Topics you study come back to you as short review prompts after one day, one week and one month, so they stick.","cat":"Learning","side":"life","lvl":"Advanced","mins":40,"tools":["Google Sheets","Google Calendar","AI assistant"],"when":"After every study session","steps":[{"h":"Set up a learning log","b":"Create a Google Sheet with columns: Date learned, Topic, Key points, Review 1 (date + 1 day), Review 2 (date + 7 days), Review 3 (date + 30 days). Use simple date formulas like adding 1, 7 and 30 to the first date."},{"h":"Log each session","b":"After studying, add one row with the topic and three to five key points."},{"h":"Prepare a review prompt","b":"Save this prompt in your notes so you can reuse it whenever a review is due.","p":"I'm reviewing topics I learned earlier. For each topic below, ask me 3 quick recall questions based on the key points, one at a time, without showing the answers first. After I answer, tell me what I missed. At the end, rate each topic as Solid, Shaky or Forgotten and tell me which to review again soon. [paste the rows due today: topic and key points]"},{"h":"Get reminded automatically","b":"Each Sunday, add calendar reminders for that week's review dates from the sheet. If your AI assistant offers scheduled tasks and can read your sheet, schedule a daily check for rows due today instead."},{"h":"Mark your results","b":"Add a Result column and note Solid, Shaky or Forgotten. Move Forgotten topics back to the start with a new date."}],"example":"Due today: Photosynthesis (Review 2), French past tense (Review 1). Q1: What two things does a plant need besides light? Result: Photosynthesis - Solid. French past tense - Shaky, review again in 3 days.","tips":["Recalling without looking is the bit that does the work. Resist peeking.","Keep key points short. If a row needs a paragraph, split it into two topics."],"auto":{"trigger":{"type":"schedule","detail":"Every morning"},"actions":[{"type":"web.fetch","detail":"Find rows in the learning log due for review today"},{"type":"ai.generate","detail":"Write recall questions for each due topic"},{"type":"notify","detail":"Send the review questions"},{"type":"sheet.update","detail":"Record the result for each topic"}]}},{"id":"get-fresh-job-leads-delivered-every-week","t":"Get fresh job leads delivered every week","d":"A scheduled weekly AI search for new roles matching your criteria, delivered as a short list you can check over coffee.","cat":"Careers","side":"life","lvl":"Advanced","mins":30,"tools":["AI assistant","Google Sheets","Gmail"],"when":"Every Monday morning","steps":[{"h":"Write down your search","b":"Note your target job titles, location or remote preference, salary floor, sectors to include and any to avoid."},{"h":"Set up a scheduled search","b":"If your plan includes scheduled tasks in ChatGPT or scheduled actions in Gemini, create a weekly task using this prompt. If not, save the prompt and run it yourself each Monday in an assistant that can search the web.","p":"Search the web for job vacancies posted in the last 7 days matching: titles [list], location [place or remote], salary at least [amount], sectors [list]. Exclude [deal-breakers]. Only include listings from employer websites or well-known job boards. Return up to 10 results as a table: Job title, Employer, Location, Salary if shown, Closing date, Link. Then highlight the 3 best fits for someone with this background: [one-line summary]. If you're not sure a listing is still open, say so."},{"h":"Log the good ones","b":"Copy any jobs you want to pursue into your job tracker sheet with the link and closing date."},{"h":"Check before applying","b":"Open each link to confirm the role is still open and the details are right, since AI searches can return old or incorrect listings."}],"example":"Week of 18 Nov: 7 matches. Top 3: Volunteer Programme Lead, City Food Network, hybrid, £30k, closes 2 Dec. Community Officer, Northgate Council, £28k, closes 29 Nov. Events Coordinator, Hillside Arts, £27k, closing date not shown.","tips":["Be wary of listings that ask for payment or bank details early. Genuine employers don't.","Tweak the search terms every few weeks based on what's coming back."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8am"},"actions":[{"type":"web.fetch","detail":"Search for new matching job listings"},{"type":"ai.classify","detail":"Rank listings against the user's criteria"},{"type":"email.send","detail":"Send the weekly job leads to the user"},{"type":"sheet.append","detail":"Add shortlisted roles to the job tracker"}]}},{"id":"do-a-15-minute-weekly-review-and-plan","t":"Do a 15-minute weekly review and plan","d":"Every Friday you get a summary of what you got done, what's still open and a suggested plan for next week, built from your calendar and tasks.","cat":"Personal Assistant","side":"life","lvl":"Advanced","mins":40,"tools":["AI assistant","Google Calendar","Notion"],"when":"Every Friday afternoon","steps":[{"h":"Keep tasks in one place","b":"Use one task list, such as a Notion page, Google Tasks or your Reminders app, and mark things done as you go."},{"h":"Write your weekly review prompt","b":"Save this prompt in your notes.","p":"Run my weekly review. Here's this week's calendar, my task list with done and not done items, and my goals for this month: [paste all three, or read them from my connected apps]. Give me: 1) what I got done this week in 5 bullets, 2) open tasks, sorted into carry over, delegate or drop, 3) next week's calendar with any busy days or clashes flagged, 4) a suggested plan of no more than 3 priorities for next week, with the best time slots to do them, and 5) one thing to celebrate. Keep it under 250 words and kind."},{"h":"Schedule it","b":"If your plan includes scheduled tasks in your AI assistant and it can read your calendar, schedule this for Fridays at 3pm. Otherwise add a recurring Friday calendar event and paste in your calendar and tasks yourself."},{"h":"Block time for priorities","b":"Add the three priorities to next week's calendar as time blocks so they actually happen."},{"h":"Adjust your goals monthly","b":"At the end of each month, update the goals in the prompt."}],"example":"Done: booked boiler service, finished tax return, two gym sessions. Carry over: sort Gran's birthday present. Drop: re-paint shed (not this month). Next week: Wednesday is packed, avoid adding anything. Priorities: buy present (Mon lunch), plan half-term (Tue evening), call bank (Thu 9am). Celebrate: tax return done!","tips":["Keep priorities to three. More than that and none get done.","Only connect the apps you're comfortable with your AI assistant reading."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3pm"},"actions":[{"type":"web.fetch","detail":"Read this week's calendar and task list"},{"type":"ai.summarize","detail":"Summarise what got done and what's open"},{"type":"ai.generate","detail":"Suggest three priorities for next week"},{"type":"calendar.create","detail":"Block time for each priority"}]}},{"id":"answer-customer-enquiries-faster-with-your-own-faq","t":"Answer customer enquiries faster with your own FAQ","d":"Build an AI helper that knows your prices, policies and tone, so drafting a reply to any enquiry takes seconds.","cat":"Email & Inbox","side":"work","lvl":"Intermediate","mins":40,"tools":["AI assistant","Google Docs","Gmail"],"when":"Whenever a customer emails a question","steps":[{"h":"Write a one-page answer sheet","b":"In a Google Doc or Word file, list your prices, opening hours, delivery or booking rules, refund policy and the ten questions you're asked most, with your usual answers."},{"h":"Create a dedicated helper","b":"Make a ChatGPT custom GPT, a Claude Project or a Gemini Gem (whichever you use), upload your answer sheet and paste these instructions.","p":"You help me reply to customer emails for [business name], a [type of business]. Only use facts from the attached answer sheet. When I paste a customer email: 1) Write a friendly reply under 120 words in British English, signed [your name]. 2) If the answer isn't in the sheet, say 'NOT IN SHEET' and suggest what I should find out, rather than guessing. 3) Below the reply, list any upsell or next step that would genuinely help the customer."},{"h":"Paste enquiries in as they arrive","b":"Copy the customer's question (leave out their address or card details) into your helper, check the draft and send it from your email."},{"h":"Keep the sheet up to date","b":"Whenever you answer something new, add it to the answer sheet and re-upload it so the helper learns it."}],"example":"Customer: Do you deliver to Hove on Saturdays? Draft: Hi Chris, yes, we deliver to Hove on Saturdays between 9am and 1pm. Orders need to be in by 6pm Thursday, and delivery is free over £40. Would you like me to reserve a slot for you? Best, Jen","tips":["Never paste payment details or full addresses; the helper doesn't need them to draft a reply.","Check every reply before sending, especially anything about refunds or prices."],"auto":{"trigger":{"type":"new_email","detail":"A customer enquiry arrives"},"actions":[{"type":"ai.classify","detail":"Check the question is covered by the answer sheet"},{"type":"ai.generate","detail":"Draft a reply using only facts from the answer sheet"},{"type":"email.draft","detail":"Save the reply as a draft for review"}]}},{"id":"get-your-day-s-meetings-and-prep-notes-every-morning","t":"Get your day's meetings and prep notes every morning","d":"Wake up to an email listing today's meetings, then turn it into a short plan with prep tasks and gaps for focused work.","cat":"Meetings & Calendar","side":"work","lvl":"Advanced","mins":30,"tools":["Google Calendar","Gmail","AI assistant","Outlook Calendar"],"when":"Every weekday morning","steps":[{"h":"Turn on your daily agenda email","b":"In Google Calendar's settings, find the notification options for your calendar and switch on the daily agenda email. Outlook users can connect their AI assistant to the calendar or copy the day view instead."},{"h":"Connect your assistant if you can","b":"Gemini with Google Workspace, Copilot in Outlook, or ChatGPT and Claude with a Google Calendar connector can read your calendar directly, if your plan includes it."},{"h":"Run your morning prompt","b":"Paste the agenda email (or ask your connected assistant) with this prompt.","p":"Here's my calendar for today: [paste agenda or 'read my calendar for today']. My top priority today is [priority]. Give me: 1) A timeline of the day with meetings and free gaps. 2) For each meeting, one line on what to prepare and how long it will take. 3) The best gap for focused work on my priority. 4) Any clashes, back-to-backs with no break, or meetings missing a video link or location. Keep it under 200 words."},{"h":"Make it a habit","b":"Create a recurring 10-minute calendar event at the start of each day called 'Plan today', with the prompt pasted in its description."}],"example":"9:30 Team stand-up (prep: nothing). 11:00 Supplier call (prep: check last invoice, 5 min). Gap 12:00-14:00: best time for the funding report. 14:00 and 15:00 back-to-back: leave 5 min early. 16:00 Interview: no video link yet, check with HR.","tips":["If your plan doesn't include connectors, the daily agenda email plus copy and paste works just as well."],"auto":{"trigger":{"type":"schedule","detail":"Weekdays at 7:30am"},"actions":[{"type":"web.fetch","detail":"Read today's calendar events"},{"type":"ai.generate","detail":"Build a day plan with prep tasks, focus gaps and clashes"},{"type":"notify","detail":"Send the plan to the user"}]}},{"id":"never-miss-a-renewal-or-deadline-again","t":"Never miss a renewal or deadline again","d":"Keep one tracker of insurance, MOT, passports, subscriptions and contracts, with calendar reminders set well before each date.","cat":"Planning & Productivity","side":"work","lvl":"Intermediate","mins":40,"tools":["Google Sheets","AI assistant","Google Calendar","Gmail"],"when":"Set up once, update whenever something renews","steps":[{"h":"Find your renewal dates","b":"Search your email for words like 'renewal', 'policy', 'subscription' and 'expires', and check documents such as your passport and driving licence."},{"h":"Turn them into a tidy list","b":"Paste the details (leaving out policy and account numbers) into your AI assistant.","p":"Organise these renewals and deadlines into a table: [paste details]. Columns: item, provider, renewal or expiry date, cost and how often it's paid, auto-renews (yes/no/unknown), how far ahead I should be reminded (e.g. 4 weeks for insurance to shop around, 10 weeks for a passport), and the action to take. Sort by date. Flag anything that looks like a duplicate or forgotten subscription."},{"h":"Save it in a spreadsheet","b":"Paste the table into Google Sheets or Excel and keep it somewhere safe and private."},{"h":"Add calendar reminders","b":"For each row, create a calendar event on the reminder date (yearly repeating where it makes sense) with the action in the description."}],"example":"Car insurance | Brightway | 14 Jan | £412/yr | auto-renews | remind 16 Dec | compare quotes. MOT | - | 3 Mar | £54.85 | no | remind 10 Feb | book garage. Streaming | ViewBox | 22nd monthly | £10.99 | yes | flag: unused?","tips":["Never paste full policy numbers, account numbers or passport numbers into an AI assistant; you only need the names and dates.","This is for staying organised; for advice on which insurance or contract to choose, speak to a qualified adviser."],"auto":{"trigger":{"type":"new_email","detail":"An email mentioning renewal, expiry or subscription arrives"},"actions":[{"type":"ai.extract","detail":"Pull the item, provider, date and cost"},{"type":"sheet.append","detail":"Add or update the row in the renewals tracker"},{"type":"calendar.create","detail":"Set a reminder ahead of the date"}]}},{"id":"find-out-how-customers-felt-after-you-helped-them","t":"Find out how customers felt after you helped them","d":"A two-question satisfaction survey sent after each solved case, low scores highlighted automatically, and a monthly AI summary of what people say.","cat":"Customer Support","side":"work","lvl":"Advanced","mins":40,"tools":["Google Forms","Google Sheets","Gmail","AI assistant"],"when":"After every solved case, with a monthly review","steps":[{"h":"Make a two-question form","b":"In Google Forms, ask 'How happy are you with the help you got?' on a 1 to 5 scale and 'What could we do better?' as a paragraph. Make the second question optional."},{"h":"Link it to a sheet and highlight low scores","b":"Link responses to a Google Sheet. Use Format, then Conditional formatting, to turn rows red when the score is 2 or less, and turn on form email notifications so you hear about them straight away."},{"h":"Add the link to a closing template","b":"Write a short 'glad we could help' Gmail template with the form link and use it whenever you close a case."},{"h":"Review every month with AI","b":"Set a monthly calendar reminder, then paste that month's responses (no names) into your AI assistant with this prompt.","p":"Here are this month's customer satisfaction responses (score 1 to 5, comment): [paste]. 1) Give the average score and how many responses. 2) Group comments into themes with counts. 3) Quote the 3 most useful comments word-for-word. 4) Suggest 2 practical changes based on low scores. 5) Write a one-paragraph summary I can share with my team. Don't infer anything that isn't in the comments."},{"h":"Close the loop on low scores","b":"Contact anyone who scored 1 or 2 within a couple of days, if they left contact details, to put things right."}],"example":"October: average 4.4 from 38 responses. Themes: quick replies (14), friendly staff (9), had to repeat information (6), slow refunds (4). Change ideas: add order number to form; confirm refund date in every refund email. Low scores to follow up: 3.","tips":["Ask for contact details only if they want a follow-up, and say so on the form.","Microsoft Forms and Excel can be used the same way, including email alerts for new responses."],"auto":{"trigger":{"type":"form_submitted","detail":"A customer submits the satisfaction survey"},"actions":[{"type":"sheet.append","detail":"Add the score and comment to the results sheet"},{"type":"notify","detail":"Alert the owner immediately for scores of 2 or less"},{"type":"ai.summarize","detail":"Each month, summarise scores and themes into a short report"}]}},{"id":"turn-bookings-into-warm-well-prepared-sales-calls","t":"Turn bookings into warm, well-prepared sales calls","d":"Prospects book through Calendly, answer a few smart questions, get reminders and a thank-you, while you get a ready brief before each call.","cat":"Sales & Leads","side":"work","lvl":"Advanced","mins":50,"tools":["Calendly","Google Calendar","Gmail","AI assistant"],"when":"Every time someone books a sales call","steps":[{"h":"Write booking questions that qualify","b":"Ask your AI assistant for questions to add to your Calendly event.","p":"I offer [service] to [ideal client] at around [price]. Write 4 short booking questions for a free 20-minute discovery call that help me prepare and understand fit, without putting people off. Include one about their main goal, one about timing, and one about budget phrased gently with ranges. Then write: a reminder email to send 24 hours before (under 80 words) and a thank-you email to send 1 hour after the call (under 100 words) with [booking link for next step] and [resource]. British English, warm."},{"h":"Set up the Calendly event","b":"Connect Calendly to your Google Calendar, then add the questions to the event's booking form so answers show in the calendar invite."},{"h":"Turn on reminders and follow-ups","b":"In Calendly's Workflows, if your plan includes them, add the reminder email before the event and the thank-you email after it. On a free plan, save them as Gmail templates and set yourself calendar reminders."},{"h":"Prepare in two minutes","b":"Before each call, copy the booking answers from the calendar event into your AI assistant and ask for 3 tailored questions and the likely best package for them."},{"h":"Review once a month","b":"Look at which booking answers led to sales and adjust the questions to screen better."}],"example":"Booking answers: Goal - 'more weekday bookings'; Timing - 'next 2 months'; Budget - '£500 to £1,000'. AI prep: Ask what days are quietest now; ask what they tried before; likely fit: Starter package (£750). Reminder sent 24h before; thank-you sent 1h after with proposal link.","tips":["Keep booking forms short: four questions is plenty or people drop off.","Tell people in the form that their answers help you prepare and are kept private."],"auto":{"trigger":{"type":"calendar_event","detail":"A new Calendly booking is added to the calendar"},"actions":[{"type":"ai.extract","detail":"Pull goal, timing and budget from the booking answers"},{"type":"ai.generate","detail":"Write a call brief with tailored questions"},{"type":"email.send","detail":"Send the reminder and thank-you emails at the set times"},{"type":"sheet.append","detail":"Log the booking in the lead tracker"}]}},{"id":"run-onboarding-on-autopilot-from-one-form","t":"Run onboarding on autopilot from one form","d":"A new-starter form feeds a tracking sheet, sends you an alert, and kicks off scheduled welcome emails and calendar check-ins for every hire.","cat":"HR & Hiring","side":"work","lvl":"Advanced","mins":60,"tools":["Google Forms","Google Sheets","Gmail","Google Calendar"],"when":"Every time someone accepts a job offer","steps":[{"h":"Create the new-starter form","b":"Make a Google Form for the manager to fill in: starter's name, role, start date, manager, buddy, equipment needed. Keep personal details like bank info out of it; collect those through your payroll process."},{"h":"Track it in a sheet","b":"Link the form to a Google Sheet and turn on email notifications for new responses. Add checklist columns (Contract sent, Equipment ready, Logins set up) with tick boxes, and use conditional formatting to turn a row red if the start date is close and anything is unticked."},{"h":"Write the welcome emails with AI","b":"Ask your AI assistant for a set of emails to schedule.","p":"Write 3 short emails for new starters at [business]: 1) sent 1 week before starting: warm welcome, first-day time, address, who to ask for, what to bring, dress code, 2) sent the evening before: a friendly 'see you tomorrow' with the plan for day one, 3) sent at the end of week one from the manager: thanks, what's next, and an invitation to share feedback. Each under 120 words, British English, use [brackets] for details. Then list 4 calendar check-ins to book (with timing and a 3-bullet agenda each) for the first 3 months."},{"h":"Schedule emails and check-ins","b":"When a form arrives, fill in the email templates and use Gmail's Schedule send for each one. Create the calendar check-ins with the starter and manager straight away."},{"h":"Review after each hire","b":"Ask each new starter what was missing, and update the form, emails and checklist."}],"example":"New row: Priya S. | Junior Designer | Starts 7 April | Manager: Leon | Buddy: Kat. Contract sent ✓ Equipment ready ✗ (row red: 5 days to go). Scheduled: welcome email 31 March 9am, see-you-tomorrow 6 April 6pm. Check-ins booked: week 1, week 4, week 8, week 12.","tips":["Keep the sheet's sharing limited to people who need it, since it holds staff details.","Microsoft Forms, Excel and Outlook can do the same, including scheduled sending in Outlook."],"auto":{"trigger":{"type":"form_submitted","detail":"A manager submits the new-starter form"},"actions":[{"type":"sheet.append","detail":"Add the starter to the onboarding tracker"},{"type":"email.send","detail":"Schedule the welcome emails at set times before and after the start date"},{"type":"calendar.create","detail":"Book the first-week, month-one and month-three check-ins"},{"type":"notify","detail":"Alert the manager about unticked tasks close to the start date"}]}},{"id":"get-a-weekly-list-of-trending-topics-in-your-niche","t":"Get a weekly list of trending topics in your niche","d":"Every Monday you get five timely post ideas based on what people are talking about in your field, logged in a sheet for planning.","cat":"Marketing & Social","side":"work","lvl":"Advanced","mins":30,"tools":["AI assistant","Google Sheets","Google Calendar"],"when":"Every Monday morning","steps":[{"h":"Set up a scheduled task","b":"In ChatGPT, if your plan includes scheduled tasks, ask it to run a task every Monday at 8am with the prompt below. It will send you the results as a notification or email.","p":"Search the web for what's being discussed this week in [your niche] that matters to [audience] in [country]. Look at news, Google Trends topics and popular questions. Give me 5 post ideas as a table: Topic, Why it's timely (one line, with the source link), Post angle for [business type], Best platform, Suggested first line. Skip anything older than 10 days, and skip sensitive tragedies."},{"h":"Have a free fallback ready","b":"No scheduled tasks? Create a recurring Monday event in Google Calendar called 'Trend check' with the prompt pasted in the description, and run it yourself in any AI assistant with web search."},{"h":"Log ideas in a sheet","b":"Make a Google Sheet called Trend ideas with the same columns plus Date and Used. Paste each week's table in so you build a bank of ideas over time."},{"h":"Check before you post","b":"Click the source link for any idea you use. Trends move fast and AI can misread dates."}],"example":"Topic: New rules on garden water butts | Timely: council grants announced Tuesday (link) | Angle: 'How to claim yours in 3 steps' | Instagram carousel | First line: 'Free water butt, anyone?'","tips":["Use Google Trends' Explore page to compare two topics quickly before you commit to one."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8am"},"actions":[{"type":"web.fetch","detail":"Search news and trend sources for the niche"},{"type":"ai.generate","detail":"Write five timely post ideas with sources"},{"type":"sheet.append","detail":"Log the ideas in the Trend ideas sheet"},{"type":"notify","detail":"Send the week's ideas to the user"}]}},{"id":"keep-track-of-websites-and-mentions-without-checking-them","t":"Keep track of websites and mentions without checking them","d":"New articles and mentions on your topics land in one Gmail label, and each Friday you get a short summary of what's worth reading.","cat":"Content & Writing","side":"work","lvl":"Advanced","mins":30,"tools":["Gmail","Google Calendar","AI assistant"],"when":"Set up once, review every Friday","steps":[{"h":"Create Google Alerts","b":"Go to Google Alerts and add alerts for your business name, competitors, key topics and sites you follow (for example 'site:example.com' plus a topic). Set delivery to once a day to your Gmail."},{"h":"Filter them into a label","b":"In Gmail's settings, under Filters, create a filter for emails from Google Alerts that skips the inbox and applies a label called Reading."},{"h":"Book a weekly review","b":"Add a recurring Friday 30-minute event in Google Calendar called 'Reading round-up'. Paste the prompt below into the event description."},{"h":"Summarise the week","b":"On Friday, open the Reading label. If your plan includes Gemini in Gmail, ask it to summarise those emails; otherwise copy the alert emails into your AI assistant with this prompt.","p":"Here are this week's Google Alerts about [topics]: [paste]. Remove duplicates and anything irrelevant to [your work]. Group the rest by topic. For each group give a 2-sentence summary and the 1-2 links most worth reading. End with 3 ideas for posts or articles I could write in response. Keep it under 300 words."},{"h":"Clear the label","b":"Archive or delete the week's alerts once you've read the summary so the label stays manageable."}],"example":"Competitors: Two local cafes announced loyalty apps (links). Your name: Mentioned in a 'best brunch in Bath' list. Topic - plastic-free packaging: new council scheme. Ideas: 'Why we're not launching an app', 'Our plastic-free year so far'.","tips":["Use quote marks in alerts for exact phrases, otherwise you'll get lots of unrelated results."],"auto":{"trigger":{"type":"new_email","detail":"New Google Alert email arrives"},"actions":[{"type":"email.label","detail":"Label it Reading and skip the inbox"},{"type":"ai.summarize","detail":"On Fridays, summarise the week's alerts by topic"},{"type":"notify","detail":"Send the round-up and writing ideas to the user"}]}},{"id":"run-a-weekly-video-production-line-for-your-channel","t":"Run a weekly video production line for your channel","d":"A repeatable weekly system that takes each video from idea to scheduled upload, with AI help, shared folders and automatic reminders.","cat":"Video, Image & Voice","side":"work","lvl":"Advanced","mins":60,"tools":["Trello","Google Drive","YouTube","AI assistant"],"when":"Set up once, run every week","steps":[{"h":"Build a production board","b":"In Trello, create lists: Ideas, Scripted, Filmed, Edited, Scheduled, Published. Each video is a card with its Google Drive folder link attached."},{"h":"Set rules to keep it moving","b":"Use Trello's built-in automation to add due dates and checklists when cards move, for example 'when moved to Filmed, add checklist: back up footage, rough cut, captions, thumbnail'."},{"h":"Organise footage in Drive","b":"Create one Google Drive folder per video with Raw, Edit and Thumbnail subfolders. Upload footage from your phone with the Drive app straight after filming."},{"h":"Use AI at each stage","b":"Script from the idea, then once the edit is done, use the transcript from YouTube Studio to create the upload details.","p":"Here's the transcript of my finished video: [paste]. Channel: [topic] for [audience]. Give me: 3 titles under 60 characters, a description with chapters from 0:00 using the real times, 10 tags, 3 thumbnail text options (max 4 words), a pinned comment that asks viewers a question, and a 2-line Community post to promote it."},{"h":"Schedule and close the loop","b":"Schedule the video in YouTube Studio, move the card to Scheduled, and add a short weekly review in your calendar to pick next week's ideas."}],"example":"Week 46: 'Fixing a dripping tap' moved Edited -> Scheduled (Sat 10am). Checklist done: captions, thumbnail, end screen, playlist. Next up: 2 cards in Scripted, 4 in Ideas. Drive: /Videos/046-dripping-tap/Raw (14 clips).","tips":["Back up raw footage before deleting it from your phone; Drive's free storage fills quickly with video, so check your plan.","Get permission from anyone who appears or speaks in your videos, and only use music you have the rights to."],"auto":{"trigger":{"type":"new_file","detail":"New footage uploaded to a video folder"},"actions":[{"type":"notify","detail":"Move the card to Filmed and remind the editor"},{"type":"ai.generate","detail":"Write titles, description, chapters and tags from the transcript"},{"type":"doc.create","detail":"Save upload details in the video folder"},{"type":"calendar.create","detail":"Add the scheduled publish time to the calendar"}]}},{"id":"read-all-your-newsletters-in-one-weekly-summary","t":"Read all your newsletters in one weekly summary","d":"Route newsletters into one folder automatically, then get a weekly AI digest of the best ideas and links, saved to Notion for later.","cat":"Research & News","side":"work","lvl":"Advanced","mins":30,"tools":["Gmail","AI assistant","Notion","Google Calendar"],"when":"Every Sunday morning","steps":[{"h":"Filter newsletters out of your inbox","b":"In Gmail's settings, under Filters, create a filter for each newsletter sender, apply the label 'Reading' and choose 'Skip the inbox'. In Outlook, use a rule that moves them to a 'Reading' folder."},{"h":"Set a weekly reading slot","b":"Create a recurring Sunday event in Google Calendar called 'Newsletter digest' and link your Notion page in it."},{"h":"Summarise the week's issues","b":"If your plan includes Gemini in Gmail, ask it to summarise the 'Reading' label. Otherwise copy the newsletters into your AI assistant with this prompt.","p":"Here are this week's newsletters about [topics]. Create a digest: 1) the 5 most useful ideas, each with the newsletter it came from and the original link, 2) any trends mentioned by more than one newsletter, 3) any events, deadlines or offers with dates, 4) one line on each remaining issue so I know whether to read it in full. Label anything that looks sponsored. Don't add facts that aren't in the newsletters. [paste newsletters]"},{"h":"Save to Notion","b":"Paste the digest into a Notion database called 'Weekly digests' with the date as the title, so you can search past weeks."},{"h":"Clear the folder","b":"Archive the week's newsletters and unsubscribe from any that never make it into your top five."}],"example":"Week of 3 Nov. Top ideas: 1) 'Price for the job, not the hour' (Trade Talk, link). 2) Short video case studies outperform blog posts for local services (Marketing Minute, link). Trend: three newsletters mention rising insurance costs. Deadline: small business awards close 30 Nov.","tips":["Check any statistic before you repeat it; newsletters often quote figures second-hand."],"auto":{"trigger":{"type":"schedule","detail":"Sundays at 9am"},"actions":[{"type":"email.label","detail":"Collect the week's emails labelled Reading"},{"type":"ai.summarize","detail":"Pick top ideas, trends and deadlines with links"},{"type":"doc.create","detail":"Save the digest to the Notion database"},{"type":"notify","detail":"Tell the user the digest is ready"}]}},{"id":"make-paper-documents-searchable-and-never-miss-dates","t":"Make paper documents searchable and never miss dates","d":"Scan letters with your phone, store them in one Drive folder, and log key dates in a sheet with calendar reminders.","cat":"Documents & Data","side":"work","lvl":"Advanced","mins":45,"tools":["Phone camera","Google Drive","Google Sheets","Google Calendar"],"when":"Whenever important post arrives, plus a monthly review","steps":[{"h":"Scan with your phone","b":"Use the scan option in the Google Drive app on Android or the Notes app on iPhone to turn letters into clear PDFs. Save them to a Drive folder called 'Paperwork inbox'."},{"h":"Pull out the key details","b":"Upload each new scan to your AI assistant with this prompt.","p":"From the attached letter, extract: sender organisation, date of the letter, what it's about (one sentence), any action I need to take, any deadline or renewal date, any amount of money mentioned, and a reference number (show only the last 4 characters). Output as one row: Date | Sender | Subject | Action | Deadline | Amount | Ref (last 4). Write 'none' where something isn't stated."},{"h":"Log it in a sheet","b":"Paste the row into a Google Sheet called 'Paperwork log', then move the scan into the right folder with a clear name."},{"h":"Add deadlines to your calendar","b":"For every deadline, create a Google Calendar event a week before, with the scan's Drive link in the description."},{"h":"Review monthly","b":"Set a recurring monthly event to sort the Paperwork log by deadline and check nothing is overdue."}],"example":"12/11/2026 | Northshire Council | Council tax bill for 2027 | Set up direct debit | 01/04/2027 | £1,842 | ...7731. Calendar: 'Council tax direct debit - due 1 Apr' on 25 March.","tips":["Black out or crop full account numbers and dates of birth before uploading scans to an AI assistant."],"auto":{"trigger":{"type":"new_file","detail":"A scan is saved to the Paperwork inbox folder"},"actions":[{"type":"ai.extract","detail":"Pull out sender, action, deadline and amount"},{"type":"sheet.append","detail":"Add a row to the Paperwork log"},{"type":"calendar.create","detail":"Create a reminder a week before any deadline"},{"type":"file.save","detail":"Rename and file the scan"}]}},{"id":"clear-your-weekly-admin-in-one-focused-hour","t":"Clear your weekly admin in one focused hour","d":"Sort invoices, receipts and supplier emails into folders automatically, then get a Friday list of what to pay, chase, file and reply to.","cat":"Small Business Admin","side":"work","lvl":"Advanced","mins":50,"tools":["Outlook","Outlook Calendar","AI assistant","Excel"],"when":"Every Friday afternoon","steps":[{"h":"Create admin folders","b":"In Outlook, create folders called 'To pay', 'Receipts', 'Suppliers' and 'Customer admin'. Gmail users can do the same with labels."},{"h":"Add rules to sort mail","b":"Use Outlook's Rules (found in its settings) to move emails into each folder by sender or by words like 'invoice', 'receipt' or 'order confirmation'. Start with your ten most frequent senders."},{"h":"Book a weekly admin hour","b":"Create a recurring Friday event in Outlook Calendar called 'Admin hour' and treat it like a client meeting."},{"h":"Get a to-do list from the week","b":"In your admin hour, copy the key details from each folder into your AI assistant (or use Copilot in Outlook if your plan includes it) with this prompt.","p":"Here are this week's admin emails, grouped by folder. Turn them into a prioritised to-do list under four headings: Pay (with amount and due date), Chase (who owes me and how much), File (receipts or documents to save and where), Reply (who and what about, with a one-line suggested reply). Put anything due in the next 7 days at the top. Leave out anything already handled. Don't include bank details. [paste emails or summaries]"},{"h":"Work the list and log it","b":"Work through the list, then update your invoices or expenses spreadsheet in Excel before closing the hour."}],"example":"PAY: Greenway Packaging £418.80 due 24 Nov; phone bill £42 due 28 Nov. CHASE: Harper & Co £960 (38 days). FILE: 6 receipts to Receipts > November. REPLY: Mill Lane Gym asking for a copy invoice - 'Attached, thanks for letting me know.'","tips":["Check your rules' folders for a couple of weeks so nothing important is filed away unnoticed."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 2pm"},"actions":[{"type":"email.label","detail":"Gather the week's emails from each admin folder"},{"type":"ai.classify","detail":"Sort items into pay, chase, file and reply"},{"type":"list.add","detail":"Create a prioritised admin to-do list"},{"type":"notify","detail":"Remind the user their admin hour is starting"}]}},{"id":"move-house-without-forgetting-who-to-tell","t":"Move house without forgetting who to tell","d":"Get a week-by-week moving plan and a change-of-address list on a Trello board you can share with whoever's helping.","cat":"Food & Home","side":"life","lvl":"Intermediate","mins":30,"tools":["AI assistant","Trello"],"when":"As soon as you have a moving date","steps":[{"h":"Describe your move","b":"Note your moving date, who's moving (including pets and children), whether you rent or own, and any services you use like energy, broadband, GP, school and subscriptions."},{"h":"Get a moving plan","b":"Paste this prompt into your AI assistant.","p":"I'm moving house on [date] from a [type of home] to a [type of home] in [country]. Household: [people, pets]. I [rent/own] both. Create: 1) a week-by-week checklist from [number] weeks before to 2 weeks after the move, including packing room by room; 2) a change-of-address list grouped by Utilities, Money, Government and council, Health, School, Subscriptions and Deliveries, with a column for 'when to tell them'; 3) a first-night box list. Format each as a checklist."},{"h":"Put it on a Trello board","b":"Create a free Trello board with lists for each week, and paste each task as a card. Invite your partner or helper so you can split the jobs."},{"h":"Tick off the address changes","b":"Use a separate Trello list for the change-of-address items and move each card to 'Done' as you update it."}],"example":"6 weeks before: book removals, start decluttering the loft. 2 weeks: confirm removals, set up post redirection. Move day: meter readings, keys, first-night box. Address list - Utilities: energy, water, broadband (2 weeks before). Health: GP, dentist, opticians.","tips":["Check official government sites for things like updating your driving licence, voter registration and council tax, as rules vary by country."],"auto":{"trigger":{"type":"manual","detail":"User enters a moving date"},"actions":[{"type":"ai.generate","detail":"Create a week-by-week moving plan and address list"},{"type":"list.add","detail":"Add each task as a card on the moving board"},{"type":"notify","detail":"Send a weekly reminder of this week's tasks"}]}},{"id":"get-a-morning-briefing-for-each-day-of-your-trip","t":"Get a morning briefing for each day of your trip","d":"Wake up to a short daily message with today's plan, bookings, weather to check and one local tip.","cat":"Travel","side":"life","lvl":"Advanced","mins":30,"tools":["AI assistant","Google Docs","Google Calendar"],"when":"Every morning while you're away","steps":[{"h":"Finish your trip document","b":"Make sure your itinerary and booking summary are in one Google Docs or Word file, with times in local time."},{"h":"Put key times in your calendar","b":"Add bookings like tours, trains and restaurant tables to Google Calendar or Outlook Calendar with reminders, so you get an alert whatever happens."},{"h":"Set up a scheduled daily task","b":"If your AI assistant offers scheduled tasks (ChatGPT does on some plans), create a daily task for each morning of the trip and paste in your itinerary with this prompt. Otherwise, set a daily phone reminder and paste the prompt yourself.","p":"Every morning at [time, local] from [start date] to [end date], send me a short briefing for that day of my trip to [destination], using this itinerary: [paste itinerary]. Include: today's plan in order with times, any bookings and their reference, how to get between places, what to pack in my day bag, a reminder to check today's weather, and one local tip or phrase. Keep it under 150 words."},{"h":"Adjust on the go","b":"If plans change, reply to the task or edit the itinerary in it so tomorrow's briefing is right."}],"example":"Wed, Day 3: 09:15 train to Sintra (Rossio station, buy tickets at the machine). 10:30 Pena Palace, timed entry, ref PP4471. Lunch in the village. Day bag: water, layers, comfy shoes - lots of hills. Check the weather: mist is common. Phrase: 'A conta, por favor' - the bill, please.","tips":["Keep a copy of your bookings offline too, in case you lose signal or the briefing doesn't arrive."],"auto":{"trigger":{"type":"schedule","detail":"Every morning at 7:30 local time during the trip"},"actions":[{"type":"ai.summarize","detail":"Summarise today's itinerary and bookings"},{"type":"web.fetch","detail":"Get today's weather forecast for the destination"},{"type":"notify","detail":"Send the daily briefing to the user's phone"}]}},{"id":"see-your-workout-progress-with-a-weekly-review","t":"See your workout progress with a weekly review","d":"Log workouts with a quick form, keep them in a sheet and get an automatic weekly progress summary by email.","cat":"Health & Fitness","side":"life","lvl":"Advanced","mins":45,"tools":["Google Forms","Google Sheets","AI assistant","Gmail"],"when":"Log after each workout, review weekly","steps":[{"h":"Make a workout log form","b":"Create a Google Forms form with questions for date, workout type, duration, main exercises and weights or distance, effort out of 10 and a note. Link it to a Google Sheet."},{"h":"Put the form on your home screen","b":"Open the form link on your phone and add it to your home screen, so logging takes under a minute after each session."},{"h":"Set up a weekly review","b":"If your AI assistant offers scheduled tasks or can read your Google Drive (some plans include this), schedule a weekly task with this prompt. Otherwise, set a Sunday reminder and paste the last week's rows yourself.","p":"Review my workout log for the last 7 days: [paste rows or point to the sheet]. Compare with the previous 4 weeks. Give me: total sessions and minutes, any lifts or distances that improved, how my effort scores are trending, whether I'm doing too much or too little based on my goal of [goal], and one suggestion for next week. Use a short table and 3 bullet points. Don't give medical advice."},{"h":"Email it to yourself","b":"Have the summary sent to your email, or copy it into an email draft to yourself, so you have a record of each week."}],"example":"Week 45: 4 sessions, 185 mins (up 20). Squat 5x5 at 52.5kg (+2.5kg). 5k run 31:10 (down from 32:05). Effort average 7.5 - a little high for 4 days. Next week: make Thursday an easy walk or rest day.","tips":["Keep the sheet private; even workout data can be personal.","If you have pain or a health condition, talk to a GP or qualified trainer before increasing load."],"auto":{"trigger":{"type":"form_submitted","detail":"User submits the workout log form"},"actions":[{"type":"sheet.append","detail":"Add the workout to the log sheet"},{"type":"ai.summarize","detail":"On Sundays, summarise the week against the last 4 weeks"},{"type":"email.send","detail":"Email the weekly progress summary to the user"}]}},{"id":"send-personal-feeling-emails-to-a-whole-list","t":"Send personal-feeling emails to a whole list","d":"Write one email, then send it to dozens of people from a spreadsheet, each with their name and a personal opening line.","cat":"Email & Inbox","side":"work","lvl":"Advanced","mins":45,"tools":["Google Sheets","AI assistant","Gmail","Word"],"when":"For invitations, updates to clients or members, or event follow-ups","steps":[{"h":"Set up your contact sheet","b":"In Google Sheets or Excel, make columns for first name, email address and a short note about each person (for example 'came to the June workshop')."},{"h":"Ask AI for personal opening lines","b":"Copy the name and note columns only (not email addresses) into your AI assistant with this prompt, then paste the result back as a new column.","p":"For each row below, write one friendly opening sentence (under 25 words) for an email about [your topic], referring naturally to the note. Don't overdo the flattery. Return a single column in the same order as the input, one line per row, with no numbering. [paste names and notes]"},{"h":"Write the main email once","b":"Draft the body in your email app or ask AI to help. Use placeholders that match your column names, such as {{First name}} and {{Opening}}."},{"h":"Send with mail merge","b":"Use Gmail's mail merge (available on some Google Workspace plans) or Word's Mailings tab with Outlook to send one email per row. Send a test to yourself first."},{"h":"Track replies","b":"Add a 'Replied' column to your sheet and tick people off as they respond, so you know who to follow up."}],"example":"Row: Hannah | came to the June workshop. Opening: 'It was lovely to meet you at the June workshop, and I hope the planning templates have been useful.' Email: Hi Hannah, It was lovely to meet you... We're running a follow-up session on 4 Dec.","tips":["Only email people who've agreed to hear from you, and for marketing include an easy way to opt out.","Check your provider's daily sending limits before sending to a big list; Mailchimp may suit larger lists better."],"auto":{"trigger":{"type":"new_row","detail":"A contact is added to the mailing sheet"},"actions":[{"type":"ai.generate","detail":"Write a personal opening line from the note"},{"type":"sheet.update","detail":"Save the opening line in the row"},{"type":"email.draft","detail":"Create a personalised email for review before sending"}]}},{"id":"keep-track-of-every-action-from-every-meeting","t":"Keep track of every action from every meeting","d":"Meeting notes are saved automatically, and each Friday you get one tracker of open actions across all your meetings.","cat":"Meetings & Calendar","side":"work","lvl":"Advanced","mins":45,"tools":["Google Meet","Google Drive","AI assistant","Google Sheets"],"when":"Every Friday afternoon","steps":[{"h":"Save every meeting's notes in one place","b":"Google Meet's 'Take notes for me' saves notes to Google Drive, Zoom AI Companion can save summaries, and Teams recaps sit with the meeting, if your plan includes them. Otherwise, save your own notes into one Drive or OneDrive folder."},{"h":"Create your action tracker","b":"Make a Google Sheet or Excel file with columns: date added, meeting, action, owner, due date, status, notes."},{"h":"Run a Friday round-up","b":"Open the week's notes (or ask a connected assistant like Gemini to read the Drive folder) and use this prompt.","p":"Here are this week's meeting notes: [paste or point to the folder]. Here is my current action tracker: [paste open rows]. 1) List every new action as rows: date added, meeting, action, owner, due date (or 'not set'). 2) For existing rows, tell me which seem done or changed based on this week's notes. 3) List overdue actions owned by me first. Output the new rows as a table I can paste straight into my spreadsheet."},{"h":"Update the sheet and chase","b":"Paste the new rows in, mark finished items done, and send a short reminder to anyone with overdue actions."},{"h":"Make it a recurring slot","b":"Add a 20-minute recurring Friday calendar event called 'Action round-up' with the prompt in the description."}],"example":"New: 12 Nov | Marketing sync | Brief designer on poster | Zoe | 19 Nov. Changed: 'Book photographer' looks done (mentioned in Thursday's notes). Overdue (you): Send budget to finance - due 7 Nov.","tips":["Ask owners to confirm their actions rather than assuming the AI read the notes correctly."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3pm"},"actions":[{"type":"ai.extract","detail":"Pull actions from the week's meeting notes"},{"type":"sheet.append","detail":"Add new actions to the tracker"},{"type":"sheet.update","detail":"Mark actions that appear finished"},{"type":"notify","detail":"Send the user their overdue actions"}]}},{"id":"wrap-up-your-week-with-one-friday-review","t":"Wrap up your week with one Friday review","d":"Every Friday, get one page that pulls together your calendar, unanswered emails and open tasks, with a starter plan for Monday.","cat":"Planning & Productivity","side":"work","lvl":"Advanced","mins":45,"tools":["AI assistant","Google Calendar","Gmail","Google Docs"],"when":"Every Friday afternoon","steps":[{"h":"Connect your tools","b":"Use Gemini with Google Workspace, Copilot with Microsoft 365, or the Gmail and Google Calendar connectors in ChatGPT or Claude, if your plan includes them. Check your workplace AI policy first."},{"h":"Keep a running task list","b":"Keep your open tasks in one Google Doc or notes page so your assistant (or you) can paste them in each week."},{"h":"Save your Friday prompt","b":"Use this prompt each week, pasting anything your assistant can't read directly.","p":"Run my Friday wrap-up. Look at: this week's calendar, emails from this week that I haven't replied to, and my open task list [paste or point to doc]. Give me: 1) What I got done this week (from meetings held and tasks ticked). 2) Loose ends: unanswered emails that need a reply, and promises I made in meetings. 3) Next week's calendar at a glance, with any day that's overloaded. 4) A starter list of 3 priorities for Monday morning. Keep it to one page."},{"h":"Schedule it and act on it","b":"Create a recurring 30-minute Friday calendar event with the prompt in the description. Spend the time clearing quick loose ends, and save the page in a 'Weekly reviews' doc."}],"example":"Done: 9 meetings, client proposal sent, Q4 budget agreed. Loose ends: Reply to Femi about workshop dates; send slides promised in Tuesday's call. Next week: Wednesday has 6 hours of meetings. Monday priorities: Finish hiring brief; confirm venue; prep Wed board meeting.","tips":["Ending the week with loose ends written down makes it much easier to switch off over the weekend."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3:30pm"},"actions":[{"type":"web.fetch","detail":"Read this week's calendar, unanswered emails and task list"},{"type":"ai.summarize","detail":"Summarise what was done and what's still open"},{"type":"doc.create","detail":"Save the weekly review page"},{"type":"notify","detail":"Send Monday's top 3 priorities to the user"}]}},{"id":"run-a-simple-ticket-board-from-your-support-inbox","t":"Run a simple ticket board from your support inbox","d":"Customer emails turn into cards on a Trello board automatically, get a checklist and due date, and move across columns as you work on them.","cat":"Customer Support","side":"work","lvl":"Advanced","mins":45,"tools":["Gmail","Trello","AI assistant"],"when":"Runs whenever a support email arrives","steps":[{"h":"Set up the board","b":"Create a Trello board with lists: New, Waiting on customer, In progress, Done. In the board's menu, find the Email-to-board settings and copy the board's email address, choosing the New list."},{"h":"Forward support emails to the board","b":"In Gmail's settings, add the Trello address under Forwarding. The confirmation code will appear as a card on your board. Then create a filter for your support emails and choose Forward to that address."},{"h":"Add automation rules in Trello","b":"Open the board's Automation menu and add rules, for example: when a card is added to New, set it due in 1 day and add your checklist; when a card moves to Done, mark it complete."},{"h":"Write the checklist with AI","b":"Ask your AI assistant for a consistent handling checklist to use in your rule.","p":"Write a 5 to 7 step checklist for handling a customer support request at [business type], from first reading to closing. Each step under 8 words, starting with a verb. Include checking the FAQ, replying within [24 hours], confirming the fix with the customer and logging the issue type. Then write a one-line rule for when a ticket should move to 'Waiting on customer'."},{"h":"Work from the board daily","b":"Each morning, drag cards along as you deal with them and reply from Gmail as normal. Check the forward filter hasn't missed any emails for the first week."}],"example":"Card: 'Re: Broken handle on order 4471' | Due tomorrow | Checklist: Read and tag issue / Check FAQ / Reply within 24h / Arrange replacement / Confirm it's fixed / Log issue type. Moved to Waiting on customer: 2 cards. Done this week: 17.","tips":["Trello's free plan limits automation runs, so check usage if you get lots of emails.","Cards hold copies of customer emails, so keep the board private to your team."],"auto":{"trigger":{"type":"new_email","detail":"A support email matches the forwarding filter"},"actions":[{"type":"list.add","detail":"Create a card in the New list"},{"type":"ai.classify","detail":"Tag the card by issue type and urgency"},{"type":"ai.generate","detail":"Suggest a first reply to attach to the card"}]}},{"id":"win-back-old-leads-with-a-gentle-email-series","t":"Win back old leads with a gentle email series","d":"A short, automated email series that reconnects with past enquiries who never bought, offering something useful rather than pestering.","cat":"Sales & Leads","side":"work","lvl":"Advanced","mins":60,"tools":["Google Sheets","Mailchimp","AI assistant"],"when":"Set up once, then add old leads every quarter","steps":[{"h":"Gather leads who said yes to emails","b":"From your sheet or inbox, list past enquiries from the last year or so who agreed to hear from you. Leave out anyone who asked not to be contacted."},{"h":"Import and tag them in Mailchimp","b":"Import the list into Mailchimp as a CSV saved from Google Sheets, and give them a tag such as 'Old lead 2026'."},{"h":"Write the series with AI","b":"Paste this prompt into your AI assistant.","p":"Write a 3-email re-engagement series for people who enquired about [service] in the last year but didn't buy. My business: [one line]. What's new since then: [new offer, prices, results]. Email 1 (day 0): friendly 'thought you might find this useful' with one genuine tip. Email 2 (day 7): a short client story with a result, no names. Email 3 (day 14): a simple invitation to [book a call / special offer until date], with an easy 'not interested' link. Each under 120 words with 2 subject line options. British English, warm, no pressure."},{"h":"Build the automation","b":"In Mailchimp, create an automated journey (Customer Journeys, if your plan includes it) that starts when the tag is added, then sends the three emails with waits of 7 days between them. On a free plan, schedule them as three regular campaigns to that tag."},{"h":"Handle replies personally","b":"Reply to anyone who responds yourself and move them into your sales tracker."}],"example":"Email 1 subject: A quick tip for your spring garden. 'Hi Laura, you asked about patio cleaning last year, so here's a trick: a stiff brush and warm soapy water clears most algae before you need a pressure washer...' Results after 3 weeks: 64 sent, 31 opened, 5 replies, 2 calls booked.","tips":["Only email people who agreed to hear from you; UK and EU rules on marketing emails are strict.","Remove anyone who doesn't open any of the three emails, to keep your list healthy."],"auto":{"trigger":{"type":"schedule","detail":"First day of each quarter"},"actions":[{"type":"ai.extract","detail":"Find enquiries older than 3 months with no sale and marketing consent"},{"type":"sheet.append","detail":"Add them to the re-engagement list"},{"type":"email.send","detail":"Send the 3-email series on days 0, 7 and 14"},{"type":"notify","detail":"Alert the user when someone replies"}]}},{"id":"run-a-weekly-social-posting-routine-on-autopilot","t":"Run a weekly social posting routine on autopilot","d":"A repeatable system where ideas in a sheet become drafted captions, branded images and scheduled posts each week with very little effort.","cat":"Marketing & Social","side":"work","lvl":"Advanced","mins":60,"tools":["Google Sheets","AI assistant","Canva","Google Calendar"],"when":"Set up once, then 30 minutes every Friday","steps":[{"h":"Build your idea sheet","b":"In Google Sheets, create columns: Week, Topic, Headline, Caption, Hashtags, Status. Add 10 or more topics you could post about. Share it with anyone who has ideas."},{"h":"Draft captions on a schedule","b":"If your ChatGPT plan includes scheduled tasks, set a weekly Friday task with this prompt and paste in the week's topics; otherwise run it yourself from a recurring Friday calendar event.","p":"For [business], a [type] serving [audience], write posts for these topics: [paste topics]. For each give: Headline (max 6 words), Caption (50-80 words, one call to action: [CTA]), 3-5 Hashtags. Output as a table with columns Topic | Headline | Caption | Hashtags so I can paste it straight into Google Sheets. British English, warm, no hype."},{"h":"Paste results into the sheet","b":"Paste the table into the matching columns and set Status to Drafted. Edit anything that doesn't sound like you."},{"h":"Make all the images at once","b":"If your Canva plan includes Bulk Create, connect the sheet's Headline column to a template to make every image in one go. Otherwise duplicate one template and paste each headline."},{"h":"Schedule and mark done","b":"Schedule the posts in Meta Business Suite, LinkedIn or Canva's Content Planner, then set Status to Scheduled. Your Friday calendar event keeps the routine going."}],"example":"Friday 3pm: 5 topics pulled from the sheet -> captions drafted -> 5 matching images from Bulk Create -> posts queued Mon to Fri at 8am. Sheet now shows Week 46: 5 Scheduled, 3 ideas left in the bank.","tips":["Top up the idea bank whenever a customer asks a good question; that's your best source of topics.","Check every drafted post before it goes out; never fully skip the human read-through."],"auto":{"trigger":{"type":"schedule","detail":"Fridays at 3pm"},"actions":[{"type":"web.fetch","detail":"Read next week's topics from the idea sheet"},{"type":"ai.generate","detail":"Write headline, caption and hashtags for each"},{"type":"sheet.update","detail":"Fill in drafts and set status to Drafted"},{"type":"notify","detail":"Ask the user to review, make images and schedule"}]}},{"id":"run-a-weekly-blog-writing-routine-with-your-team","t":"Run a weekly blog writing routine with your team","d":"A Trello board that moves each article from idea to published, with automatic reminders and AI help at every stage.","cat":"Content & Writing","side":"work","lvl":"Advanced","mins":45,"tools":["Trello","AI assistant","Google Docs","Google Calendar"],"when":"Set up once, run every week","steps":[{"h":"Build the board","b":"In Trello, create lists: Ideas, Outline, Drafting, Editing, Ready, Published. Add each article idea as a card with the target keyword in the description."},{"h":"Add automatic rules","b":"Use Trello's built-in automation (look for Automation on the board menu) to set rules such as 'when a card moves to Drafting, set a due date 3 days out and add the writer' and 'when a card moves to Ready, add a Publish checklist'."},{"h":"Use one prompt per stage","b":"Save stage prompts in a pinned card so anyone can use them. This is the outline prompt; keep similar ones for drafting and editing.","p":"Create an outline for a blog post. Title idea: [card title]. Keyword: [keyword]. Reader: [audience]. Give: 3 title options, an intro hook, 5 H2 headings with 3 bullets each, one place for a real example from us, and a closing call to action to [CTA]. Note any facts we'll need to source."},{"h":"Draft in linked Google Docs","b":"Write each draft in Google Docs and attach the link to the card so everything lives in one place."},{"h":"Hold a weekly 15-minute check","b":"Set a recurring Google Calendar event to review the board, move cards along and choose next week's ideas."}],"example":"Mon: 'How to choose a wood burner' moves to Drafting -> due Thu, assigned to Ellie automatically. Thu: moves to Editing with editor's notes attached. Fri: moves to Ready -> Publish checklist added (images, links, meta description).","tips":["Free Trello plans have limits on automation runs; keep rules simple or check your plan if you hit the cap."],"auto":{"trigger":{"type":"new_row","detail":"Card moved to a new list on the board"},"actions":[{"type":"ai.generate","detail":"Produce the outline, draft or edit notes for that stage"},{"type":"calendar.create","detail":"Set the stage due date"},{"type":"notify","detail":"Tell the assigned person their next step"}]}},{"id":"share-a-weekly-market-watch-with-your-team","t":"Share a weekly market watch with your team","d":"Gather industry news from alerts and newsletters into one place, then post a short weekly market summary to your team's Slack channel.","cat":"Research & News","side":"work","lvl":"Advanced","mins":40,"tools":["Gmail","AI assistant","Slack","Google Calendar"],"when":"Every Monday morning","steps":[{"h":"Set up your news sources","b":"Create Google Alerts for your industry, key customers and competitors, delivered weekly. Subscribe to two or three trusted trade newsletters."},{"h":"Route them to one label","b":"In Gmail's settings, under Filters, send all of these to a 'Market watch' label and skip the inbox. Outlook users can do the same with a rule and folder."},{"h":"Block 20 minutes on Mondays","b":"Add a recurring Monday event called 'Market watch' so it becomes a habit, and invite a colleague as backup."},{"h":"Draft the summary","b":"Copy the week's emails into your AI assistant with this prompt.","p":"Write a team market-watch post from the news below for a [industry] business. Format for Slack: a bold one-line headline, then 'Need to know' (3 bullets max), 'Worth watching' (3 bullets max) and 'Customers and competitors' (any mentions). Each bullet: one sentence, source name and link. Keep it under 200 words, neutral in tone, and leave out anything without a link. [paste emails]"},{"h":"Check, then post","b":"Open each link to confirm it's accurate and current, then post in your team channel (Microsoft Teams works the same way). Start a thread for discussion."}],"example":"*Market watch, 10 Nov: steel prices ease for a second month* Need to know: steel rebar down 3% (Builders Weekly, link). New site safety guidance published (link). Worth watching: two regional rivals advertising for estimators (link).","tips":["Ask colleagues to react with a thumbs up to items they found useful, and use that to tune your alerts."],"auto":{"trigger":{"type":"schedule","detail":"Mondays at 8am"},"actions":[{"type":"email.label","detail":"Gather the week's market watch emails"},{"type":"ai.summarize","detail":"Write a short team post with links"},{"type":"notify","detail":"Ask the user to review the draft"},{"type":"message.send","detail":"Post the approved summary to the team channel"}]}},{"id":"send-a-monthly-report-written-from-your-spreadsheet","t":"Send a monthly report written from your spreadsheet","d":"Each month, turn your figures into a short written report with a chart, what changed and why it matters, ready to email to your team.","cat":"Documents & Data","side":"work","lvl":"Advanced","mins":45,"tools":["Google Sheets","AI assistant","Gmail","Google Calendar"],"when":"First working day of each month","steps":[{"h":"Keep one tidy tracking sheet","b":"Have one Google Sheet or Excel file with a row per month and a column per measure (for example sales, enquiries, costs). Add a chart of the main measure from the Insert menu."},{"h":"Book the monthly slot","b":"Create a recurring calendar event for the first working day of the month called 'Monthly report' with the sheet linked."},{"h":"Draft the commentary","b":"Copy the last 13 months of data (so it can compare with last year) into your AI assistant with this prompt.","p":"Here is our monthly data for [team or business], with the newest month at the bottom. Write a short monthly report for [audience]: 1) a one-line headline, 2) 3 to 5 bullets on what changed compared with last month and the same month last year, with the actual numbers and percentages, 3) anything unusual worth looking into, 4) 2 questions for the team. Plain English, under 250 words. Don't guess at reasons. Show your calculations in a separate list at the end so I can check them. [paste data]"},{"h":"Check the maths","b":"Compare two or three of its percentages with a quick calculation in the sheet. Delete the calculation list once you're happy."},{"h":"Email it","b":"Paste the report and a screenshot of the chart into an email to your team. Gmail's scheduled send lets you prepare it in advance."}],"example":"October: enquiries up, conversions down. Enquiries 184 (+12% on Sept, +20% on last Oct). Bookings 41 (-5% on Sept). Conversion fell from 27% to 22%. Worth a look: 30% of enquiries came from the new website form. Question: are we replying to form enquiries fast enough?","tips":["Run the same prompt every month so reports are consistent and easy to compare."],"auto":{"trigger":{"type":"schedule","detail":"First working day of each month at 9am"},"actions":[{"type":"ai.generate","detail":"Write the monthly report from the latest figures"},{"type":"email.draft","detail":"Draft the email to the team with the report"},{"type":"notify","detail":"Ask the user to check the numbers and send"}]}},{"id":"catch-every-bill-and-renewal-before-it-auto-renews","t":"Catch every bill and renewal before it auto-renews","d":"Gather bills and renewal emails into one label and a tracker, with a reminder a month before each contract ends.","cat":"Food & Home","side":"life","lvl":"Advanced","mins":45,"tools":["Gmail","Google Sheets","Google Calendar","AI assistant"],"when":"Set up once, runs whenever a bill email arrives","steps":[{"h":"Label bill emails automatically","b":"In Gmail's settings, under Filters, create filters for your energy, broadband, phone, insurance and streaming senders that apply a 'Household bills' label. Outlook users can do the same with rules and a folder."},{"h":"Build a renewals tracker","b":"Make a Google Sheets or Excel file with columns: Provider, What it's for, Monthly cost, Payment day, Contract end date, Notes."},{"h":"Extract the key details","b":"Open a recent bill or renewal email, copy the text (remove account numbers first) and paste it into your AI assistant with this prompt. Gemini in Gmail can do this inside the email if your plan includes it.","p":"From this bill or renewal email, extract: provider, what the service is, monthly or annual cost, payment date, contract end or renewal date, any price rise and its date, and the notice period to cancel or switch. Output as one row with columns: Provider | Service | Monthly cost | Payment day | Contract end | Price change | Notice period. If something isn't stated, write 'not stated'. [paste email text]"},{"h":"Set renewal reminders","b":"For each contract end date, add a Google Calendar event one month earlier called 'Compare deals: [provider]'."},{"h":"Review the label monthly","b":"Once a month, open the 'Household bills' label, add any new details to the sheet and check for price rises."}],"example":"Broadband | Fibre 150 | 32.00 | 14th | 03/2027 | rises to 35.50 in April | 30 days. Car insurance | Annual | 46.25 | 1st | 22/01/2027 | not stated | not stated. Reminder set: 22 Dec - Compare deals: car insurance.","tips":["Remove account numbers, addresses and passwords before pasting emails into any AI tool.","The assistant can misread dates, so double-check contract end dates against your account online."],"auto":{"trigger":{"type":"new_email","detail":"An email lands in the 'Household bills' label"},"actions":[{"type":"ai.extract","detail":"Pull provider, cost, payment day and contract end date"},{"type":"sheet.update","detail":"Add or update the provider's row in the renewals tracker"},{"type":"calendar.create","detail":"Add a 'compare deals' reminder one month before the end date"}]}},{"id":"send-instant-replies-to-common-enquiries-automatically","t":"Send instant replies to common enquiries automatically","d":"Enquiries with set keywords get an instant helpful reply, are labelled for you and land in a weekly list of who to follow up.","cat":"Email & Inbox","side":"work","lvl":"Advanced","mins":50,"tools":["Gmail","AI assistant","Google Sheets"],"when":"Whenever a new enquiry email arrives","steps":[{"h":"Write your auto-reply templates","b":"Ask your AI assistant to draft short replies for your two or three most common enquiries.","p":"I run [business]. Write auto-reply emails for these common enquiries: [e.g. price requests, availability, opening hours]. Each must: thank them, answer the basics in under 100 words using these facts: [paste facts], say a real person will follow up within [time frame] if needed, and include a link placeholder [BOOKING LINK]. Add a subject line for each. Make it clear the email is an automatic reply."},{"h":"Save them as Gmail templates","b":"Turn on Templates in Gmail's settings (under Advanced), then paste each reply into a new email and save it as a template."},{"h":"Create a filter that replies for you","b":"Search Gmail for the words that identify each enquiry (for example sent to your contact address with 'price' in the subject), create a filter from the search, and choose to send the template and apply a label such as 'Enquiry - Prices'."},{"h":"Review the week's enquiries","b":"Every Friday, open the Enquiry labels, copy the senders and subjects into your AI assistant and ask it to turn them into a follow-up table you paste into Google Sheets."},{"h":"Test before you rely on it","b":"Send yourself an email from another account using the trigger words, and check the reply arrives and reads well."}],"example":"Auto-reply: Thanks for asking about our prices! This is an automatic reply. Our dog-walking starts at £14 for 30 minutes, with weekly discounts. You can book a free meet-and-greet here: [link]. Sam will personally reply within one working day.","tips":["Keep filter words specific, or friends and suppliers could get a sales reply by mistake.","Outlook users can do something similar with a rule that replies using a saved template."],"auto":{"trigger":{"type":"new_email","detail":"An email matching enquiry keywords arrives"},"actions":[{"type":"ai.classify","detail":"Identify the enquiry type"},{"type":"email.send","detail":"Send the matching automatic reply"},{"type":"email.label","detail":"Label the enquiry by type"},{"type":"sheet.append","detail":"Add the sender and topic to the follow-up sheet"}]}}]};
